import { AE_MODES } from "../config/ffg-active-effect-modes.js";
/**
 * The system's Actor sheet — native ApplicationV2 DocumentSheetV2 (via the
 * shared FFGActorSheet → FFGDocumentSheet bases). Handles every FFG actor type.
 * @extends {FFGActorSheet}
 */
import { FFGActorSheet } from "../apps/ffg-actor-sheet.js";
import PopoutEditor from "../popout-editor.js";
import DiceHelpers from "../helpers/dice-helpers.js";
import ActorOptions from "./actor-ffg-options.js";
import ImportHelpers from "../importer/import-helpers.js";
import ModifierHelpers from "../helpers/modifiers.js";
import ActorHelpers, {xpLogEarn, xpLogSpend} from "../helpers/actor-helpers.js";
import ItemHelpers from "../helpers/item-helpers.js";
import EmbeddedItemHelpers from "../helpers/embeddeditem-helpers.js";
import EffectHelpers from "../helpers/effects.js";
import { killMinion, killMinionGroup } from "../helpers/minions.js";
import {
  change_role,
  deregister_crew,
  build_crew_roll,
  updateRoles,
  handlePilotCheck,
  buildPilotRoll
} from "../helpers/crew.js";
import {DicePoolFFG} from "../dice/pool.js";
import {get_dice_pool} from "../helpers/dice-helpers.js";
import {itemPillHover} from "../swffg-main.js";

const { DialogV2 } = foundry.applications.api;

export class ActorSheetFFG extends FFGActorSheet {
  constructor(...args) {
    super(...args);
    /**
     * Track the set of filters which are applied
     * @type {Set}
     */
    this._filters = {
      skills: new Set(),
    };
  }

  pools = new Map();

  static DEFAULT_OPTIONS = {
    // `v2` is REQUIRED, not cosmetic: the served stylesheets key actor-sheet
    // layout off `.starwarsffg.sheet.actor.v2`. It was the makeDefault sheet
    // pre-migration, so the collapsed sheet keeps the class to preserve
    // appearance (Stage 4.8). Submit flags / dragDrop / secrets / resizable are
    // inherited from FFGActorSheet; the per-type template comes from get template().
    classes: ["starwarsffg", "sheet", "actor", "v2"],
    position: { width: 710, height: 650 },
    tabs: [{ navSelector: ".sheet-tabs", contentSelector: ".sheet-body", initial: "characteristics" }],
    scrollY: [".tableWithHeader", ".tab", ".skillsGrid", ".skillsTablesGrid"],
  };

  /** @override */
  get template() {
    const path = "systems/starwarsffg/templates/actors";
    return `${path}/ffg-${this.actor.type}-sheet.html`;
  }

  /** @override */
  async _onDropItem(event, data) {
    if(!this.actor.verifyEditModeIsNotEnabled()) return false;

    if (data?.type === "Item") {
      // this is the stock implementation, except that we do not pass "true" to item.toObject
      if ( !this.actor.isOwner ) return false;
      const item = await Item.implementation.fromDropData(data);
      // do not Draw values from the underlying data source rather than transformed values - we want to use adjusted values
      const itemData = item.toObject(false);

      // Handle item sorting within the same Actor
      if ( this.actor.uuid === item.parent?.uuid ) return this._onSortItem(event, itemData);

      if (["character", "minion", "rival"].includes(this.actor.type) && ["itemmodifier", "itemattachment"].includes(itemData.type)) {
        ui.notifications.warn("You cannot add Item Modifiers or Attachments directly to actors.");
        return false;
      }

      if (this.actor.type === "character" && itemData.type === "species") {
        // add starting XP from species
        const curAvailable = parseInt(this.actor.system?.experience?.available);
        const curTotal = parseInt(this.actor.system?.experience?.total);
        const startingXP = parseInt(itemData.system?.startingXP);
        await this.actor.update(
          {
            system: {
              experience: {
                available: curAvailable + startingXP,
                total: curTotal + startingXP,
              }
            }
          }
        );
        await xpLogEarn(this.actor, startingXP, curAvailable + startingXP, curTotal + startingXP, game.i18n.format("SWFFG.GrantXPSpecies", {species: itemData.name}) );
      }

      if (this.actor.type === "character" && ["talent", "specialization", "signatureability", "forcepower"].includes(itemData.type)) {
        // Always prompt Buy (spend XP) or Grant (free) when one of these is dropped
        // on a character. calcPurchasePrice returns the XP cost, or -1 when it can't
        // be determined (e.g. a specialization with no career) -- clamp to 0. Force
        // powers and signature abilities default to base_cost 0, so the previous
        // `cost > 0 && cost < availableXP` gate meant they never prompted at all.
        const cost = Math.max(0, await this.calcPurchasePrice(itemData));
        const availableXP = this.actor.system.experience.available;
        await DialogV2.wait({
          window: { title: game.i18n.localize("SWFFG.DragDrop.Title") },
          classes: ["dialog", "starwarsffg"],
          content: "",
          buttons: [
            {
              action: "purchase",
              icon: "fas fa-hourglass",
              label: game.i18n.localize("SWFFG.DragDrop.PurchaseItem"),
              default: true,
              callback: async () => {
                if(!this.actor.verifyEditModeIsNotEnabled()) return false;
                if (cost <= 0) return; // nothing to spend
                if (cost > availableXP) {
                  ui.notifications.warn(`Not enough available XP to purchase ${itemData.name} (cost ${cost}, available ${availableXP}); granting instead.`);
                  return;
                }

                const AEState = await ActorHelpers.beginEditMode(this.actor, true);
                const updatedAvailableXP = this.actor.system.experience.available;
                await this.object.update({
                  system: {
                    experience: {
                      available: updatedAvailableXP - cost,
                    }
                  }
                });
                await xpLogSpend(
                    this.actor, `${game.i18n.localize("SWFFG.DragDrop.XPLog")} ${itemData.type} ${itemData.name}`,
                    cost,
                    this.actor.system.experience.available,
                    this.actor.system.experience.total
                );
                await ActorHelpers.endEditMode(this.actor, AEState, true);
              },
            },
            {
              action: "grant",
              icon: "fas fa-recycle",
              label: game.i18n.localize("SWFFG.DragDrop.GrantItem"),
            },
          ],
          rejectClose: false,
        });
      }

      if (Object.keys(itemData).includes("effects") && ["armour", "weapon"].includes(itemData.type)) {
        // make sure all non-inherent AEs are disabled on the item before the drag-and-drop
        for (const effect of itemData.effects) {
          if (effect.name !== "(inherent)") {
            effect.disabled = true;
          }
        }
      }

      // Create the owned item
      return this._onDropItemCreate(itemData);
    } else {
      return super._onDropItem(event, data);
    }
  }

  async calcPurchasePrice(itemData) {
    let cost = 0;
    if (itemData.type === "specialization") {
      // check if the specialization is in career
      const career = this.actor.items.find(i => i.type === "career");
      if (career) {
        const inCareerSpecializations = Object.values(career?.system?.specializations) || [];
        let inCareer = false;
        for (const careerSpecialization of inCareerSpecializations) {
          if (careerSpecialization.name === itemData.name) {
            inCareer = true;
            break;
          }
        }
        const specializationCount = (this.actor.items.filter(i => i.type === "specialization") || []).length;
        cost = (specializationCount + 1) * 10;
        if (!inCareer && !itemData.system.universal) {
          cost += 10;
        }
        return cost;
      } else {
        return -1;
      }
    } else if (itemData.type === "talent" && game.settings.get("starwarsffg", "dicetheme") === "genesys") {
      return itemData.system.tier * 5;
    } else if (itemData.type === "signatureability") {
      return itemData.system.base_cost;
    } else if (itemData.type === "forcepower") {
      return itemData.system.base_cost;
    }
    return -1;
  }

  /* -------------------------------------------- */

  /** @override */
  async getData(options) {
    const data = await super.getData(options);
    // The sheet templates branch on `contains classType "V2"` to render the V2
    // layout (icon tab strip, refined panels, shown-by-default tabs). After the
    // Stage 4 collapse the real classes are `ActorSheetFFG`/`AdversarySheetFFG`
    // (no "V2" suffix), so carry the V2 marker explicitly — these ARE the V2
    // sheets. Without it the templates fall back to the retired V1 layout.
    data.classType = this.constructor.name.includes("V2") ? this.constructor.name : `${this.constructor.name}V2`;

    // Compatibility for Foundry 0.8.x with backwards compatibility (hopefully)
    // for 0.7.x. Actor sheet templates depend on prepared actor data here; the
    // base document context can omit prepared skill rows and collapse skill
    // sections to headers only.
    const actorData = this.actor.toObject(false);
    // A registered system DataModel's toObject() serializes only declared schema
    // fields, so top-level derived data attached to `system` during
    // prepareDerivedData (skilltypes, …) is dropped — template.json's plain
    // object retained it, and the templates/helpers expect it. Overlay those
    // derived props from the live system. `effects` is skipped on purpose: it
    // holds live ActiveEffect Documents, which must not be placed on this plain
    // copy (it gets deep-cloned/merged below and elsewhere, which would recurse
    // into Document back-references); it is read from the live system directly
    // where consumed (see the effects mapping later in getData).
    const liveSystem = this.actor.system;
    // These prepared fields may already exist on the raw serialized system as
    // empty/default schema values, so the generic "missing keys only" overlay
    // below is not enough to keep skill rows rendered.
    for (const key of ["skills", "skilltypes"]) {
      if (liveSystem[key] !== undefined) {
        actorData.system[key] = foundry.utils.deepClone(liveSystem[key]);
      }
    }
    for (const key of Object.keys(liveSystem)) {
      if (key === "effects" || key in actorData.system) continue;
      actorData.system[key] = foundry.utils.deepClone(liveSystem[key]);
    }
    data.actor = actorData;
    data.data = actorData.system;
    data.talentList = this.actor.talentList;
    data.rollData = this.actor.getRollData.bind(this.actor);

    data.token = this.token;
    data.items = this.actor.items;

    if (options?.action === "update" && this.object.compendium) {
      data.item = foundry.utils.mergeObject(data.actor, options.data);
    }

    data.dtypes = ["String", "Number", "Boolean"];
    for (let attr of Object.values(data.data.attributes)) {
      attr.isCheckbox = attr.dtype === "Boolean";
    }
    data.FFG = CONFIG.FFG;

    let autoSoakCalculation = true;

    if (typeof this.actor.flags?.starwarsffg?.config?.enableAutoSoakCalculation === "undefined") {
      autoSoakCalculation = game.settings.get("starwarsffg", "enableSoakCalc");
    } else {
      autoSoakCalculation = this.actor.flags?.starwarsffg?.config?.enableAutoSoakCalculation;
    }

    data.settings = {
      enableSoakCalculation: autoSoakCalculation,
      enableCriticalInjuries: this.actor.flags?.starwarsffg?.config?.enableCriticalInjuries,
    };

    // Establish sheet width and height using either saved persistent values or default values defined in swffg-config.js.
    // FIRST RENDER ONLY. Re-applying this every render is what made a resized sheet
    // snap back to default (#14), and it did so invisibly: `position` is a Proxy
    // whose set trap re-runs _updatePosition but never #applyPosition, and
    // _updatePosition only writes el.style for dimensions that are "auto" -- which
    // these are not. So the write moved internal state while the DOM kept the size
    // the user dragged, and nothing looked wrong until the next setPosition replayed
    // the stale clone. Dragging the header is exactly that: #onWindowDragMove
    // replays width and height, not just top/left. Hence the two-step repro (edit,
    // THEN move).
    // The guard mirrors item-sheet-ffg.js:248, where the same thing is already
    // fixed. Ordering is safe: the render's own getData (via _prepareContext) runs
    // before activateListeners, so it consumes the flag and the unawaited per-skill
    // getData() calls further down become no-ops.
    // Skip while minimized/minimizing -- otherwise this fights the V13 minimize
    // collapse and snaps the sheet back to full size on the next render.
    const setInitialSize = !this._sizeInitialized;
    this._sizeInitialized = true;
    if (setInitialSize && !this.minimized && !this._minimizing) {
      this.position.width = this.sheetWidth || CONFIG.FFG.sheets.defaultWidth[this.actor.type];
      this.position.height = this.sheetHeight || CONFIG.FFG.sheets.defaultHeight[this.actor.type];
    }

    switch (this.actor.type) {
      case "character":
      case "nemesis":
      case "rival":
        // Same first-render guard as the sizing block above — without it a limited
        // sheet re-poisons its height on every render and snaps on the next drag.
        if (data.limited && setInitialSize) {
          this.position.height = 165;
        }
        // we need to update all specialization talents with the latest talent information
        if (!this.actor.flags.starwarsffg?.loaded && this.actor.type !== "rival") {
          // TODO: is this actually needed?
          await this._updateSpecialization(data);
          await this.object._prepareCharacterData(data);
        }

        if (data.data.stats.credits.value > 999) {
          data.data.stats.credits.value = data.data.stats.credits.value.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ",");
        }
        data.data.enrichedBio = await foundry.applications.ux.TextEditor.implementation.enrichHTML(this.actor.system.biography, {secrets: !data.limited});
        data.data.general.enrichedNotes = await foundry.applications.ux.TextEditor.implementation.enrichHTML(this.actor.system.general?.notes) || "";
        data.data.general.enrichedFeatures = await foundry.applications.ux.TextEditor.implementation.enrichHTML(this.actor.system.general?.features) || "";
        data.maxAttribute = game.settings.get("starwarsffg", "maxAttribute");
        data.obligationItems = {
          obligations: data.items.filter(i => i.system?.type === "obligation"),
          duties: data.items.filter(i => i.system?.type === "duty"),
          moralities: data.items.filter(i => i.system?.type === "morality"),
        };
        break;
      case "vehicle":
        data.data.enrichedBio = await foundry.applications.ux.TextEditor.implementation.enrichHTML(this.actor.system.biography);
        // add the crew to the items of the vehicle
        data.crew = [];
        // look up the flag data
        const crew = this.actor.getFlag('starwarsffg', 'crew');
        if (crew) {
          for (let i = 0; i < crew.length; i++) {
            try {
              // iterate over the crew members in the flag data
              const actor = game.actors.get(crew[i].actor_id);
              // pull the image from the actor to display it
              const img = actor?.img || 'icons/svg/mystery-man.svg';

              // add them to the items, so we can render them on the sheet
              let roll;
              if (actor) {
                if (crew[i].role !== "Pilot") {
                  roll = build_crew_roll(this.actor.id, crew[i].actor_id, crew[i].role);
                } else {
                  roll = (await buildPilotRoll(this.actor.id, crew[i].actor_id, 0)).renderPreview().innerHTML;
                }
              } else {
                deregister_crew(this.actor, crew[i].actor_id, crew[i].role);
              }
              if (!roll) {
                roll = 'N/A';
              }
              data.crew.push({
                'type': 'shipcrew',
                'id': crew[i].actor_id,
                'name': crew[i].actor_name,
                'role': crew[i].role,
                'img': img,
                'roll': roll,
                'link': crew[i]?.link,
              });
            } catch (e) {
              data.crew.push({
                'type': 'shipcrew',
                'id': crew[i].actor_id,
                'name': crew[i].actor_name,
                'role': crew[i].role,
                'img': '',
                'roll': '(broken role)',
                'link': '',
              });
            }
          }
        }
      default:
    }

    if (this.actor.type !== "vehicle" && this.actor.type !== "homestead") {
      // Filter out skills that are not custom (manually added) or part of the current system skill list
      Object.keys(data.data.skills)
      .filter(s => !data.data.skills[s].custom && !CONFIG.FFG.skills[s])
      .forEach(s => delete data.data.skills[s]);

      data.data.skilllist = this._createSkillColumns(data);
    }

    if (this.actor.flags?.starwarsffg?.xpLog) {
      data.xpLog = this.object.getFlag("starwarsffg", "xpLog") || [];
    }

    data.actor.items = ActorSheetFFG.sortForActorSheet(data.actor.items);
    const editModeEnabled = this.object.getFlag("starwarsffg", "config.enableEditMode");
    const editModeActor = this.object.getFlag("starwarsffg", "config.editModeActor");
    data.disabled = !(editModeEnabled && editModeActor === game.user.id);

    data.modTypeSelected = "all"; // TODO: should this be something else?
    data.modifierTypes = CONFIG.FFG.allowableModifierTypes;
    data.modifierChoices = CONFIG.FFG.allowableModifierChoices;

    // Include active effects. `effects` is derived data attached to system in
    // prepareDerivedData (a list of live ActiveEffect Documents), not a schema
    // field — so a registered system DataModel's toObject() (used for actorData
    // above) drops it. Read it from the live system instead. `?? []` guards any
    // actor whose prepare hasn't populated it.
    data.effects = (this.actor.system.effects ?? []).map(EffectHelpers.transformEffects);

    return data;
  }

  /**
   * Sorts actor items by name so that they are presented in a constant order
   * @param items
   * @returns {*}
   */
  static sortForActorSheet(items) {
    return items.sort(function(a, b) {
       return a.name.localeCompare(b.name);
    });
  }

  /* -------------------------------------------- */

  /** @override */
  activateListeners(html) {
    super.activateListeners(html);
    // convert jquery element to HTMLElement for usage with Foundry calls
    const htmlElement = html.get(0);

    // Tabs are bound by FFGDocumentSheet._activateCoreListeners using the
    // DEFAULT_OPTIONS.tabs config and the per-document _activeTabCache. Do not
    // re-bind here -- a second Tabs controller on the same nav would race and
    // immediately activate the default tab, defeating the cache.

    html.find(".alt-tab").click((ev) => {
      const item = $(ev.currentTarget);
      this._tabs[0].activate(item.data("tab"));
    });

    // Skill career/group toggle: minion sheets recompute the displayed
    // skill rank in _prepareMinionData based on `groupskill`. Without an
    // explicit re-render after the submit, the rank input keeps showing
    // the stale stored value and the toggle appears to "do nothing".
    // (For character actors the toggle still just flips careerskill and a
    // render keeps the UI consistent with the chip color.) Stop the event
    // from bubbling to the form-level change handler so we don't run the
    // default render:false submit on top of our render:true one.
    html.find("input.careerskill-toggle").on("change", async (event) => {
      event.stopPropagation();
      await this._onSubmit(event, { render: true });
    });

    // Editing a skill rank changes that skill's dice pool (and any weapon's that
    // uses it), which is rebuilt only during render. The default pipeline submits
    // render:false, so the pool stayed stale until the next full render (e.g.
    // leaving edit mode). Re-render on change — `change` fires on blur, so the
    // typed value is committed first and there's no mid-typing DOM swap.
    html.find("input.careerskill-rank").on("change", async (event) => {
      event.stopPropagation();
      await this._onSubmit(event, { render: true });
    });

    // Same for characteristic edits — they drive every skill's (and weapon's)
    // dice pool, which only rebuilds on render. `change` fires on blur/step, so
    // the value is committed before the re-render.
    html.find('input[name^="data.characteristics."][name$=".value"]').on("change", async (event) => {
      event.stopPropagation();
      await this._onSubmit(event, { render: true });
    });

    // Minion sheets compute several display fields in _prepareMinionData
    // from raw inputs that the user edits directly:
    //   unit_wounds.value + quantity.max -> stats.wounds.max
    //   stats.wounds.value + unit_wounds.value -> quantity.value (alive)
    //   quantity.value + groupskill -> skill.rank
    // The default change pipeline submits with render: false, so editing
    // any of those raw inputs persists the value but leaves the derived
    // fields displaying their pre-edit numbers until the sheet is closed
    // and reopened. Force render: true on change for these specific
    // numeric/select inputs (text-typing inputs aren't in this list, so
    // mid-typing DOM swaps remain prevented).
    if (this.actor.type === "minion") {
      const minionDerivedInputs = [
        'input[name="data.unit_wounds.value"]',
        'input[name="data.quantity.max"]',
        'input[name="data.stats.wounds.value"]',
      ].join(", ");
      html.find(minionDerivedInputs).on("change", async (event) => {
        event.stopPropagation();
        await this._onSubmit(event, { render: true });
      });
    }

    html.find(".popout-editor").on("mouseover", (event) => {
      $(event.currentTarget).find(".popout-editor-button").show();
    });
    html.find(".popout-editor").on("mouseout", (event) => {
      $(event.currentTarget).find(".popout-editor-button").hide();
    });
    html.find(".popout-editor .popout-editor-button").on("click", this._onPopoutEditor.bind(this));

    // Setup dice pool image and hide filtered skills.
    html.find(".skill").each(async (_, elem) => {
      await DiceHelpers.addSkillDicePool(await this.getData({}), elem);
      const filters = this._filters.skills;
    });

    // Everything below here is only needed if the sheet is editable
    if (!this.isEditable) return;

    this._bindActorContextMenus(htmlElement);

    html.find(".skill-purchase").click(async (ev) => {
      const target = $(ev.currentTarget).parents().filter("[data-ability]");
      await this._buySkillRank(target);
    });

    html.find(".xp-adjustment").click(async (ev) => {
      await this._xpAdjustment(ev);
    });

    html.find(".xp-export").click(async (ev) => {
      await this._xpExport(ev);
    });

    html.find(".xp-import").click(async (ev) => {
      await this._xpImport(ev);
    });

    html.find(".minion-control").click(async (ev) => {
      await this._handleKillMinion(ev);
    });

    html.find(".ffg-purchase").click(async (ev) => {
      await this._buyCore(ev)
    });

    html.find(".xp.purchase").click(async (ev) => {
      const purchaseId = $(ev.currentTarget).children("a").data("id");
      await this._refundPurchase(purchaseId, "purchase")
    });
    html.find(".xp.adjusted").click(async (ev) => {
      const purchaseId = $(ev.currentTarget).children("a").data("id");
