  /**
   * Drop Event function for transferring items between actors
   *
   * @param  {Object} event
   */
  async _onTransferItemDrop(event) {
    // Try to extract the data
    let data;
    try {
      data = JSON.parse(event.dataTransfer.getData("text/plain"));
    } catch (err) {
      return false;
    }
    // Only OUR cross-actor "Transfer" payload should be consumed here. Anything
    // else (a normal Item/Folder/Actor drop that lands on the stock .sheet-body,
    // to which this handler is bound) must be left to bubble up to the native
    // root _onDrop, which creates the embedded item. Returning early WITHOUT
    // stopPropagation is what lets that happen -- a previous unconditional
    // stopPropagation() here swallowed every non-Transfer drop on stock sheets,
    // so items could never be dropped onto them (codex sheets were unaffected
    // because their drop target is a display:contents element that never fires).
    if (data.type !== "Transfer") return;
    // Confirmed Transfer: stop the event before it also reaches the native root
    // _onDrop (which now routes "Transfer" too), otherwise the item would be
    // created and the source deleted twice. Synchronous -- runs before any await.
    event.stopPropagation();

    if (data.data) {
      let sameActor = data.actorId === this.actor.id;
      if (!sameActor) {
        try {
          this.actor.createEmbeddedDocuments("Item", [foundry.utils.duplicate(data.data)]); // Create a new Item
          let token;
          if (game.scenes.current) {
            token = game.scenes.current.tokens.get(data?.tokenId);
            if (token) {
              // Delete originating item from other _token_
              token.actor.items.get(data.data._id)?.delete();
              return;
            }
          }
          const actor = game.actors.get(data.actorId);
          await actor.items.get(data.data._id)?.delete(); // Delete originating item from other actor
        } catch (err) {
          CONFIG.logger.error(`Error transferring item between actors.`, err);
        }
      }
    }

    await this._suspendActiveEffects(await fromUuid(data.uuid));
  }

  /**
   * ActiveEffects are transferred to actors by default. In some cases, we don't want them transferred.
   * Suspend anything we don't want (for example, item attachment AEs shouldn't be transferred to an actor because they're holding it)
   * @param droppedItem - the fromUuid item dropped onto this object
   * @returns {Promise<void>}
   * @private
   */
  async _suspendActiveEffects(droppedItem) {
    // Note: this function is currently placeholder. I may implement it - if we get better support for holding attachments
    return;
    const droppedType = droppedItem.type;
    const myType = this.object.type;
    const toSuspend = [];

    if (["itemattachment", "itemmodifier"].includes(droppedType)) {
      CONFIG.logger.info(`Suspending AEs for drag-and-drop of ${droppedType} -> ${myType}`);
      for (const activeEffect of droppedItem.effects) {
        toSuspend.push(activeEffect);
      }
      await this.object.createEmbeddedDocuments("ActiveEffect", toSuspend);
    }
  }

  /**
   * Update specialization talents
   * @param  {Object} data
   */
  async _updateSpecialization(data) {
    CONFIG.logger.debug(`Running Actor initial load`);
    if (this.actor.flags.starwarsffg === undefined) {
        this.actor.flags.starwarsffg = {};
    }
    this.actor.flags.starwarsffg.loaded = true;

    const specializations = this.actor.items.filter((item) => {
      return item.type === "specialization";
    });

    CONFIG.logger.debug(`_updateSpecialization(): data.talentList before we start:`);
    CONFIG.logger.debug(data.talentList.slice());

    // start the talent list only with talents that did not come from a specialization
    const globalTalentList = data.talentList.filter(i => i.source.filter(s => s.type === "talent").length > 0)

    for await (const spec of specializations) {
      CONFIG.logger.debug(`_updateSpecialization(): starting work on ${spec.name}`);

      if (spec?.talentList && spec.talentList.length > 0) {
        spec.talentList.forEach((talent) => {
          const item = talent;
          item.firstSpecialization = spec.id;

          if (item.isRanked) {
            item.rank = typeof talent.rank === "number" ? talent.rank : 1;
          } else {
            item.rank = "N/A";
          }

          let index = globalTalentList.findIndex((obj) => {
            return obj.name === item.name;
          });

          if (index < 0 || !item.isRanked) {
            globalTalentList.push(item);
          } else {
            globalTalentList[index].rank += talent.rank;
          }
        });
      }
      CONFIG.logger.debug(`_updateSpecialization(): globalTalentList after current specialization:`);
      CONFIG.logger.debug(globalTalentList.slice());
    }

    data.talentList = globalTalentList;

    CONFIG.logger.debug(`_updateSpecialization(): data.talentList after update:`);
    CONFIG.logger.debug(data.talentList.slice());
  }

  /**
   * Open dialog for popout editor
   * @param  {Object} event
   */
  /**
   * Creates two even columns of skills for display while also sorting them.
   * @param  {Object} data
   */
  _createSkillColumns(data) {
    const numberSkills = Object.values(data.data.skills).length;
    const totalRows = numberSkills + Object.values(data.data.skilltypes).length;

    let colRowCount = Math.ceil(totalRows / 2.0);

    const cols = [[], []];

    let currentColumn = 0;
    let rowsLeft = colRowCount;

    data.data.skilltypes.forEach((type) => {
      // filter and sort skills for current skill category
      let sortFunction = (a, b) => {
        if (a.toLowerCase() > b.toLowerCase()) return 1;
        if (a.toLowerCase() < b.toLowerCase()) return -1;
        return 0;
      };
      if (game.settings.get("starwarsffg", "skillSorting")) {
        sortFunction = (a, b) => {
          return data.data.skills[a].label.localeCompare(data.data.skills[b].label, game.i18n.lang);
        };
      }

      const skills = Object.keys(data.data.skills)
        .filter((s) => data.data.skills[s].type === type.type)
        .sort(sortFunction);

      // if the skill list is larger that the column row count then take into account the added header row.
      if (skills.length >= colRowCount) {
        if (skills.length - colRowCount > 2) {
          colRowCount = Math.ceil((totalRows + 1) / 2.0);
          rowsLeft = colRowCount;
        } else {
          colRowCount = skills.length + 1;
          rowsLeft = colRowCount;
        }
      }

      cols[currentColumn].push({ id: "header", ...type });
      rowsLeft -= 1;
      skills.forEach((s, index) => {
        cols[currentColumn].push({ name: s, ...data.data.skills[s] });
        rowsLeft -= 1;
        if (rowsLeft <= 0 && currentColumn === 0) {
          currentColumn += 1;
          rowsLeft = colRowCount;

          if (index + 1 < skills.length) {
            cols[currentColumn].push({ id: "header", ...type });
            rowsLeft -= 1;
          }
        }
      });
    });

    return cols;
  }

  async _buyCore(event) {
    if(!this.actor.verifyEditModeIsNotEnabled()) return;

    // Read from currentTarget (the bound .ffg-purchase element that carries the
    // data-* attrs), NOT event.target — clicking a label with child spans (e.g.
    // the codex characteristic chip's full/abbr label) lands on a child that has
    // no data-buy-action, which previously made the purchase silently bail.
    const action = $(event.currentTarget).data("buy-action");
    const template = "systems/starwarsffg/templates/dialogs/ffg-confirm-purchase.html";
    let content;
    const availableXP = this.object.system.experience.available;
    const totalXP = this.object.system.experience.total;
    let itemType;
    const groups = [];
    if (action === "specialization") {
      const inCareer = this.object.items.find(i => i.type === "career")?.system?.specializations;
      if (!inCareer) {
        ui.notifications.warn("Could not locate any specializations in your career! Please define them first");
        return;
      }
      const inCareerNames = Object.values(inCareer).map(i => i.name);
      const sources = game.settings.get("starwarsffg", "specializationCompendiums").split(",");
      let outCareer = [];
      let universal = [];
      for (const source of sources) {
        const pack = game.packs.get(source);
        if (!pack) {
          continue;
        }
        const items = await pack.getDocuments();
        for (const item of items) {
          if (!inCareerNames.includes(item.name) && item.system.universal) {
            universal.push({
              name: item.name,
              id: item.id,
              source: item.uuid,
            });
          } else if (!inCareerNames.includes(item.name)) {
            outCareer.push({
              name: item.name,
              id: item.id,
              source: item.uuid,
            });
          }
        }
      }
      outCareer = sortDataBy(outCareer, "name");
      universal = sortDataBy(universal, "name");
      const baseCost = (this.object.items.filter(i => i.type === "specialization").length + 1) * 10;
      const increasedCost = baseCost + 10;
      if (baseCost > availableXP) {
        ui.notifications.warn(game.i18n.localize("SWFFG.Actors.Sheets.Purchase.NotEnoughXP"));
        return;
      } else if (increasedCost > availableXP) {
        outCareer = [];
      }
      itemType =  game.i18n.localize("TYPES.Item.specialization");
      groups.push("Universal");
      groups.push("In Career");
      groups.push("Out of Career");
      content = await foundry.applications.handlebars.renderTemplate(template, { inCareer, outCareer, universal, baseCost, increasedCost, itemType: itemType, itemCategory: "specialization", groups: groups });
    } else if (action === "signatureability") {
      const sources = game.settings.get("starwarsffg", "signatureAbilityCompendiums").split(",");
      const rawSelectableItems =  this.object.items.find(i => i.type === "career").system.signatureabilities;
      const sigAbilityNames = Object.values(rawSelectableItems).map(i => i.name);
      let selectableItems = [];
      // pull items out of the world
      for (const itemId of Object.keys(rawSelectableItems)) {
        const item = rawSelectableItems[itemId];
        let retrievedItem = game.items.get(item.id);
        if (retrievedItem) {
          selectableItems.push({
            name: retrievedItem.name,
            id: retrievedItem.id,
            source: retrievedItem.uuid,
            cost: parseInt(retrievedItem.system.base_cost),
          });
        }
      }
      // pull items out of compendiums
      for (const source of sources) {
        const pack = game.packs.get(source);
        if (!pack) {
          continue;
        }
        const items = await pack.getDocuments();
        for (const item of items) {
          if (sigAbilityNames.includes(item.name)) {
            selectableItems.push({
              name: item.name,
              id: item.id,
              source: item.uuid,
              cost: parseInt(item.system.base_cost),
            });
          }
        }
      }
      if (selectableItems.length === 0) {
        ui.notifications.warn(game.i18n.localize("SWFFG.Actors.Sheets.Purchase.SA.NotSet"));
        return;
      }
      // filter purchasable signature abilities to those where the required specialization upgrades have been purchased
      // filter specializations to those within the career
      const career = this.object.items.find(i => i.type === "career");
      if (!career) {
        ui.notifications.warn(game.i18n.localize("SWFFG.Actors.Sheets.Purchase.CareerNotSet"));
        return;
      }
      const permittedSpecializations = Object.values(career.system.specializations).map(i => i.name);
      const matchingSpecializations = this.object.items.filter(i => i.type === "specialization" && permittedSpecializations.includes(i.name));
      if (!matchingSpecializations) {
        ui.notifications.warn(game.i18n.localize("SWFFG.Actors.Sheets.Purchase.Career.Specializations.NotSet"));
        return;
      }
      // loop through signature abilities and build a map of required upgrades
      let newSelectableItems = [];
      for (const selectableItem of selectableItems) {
        const fullItem = fromUuidSync(selectableItem.source);
        // check if any specializations match the required upgrades, discarding them if they do not
        let match;
        for (const specialization of matchingSpecializations) {
          match = true;
          for (let i = 0; i < 4; i++) {
            // if the upgrade is required, and we don't have it learned, this is not a match
            if (fullItem.system.uplink_nodes[`uplink${i}`] && !specialization.system.talents[`talent${i + 16}`].islearned) {
              match = false;
              break;
            }
          }
          if (match) {
            // if any specialization matches the required upgrades, do not check further specializations
            newSelectableItems.push(selectableItem);
            break;
          }
        }
      }
      if (newSelectableItems.length === 0) {
        ui.notifications.warn(game.i18n.localize("SWFFG.Actors.Sheets.Purchase.SA.NoMatch"));
        return;
      }

      // update the list with the filtered list
      selectableItems = newSelectableItems;

      selectableItems = sortDataBy(selectableItems, "name");
      itemType = game.i18n.localize("TYPES.Item.signatureability");
      content = await foundry.applications.handlebars.renderTemplate(template, { selectableItems, itemType: itemType, itemCategory: "signatureability" });
    } else if (action === "forcepower") {
      const sources = game.settings.get("starwarsffg", "forcePowerCompendiums").split(",");
      let selectableItems = [];
      const worldItems = game.items.filter(i => i.type === "forcepower");
      for (const worldItem of worldItems) {
        selectableItems.push({
          name: worldItem.name,
          id: worldItem.id,
          source: worldItem.uuid,
          cost: worldItem.system.base_cost,
          requiredForceRating: parseInt(worldItem.system.required_force_rating),
        });
        addIfNotExist(groups, parseInt(worldItem.system.required_force_rating));
      }
      for (const source of sources) {
        const pack = game.packs.get(source);
        if (!pack) {
          continue;
        }
        const items = await pack.getDocuments();
        for (const item of items) {
          selectableItems.push({
            name: item.name,
            id: item.id,
            source: item.uuid,
            cost: item.system.base_cost,
            requiredForceRating: parseInt(item.system.required_force_rating),
          });
          addIfNotExist(groups, parseInt(item.system.required_force_rating));
        }
      }
      selectableItems = sortDataBy(selectableItems, "name");
      itemType = game.i18n.localize("TYPES.Item.forcepower");
      groups.sort();
      content = await foundry.applications.handlebars.renderTemplate(template, { selectableItems, itemType: itemType, itemCategory: "forcepower", groups: groups });
    } else if (action === "talent") {
      const purchasedItems = this.object.talentList;
      const sources = game.settings.get("starwarsffg", "talentCompendiums").split(",");
      let selectableItems = [];
      const worldItems = game.items.filter(i => i.type === "talent");
      let worldItemsPack = [];
      for (const worldItem of worldItems) {
        const purchasedItem = purchasedItems.find((pItem) => pItem.name === worldItem.name)
        if(!purchasedItem || purchasedItem.isRanked) {
          worldItemsPack.push({
            name: worldItem.name,
            id: worldItem.id,
            source: worldItem.uuid,
            cost: purchasedItem?.isRanked ? worldItem.system.tier * 5 + 5 * purchasedItem.rank: worldItem.system.tier * 5,
          });
        }
      }
      worldItemsPack = sortDataBy(worldItemsPack, "name");
      selectableItems.push({pack: game.i18n.localize("SWFFG.Actors.Sheets.Purchase.Talent.WorldItemsGroup"), items: worldItemsPack});

      for (const source of sources) {
        const pack = game.packs.get(source);
        if (!pack) {
          continue;
        }
        let packItems = [];
        const items = await pack.getDocuments();
        for (const item of items) {
          const purchasedItem = purchasedItems.find((pItem) => pItem.name === item.name)
          if(!purchasedItem || purchasedItem.isRanked) {
            packItems.push({
              name: item.name,
              id: item.id,
              source: item.uuid,
              cost: purchasedItem?.isRanked ? item.system.tier * 5 + 5 * purchasedItem.rank: item.system.tier * 5,
            });
          }
        }
        packItems = sortDataBy(packItems, "name");
        selectableItems.push({pack: pack.metadata.label, items: packItems});
      }
      itemType = game.i18n.localize("TYPES.Item.talent");
      content = await foundry.applications.handlebars.renderTemplate(template, { selectableItems, itemType: itemType, itemCategory: "talent" });
    } else if (action === "characteristic") {
      const characteristic = $(event.currentTarget).data("buy-characteristic");
      await this._buyCharacteristicRank(characteristic);
      return;
    } else if (action === "skill") {
      await this._buySkillRank(event.target.parentElement.parentElement.parentElement);
      return;
    } else {
      CONFIG.logger.debug(`Refusing purchase action ${action} since it is not registered`);
      return;
    }

    DialogV2.wait({
      window: { title: game.i18n.format("SWFFG.Actors.Sheets.Purchase.DialogTitle", {itemType: itemType}) },
      classes: ["dialog", "starwarsffg"],
      content: content,
      buttons: [
        {
          action: "done",
          icon: "fa-regular fa-circle-up",
          label: game.i18n.localize("SWFFG.Actors.Sheets.Purchase.ConfirmPurchase"),
          default: true,
          callback: async (event, button, dialog) => {
              if(!this.actor.verifyEditModeIsNotEnabled()) return;

              const cost = $("#ffgPurchase option:selected", dialog.element).data("cost");
              const selected_id = $("#ffgPurchase option:selected", dialog.element).data("id");
              const selected_source = $("#ffgPurchase option:selected", dialog.element).data("source");
              if (cost > availableXP) {
                ui.notifications.warn(game.i18n.localize("SWFFG.Actors.Sheets.Purchase.NotEnoughXP"));
                return;
              }
              let purchasedItem = game.items.get(selected_id);
              if (!purchasedItem) {
                purchasedItem = await fromUuid(selected_source);
              }
              if (purchasedItem.type === "forcepower") {
                const currentForceRating = parseInt(this.actor.system.stats.forcePool.max);
                const requiredForceRating = parseInt(purchasedItem.system.required_force_rating);
                if (currentForceRating < requiredForceRating) {
                  ui.notifications.warn(game.i18n.format("SWFFG.Actors.Sheets.Purchase.FP.FRTooLow", {forceRating: currentForceRating, requiredForceRating: requiredForceRating}));
                  return;
                }
              }
              await this.object.createEmbeddedDocuments("Item", [purchasedItem]);
              const AEState = await ActorHelpers.beginEditMode(this.actor, true);
              const updatedAvailableXP = this.actor.system.experience.available;
              // this does not use _spendXp as it's granting items, which AEs cannot reasonably do
              await this.object.update({
                system: {
                  experience: {
                    available: updatedAvailableXP - cost,
                  },
                },
              });
              await xpLogSpend(game.actors.get(this.object.id), `new ${action} ${purchasedItem.name}`, cost, availableXP - cost, totalXP, undefined);
              await ActorHelpers.endEditMode(this.actor, AEState, true);
            },
          },
          {
            action: "cancel",
            icon: "fas fa-cancel",
            label: game.i18n.localize("SWFFG.Actors.Sheets.Purchase.CancelPurchase"),
          },
        ],
        rejectClose: false,
      });
  }

  async _buyCharacteristicRank(characteristic) {
    // this is the current value of the characteristic (including Active Effects)
    const characteristicValue = this.actor.system.characteristics[characteristic].value;
    // this is the value without items that modify it
    const characteristicWithoutAEs =  this.object.toObject().system.characteristics[characteristic].value;

    if (characteristicValue >= game.settings.get("starwarsffg", "maxAttribute")) {
      ui.notifications.warn(game.i18n.localize("SWFFG.Actors.Sheets.Purchase.Characteristic.Max"));
      return;
    }
    const availableXP = this.actor.system.experience.available;
    const totalXP = this.actor.system.experience.total;
    const cost = (characteristicValue + 1) * 10;
    if (cost > availableXP) {
      ui.notifications.warn(game.i18n.localize("SWFFG.Actors.Sheets.Purchase.NotEnoughXP"));
      return;
    }
    DialogV2.wait({
      window: { title: game.i18n.format("SWFFG.Actors.Sheets.Purchase.Characteristic.ConfirmTitle", {characteristic: characteristic}) },
      classes: ["dialog", "starwarsffg"],
      content: game.i18n.format("SWFFG.Actors.Sheets.Purchase.Characteristic.ConfirmText", {cost: cost, level: characteristicValue + 1, characteristic: characteristic}),
      buttons: [
        {
          action: "done",
          icon: "fa-regular fa-circle-up",
          label: game.i18n.localize("SWFFG.Actors.Sheets.Purchase.ConfirmPurchase"),
          default: true,
          callback: async () => {
            if(!this.actor.verifyEditModeIsNotEnabled()) return;

            const statusId = await this._spendXp(`system.characteristics.${characteristic}.value`, 1, cost);
            await xpLogSpend(game.actors.get(this.object.id), `characteristic ${characteristic} level ${characteristicValue} --> ${characteristicValue + 1}`, cost, availableXP - cost, totalXP, statusId);
            await this.render(true);
          },
        },
        {
          action: "cancel",
          icon: "fas fa-cancel",
          label: game.i18n.localize("SWFFG.Actors.Sheets.Purchase.CancelPurchase"),
        },
      ],
      rejectClose: false,
    });
  }

  /**
   * Handle clicking the kill minion button
   * @param event
   * @returns {Promise<void>}
   * @private
   */
  async _handleKillMinion(event) {
    event.stopPropagation();
    const target = $(event.currentTarget);
    if (target.hasClass("kill-minion")) {
      await killMinion(this.actor);
    } else if (target.hasClass("kill-group")) {
      await killMinionGroup(this.actor);
    }
  }

  async _xpAdjustment(event) {
    event.preventDefault();
    event.stopPropagation();

    const content = `
    <label for="adjustAmount">${game.i18n.localize("SWFFG.XP.Adjust.Window.Amount")}</label>
    <input type="number" id="adjustAmount" name="adjustAmount" value="0" />
    <label for="adjustReason">${game.i18n.localize("SWFFG.XP.Adjust.Window.Reason")}</label>
    <input type="text" id="adjustReason" name="adjustReason" value="${game.i18n.localize("SWFFG.XP.Adjust.Window.Default")}" />
    `;

    DialogV2.wait({
      window: { title: game.i18n.localize("SWFFG.XP.Adjust.Window.Title") },
      classes: ["dialog"],
      content: content,
      buttons: [
        {
          action: "one",
          icon: "fas fa-check",
          label: game.i18n.localize("SWFFG.XP.Adjust.Confirm"),
          default: true,
          callback: async (event, button, dialog) => {
            const availableXPToLog = foundry.utils.deepClone(parseInt(this.actor.system.experience.available));
            // Empty input -> parseInt("") -> NaN. Writing NaN to system.experience.available
            // / total corrupts the actor (every later XP read becomes NaN and propagates).
            // Default to 0 (effective no-op) so the dialog can never poison the XP fields.
            const rawAdjust = parseInt($(dialog.element).find("#adjustAmount").val());
            const adjustAmount = Number.isFinite(rawAdjust) ? rawAdjust : 0;
            const adjustReason = foundry.utils.deepClone($(dialog.element).find("#adjustReason").val());
            const AEState = await ActorHelpers.beginEditMode(this.actor, true);
            // beginEditMode persisted disabled=true on every AE on the actor;
            // endEditMode MUST run even if the update or log step throws, otherwise
            // the actor is left with all AEs disabled (characteristics fall to 0).
            try {
              const startingAvailableXP =  foundry.utils.deepClone(parseInt(this.actor.system.experience.available));
              const totalXP =  foundry.utils.deepClone(parseInt(this.actor.system.experience.total));
              const updatedAvailableXP = startingAvailableXP + adjustAmount;
              const updatedTotalXP = totalXP + adjustAmount;
              await this.actor.update({ 'system.experience.available': updatedAvailableXP, 'system.experience.total': updatedTotalXP });
              await xpLogEarn(
                this.object,
                adjustAmount,
                availableXPToLog + adjustAmount,
                updatedTotalXP,
                adjustReason,
                "Self"
              );
            } finally {
              await ActorHelpers.endEditMode(this.actor, AEState, true);
            }
          },
        },
        {
          action: "two",
          icon: "fas fa-times",
          label: "Cancel",
        },
      ],
      rejectClose: false,
    });
  }

  async _xpExport(event) {
    event.preventDefault();
    event.stopPropagation();
    const existingLog = this.actor.getFlag("starwarsffg", "xpLog");
    const downloadLog = [];
    for (const entry of existingLog) {
      if (Object.keys(entry).includes("id")) {
        delete entry.id;
      }
      downloadLog.push(entry);
    }
    const blob = new Blob([JSON.stringify(downloadLog)], {type: "text/plain"});
    const blobUrl = URL.createObjectURL(blob);
    const link = document.createElement("a");
    link.href = blobUrl;
    link.download = `${this.actor.name}-xpLog.txt`;
    link.click();
    URL.revokeObjectURL(blobUrl);
  }

  async _xpImport(event) {
    event.preventDefault();
    event.stopPropagation();

    const content = `
    <label for="adjustAmount">${game.i18n.localize("SWFFG.XP.Import.Title")}</label>
    <div>
      <input type="file" name="xpLogFile" id="xpLogFile" accept=".txt" />
    </div>
    `;

    DialogV2.wait({
      window: { title: game.i18n.localize("SWFFG.XP.Import.Title") },
      classes: ["dialog"],
      content: content,
      buttons: [
        {
          action: "one",
          icon: "fas fa-check",
          label: game.i18n.localize("SWFFG.XP.Import.Title"),
          default: true,
          callback: async (event, button, dialog) => {
            const fileElement = $(dialog.element).find("#xpLogFile");
            const file = fileElement[0].files?.[0];
            const reader = new FileReader();
            reader.readAsText(file, 'UTF-8');
            reader.onload = async ({ target }) => {
              const parsedLog = JSON.parse(target.result);
              CONFIG.logger.debug(`Loading processed XP log: ${JSON.stringify(parsedLog)}`);
              await this.actor.setFlag("starwarsffg", "xpLog", parsedLog);
            }
            reader.onerror = function() {
              ui.notifications.error("Failed to load file contents");
            }
          },
        },
        {
          action: "two",
          icon: "fas fa-times",
          label: "Cancel",
        },
      ],
      rejectClose: false,
    });
  }

  debounceRender = foundry.utils.debounce(
    (force, options) => {
      // A close() that lands after a render was queued must win. Renders here
      // are debounced (~100ms), so a trailing render scheduled by a field edit
      // -- minion sheets force render:true on wounds/quantity edits -- fires
      // after close() finished and reset its transient `_closing` flag, and
      // would re-attach the sheet the user just closed (the "minion close
      // button does nothing" bug). `_sheetClosed` is latched in close() and
      // only cleared by a genuine (non-closing) render(), so a stray trailing
      // render bails here.
      if (this._sheetClosed) return;
      super.render(force, options);
    },
    100,
    {
      leading: true,
      maxWait: 100,
    },
  );

  /** @override **/
  render(force, options) {
    // A real (re)open clears the closed latch. Auto-renders fired *during*
    // close (document.update in submit-on-close) run while `_closing` is true
    // and must NOT clear it, or they would reschedule a reopen.
    if (!this._closing) this._sheetClosed = false;
    this.debounceRender(force, options);
  }

  /** @override **/
  async close(options = {}) {
    // Latch closed so any debounced render still in flight (or one scheduled by
    // a close-time auto-render) cannot reopen the sheet. Cleared by the next
    // genuine render() above.
    this._sheetClosed = true;
    return super.close(options);
  }

  /** @override **/
  async _onSubmit(event, options = {}) {
    const formValid = event?.target?.form?.reportValidity();
    if (formValid === false) {
      return;
    }
    return await super._onSubmit(event, options);
  }

}

/**
 * Sort an array of dicts by a key. Totally not AI generated. But it works :)
 * @param data
 * @param byKey
 * @returns {*}
 */
export function sortDataBy(data, byKey) {
 return data.sort((a, b) => {
    if (a[byKey] < b[byKey]) {
      return -1;
    }
    if (a[byKey] > b[byKey]) {
      return 1;
    }
    return 0;
 });
}

/**
 * Add an element to an array only if it isn't already present in that array
 * @param array
 * @param element
 * @returns {*}
 */
export function addIfNotExist(array, element) {
  let index = array.indexOf(element);
  // Check if the object with the specified property value exists in the array
  if (index === -1) {
    // If not found, push a new object with the desired properties
    array.push(element);
  }
  return array;
}

import { ActorSheetFFG } from "./actor-sheet-ffg.js";
import ActorOptions from "./actor-ffg-options.js";

export class AdversarySheetFFG extends ActorSheetFFG {
  constructor(...args) {
    super(...args);
  }

  /** @override */
  get template() {
    const path = "systems/starwarsffg/templates/actors";
    return `${path}/ffg-adversary-sheet.html`;
  }

  // Only the adversary-specific delta from ActorSheetFFG. `position`, `tabs`,
  // and `scrollY` are inherited and intentionally NOT re-declared: DEFAULT_OPTIONS
  // arrays concatenate across the inheritance chain, so re-declaring `tabs` would
  // bind two Tabs instances. The per-type template comes from get template().
  static DEFAULT_OPTIONS = {
    classes: ["starwarsffg", "sheet", "actor", "adversary", "v2"],
  };

  /**
   * @override
   * NOTE: `getData` MUST be async and MUST await `super.getData()` — the parent
   * `ActorSheetFFG.getData` is async (returns a Promise). Previously this method
   * was sync and did `const data = super.getData()` (no await), so `data` was a
   * Promise: the un-awaited `_updateSpecialization(data)` rejected with
   * "Cannot read properties of undefined (reading 'slice')" (data.talentList),
   * and the `data.limited` / `data.items` tweaks were written onto the Promise
   * wrapper and silently lost.
   */
  async getData() {
    const data = await super.getData();
    // FIRST RENDER ONLY — same reason as the base sheet's sizing block (see
    // actor-sheet-ffg.js): re-applying every render snaps a resized sheet back to
    // default (#14). This carries its OWN latch rather than reusing the base's:
    // `await super.getData()` above has already consumed that one, and this block
    // runs afterwards, so without a latch here it would overwrite the values the
    // base just guarded and the fix would do nothing on adversary sheets.
    const setInitialSize = !this._advSizeInitialized;
    this._advSizeInitialized = true;
    switch (this.actor.type) {
      case "character":
        if (setInitialSize) {
          this.position.width = 595;
          this.position.height = 783;
          if (data.limited) {
            this.position.height = 165;
          }
        }

        // we need to update all specialization talents with the latest talent information
        if (!this.actor.flags.starwarsffg?.loaded) {
          await super._updateSpecialization(data);
        }

        break;
      default:
    }

    data.items = this.actor.items.map((item) => item);

    return data;
  }

  /** @override */
  activateListeners(html, context, options) {
    const skillPools = super.activateListeners(html, context, options);

    if (!this.options.editable) return skillPools;

    if (this.actor.type === "character") {
      this.sheetoptions.clear();
      this.sheetoptions.register("enableAutoSoakCalculation", {
        name: game.i18n.localize("SWFFG.EnableSoakCalc"),
        hint: game.i18n.localize("SWFFG.EnableSoakCalcHint"),
        type: "Boolean",
        default: true,
      });
      this.sheetoptions.register("enableForcePool", {
        name: game.i18n.localize("SWFFG.EnableForcePool"),
        hint: game.i18n.localize("SWFFG.EnableForcePoolHint"),
        type: "Boolean",
        default: true,
      });
      this.sheetoptions.register("enableStrainThreshold", {
        name: game.i18n.localize("SWFFG.EnableStrainThreshold"),
        hint: game.i18n.localize("SWFFG.EnableStrainThresholdHint"),
        type: "Boolean",
        default: true,
      });
      this.sheetoptions.register("talentSorting", {
        name: game.i18n.localize("SWFFG.EnableSortTalentsByActivation"),
        hint: game.i18n.localize("SWFFG.EnableSortTalentsByActivationHint"),
        type: "Array",
        default: 0,
        options: [game.i18n.localize("SWFFG.UseGlobalSetting"), game.i18n.localize("SWFFG.OptionValueYes"), game.i18n.localize("SWFFG.OptionValueNo")],
      });
    }
    return skillPools;
  }
}

/**
 * CODEX II — collapsible "pill stack" interaction (reusable).
 *
 * A pill stack (specializations, force powers, signature abilities, …) shows its
 * members as a vertical stack of notched pills (styling lives in cdx.css under
 * `.cdx-stack`). This class owns the INTERACTION:
 *
 *   single pill (not collapsible) + click pill → onActivate(id): open its tree
 *   single pill + click `.item-delete`         → onDelete(id)
 *   collapsed + click anywhere on the stack    → expand it
 *   expanded  + click a pill                   → onActivate(id): open its tree
 *                                                (the stack STAYS open)
 *   expanded  + click a pill's `.item-delete`  → onDelete(id), then collapse
 *   expanded  + click elsewhere on the sheet    → collapse
 *
 * Scope — the single capture listener lives on the sheet ROOT, not the document.
 * That has two important consequences:
 *  - Every click it handles is consumed (preventDefault + stopPropagation) in the
 *    capture phase, so it never leaks to the stock `.item` / `.item-delete`
 *    handlers the pills also carry, nor to the sheet content an open stack
 *    overlaps.
 *  - It never sees clicks in OTHER windows (e.g. the tree we just opened) or on
 *    the canvas, so those cannot collapse the stack. The collapse-on-click-
 *    elsewhere therefore only fires while the user is interacting with this
 *    sheet — opening and browsing a tree leaves the stack open.
 *
 * The listener is bound per render and dies with its root; {@link #destroy} (on
 * re-render and close) detaches it belt-and-suspenders.
 *
 * The class is document-agnostic — it resolves a pill via `data-item-id` and
 * hands the id to the caller's `onActivate` / `onDelete` — so the same widget
 * drives specs, force powers, signature abilities: anything rendered as a
 * `.cdx-stack` of `.cdx-pill[data-item-id]` (the `.cdx-collapsible` modifier is
 * added only when there are 2+ pills to stack).
 */
export class CdxPillStack {
  /**
   * @param {HTMLElement} root  the sheet root scanned for `.cdx-stack.cdx-collapsible`
   * @param {object} [opts]
   * @param {(id: string) => void} [opts.onActivate]  open a pill item's window
   * @param {(id: string) => void} [opts.onDelete]    remove a pill item
   */
  constructor(root, { onActivate, onDelete } = {}) {
    this.root = root;
    this.onActivate = onActivate;
    this.onDelete = onDelete;
    this._onClick = this._onClick.bind(this);
    this._onMouseDown = this._onMouseDown.bind(this);

    // All pill stacks, collapsible (2+ pills) or not (a single pill renders as a
    // plain `.cdx-stack` with no `.cdx-collapsible`). We manage both so a lone
    // pill opens its tree directly instead of pointlessly toggling an empty
    // expand/collapse on a stack with nothing to reveal.
    this._stacks = root ? [...root.querySelectorAll(".cdx-stack")] : [];
    // One capture listener on the sheet root. Capture so it runs before the
    // pills' own bubble-phase handlers; rooted on the sheet so clicks in other
    // windows never reach it (and so can't collapse us).
    if (root) {
      root.addEventListener("click", this._onClick, true);
      // Selectable text swallows the `click` event when a press creates a text
      // selection — and `<input>` fields (a characteristic's number, …) stay
      // user-selectable even though Foundry sets `user-select:none` on the rest
      // of the sheet. A click on such a field would never reach _onClick to
      // collapse the stack, so suppress that selection at mousedown while a
      // stack is open and the click then reliably fires.
      root.addEventListener("mousedown", this._onMouseDown, true);
    }
  }

  /** Detach the listeners. Safe to call repeatedly. */
  destroy() {
    if (this.root) {
      this.root.removeEventListener("click", this._onClick, true);
      this.root.removeEventListener("mousedown", this._onMouseDown, true);
    }
    this._stacks = [];
  }

  /** The currently-open stack, if any. */
  _openStack() {
    return this._stacks.find((s) => s.classList.contains("open")) ?? null;
  }

  _consume(ev) {
    ev.preventDefault();
    ev.stopPropagation();
  }

  /**
   * While a stack is open (or when pressing on a collapsed stack), suppress the
   * browser's text-selection so the `click` that follows is actually delivered —
   * a press that selects text otherwise swallows the click, which is why a click
   * on a selectable `<input>` (a characteristic's number, …) would fail to
   * collapse the stack. We ONLY preventDefault here; propagation is left intact
   * so the click still reaches _onClick, which does the real work + consuming.
   * Primary button only, so right/middle-click (context menu) is untouched.
   */
  _onMouseDown(ev) {
    if (ev.button !== 0) return;
    if (this._openStack() || ev.target.closest?.(".cdx-stack")) {
      ev.preventDefault();
    }
  }

  _onClick(ev) {
    const open = this._openStack();
    if (open) {
      // A stack is open: this click is ours to handle and swallow.
      this._consume(ev);
      const pill = open.contains(ev.target) ? ev.target.closest(".cdx-pill") : null;
      const id = pill?.dataset.itemId;
      if (id && ev.target.closest(".item-delete")) {
        this.onDelete?.(id); // delete → fall through and collapse
      } else if (id) {
        this.onActivate?.(id); // open the tree and LEAVE the stack open
        return;
      }
      open.classList.remove("open"); // delete, or a click elsewhere on the sheet
      return;
    }
    // Nothing open: the click landed on one of our stacks.
    const stack = ev.target.closest?.(".cdx-stack");
    if (stack && this._stacks.includes(stack)) {
      this._consume(ev);
      // A single-pill stack is NOT collapsible (no `.cdx-collapsible`) — there is
      // nothing to expand, so route the click straight to that lone pill: its
      // delete-X removes it, anything else opens its tree (as if it had been
      // clicked while expanded).
      const pills = stack.querySelectorAll(".cdx-pill");
      if (pills.length === 1) {
        const id = pills[0].dataset.itemId;
        if (id && ev.target.closest(".item-delete")) this.onDelete?.(id);
        else if (id) this.onActivate?.(id);
        return;
      }
      // Multi-pill: only collapsible stacks expand (single/empty never do).
      if (stack.classList.contains("cdx-collapsible")) stack.classList.add("open");
    }
  }
}

/**
 * Fated Sigils — Eldritch Horror.
 *
 * Deterministic, per-actor header ornaments generated at runtime on an offscreen
 * canvas and cached as PNG data-URLs, used as the ALPHA masks for the two
 * Eldritch sheet headers. Both styles are built here:
 *
 *  - "deco" (Fate) — a crisp 512 sigil tile laid 2×2 into the mask canvas, then
 *    multiplied by a WEAR layer to erode it into a wall of worn sigils.
 *  - "medallion" (Scholar) — one bespoke sigil drawn to fill the canvas. Drawn
 *    CLEAN: its call site pins wearSource:"none", so no wear is multiplied in.
 *
 * The wear layer is selectable (see wearSource): "grunge" (default) remaps a
 * seamless scanned texture, "procedural" builds the original layered value noise
 * → soft threshold → empty patches → scratches → grain, each layer drawing from
 * its own salted PRNG so they vary independently but stay stable for a given seed
 * (so an actor sees the same sigil every time). The deco path is ported from the
 * crea "foundry_fated_sigils" handoff.
 *
 * The output encodes visibility in the ALPHA channel (RGB = white), so it works
 * as a CSS alpha mask (mask-mode:alpha / -webkit-mask-image) over a coloured fill.
 */

/* ---- deterministic PRNG (xmur3 seed → mulberry32 stream) ------------------- */
function xmur3(str) {
  let h = 1779033703 ^ str.length;
  for (let i = 0; i < str.length; i++) {
    h = Math.imul(h ^ str.charCodeAt(i), 3432918353);
    h = (h << 13) | (h >>> 19);
  }
  return function () {
    h = Math.imul(h ^ (h >>> 16), 2246822507);
    h = Math.imul(h ^ (h >>> 13), 3266489909);
    return (h ^= h >>> 16) >>> 0;
  };
}
function mulberry32(a) {
  return function () {
    let t = (a += 0x6d2b79f5);
    t = Math.imul(t ^ (t >>> 15), t | 1);
    t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}
function rngFromSeed(source, salt = "") {
  return mulberry32(xmur3(`${source}::${salt}`)());
}

/**
 * Art-direction defaults. Tune to taste — see wearSource for which knobs reach
 * which style; the wear knobs are Fate-only, as Scholar's medallion opts out.
 *
 * The procedural (cloud/patch/scratch/grain) knobs carry the handoff's history:
 * its "extreme" patch tuning (264 large ellipses) covered the whole tile and
 * zeroed everything, so that path instead starts mostly-visible and carves holes
 * with a cloud ramp + a handful of empty patches. They are inert unless
 * wearSource is "procedural".
 */
export const CDX_FATED_DEFAULTS = {
  style: "deco",          // "deco" = ported mystic_patterns wall; "medallion" = bespoke sigil
  sigilSize: 512,
  maskSize: 1024,
  // Scholar medallion only ("medallion" style): scales its stroke weight. 1 =
  // ~1.3px on the 512 canvas it's drawn at. The tile is then shown at
  // --cdx-scholar-size (~260px), i.e. ~half its drawn size, so a stroke lands at
  // roughly half this on screen — hence a default above 1, which keeps the
  // linework from thinning below a whole pixel and washing out.
  medallionLineScale: 1.5,
  // Wear source. "grunge" masks the sigil with the seamless photo-grunge scan
  // (grunge-wear-seamless.webp); "procedural" builds the layered-noise fog +
  // patches + scratches + grain below instead (the pre-grunge look, kept for
  // A/B); "none" emits the sigil clean. This default only reaches the Fate wall
  // — the Scholar medallion pins "none" at its call site (see _cdxFatedSigil),
  // so every knob from here down is Fate-only art direction.
  wearSource: "grunge",
  // Blotch scale: px each copy of the scan occupies inside the maskSize canvas, so
  // it scales independently of the deco wall (which sigilSize drives). Rounded to
  // a whole number of copies to keep the mask tileable — see grungeWearFloat.
  //   1024 = 1×1, biggest blotches (the deco tile is 512, i.e. 2×2, so the fog
  //          reads at 2× the wall's scale) · 512 = 2×2, matches the wall · 256 = 4×4.
  // For blotches BIGGER than 1×1, shrink the wall instead (sigilSize 256) and take
  // --cdx-fated-tile up to compensate; the mask canvas can't zoom past its own tile.
  grungeSize: 1024,
  // Levels remap of the scan, applied BEFORE the floor. The raw scan only bottoms
  // out (<0.02) on 0.7% of its area, so a plain multiply just dims the wall
  // evenly instead of carving it — the remap is what turns the blotches into real
  // holes, standing in for the procedural patches' `v -= patch[i]` subtraction.
  // Widen the gap for a softer fog; raise both to erode harder.
  grungeLow: 0.65,         // scan luma at/below this → fully eroded (41% of the tile; 0.5 → 22%, 0.2 → 4%)
  grungeHigh: 0.85,        // scan luma at/above this → fully intact (the narrow 0.2 gap = crisp hole edges)
  grungeFloor: 0.0,       // lift applied AFTER the remap; >0 keeps the wall faintly readable in the holes
  // cloud ramp: noise below cloudLow → visFloor, above cloudHigh → fully visible.
  // visFloor raised to 0.5 makes the cloud ~1.5x less impactful (swing 0.75→0.5).
  cloudLow: 0.34,
  cloudHigh: 0.72,
  visFloor: 0.5,
  // empty patches (missing regions carved out of the wall)
  patchCount: 17,          // 1.5x fewer than the previous 26
  patchScale: 1.25,
  // gouge scratches
  scratchCount: 34,
  scratchWidthMin: 3.0,
  scratchWidthMax: 6.0,
  minVisibility: 0.0,
};

function makeCanvas(w, h) {
  const c = document.createElement("canvas");
  c.width = w; c.height = h;
  return c;
}

/** A blurred value-noise field (Float32Array, 0..255): a small random grid
 *  upscaled with bilinear smoothing, then Gaussian-blurred via the 2D filter. */
function noiseFloat(rng, size, cells, blur) {
  const small = makeCanvas(cells, cells);
  const sc = small.getContext("2d");
  const id = sc.createImageData(cells, cells);
  for (let i = 0; i < cells * cells; i++) {
    const v = (rng() * 255) | 0;
    id.data[i * 4] = v; id.data[i * 4 + 1] = v; id.data[i * 4 + 2] = v; id.data[i * 4 + 3] = 255;
  }
  sc.putImageData(id, 0, 0);

  const big = makeCanvas(size, size);
  const bc = big.getContext("2d");
  bc.imageSmoothingEnabled = true;
  bc.imageSmoothingQuality = "high";
  // Blur is a px amount tuned for 1024; scale it so smaller maskSize keeps the look.
  if (blur > 0) bc.filter = `blur(${blur * size / 1024}px)`;
  bc.drawImage(small, 0, 0, cells, cells, 0, 0, size, size);
  bc.filter = "none";

  const d = bc.getImageData(0, 0, size, size).data;
  const out = new Float32Array(size * size);
  for (let i = 0; i < out.length; i++) out[i] = d[i * 4];
  return out;
}

/** White ellipse "empty patches" on black, blurred; returns strength 0..1. */
function patchesFloat(rng, size, D) {
  const s = size / 1024;              // px params are tuned for 1024; scale with size
  const c = makeCanvas(size, size);
  const x = c.getContext("2d");
  x.fillStyle = "#000"; x.fillRect(0, 0, size, size);
  x.fillStyle = "#fff";
  const count = Math.round(D.patchCount);
  const rmul = D.patchScale * s;
  for (let i = 0; i < count; i++) {
    const cx = rng() * size, cy = rng() * size;
    const rx = (35 + rng() * 115) * rmul, ry = (22 + rng() * 88) * rmul;
    x.beginPath();
    x.ellipse(cx, cy, rx, ry, rng() * Math.PI, 0, Math.PI * 2);
    x.fill();
  }
  const b = makeCanvas(size, size);
  const bc = b.getContext("2d");
  bc.filter = `blur(${30 * s}px)`;
  bc.drawImage(c, 0, 0);
  bc.filter = "none";
  const d = bc.getImageData(0, 0, size, size).data;
  const out = new Float32Array(size * size);
  for (let i = 0; i < out.length; i++) out[i] = d[i * 4] / 255;
  return out;
}

/** White gouge "scratches" on black, softly blurred; returns strength 0..1. */
function scratchesFloat(rng, size, D) {
  const s = size / 1024;              // px params are tuned for 1024; scale with size
  const c = makeCanvas(size, size);
  const x = c.getContext("2d");
  x.fillStyle = "#000"; x.fillRect(0, 0, size, size);
  x.strokeStyle = "#fff"; x.lineCap = "round";
  const count = Math.round(D.scratchCount);
  for (let i = 0; i < count; i++) {
    const x0 = rng() * size, y0 = rng() * size;
    const ang = rng() * Math.PI * 2;
    const len = (70 + rng() * 190) * s;
    const drift = (rng() * 2 - 1) * 28 * s;
    const x1 = x0 + Math.cos(ang) * len + Math.cos(ang + Math.PI / 2) * drift;
    const y1 = y0 + Math.sin(ang) * len + Math.sin(ang + Math.PI / 2) * drift;
    x.lineWidth = (D.scratchWidthMin + rng() * (D.scratchWidthMax - D.scratchWidthMin)) * s;
    x.globalAlpha = Math.min(1, (30 + rng() * 80) / 255);
    x.beginPath(); x.moveTo(x0, y0); x.lineTo(x1, y1); x.stroke();
  }
  x.globalAlpha = 1;
  const b = makeCanvas(size, size);
  const bc = b.getContext("2d");
  bc.filter = `blur(${1.2 * s}px)`;
  bc.drawImage(c, 0, 0);
  bc.filter = "none";
  const d = bc.getImageData(0, 0, size, size).data;
  const out = new Float32Array(size * size);
  for (let i = 0; i < out.length; i++) out[i] = d[i * 4] / 255;
  return out;
}

/** Sparse fine grain (128-cell noise, thresholded); returns 0/1 per pixel. */
function grainFloat(rng, size) {
  const n = noiseFloat(rng, size, 128, 0.4);
  const out = new Float32Array(size * size);
  for (let i = 0; i < out.length; i++) out[i] = n[i] > 238 ? 1 : 0;
  return out;
}

/* ---- grunge wear (the default wear source) ---------------------------------
   A seamless scanned-grunge tile used in place of the procedural fog: light
   paper = intact, dark blotches = eroded, so it drops straight into the same
   0..1 visibility contract makeWear() returns. Made seamless via a
   periodic+smooth decomposition, so it survives the CSS `mask-repeat:repeat` on
   the header.
   512 and LOSSLESS on purpose: the levels remap below divides by the
   grungeHigh−grungeLow span, so it amplifies any codec error by ~5x at the
   default tuning — right on the hole edges. 512 still supersamples the ~340px
   on-screen tile, and grungeSize scales the draw independently of the file. */
const GRUNGE_URL = "/systems/starwarsffg/images/codex/eldritch/grunge-wear-seamless.webp";
let _grungeImg = null;
const _grungeWear = new Map();          // size → Float32Array (0..1)

function loadGrungeImage() {
  if (!_grungeImg) {
    _grungeImg = new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = () => reject(new Error(`Codex | grunge wear failed to load: ${GRUNGE_URL}`));
      img.src = GRUNGE_URL;
    });
  }
  return _grungeImg;
}

/** Grunge visibility (Float 0..1, 1 = intact), resampled to `size` and cached.
 *  The scan is laid n×n into the mask canvas (@see makeSigilVis) so its blotch
 *  scale is independent of the deco wall's. n is forced to a whole number: the
 *  mask canvas itself becomes the CSS `mask-repeat:repeat` tile, so anything but a
 *  whole number of copies would land a partial tile against its own edge and
 *  reintroduce the seam we removed from the scan. */
async function grungeWearFloat(size, D) {
  const key = `${size}::${D.grungeSize}::${D.grungeLow}::${D.grungeHigh}::${D.grungeFloor}`;
  let out = _grungeWear.get(key);
  if (out) return out;

  const img = await loadGrungeImage();
  const c = makeCanvas(size, size);
  const x = c.getContext("2d");
  x.imageSmoothingEnabled = true;
  x.imageSmoothingQuality = "high";
  const n = Math.max(1, Math.round(size / (D.grungeSize || size)));
  const step = size / n;
  for (let i = 0; i < n; i++) for (let j = 0; j < n; j++) {
    x.drawImage(img, 0, 0, img.width, img.height, i * step, j * step, step, step);
  }

  const lum = lumaFloat(c, size);
  out = new Float32Array(size * size);
  const floor = D.grungeFloor;
  const span = (D.grungeHigh - D.grungeLow) || 1;
  for (let i = 0; i < out.length; i++) {
    let v = (lum[i] - D.grungeLow) / span;
    v = v < 0 ? 0 : v > 1 ? 1 : v;
    out[i] = floor + (1 - floor) * v;
  }
  _grungeWear.set(key, out);
  return out;
}

/** Fog/wear visibility (Float 0..1, 1 = intact). */
function makeWear(size, D, rFog, rPat, rScr, rGrn) {
  const broad = noiseFloat(rFog, size, 5, 38);
  const mid = noiseFloat(rFog, size, 11, 18);
  const fine = noiseFloat(rFog, size, 31, 4);
  const patch = patchesFloat(rPat, size, D);
  const scr = scratchesFloat(rScr, size, D);
  const grn = grainFloat(rGrn, size);

  const vis = new Float32Array(size * size);
  const cl = D.cloudHigh - D.cloudLow || 1;
  for (let i = 0; i < vis.length; i++) {
    // layered noise: lerp(broad, mid, .42) then lerp(result, fine, .14)
    let f = broad[i] * 0.58 + mid[i] * 0.42;
    f = f * 0.86 + fine[i] * 0.14;
    // cloud ramp → mostly visible, dimming toward visFloor in the dark clouds
    let c = (f / 255 - D.cloudLow) / cl;
    c = c < 0 ? 0 : c > 1 ? 1 : c;
    let v = D.visFloor + (1 - D.visFloor) * c;
    // carve wear out of it
    v -= patch[i];
    v -= scr[i] * 0.85;
    v -= grn[i] * 0.4;
    if (v < D.minVisibility) v = D.minVisibility;
    if (v < 0) v = 0; else if (v > 1) v = 1;
    vis[i] = v;
  }
  return vis;
}

/* ===========================================================================
   Style "medallion" — the original bespoke generator: a single centred sigil
   (rings / polygons / orbital ellipses / spokes / stars). Kept as an alternative
   to the ported deco wall below; selected via opts.style = "medallion".
   ========================================================================== */
/** One crisp geometric sigil (white linework on black), seeded for variety.
 *  Every element below inherits this single lineWidth — none override it — so
 *  medallionLineScale is the one control for the whole medallion's weight. */
function makeSigilTile(rng, size, D) {
  const c = makeCanvas(size, size);
  const x = c.getContext("2d");
  x.fillStyle = "#000"; x.fillRect(0, 0, size, size);
  x.translate(size / 2, size / 2);
  x.strokeStyle = "#fff"; x.fillStyle = "#fff";
  x.lineCap = "round"; x.lineJoin = "round";
  x.lineWidth = D.medallionLineScale * Math.max(1.1, size * 0.0026);
  const R = size * 0.42;

  // concentric rings, some dashed
  const rings = 3 + ((rng() * 3) | 0);
  for (let i = 0; i < rings; i++) {
    const r = R * (0.22 + 0.76 * (rings < 2 ? 1 : i / (rings - 1)));
    x.beginPath(); x.arc(0, 0, r, 0, Math.PI * 2);
    if (rng() < 0.55) x.setLineDash([1 + rng() * 3, 4 + rng() * 8]); else x.setLineDash([]);
    x.stroke();
  }
  x.setLineDash([]);

  // two nested polygons
  const sides = 3 + ((rng() * 5) | 0);
  const rot = rng() * Math.PI * 2;
  for (const rr of [R * 0.72, R * 0.44]) {
    x.beginPath();
    for (let k = 0; k < sides; k++) {
      const a = rot + (k / sides) * Math.PI * 2;
      const px = Math.cos(a) * rr, py = Math.sin(a) * rr;
      k ? x.lineTo(px, py) : x.moveTo(px, py);
    }
    x.closePath(); x.stroke();
  }

  // orbital ellipses
  const orb = 2 + ((rng() * 3) | 0);
  for (let i = 0; i < orb; i++) {
    x.save(); x.rotate(rng() * Math.PI);
    x.beginPath(); x.ellipse(0, 0, R * 0.82, R * (0.2 + rng() * 0.28), 0, 0, Math.PI * 2); x.stroke();
    x.restore();
  }

  // radial spokes + diamond marks
  const spokes = [6, 8, 12][(rng() * 3) | 0];
  const s = size * 0.012;
  for (let i = 0; i < spokes; i++) {
    x.save(); x.rotate((i / spokes) * Math.PI * 2);
    x.beginPath(); x.moveTo(0, -R * 0.98); x.lineTo(0, -R * 0.86); x.stroke();
    const dy = -R * 0.9;
    x.beginPath(); x.moveTo(0, dy - s); x.lineTo(s, dy); x.lineTo(0, dy + s); x.lineTo(-s, dy); x.closePath(); x.stroke();
    x.restore();
  }

  // core
  x.beginPath(); x.arc(0, 0, R * 0.07, 0, Math.PI * 2); x.stroke();
  x.beginPath(); x.arc(0, 0, R * 0.025, 0, Math.PI * 2); x.fill();

  // scattered small stars
  const stars = 3 + ((rng() * 4) | 0);
  for (let i = 0; i < stars; i++) {
    const a = rng() * Math.PI * 2, rr = R * (0.5 + rng() * 0.5);
    const sx = Math.cos(a) * rr, sy = Math.sin(a) * rr, ss = size * 0.01 * (0.7 + rng());
    x.beginPath(); x.moveTo(sx - ss, sy); x.lineTo(sx + ss, sy); x.moveTo(sx, sy - ss); x.lineTo(sx, sy + ss); x.stroke();
    x.beginPath(); x.arc(sx, sy, ss * 0.4, 0, Math.PI * 2); x.stroke();
  }
  return c;
}

/* ===========================================================================
   Style "deco" (default) — a faithful JS port of mystic_patterns.py's
   dense_deco_pattern(): a dense, SEAMLESS full-tile occult Art-Deco wall
