    dLine(d, [[cx + sg * r, cy + r * 0.8], [cx + sg * r * 0.62, cy + r * 0.8], [cx + sg * r * 0.62, cy + r * 0.45], [cx + sg * r * 0.25, cy + r * 0.45]], DW, 2);
