    dWrapped((dx, dy) => dDiamond(d, cx + dx, cy + dy, 78 - (mode % 3) * 8, DS, 1));
    dWrapped((dx, dy) => dMedallion(d, cx + dx, cy + dy, seed + cx + cy + mode, 0.9));
