const CDX_MARBLE_SEL = [
  ".cdx-stat", ".cdx-panel", ".cdx-card", ".cdx-injury", ".cdx-forcepool",
  ".cdx-talent", ".cdx-pane.effects", ".cdx-pane.attributes", ".cdx-sub",
  ".cdx-istat", ".cdx-idesc", ".cdx-icheck2", ".cdx-item-body .item.force-power",
  ".cdx-ft-card", ".cdx-sk-row",
].join(",");

const CDX_NOTCH = 9;   // notch size in px — must match --cdx-notch in the CSS

/**
 * Redraw one block's SVG notch outline at a KNOWN border-box size (px). The
 * <path> traces the SAME octagon as the block's clip-path fill (fixed CDX_NOTCH
 * corner, inset slightly so the stroke sits inside the clip), so fill and outline
 * stay aligned at any size — including short pills (~18–20px), which must still
 * get their diagonals. The notch is clamped to half the smaller side only so the
 * path can't self-cross on a pathologically tiny block (real blocks are ≥18px, so
 * this never fires and the outline matches the fixed-9px clip exactly). Callers
 * pass w/h from the ResizeObserver entry so this never reads the DOM; if omitted
 * it measures (forces a layout — the slow path, kept only as a fallback).
 */
export function cdxDrawNotch(el, w, h) {
  const svg = el.querySelector(":scope > svg.cdx-notch");
  if (!svg) return;
  if (w == null || h == null) {             // fallback: measure (border box) — forces layout
    const r = el.getBoundingClientRect();
    w = r.width; h = r.height;
  }
  if (w < 2 || h < 2) return;               // hidden / unlaid-out — observer redraws later
  const i = 0.75;                           // i: inset so the stroke stays inside the clip
  const n = Math.min(CDX_NOTCH, w / 2, h / 2);
  const d =
    `M${i},${n} L${n},${i} L${w - n},${i} L${w - i},${n}` +
    ` L${w - i},${h - n} L${w - n},${h - i} L${n},${h - i} L${i},${h - n} Z`;
  svg.setAttribute("viewBox", `0 0 ${w} ${h}`);
  svg.firstChild.setAttribute("d", d);
}

/**
 * Give every notched block (CDX_NOTCH_SEL) inside `root` an <svg.cdx-notch>
 * overlay whose stroked <path> outlines the same octagon as its clip-path fill,
 * so the two can never drift. The path is built from the block's live px size, so
 * notches stay a fixed 9px and the stroke a uniform 1px at any size / DPR. A
 * single ResizeObserver (stored on `host`, rebuilt each call, torn down in the
 * sheet's close) redraws blocks on resize — tab switch, window resize, header
 * collapse, talent expand.
 *
 * Perf: the observer reads the size straight off each entry (borderBoxSize), so
 * it never calls getBoundingClientRect, and its initial per-element fire does the
 * FIRST draw — so the build loop only creates nodes. No forced layout on either
 * path (avoids read-after-write layout thrashing across N blocks).
 */
export function cdxBuildNotchOutlines(host, root) {
  if (!root) return;
  host._cdxNotchRO?.disconnect();
  host._cdxNotchRO = new ResizeObserver((entries) => {
    for (const e of entries) {
      const box = e.borderBoxSize && e.borderBoxSize[0];
      if (box) cdxDrawNotch(e.target, box.inlineSize, box.blockSize);
      else cdxDrawNotch(e.target);          // legacy fallback: measures
    }
  });
  for (const el of root.querySelectorAll(CDX_NOTCH_SEL)) {
    if (!el.querySelector(":scope > svg.cdx-notch")) {
      const NS = "http://www.w3.org/2000/svg";
      const svg = document.createElementNS(NS, "svg");
      svg.setAttribute("class", "cdx-notch");
      svg.setAttribute("aria-hidden", "true");
      svg.setAttribute("preserveAspectRatio", "none");
      svg.appendChild(document.createElementNS(NS, "path"));
      // Append (not prepend): an absolutely-positioned last child keeps the
      // block's `:first-child` rules intact (e.g. .cdx-vr-k:not(:first-child)),
      // and there are no `:last-child` rules to disturb. pointer-events:none
      // keeps the on-top overlay click-through.
      el.append(svg);
    }
    // observe() delivers an initial size on the next frame -> first draw. No
    // explicit cdxDrawNotch here, so this loop performs zero layout reads.
    host._cdxNotchRO.observe(el);
  }
}

/**
 * Texture origin (Eldritch scheme). Each framed block reveals the texture through
 * a luminance mask on its ::before; on its own that mask re-tiles per block (every
 * block starts the tile at its own corner). To read as ONE continuous slab glued
 * to the sheet, we set each block's --cdx-marble-x/y (its CSS mask-position) to
 * MINUS the block's offset within the scroll content. That aligns every block's
 * tile to a single origin at the content's top-left, so:
 *   - adjacent blocks' veins line up (shared origin), and
 *   - because the offset is measured in the content frame (scroll-independent),
 *     the whole slab moves with the blocks as the sheet scrolls — no scroll
 *     listener needed.
 * Offsets only change on reflow (resize, tab switch, expand/collapse, add/remove),
 * so a ResizeObserver on the container + blocks recomputes all of them (rAF-
 * debounced). Non-Eldritch schemes don't paint the marble, so this tears down and
 * returns. The observer is owned by `host` and disconnected in the sheet's close.
 */
export function cdxPositionMarble(host, root) {
  host._cdxMarbleRO?.disconnect();
  host._cdxMarbleRO = null;
  if (host._cdxMarbleRAF) { cancelAnimationFrame(host._cdxMarbleRAF); host._cdxMarbleRAF = null; }
  if (!root) return;

  // The scroll container is the content <form> (made overflow:auto in _cdxActivate).
  const container = host.form
    ?? (root.matches?.("form.window-content") ? root : root.querySelector?.("form.window-content"));
  if (!container?.classList?.contains("scheme-eldritch")) return;   // both Eldritch variants (Scholar/Fate) carry this base class

  const recompute = () => {
    const cRect = container.getBoundingClientRect();
    const sx = container.scrollLeft, sy = container.scrollTop;
    const blocks = container.querySelectorAll(CDX_MARBLE_SEL);
    const rects = [];
    for (const b of blocks) rects.push(b.getBoundingClientRect());  // batch reads (no interleaved writes)
    let i = 0;
    for (const b of blocks) {
      const r = rects[i++];
      if (r.width < 2 && r.height < 2) continue;                    // hidden (inactive tab) — repositioned when shown
      const x = Math.round(r.left - cRect.left + sx);
      const y = Math.round(r.top - cRect.top + sy);
      b.style.setProperty("--cdx-marble-x", `${-x}px`);
      b.style.setProperty("--cdx-marble-y", `${-y}px`);
    }
  };

  host._cdxMarbleRO = new ResizeObserver(() => {
    if (host._cdxMarbleRAF) cancelAnimationFrame(host._cdxMarbleRAF);
    host._cdxMarbleRAF = requestAnimationFrame(recompute);          // coalesce resize storms to one pass/frame
  });
  host._cdxMarbleRO.observe(container);
  for (const b of container.querySelectorAll(CDX_MARBLE_SEL)) host._cdxMarbleRO.observe(b);
  recompute();                                                       // initial pass
}

/** Run `fn` off the first-paint path: requestIdleCallback (fires after paint, when
 *  idle) if available, else a macrotask. Returns a canceller. */
function cdxDeferIdle(fn) {
  if (typeof requestIdleCallback === "function") {
    const id = requestIdleCallback(fn, { timeout: 800 });
    return () => cancelIdleCallback(id);
  }
  const id = setTimeout(fn, 0);
  return () => clearTimeout(id);
}

export const CDX_SCHEME_LABELS = {
  republic: "Republic",
  empire: "Empire",
  dark: "Dark",
  light: "Light",
  mercenary: "Mercenary",
  "eldritch-scholar": "Eldritch Horror - Scholar",
  "eldritch-fate": "Eldritch Horror - Fate",
};

/** Scheme picker grouped into two categories — "Modern" and "Eldritch Horror"
 *  (the two Eldritch buttons shown as just "Scholar" / "Fate"). Opens a DialogV2
 *  and resolves the chosen scheme id, or null if cancelled. Shared by the actor
 *  and item sheets. */
export async function cdxPickScheme(current, subjectName) {
  const GROUPS = [
    ["Modern", ["republic", "empire", "dark", "light", "mercenary"]],
    ["Eldritch Horror", ["eldritch-scholar", "eldritch-fate"]],
  ];
  const SHORT = { "eldritch-scholar": "Scholar", "eldritch-fate": "Fate" };
  // Scheme choices are Foundry-styled <button>s (same look as before), grouped into
  // labelled category panels. Clicking one applies immediately. All styling is
  // INLINE — DialogV2 drops <style> blocks from content, so a stylesheet wouldn't
  // take (that's what left the buttons stacked vertically).
  const btn = (s) =>
    `<button type="button" data-cdx-scheme="${s}" style="flex:0 0 auto;width:auto;margin:0` +
    `${s === current ? ";box-shadow:0 0 0 2px var(--color-warm-2,#c9593f)" : ""}">` +
    `${SHORT[s] ?? CDX_SCHEME_LABELS[s]}</button>`;
  const group = ([title, list]) =>
    `<fieldset style="border:1px solid rgba(127,127,127,.35);border-radius:6px;margin:.5rem 0;padding:.3rem .6rem .6rem">` +
    `<legend style="padding:0 .4rem;font-weight:700;font-size:.72rem;letter-spacing:.08em;text-transform:uppercase;opacity:.7">${title}</legend>` +
    `<div style="display:flex;flex-wrap:wrap;gap:.4rem;margin-top:.2rem">${list.map(btn).join("")}</div>` +
    `</fieldset>`;
  const content =
    `<div class="cdx-scheme-picker">` +
    `<p style="margin:.2rem 0 .5rem">Colour scheme for <b>${subjectName ?? ""}</b>:</p>` +
    GROUPS.map(group).join("") +
    `</div>`;

  // The scheme buttons live in the content, so wire their clicks via the render
  // hook (scoped to our dialog by the .cdx-scheme-picker marker): set the choice
  // and close, which resolves DialogV2.wait (rejectClose:false → no throw).
  let choice = null;
  const hookId = Hooks.on("renderDialogV2", (app, element) => {
    const root = element instanceof HTMLElement ? element : element?.[0];
    if (!root?.querySelector?.(".cdx-scheme-picker")) return;
    for (const b of root.querySelectorAll("[data-cdx-scheme]")) {
      b.addEventListener("click", () => { choice = b.dataset.cdxScheme; app.close(); });
    }
  });
  try {
    await foundry.applications.api.DialogV2.wait({
      window: { title: "Codex II — Scheme" },
      position: { width: 640 },   // ~3x the default so both category rows fit comfortably
      content,
      buttons: [{ action: "cancel", icon: "fa-solid fa-times", label: "Cancel" }],
      rejectClose: false,
    });
  } catch (e) { /* dismissed */ } finally {
    Hooks.off("renderDialogV2", hookId);
  }
  return choice && CDX_SCHEMES.includes(choice) ? choice : null;
}

const CDX_TEMPLATES = "systems/starwarsffg/templates/actors/codex";

/** The default Codex colour scheme, derived from the Default Sheet Theme setting
 *  (value `codex-<scheme>`), used when a document has no per-document scheme flag.
 *  Falls back to republic (also covers the legacy bare "codex" value). */
export function cdxDefaultScheme() {
  try {
    const t = String(game.settings.get("starwarsffg", "defaultSheetTheme") ?? "");
    const s = t.startsWith("codex-") ? t.slice("codex-".length) : null;
    return cdxNormalizeScheme(s) ?? "republic";
  } catch (e) { return "republic"; }
}

/**
 * Codex alignment — drives the Force chip's background colour (neutral=white,
 * good=blue, evil=red). A per-actor flag `flags.starwarsffg.codexAlignment` ∈
 * {neutral, good, evil} is the manually-set baseline; the *effective* alignment
 * applies Morality with hysteresis:
 *   - neutral: stays neutral while Morality ∈ [30,70]; ≥71 → good, ≤29 → evil
 *   - good:    stays good until Morality drops to ≤29 → evil
 *   - evil:    stays evil until Morality reaches ≥71 → good
 * Morality of 0 / unset is treated as "not tracked" (template default is 0), so
 * the baseline is returned unchanged — a Force user who doesn't use the Morality
 * system isn't painted evil. A genuinely evil 0-Morality actor can be set
 * "evil" by hand.
 */
export const CDX_ALIGNMENTS = ["neutral", "good", "evil"];
export function cdxEffectiveAlignment(stored, moralityRaw) {
  const s = CDX_ALIGNMENTS.includes(stored) ? stored : "neutral";
  if (moralityRaw === null || moralityRaw === undefined || moralityRaw === "") return s;
  const m = Number(moralityRaw) || 0;
  if (m <= 0) return s; // 0 / untracked → keep the baseline
  if (s === "good") return m <= 29 ? "evil" : "good";
  if (s === "evil") return m >= 71 ? "good" : "evil";
  return m >= 71 ? "good" : (m <= 29 ? "evil" : "neutral");
}

// Persist alignment transitions: when an actor's Morality crosses a boundary,
// commit the new alignment to the flag so the state is sticky (true hysteresis)
// instead of being recomputed from the baseline every time. Only the user who
// made the change writes (no multi-client races); only actors that already carry
// the flag (i.e. configured via a Codex sheet) are touched; the follow-up
// setFlag carries no Morality delta so it can't re-trigger this.
Hooks.on("updateActor", async (actor, changed, options, userId) => {
  try {
    if (userId !== game.user?.id) return;
    if (!foundry.utils.hasProperty(changed, "system.morality.value")) return;
    const current = actor.getFlag("starwarsffg", "codexAlignment");
    if (current === undefined) return;
    const next = cdxEffectiveAlignment(current, actor.system?.morality?.value);
    if (next !== current) await actor.setFlag("starwarsffg", "codexAlignment", next);
  } catch (e) { /* never let a hook break actor updates */ }
});

/**
 * Manual inventory order (Codex weapon/armour/gear cards, reorderable by their drag
 * grips). Items are ordered by Foundry's `sort` field ascending; an item that has
 * never been sorted (sort 0) falls to the BOTTOM in name order. So a fresh actor lists
 * each category alphabetically; once a player drags a card the category keeps the chosen
 * order; a newly added item lands at the end. Shared by getData (the render order) and
 * the drag handler (to reconstruct the current order before re-numbering). `_cdxReorderItem`
 * writes sort values as multiples of CDX_SORT_BASE so the order stays well-spaced.
 */
const CDX_SORT_BASE = 100000;
function cdxInventoryOrder(a, b) {
  const ea = (Number(a.sort) || 0) || Number.MAX_SAFE_INTEGER;
  const eb = (Number(b.sort) || 0) || Number.MAX_SAFE_INTEGER;
  return (ea - eb) || String(a.name ?? "").localeCompare(String(b.name ?? ""));
}

/**
 * Shared Codex behaviour, mixed onto whichever stock sheet base a given actor
 * type uses. Applied to ActorSheetFFG and AdversarySheetFFG below.
 */
export const CodexSchemeMixin = (Base) => class extends Base {
  // Concatenated onto the base's classes by ApplicationV2 → the OUTER window
  // <div> ends up `…actor v2 cdx`. `cdx` is our CSS scope.
  static DEFAULT_OPTIONS = {
    classes: ["cdx"],
  };

  /** The per-actor palette, defaulting to republic. */
  _cdxScheme() {
    const s = this.actor?.getFlag?.("starwarsffg", "scheme");
    return cdxNormalizeScheme(s) ?? cdxDefaultScheme();
  }

  /**
   * Replace (not extend) the legacy root classes: return ONLY the palette
   * class. Deliberately does NOT call super — that would re-add the actor-type
   * class (`character`/…) and let mandar's structural form rules match us. The
   * editable/locked classes are still applied by the base _applyLegacyRootClasses.
   * @override
   */
  _getLegacyRootClasses(_context = {}) {
    return cdxSchemeClasses(this._cdxScheme());
  }

  /**
   * Strip stale `scheme-*` (incl. the shared `scheme-eldritch` base) before super
   * re-adds the current one(s) (the base only ever ADDS classes), so switching
   * palettes doesn't accumulate them.
   * @override
   */
  _applyLegacyRootClasses(form, context = {}) {
    for (const c of CDX_SCHEME_STRIP) form.classList.remove(c);
    super._applyLegacyRootClasses(form, context);
  }

  /** @override — add the Codex-only listeners on top of the stock ones. */
  activateListeners(html) {
    super.activateListeners(html);
    this._cdxRegisterSheetOptions();
    this._cdxActivate(html);
  }

  /**
   * Codex-only Sheet Options, added on top of the stock per-type ones. Registered
   * here (not in the base actor-sheet-ffg per-type blocks) so the option appears
   * ONLY when a Codex sheet is the active sheet — i.e. "the Codex theme is
   * selected" is exactly "this sheet class is in use". `this.sheetoptions` is
   * created by the base activateListeners (run via super above) for every actor
   * type the Codex sheet supports.
   *
   *  - Inventory Style: "split" (default) keeps the separate Combat + Gear tabs;
   *    "combined" merges weapons/armour/gear under one Inventory tab. Only the
   *    actor types with those tabs get it (vehicles have a different tab set).
   *    Stored as a semantic string (NOT an index) because the dialog's Array
   *    type renders an object's keys as the <option value>s; see getData/the
   *    templates which branch on the "combined" value.
   */
  _cdxRegisterSheetOptions() {
    if (!this.sheetoptions) return;
    if (!["character", "rival", "nemesis", "minion"].includes(this.actor?.type)) return;
    this.sheetoptions.register("codexInventoryStyle", {
      name: game.i18n.localize("SWFFG.Codex.InventoryStyle"),
      hint: game.i18n.localize("SWFFG.Codex.InventoryStyleHint"),
      type: "Array",
      default: "split",
      options: {
        split: game.i18n.localize("SWFFG.Codex.InventoryStyleSplit"),
        combined: game.i18n.localize("SWFFG.Codex.InventoryStyleCombined"),
      },
    });
  }

  /** @override — drop the pill-stack's document listener when the sheet closes. */
  async close(options = {}) {
    this._cdxPillStack?.destroy();
    this._cdxPillStack = null;
    if (this._cdxTalentCardRoot && this._onCdxTalentCardClickBound) {
      this._cdxTalentCardRoot.removeEventListener("click", this._onCdxTalentCardClickBound, true);
    }
    this._cdxTalentCardRoot = null;
    this._cdxNotchRO?.disconnect();
    this._cdxNotchRO = null;
    this._cdxMarbleRO?.disconnect();
    this._cdxMarbleRO = null;
    if (this._cdxMarbleRAF) { cancelAnimationFrame(this._cdxMarbleRAF); this._cdxMarbleRAF = null; }
    this._cdxSigilCancel?.();
    this._cdxSigilCancel = null;
    this._cdxXpBuy = false; // never persist XP-buy mode across reopenings
    return super.close(options);
  }

  /**
   * @override — fix skill-rank purchase for the Codex markup. The stock _buyCore
   * resolves the skill row by walking a FIXED three parents up from the clicked
   * icon (event.target.parentElement ×3); our bespoke skills grid nests the icon
   * one level shallower, so that walk overshoots the row (lands on the column)
   * and _buySkillRank gets no data-ability — the buy silently fails. Resolve the
   * row by data-ability instead, which is nesting-independent. Every other buy
   * action is untouched and defers to super.
   */
  async _buyCore(event) {
    if (event?.target?.dataset?.buyAction === "skill") {
      if (this.actor?.verifyEditModeIsNotEnabled?.() === false) return;
      const row = event.target.closest?.("[data-ability]");
      if (row) await this._buySkillRank(row);
      return;
    }
    return super._buyCore(event);
  }

  _cdxActivate(html) {
    const root = html?.[0] ?? this.form ?? this.element;
    if (!root) return;

    // mandar forces `overflow: visible !important` on the content <form> (it
    // scrolls its own .sheet-body, which our bespoke layout doesn't have). A
    // CSS override can't reliably win that !important battle, so set it inline
    // (inline !important beats any stylesheet rule) — this makes the form the
    // scroll container so the body stops overflowing the window.
    const form = this.form;
    if (form) {
      form.style.setProperty("overflow-y", "auto", "important");
      form.style.setProperty("overflow-x", "hidden", "important");
    }

    // Reflect FFG edit mode as a class so view-only chrome can hide itself when
    // editing is off — e.g. the career-skill ("CS") column, which is redundant
    // with the left career highlight. Mirrors data.disabled in the base getData.
    const editOn = !!(
      this.actor?.getFlag?.("starwarsffg", "config.enableEditMode") &&
      this.actor?.getFlag?.("starwarsffg", "config.editModeActor") === game.user?.id
    );
    (form ?? root).classList.toggle("cdx-editmode", editOn);

    // Reflect GM status as a class so GM-only chrome can hide itself for players —
    // currently the per-pill delete cross (species/career/spec/force/sig). CSS
    // hides `.cdx-pill .item-delete` when this class is absent.
    (form ?? root).classList.toggle("cdx-gm", !!game.user?.isGM);

    // Collapsible header toggle (characters/rivals/nemeses/minions; vehicles have no
    // button). Flip the class live and swap the button label/icon for instant
    // feedback, then persist the per-actor flag WITHOUT a re-render (the class
    // already reflects the new state, so a re-render would only cause a flash).
    root.querySelector(".cdx-hcollapse-btn")?.addEventListener("click", async (ev) => {
      ev.preventDefault();
      const header = root.querySelector(".cdx-header");
      if (!header) return;
      const collapsed = header.classList.toggle("cdx-hcollapsed");
      const btn = ev.currentTarget;
      const label = btn.querySelector(".cdx-hcollapse-label");
      if (label) label.textContent = collapsed ? "Expand" : "Collapse";
      const icon = btn.querySelector("i");
      if (icon) icon.className = collapsed ? "fas fa-caret-down" : "fas fa-caret-up";
      await this.actor.update({ "flags.starwarsffg.codexHeaderCollapsed": collapsed }, { render: false });
    });

    // Bespoke tab switching — no Foundry Tabs controller, no .sheet-tabs.
    root.querySelectorAll(".cdx-tab").forEach((btn) => {
      btn.addEventListener("click", (ev) => {
        ev.preventDefault();
        const tab = ev.currentTarget.dataset.tab;
        if (!tab) return;
        root.querySelectorAll(".cdx-tab").forEach((t) => t.classList.toggle("active", t.dataset.tab === tab));
        root.querySelectorAll(".cdx-pane").forEach((p) => p.classList.toggle("active", p.dataset.tab === tab));
        // remember the active tab across re-renders (e.g. on a scheme change)
        this._cdxTab = tab;
      });
    });
    // Restore the remembered tab after a re-render.
    if (this._cdxTab) {
      const has = root.querySelector(`.cdx-tab[data-tab="${this._cdxTab}"]`);
      if (has) {
        root.querySelectorAll(".cdx-tab").forEach((t) => t.classList.toggle("active", t.dataset.tab === this._cdxTab));
        root.querySelectorAll(".cdx-pane").forEach((p) => p.classList.toggle("active", p.dataset.tab === this._cdxTab));
      }
    }

    // Collapsible pill stacks (specializations, force powers, signature
    // abilities, …): a reusable widget owns the click handling — first click
    // expands, a click on a pill opens that item's tree, a click anywhere else
    // collapses — and consumes every click so none leaks to the sheet beneath.
    this._cdxPillStack?.destroy();
    this._cdxPillStack = new CdxPillStack(root, {
      onActivate: (id) => { this.actor?.items?.get(id)?.sheet?.render(true); },
      onDelete: (id) => {
        if (this.actor?.verifyEditModeIsNotEnabled?.() === false) return;
        this.actor?.items?.get(id)?.delete();
      },
    });

    // Species/career pills are single `.cdx-pill.item[data-item-id]` spans in
    // `.cdx-pills` — NOT inside a `.cdx-stack`, so CdxPillStack (which only scans
    // `.cdx-stack`) ignores them, and NOT inside `.items`/`.header-description-
    // block`/`.injuries`, so the stock opener in actor-sheet-ffg.js never matches
    // them either. That left the pill body a dead click. Open the item sheet
    // directly; the delete-X keeps flowing to the stock `.item-delete` handler
    // (the pill span is itself `.item`, which that handler resolves via
    // `.parents(".item")`), so it stays edit-mode-gated.
    root.querySelectorAll(".cdx-pill.species[data-item-id], .cdx-pill.career[data-item-id]").forEach((pill) => {
      pill.addEventListener("click", (ev) => {
        if (ev.target.closest(".item-delete")) return; // delete-X → stock handler
        ev.preventDefault();
        ev.stopPropagation();
        this.actor?.items?.get(pill.dataset.itemId)?.sheet?.render(true);
      });
    });

    // XP-buy mode: clicking the XP chip reveals every purchase affordance (skill
    // upgrades, characteristic/talent/spec/force/signature buys); otherwise they
    // are hidden (see `.cdx-xpbuy` in cdx.css). The flag is TRANSIENT — held on
    // the instance, re-applied on re-render, and reset in close() — so it never
    // persists across reopenings and always starts hidden.
    // Edit mode and buy mode are mutually exclusive (purchases are blocked while
    // editing): edit mode forces buy mode off and makes the XP chip inert.
    if (editOn) this._cdxXpBuy = false;
    (form ?? root).classList.toggle("cdx-xpbuy", !!this._cdxXpBuy);
    root.querySelectorAll(".cdx-xp").forEach((chip) => {
      chip.classList.toggle("active", !!this._cdxXpBuy);
      if (editOn) return; // XP chip is not clickable while edit mode is on
      chip.addEventListener("click", (ev) => {
        ev.preventDefault();
        this._cdxXpBuy = !this._cdxXpBuy;
        (form ?? root).classList.toggle("cdx-xpbuy", this._cdxXpBuy);
        chip.classList.toggle("active", this._cdxXpBuy);
      });
    });

    // Weapon-card dice pools (skill roll preview) — render for viewers too.
    this._cdxWeaponPools(root);

    // Equip toggle: consume clicks on the whole button so they never leak to the
    // card's expand handler. (Clicking the button box outside the glyph used to
    // also expand the card, since the stock handler only skips icon/rollable targets.)
    root.querySelectorAll(".cdx-equip").forEach((el) => {
      el.addEventListener("click", (ev) => ev.stopPropagation());
    });

    // Carried toggle (Codex inventory, weapon/armour/gear): flip flags.starwarsffg.carried.
    // Un-pressed = left on a ship/base → the item's encumbrance*qty is excluded from the
    // actor's encumbrance (ActorFFG._calculateDerivedValues honours the flag; default =
    // carried). stopPropagation so the click doesn't expand/roll the card.
    root.querySelectorAll(".toggle-carried").forEach((el) => {
      el.addEventListener("click", async (ev) => {
        ev.preventDefault();
        ev.stopPropagation();
        if (!this.options.editable) return;
        if (this.actor?.verifyEditModeIsNotEnabled && !this.actor.verifyEditModeIsNotEnabled()) return;
        const item = this.actor?.items?.get(ev.currentTarget.dataset.itemId);
        if (!item) return;
        const carried = item.getFlag("starwarsffg", "carried") !== false;
        await item.setFlag("starwarsffg", "carried", !carried);
      });
    });

    // Force powers / signature abilities (Talents tab): clicking the card should
    // expand inline details, NOT open the item's tree. The stock `.items .item`
    // handler opens the sheet for these types; intercept in the capture phase so
    // we beat that bubble handler. Control clicks (edit/delete/roll) pass through;
    // clicks inside an already-open detail block don't toggle it shut.
    this._bindCdxTalentCardHandler(root);

    // Crit-Trauma weekly recovery controls (Resilience self-heal / Medicine /
    // Mechanics markers). Bound for viewers too so a permitted ally (≥OBSERVER,
    // non-owner) can mark the Medicine failure, which is forwarded to the GM.
    this._cdxWireCritRecovery(root);

    if (!this.options.editable) return;
    this._cdxWireReorder(root);
    this._cdxWireCredits(root);
    // Alignment selector (bio) → write the Codex alignment flag; the chip recolours
    // on the resulting re-render.
    root.querySelector(".cdx-align-select")?.addEventListener("change", (ev) => {
      const v = ev.currentTarget.value;
      if (CDX_ALIGNMENTS.includes(v)) this.actor?.setFlag("starwarsffg", "codexAlignment", v);
    });
    this._cdxWireAmmo(root);
    // Strain recovery — self-contained post-encounter strain recovery dialog.
    root.querySelectorAll(".cdx-strain-rest").forEach((btn) => {
      btn.addEventListener("click", (ev) => { ev.preventDefault(); this._cdxStrainRecovery(); });
    });
    // Wounds / strain steppers (−/+). Floored at 0 but NOT capped at the
    // threshold — current wounds/strain may exceed the threshold (that's the
    // incapacitated/overburdened state), so the only bound is the lower one.
    root.querySelectorAll(".cdx-step").forEach((btn) => {
      btn.addEventListener("click", async (ev) => {
        ev.preventDefault();
        const stat = ev.currentTarget.dataset.stat;
        const dir = Number(ev.currentTarget.dataset.dir) || 0;
        const s = this.actor?.system?.stats?.[stat];
        if (!s) return;
        const val = Math.max(0, (Number(s.value) || 0) + dir);
        await this.actor.update({ [`system.stats.${stat}.value`]: val });
      });
    });
    // Threshold value & max edited directly (typing, not the ± buttons) -- wounds &
    // strain on actors, hull trauma & system strain on vehicles -- drive the DERIVED
    // progress track (cdxTracks/cdxVehTracks → bar width / pips), which getData only
    // recomputes on render. The generic form pipeline submits with render:false, so
    // the bar/pips stayed stale until the next full re-render. Persist via the
    // explicit system path and let actor.update re-render (default) so the track
    // updates live; change fires on blur (not mid-typing) so the value survives, and
    // stopPropagation keeps the generic submit from also firing and racing us.
    root.querySelectorAll([
      'input[name="data.stats.wounds.value"]', 'input[name="data.stats.wounds.max"]',
      'input[name="data.stats.strain.value"]', 'input[name="data.stats.strain.max"]',
      'input[name="data.stats.hullTrauma.value"]', 'input[name="data.stats.hullTrauma.max"]',
      'input[name="data.stats.systemStrain.value"]', 'input[name="data.stats.systemStrain.max"]',
    ].join(", ")).forEach((input) => {
      input.addEventListener("change", async (ev) => {
        ev.stopPropagation();
        const raw = parseInt(String(ev.currentTarget.value).replace(/[^\d-]/g, ""), 10);
        const val = Math.max(0, Number.isFinite(raw) ? raw : 0);
        const path = ev.currentTarget.name.replace(/^data\./, "system.");
        await this.actor.update({ [path]: val });
      });
    });
    // Ratio-chip steppers (−/+): adjust the value at data-cdx-path, clamped to
    // [0, data-cdx-max]. Drives the Force chip (committed dice) and the vehicle
    // Speed chip from one handler. Always active (a play action).
    root.querySelectorAll(".cdx-ratio-step").forEach((btn) => {
      btn.addEventListener("click", async (ev) => {
        ev.preventDefault(); ev.stopPropagation();
        const dir = Number(ev.currentTarget.dataset.dir) || 0;
        const path = ev.currentTarget.dataset.cdxPath;
        if (!path) return;
        const max = Number(ev.currentTarget.dataset.cdxMax);
        const cur = Number(foundry.utils.getProperty(this.actor, path)) || 0;
        let val = cur + dir;
        val = Math.max(0, Number.isFinite(max) ? Math.min(max, val) : val);
        if (val === cur) return;
        await this.actor.update({ [path]: val });
      });
    });
    // Minion Group-Strength steppers (members alive ±1). Alive count is DERIVED
    // from wounds (system prepareData):
    //   alive = qmax - floor((wounds - 1) / unit)
    // The wound track is 1-indexed -- the first point of damage is wound 1, so a
    // member only drops at unit+1 wounds, NOT unit. A flat ±unit step is therefore
    // off by one: from a clean group, −unit (e.g. 0 → 3 at unit 3) leaves the
    // count unchanged because wound 3 still hasn't crossed the kill boundary.
    // Instead, decompose the current wounds into dead members + partial damage on
    // the leading (still-alive) member, move the dead count by one, and re-attach
    // the SAME partial. This costs unit+1 from a clean group (kills a member) and
    // unit mid-damage, while preserving the carried partial damage.
    //   e.g. 3/member, 2 applied, − → 5 wounds = 1 dead + the 2 carried over.
    // Clamped to [0, qmax·unit + 1] (the latter = whole group dead, matching
    // killMinionGroup; one past wounds.max because the alive formula needs the
    // extra point to drop the final member).
    root.querySelectorAll(".cdx-gs-step").forEach((btn) => {
      btn.addEventListener("click", async (ev) => {
        ev.preventDefault();
        const dir = Number(ev.currentTarget.dataset.dir) || 0; // −1 kill, +1 revive
        const sys = this.actor?.system;
        if (!sys) return;
        const unit = Math.max(1, Math.trunc(Number(sys.unit_wounds?.value) || 1));
        const qmax = Math.max(0, Math.trunc(Number(sys.quantity?.max) || 0));
        const cur = Math.max(0, Math.trunc(Number(sys.stats?.wounds?.value) || 0));
        const ceiling = qmax * unit + 1;
        const deaths = cur >= 1 ? Math.floor((cur - 1) / unit) : 0;
        const partial = cur >= 1 ? (cur - 1) - deaths * unit : 0;
        const targetDeaths = Math.max(0, Math.min(qmax, deaths - dir));
        const next = (targetDeaths === 0 && partial === 0)
          ? 0
          : Math.max(0, Math.min(ceiling, targetDeaths * unit + partial + 1));
        if (next === cur) return;
        await this.actor.update({ "system.stats.wounds.value": next });
      });
    });
    // Wipe Out — eliminate the whole group (wounds → max+1 ⇒ alive 0).
    root.querySelectorAll(".cdx-wipeout").forEach((btn) => {
      btn.addEventListener("click", async (ev) => {
        ev.preventDefault();
        await killMinionGroup(this.actor);
      });
    });
    // Minion config inputs — group size (quantity.max) and wounds-per-member
    // (unit_wounds.value). These drive DERIVED values (wounds.max, alive count,
    // the wound-pool track), so they need an explicit, re-rendering write:
    //  • The generic change pipeline submits with render:false, so the combined
    //    wound pool never updated in place after an edit.
    //  • Worse, leaving edit mode triggers its own re-render that could race the
    //    in-flight render:false submit, leaving the typed value seemingly lost.
    // Persist via an explicit system path (no reliance on the data.* alias) and
    // let actor.update re-render (default), so the pool updates live and the
    // value survives leaving edit mode. stopPropagation keeps the generic form
    // submit from also firing for this field and racing us.
    root.querySelectorAll('input[name="data.quantity.max"], input[name="data.unit_wounds.value"]').forEach((input) => {
      input.addEventListener("change", async (ev) => {
        ev.stopPropagation();
        const raw = parseInt(String(ev.currentTarget.value).replace(/[^\d-]/g, ""), 10);
        const val = Math.max(0, Number.isFinite(raw) ? raw : 0);
        const path = ev.currentTarget.name === "data.quantity.max" ? "system.quantity.max" : "system.unit_wounds.value";
        await this.actor.update({ [path]: val });
      });
    });

    // Notched-block outlines. A CSS `border` on a --cdx-clip octagon is sliced
    // off at the 45° notches; instead each notched block carries an SVG overlay
    // whose single stroked <path> traces the SAME octagon geometry as the clip,
    // sized to the block in px so the notches stay a fixed 9px and the line is a
    // uniform 1px on every edge (see _cdxNotchOutlines).
    this._cdxNotchOutlines(root);

    // Eldritch marble: glue each block's marble to one content-anchored origin so
    // the veins are continuous across blocks and scroll with the sheet.
    cdxPositionMarble(this, root);

    // Eldritch sigils: a per-actor procedural mask generated once and cached, fed
    // to the header ornament as its CSS mask — Fate gets the dense "deco" wall,
    // Scholar gets a single "medallion" sigil. Both seed off the actor + carry
    // clouds/wear. Other schemes ignore it.
    this._cdxFatedSigil();
  }

  /** Set the per-actor procedural sigil mask on the form (Fate → --cdx-fated-sigil,
   *  Scholar → --cdx-scholar-sigil). Cleared for non-Eldritch schemes.
   *  Generation (~a few 1024² passes) is deferred off the first-paint path so the
   *  sheet opens instantly — the CSS transparent fallback hides the ornament until
   *  the mask lands. Cached per (seed, style), and skipped when already set. */
  _cdxFatedSigil() {
    const form = this.form;
    if (!form) return;
    const scheme = this._cdxScheme();
    const isFate = scheme === "eldritch-fate";
    const isScholar = scheme === "eldritch-scholar";
    if (!isFate) form.style.removeProperty("--cdx-fated-sigil");
    if (!isScholar) form.style.removeProperty("--cdx-scholar-sigil");
    if (!isFate && !isScholar) return;

    const prop = isFate ? "--cdx-fated-sigil" : "--cdx-scholar-sigil";
    if (form.style.getPropertyValue(prop)) return;   // already on this form — skip cheap re-renders

    // Fate uses the 1024 deco wall (its 2× size breaks tiling); the Scholar single
    // sigil is shown small, so 512 is ample and ~4x cheaper (cost is canvas area).
    // Only the Fate wall is worn — the Scholar medallion is drawn clean, so it
    // opts out of the wear pass entirely rather than inheriting the Fate default.
    const opts = isFate
      ? { style: "deco" }
      : { style: "medallion", maskSize: 512, wearSource: "none" };
    const seed = this.actor?.uuid ?? this.actor?.id ?? this.actor?.name ?? "codex";
    this._cdxSigilCancel?.();
    this._cdxSigilCancel = cdxDeferIdle(async () => {
      this._cdxSigilCancel = null;
      if (this.form !== form || this._cdxScheme() !== scheme) return;   // stale render / scheme changed
      const url = await getFatedSigilMask(seed, opts);
      // Re-check: the mask now decodes an image, so the sheet may have
      // re-rendered or switched scheme while we awaited it.
      if (this.form !== form || this._cdxScheme() !== scheme) return;
      if (url) form.style.setProperty(prop, `url("${url}")`);
    });
  }

  /** @see cdxBuildNotchOutlines — thin instance wrapper so the observer is
   *  owned by (and torn down with) this sheet. */
  _cdxNotchOutlines(root) {
    cdxBuildNotchOutlines(this, root);
  }

  /**
   * In-place credits editor: the "Change" tab on the CR chip opens a small +/-
   * panel. + and − are a mutually-exclusive toggle (selecting one deselects the
   * other); Confirm adds or subtracts the entered amount from the actor's
   * credits, Cancel/Escape dismiss. Transient (no flag), re-wired each render.
   */
  _cdxWireCredits(root) {
    const wrap = root.querySelector(".cdx-credits-wrap");
    if (!wrap) return;
    const amount = wrap.querySelector(".cdx-cr-amount");
    const ops = [...wrap.querySelectorAll(".cdx-cr-op")];
    const setOp = (b) => ops.forEach((x) => x.classList.toggle("active", x === b));
    const close = () => wrap.classList.remove("editing");
    // Stored credits as a plain integer, and a thousands-separated render of one.
    const curCredits = () => parseInt(String(this.actor?.system?.stats?.credits?.value ?? "0").replace(/[^\d]/g, ""), 10) || 0;
    const fmt = (v) => (parseInt(String(v).replace(/[^\d]/g, ""), 10) || 0).toLocaleString("en-US");
    const open = () => {
      wrap.classList.add("editing");
      if (amount) amount.value = "";
      setOp(ops.find((b) => b.dataset.op === "add") ?? ops[0]);
      setTimeout(() => amount?.focus(), 0);
    };
    const commit = async () => {
      const op = wrap.querySelector(".cdx-cr-op.active")?.dataset.op ?? "add";
      const delta = parseInt(String(amount?.value ?? "").replace(/[^\d]/g, ""), 10) || 0;
      close();
      if (!delta) return;
      const next = Math.max(0, op === "sub" ? curCredits() - delta : curCredits() + delta);
      try { await this.actor?.update({ "system.stats.credits.value": String(next) }); } catch (e) { /* no permission */ }
    };
    // Main credits field — display with thousands-separating commas; show raw
    // digits while editing, reformat + persist on commit. The input is NOT
    // Foundry-bound (no name=), so the comma'd string can never round-trip into
    // the stored value when a neighbouring field triggers a form submit.
    const field = wrap.querySelector(".cdx-sq-input");
    if (field) {
      field.value = fmt(curCredits());
      field.addEventListener("focus", () => { field.value = String(curCredits()); setTimeout(() => field.select(), 0); });
      field.addEventListener("input", () => {
        const caret = field.selectionStart;
        const stripped = field.value.replace(/[^\d]/g, "");
        if (stripped !== field.value) { field.value = stripped; try { field.setSelectionRange(caret - 1, caret - 1); } catch (e) { /* noop */ } }
      });
      field.addEventListener("keydown", (ev) => {
        if (ev.key === "Enter") { ev.preventDefault(); field.blur(); }
        else if (ev.key === "Escape") { ev.preventDefault(); field.value = String(curCredits()); field.blur(); }
      });
      field.addEventListener("blur", async () => {
        const n = parseInt(field.value.replace(/[^\d]/g, ""), 10) || 0;
        field.value = fmt(n);
        if (n !== curCredits()) { try { await this.actor?.update({ "system.stats.credits.value": String(n) }); } catch (e) { /* no permission */ } }
      });
    }
    // Amount field (the +/- panel) — digits only too.
    amount?.addEventListener("input", () => { const c = amount.selectionStart; const s = amount.value.replace(/[^\d]/g, ""); if (s !== amount.value) { amount.value = s; try { amount.setSelectionRange(c - 1, c - 1); } catch (e) { /* noop */ } } });
    wrap.querySelector(".cdx-cr-change")?.addEventListener("click", (ev) => { ev.preventDefault(); ev.stopPropagation(); open(); });
    ops.forEach((b) => b.addEventListener("click", (ev) => { ev.preventDefault(); setOp(b); amount?.focus(); }));
    wrap.querySelector(".cdx-cr-cancel")?.addEventListener("click", (ev) => { ev.preventDefault(); close(); });
    wrap.querySelector(".cdx-cr-confirm")?.addEventListener("click", (ev) => { ev.preventDefault(); commit(); });
    amount?.addEventListener("keydown", (ev) => {
      if (ev.key === "Enter") { ev.preventDefault(); commit(); }
      else if (ev.key === "Escape") { ev.preventDefault(); close(); }
    });
  }

  /**
   * Ammo chip on expanded weapon cards: the −/+ steppers adjust the weapon's
   * system.ammo magazine. Writes use {render:false} + an optimistic DOM update
   * so a +/- doesn't collapse the expanded card; the persisted value is correct
   * even if a render still occurs.
   */
  _cdxWireAmmo(root) {
    // Swallow clicks inside the chip so they don't toggle the card's expand state.
    root.querySelectorAll(".cdx-ammo").forEach((chip) => {
      chip.addEventListener("click", (ev) => ev.stopPropagation());
    });
    root.querySelectorAll(".cdx-ammo-step").forEach((btn) => {
      btn.addEventListener("click", async (ev) => {
        ev.preventDefault(); ev.stopPropagation();
        const chip = ev.currentTarget.closest(".cdx-ammo"); if (!chip) return;
        const w = this.actor?.items?.get(chip.dataset.weaponId); if (!w) return;
        const dir = Number(ev.currentTarget.dataset.dir) || 0;
        const mx = Number(w.system?.ammo?.max) || 0;
        let cur = (Number(w.system?.ammo?.value) || 0) + dir;
        cur = Math.max(0, mx ? Math.min(mx, cur) : cur);
        try { await w.update({ "system.ammo.value": cur }, { render: false }); } catch (e) { return; }
        const cEl = chip.querySelector(".cdx-ammo-count"); if (cEl) cEl.textContent = `${cur}/${mx}`;
      });
    });
  }

  /**
   * Inventory card reordering (weapons / armour / gear). Each card carries a left-edge
   * grip (`.cdx-grip`, draggable); dragging it reorders cards WITHIN their own category by
   * rewriting the items' Foundry `sort` field. The whole-card cross-actor transfer drag
   * (base DragDrop, dragSelector `.cdx-card`) is left intact: the grip's dragstart calls
   * stopPropagation so the base transfer dragstart never fires for a grip drag, and the
   * grip drop calls stopPropagation so it never bubbles to the base sheet drop zone (which
   * would route it through _onSortItem and double-sort). A grip dropped on empty space just
   * no-ops — the base _onTransferItemDrop ignores our non-JSON payload.
   */
  _cdxWireReorder(root) {
    const clearMarks = () => root
      .querySelectorAll(".cdx-card.cdx-drop-before, .cdx-card.cdx-drop-after")
      .forEach((c) => c.classList.remove("cdx-drop-before", "cdx-drop-after"));

    root.querySelectorAll(".cdx-card .cdx-grip").forEach((grip) => {
      const card = grip.closest(".cdx-card[data-item-id]");
      if (!card) return;
      // A plain click on the grip must not expand/roll the card.
      grip.addEventListener("click", (ev) => ev.stopPropagation());
      grip.addEventListener("dragstart", (ev) => {
        ev.stopPropagation(); // beat the base .cdx-card transfer dragstart
        const item = this.actor?.items?.get(card.dataset.itemId);
        if (!item) return;
        this._cdxReorder = { id: item.id, type: item.type, card };
        try {
          ev.dataTransfer.effectAllowed = "move";
          ev.dataTransfer.setData("text/plain", item.id); // Firefox needs a payload to start a drag
          ev.dataTransfer.setDragImage(card, 12, 16);      // ghost the whole card, not the 5px sliver
        } catch (e) { /* dataTransfer may be restricted; the drag still works */ }
        card.classList.add("cdx-dragging");
      });
      grip.addEventListener("dragend", () => {
        this._cdxReorder = null;
        card.classList.remove("cdx-dragging");
        clearMarks();
      });
    });

    root.querySelectorAll(".cdx-card[data-item-id]").forEach((card) => {
      // Whether the pointer is in the card's lower half → drop AFTER it, else BEFORE.
      const dropsAfter = (ev) => {
        const rect = card.getBoundingClientRect();
        return (ev.clientY - rect.top) > rect.height / 2;
      };
      const validTarget = () => {
        const drag = this._cdxReorder;
        if (!drag) return null;
        const target = this.actor?.items?.get(card.dataset.itemId);
        // Same category only, and never the dragged card itself.
        if (!target || target.type !== drag.type || target.id === drag.id) return null;
        return { drag, target };
      };
      card.addEventListener("dragover", (ev) => {
        const v = validTarget();
        if (!v) return;            // not a grip reorder (or wrong category) → let the base transfer handle it
        ev.preventDefault();       // mark the card as a valid drop target
        ev.stopPropagation();
        const after = dropsAfter(ev);
        card.classList.toggle("cdx-drop-after", after);
        card.classList.toggle("cdx-drop-before", !after);
      });
      card.addEventListener("dragleave", () => {
        card.classList.remove("cdx-drop-before", "cdx-drop-after");
      });
      card.addEventListener("drop", async (ev) => {
        const v = validTarget();
        if (!v) return;
        ev.preventDefault();
        ev.stopPropagation();      // never reach the base sheet drop (it would also _onSortItem)
        const after = dropsAfter(ev);
        clearMarks();
        // Persist the new order WITHOUT a re-render, then move the card in place. A
        // re-render would reset the form's scroll (you've usually scrolled into the
        // inventory) and flash; the optimistic DOM move mirrors the ammo stepper.
        const ok = await this._cdxReorderItem(v.drag.id, v.target.id, v.drag.type, after);
        if (ok && v.drag.card) { if (after) card.after(v.drag.card); else card.before(v.drag.card); }
      });
    });
  }

  /**
   * Persist a within-category reorder: re-number every item of `type` so the dragged item
   * lands before/after the target, writing the Foundry `sort` field. Re-numbering the whole
   * category (rather than a single relative sort) keeps the result deterministic even from a
   * cold start where every item still has sort 0. Only items whose sort actually changes are
   * written, and with {render:false} — the caller moves the card in the DOM. Returns true on
   * success so the caller knows it's safe to do the optimistic move.
   */
  async _cdxReorderItem(dragId, targetId, type, after) {
    if (dragId === targetId) return false;
    const dragItem = this.actor?.items?.get(dragId);
    if (!dragItem) return false;
    const sibs = (this.actor?.items?.filter((i) => i.type === type) ?? []).sort(cdxInventoryOrder);
    const from = sibs.findIndex((i) => i.id === dragId);
    if (from < 0) return false;
    sibs.splice(from, 1);
    let to = sibs.findIndex((i) => i.id === targetId);
    if (to < 0) return false;
    if (after) to += 1;
    sibs.splice(to, 0, dragItem);
    const updates = [];
    sibs.forEach((it, idx) => {
      const want = (idx + 1) * CDX_SORT_BASE;
      if ((Number(it.sort) || 0) !== want) updates.push({ _id: it.id, sort: want });
    });
    try {
      if (updates.length) await this.actor.updateEmbeddedDocuments("Item", updates, { render: false });
    } catch (e) {
      return false;
    }
    return true;
  }

  _bindCdxTalentCardHandler(root) {
    if (!root) return;
    this._onCdxTalentCardClickBound ??= this._onCdxTalentCardClick.bind(this);
    if (this._cdxTalentCardRoot === root) return;
    this._cdxTalentCardRoot?.removeEventListener("click", this._onCdxTalentCardClickBound, true);
    this._cdxTalentCardRoot = root;
    root.addEventListener("click", this._onCdxTalentCardClickBound, true);
  }

  _onCdxTalentCardClick(ev) {
    const card = ev.target.closest?.(".cdx-talent[data-item-id]");
    if (!card || ev.target.closest(".item-control")) return;
    const item = this.actor?.items?.get(card.dataset.itemId);
    if (!item || !["forcepower", "signatureability"].includes(item.type)) return;
    ev.preventDefault();
    ev.stopPropagation();
    if (ev.target.closest(".item-details")) return;
    this._itemDisplayDetails(item, { preventDefault() {}, currentTarget: card });
  }

  /**
   * Fill each weapon card's dice-pool node with the actor's pool for that weapon's
   * combat skill, reusing the same DiceHelpers.addSkillDicePool the Skills tab uses
   * (so it's the real, full pool). The .roll-button node is display-only here
   * (pointer-events:none in CSS) — the weapon icon is the roll trigger.
   */
  async _cdxWeaponPools(root) {
    const nodes = root.querySelectorAll(".cdx-wpn-skill[data-ability]");
    if (!nodes.length) return;
    let data;
    try { data = await this.getData({}); } catch (e) { return; }
    // Hints live on the form, outside the cards, so they outlive a content re-render.
    this.form?.querySelectorAll(".cdx-wpn-tip").forEach((n) => n.remove());
    // Awaited (not forEach): the tooltip only exists once the pool has rendered.
    for (const elem of nodes) {
      // Resolve the weapon item from its card so its roll modifiers are folded
      // into the previewed pool (matches what clicking the weapon rolls).
      const card = elem.closest(".cdx-card.weapon[data-item-id]");
      const item = card ? (this.actor?.items?.get(card.dataset.itemId) ?? null) : null;
      try { await DiceHelpers.addSkillDicePool(data, elem, item); } catch (e) { continue; }
      this._cdxWeaponPoolHint(elem);
    }
  }

  /**
   * Drive a weapon pool's source hint from its row, with the tooltip re-homed onto
   * the form. Two things stop the shared `.hover:hover .tooltip2` mechanism working
   * in place here:
   *   - .cdx-card carries a clip-path (the notches), which clips its whole subtree —
   *     a tooltip anchored inside the card is cut off at the card's edge.
   *   - .cdx-wpn-pool is pointer-events:none, so it can never be :hover-ed. That is
   *     deliberate: .roll-button has a global handler, and the pool sits one level
   *     deeper than rollSkill's parent-walk expects, so a click there would roll a
   *     bare skill instead of the weapon. Clicks must keep falling through to the
   *     card's icon, which sits at the depth rollSkill wants.
   * The form is unclipped, and an absolutely positioned child of it scrolls with the
   * content, so the hint tracks its row. The `.hover` host keeps the shared
   * `.starwarsffg .hover .tooltip2` styling matching, so it looks like the skill hint.
   */
  _cdxWeaponPoolHint(elem) {
    const tip = elem.querySelector(".tooltip2");
    const form = this.form;
    if (!tip || !form) return;

    const host = document.createElement("div");
    host.className = "hover cdx-wpn-tip";
    host.appendChild(tip);
    form.appendChild(host);

    const show = () => {
      // Measure against offsetParent — by definition what position:absolute resolves
      // to — rather than assuming the form is positioned. Adding position:relative to
      // the form would silently re-anchor the sheet's other ~30 absolute elements.
      const anchor = host.offsetParent ?? form;
      const a = anchor.getBoundingClientRect();
      const r = elem.getBoundingClientRect();
      host.style.left = `${r.left - a.left + anchor.scrollLeft}px`;
      host.style.top = `${r.bottom - a.top + anchor.scrollTop + 3}px`;
      host.classList.add("cdx-tip-on");
    };
    elem.addEventListener("pointerenter", show);
    elem.addEventListener("pointerleave", () => host.classList.remove("cdx-tip-on"));
  }

  /**
   * Distribute skills into two columns WITHOUT splitting a skill group across the
   * break. The stock _createSkillColumns fills column 1 to a row target and spills
   * a group across the gap (repeating its header); instead we keep each group
   * [header, ...skills] whole and pick the in-order boundary that best balances the
   * two columns — so e.g. Combat (Brawl…) moves wholesale to the second column
   * rather than starting at the bottom of the first. @override
   */
  _createSkillColumns(data) {
    const byLabel = game.settings.get("starwarsffg", "skillSorting");
    const sortFn = byLabel
      ? (a, b) => data.data.skills[a].label.localeCompare(data.data.skills[b].label, game.i18n.lang)
      : (a, b) => a.toLowerCase().localeCompare(b.toLowerCase());

    // Each group = its header row + sorted skill rows; treated as one unbreakable unit.
    const groups = data.data.skilltypes.map((type) => {
      const skills = Object.keys(data.data.skills)
        .filter((s) => data.data.skills[s].type === type.type)
        .sort(sortFn)
        .map((s) => ({ name: s, ...data.data.skills[s] }));
      return [{ id: "header", ...type }, ...skills];
    }).filter((g) => g.length > 1);

    // Pick the in-order split point (k groups in column 0, the rest in column 1)
    // that minimises the row-count imbalance between the two columns.
    const total = groups.reduce((n, g) => n + g.length, 0);
    let bestK = groups.length, bestDiff = Infinity, running = 0;
    for (let k = 1; k <= groups.length; k++) {
      running += groups[k - 1].length;
      const diff = Math.abs(running - (total - running));
      if (diff < bestDiff) { bestDiff = diff; bestK = k; }
    }

    const cols = [[], []];
    groups.forEach((g, i) => cols[i < bestK ? 0 : 1].push(...g));
    return cols.filter((c) => c.length > 0);
  }

  /**
   * Expose the crit-injury count (Injuries tab badge) and the wound/strain
   * damage tracks (the colored pip bars next to the steppers). @override
   */
  async getData(options) {
    const ctx = await super.getData(options);
    // Per-actor collapsed-header preference (characters/rivals/nemeses/minions).
    ctx.cdxHeaderCollapsed = !!this.actor?.getFlag?.("starwarsffg", "codexHeaderCollapsed");
    // Inventory Style (Sheet Option): "combined" merges weapons/armour/gear into
    // one Inventory tab; anything else (default "split") keeps the Combat + Gear
    // tabs. Dotted-key getFlag, same idiom as config.enableEditMode above.
    ctx.cdxCombinedInventory = this.actor?.getFlag?.("starwarsffg", "config.codexInventoryStyle") === "combined";
    // Inventory render order: cdxItems is the actor's items in manual drag-sort order
    // (see cdxInventoryOrder). The weapon/armour/gear partials iterate THIS instead of the
    // collection-ordered `items`, so reordering via the card grips is reflected. These are
    // still the live Item documents (not toObject'd), so the templates keep full
    // item.system / item.flags / item.img access.
    ctx.cdxItems = [...(this.actor?.items ?? [])].sort(cdxInventoryOrder);
    // Show the inventory drag grips only to a user who can actually edit the actor —
    // isEditable folds in document ownership (options.editable alone can be true for a
    // non-owner, who would then get a permission error on drop). The wiring in
    // _cdxWireReorder is gated by options.editable; with no grips rendered it's a no-op.
    ctx.cdxCanReorder = !!this.isEditable;
    // Labels for the codex header/bio-stats. The codex templates render these via
    // context vars (not bare {{localize}}) so they reliably reflect the optional
    // label override settings: the configured override when set, otherwise the
    // localized default. Covers the credits square (expanded + collapsed) and the
    // Obligation / Morality / Conflict bio-stats.
    const cdxLabel = (settingKey, i18nKey) =>
      game.settings.get("starwarsffg", settingKey) || game.i18n.localize(i18nKey);
    ctx.cdxCreditsLabel = cdxLabel("labelCredits", "SWFFG.DescriptionCredits");
    ctx.cdxObligationLabel = cdxLabel("labelObligation", "SWFFG.DescriptionObligation");
    ctx.cdxMoralityLabel = cdxLabel("labelMorality", "SWFFG.DescriptionMorality");
    ctx.cdxConflictLabel = cdxLabel("labelConflict", "SWFFG.DescriptionConflict");
    try {
      ctx.cdxCritCount = this.actor?.items?.filter((i) => i.type === "criticalinjury").length ?? 0;
      // Header pill stacks (specializations / force powers / signature abilities):
      // same shape, all driven by CdxPillStack. Ordered by acquisition — the one
      // bought FIRST (oldest createdTime) comes first → first pill → top of stack.
      // A null createdTime (e.g. carried over by a duplicated actor) sorts oldest;
      // sort then id break exact ties.
      const cdxStack = (type) => (this.actor?.items?.filter((i) => i.type === type) ?? [])
        .sort((a, b) => ((a._stats?.createdTime ?? 0) - (b._stats?.createdTime ?? 0)) || (a.sort - b.sort) || a._id.localeCompare(b._id));
      const specItems = cdxStack("specialization");
      ctx.cdxSpecs = specItems; ctx.cdxSpecCount = specItems.length; ctx.cdxSpecExtra = Math.max(0, specItems.length - 1);
      const forceItems = cdxStack("forcepower");
      ctx.cdxForcePowers = forceItems; ctx.cdxForceCount = forceItems.length; ctx.cdxForceExtra = Math.max(0, forceItems.length - 1);
      const sigItems = cdxStack("signatureability");
      ctx.cdxSigs = sigItems; ctx.cdxSigCount = sigItems.length; ctx.cdxSigExtra = Math.max(0, sigItems.length - 1);
    } catch (e) { ctx.cdxCritCount = 0; }
    ctx.cdxTracks = {};
    try {
      for (const stat of ["wounds", "strain"]) {
        const s = this.actor?.system?.stats?.[stat];
        if (!s || s.max == null) continue;
        ctx.cdxTracks[stat] = this._cdxTrack(Number(s.value) || 0, Number(s.max) || 0);
      }
    } catch (e) { /* leave tracks empty */ }
    // First-two-letters + dot abbreviation per characteristic (e.g. "WILLPOWER"
    // → "WI."), shown by the chip label when the window is too narrow for the
    // full word. A single dot — NOT an ellipsis.
    ctx.cdxCharAbbr = {};
    try {
      for (const [id, c] of Object.entries(ctx.data?.characteristics ?? {})) {
        ctx.cdxCharAbbr[id] = String(c?.label ?? id).slice(0, 2) + ".";
      }
    } catch (e) { /* leave empty */ }
    // Defence melee/ranged → setback-die render data for the locked (display)
    // view. 0 → em-dash, 1–4 → that many black setback dice, 5+ → a plain digit
    // (rules-illegal but shown rather than dropped). Built with an explicit
    // for-loop on purpose: Array.from({length}).map can drop items under some
    // transpilers. In edit mode the template shows plain number inputs instead.
    ctx.cdxDef = {};
    try {
      for (const key of ["melee", "ranged"]) {
        const v = Math.max(0, Math.trunc(Number(this.actor?.system?.stats?.defence?.[key]) || 0));
        const dice = [];
        if (v >= 1 && v <= 4) for (let i = 0; i < v; i++) dice.push(i);
        // Group dice into unbreakable pairs so the layout can only wrap at pair
        // boundaries: 4 → 2×2 (never 3+1), 3 → 2+1 pyramid. A single row still
        // shows when there's room (the whole block stays on one line).
        const pairs = [];
        for (let i = 0; i < dice.length; i += 2) pairs.push(dice.slice(i, i + 2));
        ctx.cdxDef[key] = { value: v, mode: v <= 0 ? "dash" : (v > 4 ? "digit" : "dice"), pairs };
      }
      // Larger of the two dice counts — both rows use it to flip single-row ⇄
      // collapsed at the SAME width (so they switch together, never one of each).
      const poolMax = Math.max(
        ctx.cdxDef.melee.mode === "dice" ? ctx.cdxDef.melee.value : 0,
        ctx.cdxDef.ranged.mode === "dice" ? ctx.cdxDef.ranged.value : 0,
      );
      ctx.cdxDef.melee.poolMax = poolMax;
      ctx.cdxDef.ranged.poolMax = poolMax;
    } catch (e) {
      ctx.cdxDef = { melee: { value: 0, mode: "dash", pairs: [], poolMax: 0 }, ranged: { value: 0, mode: "dash", pairs: [], poolMax: 0 } };
    }
    // Force-chip alignment colour: cdxAlign = effective (baseline + Morality
    // hysteresis), cdxAlignStored = the manually-set baseline (for the selector).
    try {
      const stored = this.actor?.getFlag("starwarsffg", "codexAlignment") ?? "neutral";
      ctx.cdxAlignStored = CDX_ALIGNMENTS.includes(stored) ? stored : "neutral";
      ctx.cdxAlign = cdxEffectiveAlignment(stored, this.actor?.system?.morality?.value);
    } catch (e) { ctx.cdxAlignStored = "neutral"; ctx.cdxAlign = "neutral"; }
    // Ammo chip on expanded weapon cards (system.ammo, gated by the item's
    // config.enableAmmo flag). cdxAmmo is keyed by weapon _id.
    ctx.cdxAmmo = {};
    try {
      for (const item of (this.actor?.items ?? [])) {
        if (item.type !== "weapon") continue;
        if (!item.getFlag("starwarsffg", "config.enableAmmo")) continue;
        ctx.cdxAmmo[item._id] = {
          current: Number(item.system?.ammo?.value) || 0,
          max: Number(item.system?.ammo?.max) || 0,
        };
      }
    } catch (e) { ctx.cdxAmmo = {}; }
    // Short talent activation labels (shown on the talent card's controls line).
    // "Active (Incidental, Out of Turn)" → "Active (OOT)"; others kept as-is.
    try {
      for (const t of (ctx.talentList ?? [])) {
        const act = (t && typeof t.activation === "object") ? (t.activation?.value ?? "") : (t?.activation ?? "");
        t.cdxAct = /out of turn/i.test(String(act)) ? "Active (OOT)" : String(act);
      }
    } catch (e) { /* leave talentList untouched */ }
    // Minion combined-wound-pool track: a grid of member groups, each
    // `unit_wounds` segments wide, filled left-to-right by total wounds suffered.
    // Precomputed here (booleans) rather than via Handlebars arithmetic helpers,
    // which aren't all available. The system already derives quantity.value
    // (alive) and stats.wounds.max (= unit_wounds × quantity.max) from wounds.
    if (this.actor?.type === "minion") {
      try {
        const unit = Math.max(1, Math.trunc(Number(this.actor.system?.unit_wounds?.value) || 1));
        const qmax = Math.max(0, Math.trunc(Number(this.actor.system?.quantity?.max) || 0));
        const woundsVal = Math.max(0, Math.trunc(Number(this.actor.system?.stats?.wounds?.value) || 0));
        const groups = [];
        for (let g = 0; g < qmax; g++) {
          const seg = [];
          for (let s = 0; s < unit; s++) seg.push((g * unit + s) < woundsVal);
          groups.push(seg);
        }
        ctx.cdxMinionGroups = groups;
        // Pre-format the hint here (game.i18n.format is reliable; the {{localize}}
        // Handlebars helper's hash-format support is version-dependent).
        ctx.cdxMinionWoundHint = game.i18n.format("SWFFG.Codex.WoundsSuffered", { n: unit });
      } catch (e) { ctx.cdxMinionGroups = []; }
    }
    // Vehicle derived data: hull/strain damage tracks, hardpoints used (sum of
    // attachment hardpoints), crew count, and a compact cost string.
    if (this.actor?.type === "vehicle") {
      try {
        const s = this.actor.system?.stats ?? {};
        ctx.cdxVehTracks = {
          hull: this._cdxTrack(Number(s.hullTrauma?.value) || 0, Number(s.hullTrauma?.max) || 0),
          strain: this._cdxTrack(Number(s.systemStrain?.value) || 0, Number(s.systemStrain?.max) || 0),
        };
        let hpUsed = 0, crew = 0, crit = 0;
        for (const it of (this.actor.items ?? [])) {
          if (it.type === "shipattachment") hpUsed += Number(it.system?.hardpoints?.value) || 0;
          if (it.type === "shipcrew") crew += 1;
          if (it.type === "criticaldamage") crit += 1;
        }
        ctx.cdxVehHpUsed = hpUsed;
        ctx.cdxVehCrewCount = crew;
        ctx.cdxVehCritCount = crit;
        const cost = Number(s.cost?.value) || 0;
        ctx.cdxVehCost = cost >= 1000 ? `${(cost / 1000).toLocaleString("en-US", { maximumFractionDigits: 1 })}k` : String(cost);
        // Speed-chip background ramp: white at 0, red-orange at full speed.
        const spMax = Number(s.speed?.max) || 0;
        const spVal = Number(s.speed?.value) || 0;
        ctx.cdxVehSpeedPct = spMax > 0 ? Math.max(0, Math.min(100, Math.round((spVal / spMax) * 100))) : 0;
      } catch (e) { ctx.cdxVehTracks = { hull: {}, strain: {} }; ctx.cdxVehHpUsed = 0; ctx.cdxVehCrewCount = 0; ctx.cdxVehCost = "0"; }
    }
    return ctx;
  }

  /** Build a damage track: pips for small thresholds, a bar for large ones.
   *  Colour escalates green → amber → red as current nears threshold. */
  _cdxTrack(cur, max) {
    const ratio = max > 0 ? cur / max : 0;
    const color = ratio >= 0.8 ? "#a51f17" : ratio >= 0.5 ? "#c8902e" : "#3f7d3a";
    if (max <= 0 || max >= 20) return { useBar: true, color, pct: Math.max(0, Math.min(100, Math.round(ratio * 100))) };
    const pips = [];
    for (let i = 0; i < max; i++) pips.push(i < cur);
    return { useBar: false, color, pips };
  }

  /**
   * Surface the per-actor scheme picker in the window-header controls menu (the
   * ⋮ dropdown), rather than as an in-sheet button strip.
   * @override
   */
  _getHeaderControls() {
    const controls = super._getHeaderControls();
    controls.push({
      action: "cdxScheme",
      icon: "fa-solid fa-palette",
      label: "Scheme",
      onClick: () => this._cdxPickScheme(),
    });
    return controls;
  }

  /** Categorised DialogV2 palette picker; writes the actor flag. */
  async _cdxPickScheme() {
    const choice = await cdxPickScheme(this._cdxScheme(), this.actor?.name);
    if (choice) await this.actor.setFlag("starwarsffg", "scheme", choice);
  }

  /**
   * Post-Encounter strain recovery for this actor. Ported from the
   * token-action-hud-ffgsw "strainRecovery" macro (AdmiralDave/Wrycu) so the codex
   * sheet no longer depends on that module: pops a Cool/Discipline dice-pool
   * chooser, rolls the chosen pool, and removes strain equal to
   * success + floor(advantage / 2). Operates directly on this actor (no token
   * selection needed). No-op with a notice if there's no strain to heal.
   */
  async _cdxStrainRecovery() {
    const actor = this.actor;
    const currentStrain = Number(actor?.system?.stats?.strain?.value) || 0;
    if (currentStrain <= 0) {
      ui.notifications?.info(game.i18n.format("SWFFG.Codex.StrainRecovery.NoStrain", { name: actor?.name ?? "" }));
      return;
    }

    const skills = actor.system?.skills ?? {};
    const coolSkill = skills["Cool"];
    const disciplineSkill = skills["Discipline"];
    const coolChar = coolSkill ? actor.system?.characteristics?.[coolSkill.characteristic] : null;
    const disciplineChar = disciplineSkill ? actor.system?.characteristics?.[disciplineSkill.characteristic] : null;
    if (!coolSkill || !disciplineSkill || !coolChar || !disciplineChar) {
      ui.notifications?.error(game.i18n.format("SWFFG.Codex.StrainRecovery.MissingSkill", { name: actor?.name ?? "" }));
      return;
    }

    const buildPool = (skill, characteristic) => {
      const pool = new DicePoolFFG({
        ability: Math.max(characteristic?.value ?? 0, skill?.rank ?? 0),
        boost: skill.boost,
        setback: skill.setback,
        remsetback: skill.remsetback,
        force: skill.force ?? 0,
        advantage: skill.advantage,
        dark: skill.dark,
        light: skill.light,
        failure: skill.failure,
        threat: skill.threat,
        success: skill.success,
        triumph: skill?.triumph ?? 0,
        despair: skill?.despair ?? 0,
      });
      pool.upgrade(Math.min(characteristic.value ?? 0, skill.rank ?? 0));
      return pool;
    };

    const coolPool = buildPool(coolSkill, coolChar);
    const disciplinePool = buildPool(disciplineSkill, disciplineChar);

    // Pre-select the stronger pool (more ability+proficiency+boost, proficiency breaks ties).
    const weight = (p) => p.ability + p.proficiency + p.boost;
    const coolBetter = weight(coolPool) > weight(disciplinePool)
      || (weight(coolPool) === weight(disciplinePool) && coolPool.proficiency > disciplinePool.proficiency);

    const content = `<form class="form cdx-strain-recovery">
      <p>${game.i18n.localize("SWFFG.Codex.StrainRecovery.SelectSkill")}</p>
      <div class="cdx-strain-choices">
        <label><input type="radio" name="selected_skill" value="Cool"${coolBetter ? " checked" : ""} /> ${coolSkill.label} ${coolPool.renderPreview().outerHTML}</label>
        <label><input type="radio" name="selected_skill" value="Discipline"${coolBetter ? "" : " checked"} /> ${disciplineSkill.label} ${disciplinePool.renderPreview().outerHTML}</label>
      </div>
    </form>`;

    await foundry.applications.api.DialogV2.wait({
      window: { title: game.i18n.localize("SWFFG.Codex.StrainRecovery.Title"), icon: "fa-solid fa-laptop-medical" },
      content,
      modal: true,
      rejectClose: false,
      buttons: [{
        action: "recover",
        label: game.i18n.localize("SWFFG.Codex.StrainRecovery.Recover"),
        default: true,
        callback: async (event, button) => {
          const chosen = button.form.elements.selected_skill.value === "Cool" ? coolPool : disciplinePool;
          await this._cdxApplyStrainRecovery(chosen, currentStrain);
        },
      }],
    });
  }

  /**
   * Roll a recovery pool and remove the recovered strain from this actor.
   * Healed = success (+ floor(advantage / 2) when the "advantages heal strain"
   * house rule is enabled), capped at current strain.
   */
  async _cdxApplyStrainRecovery(pool, currentStrain) {
    const actor = this.actor;
    const message = await new game.ffg.RollFFG(pool.renderDiceExpression()).toMessage({
      speaker: { actor },
      flavor: `${game.i18n.localize("SWFFG.Rolling")} ${game.i18n.localize("SWFFG.Codex.StrainRecovery.Title")}...`,
    });
    const result = message.rolls?.[0]?.ffg ?? {};
    const advantageHeals = game.settings.get("starwarsffg", "codexAdvantageHealsStrain");
    const rolled = (result.success ?? 0) + (advantageHeals ? Math.floor((result.advantage ?? 0) / 2) : 0);
    const healed = Math.min(currentStrain, Math.max(0, rolled));
    await ChatMessage.create({
      speaker: { actor },
      content: game.i18n.format("SWFFG.Codex.StrainRecovery.Healed", { quantity: healed }),
    });
    await actor.update({ "system.stats.strain.value": currentStrain - healed });
  }

  /**
   * Wire the crit-card weekly-recovery controls. Elements are recreated every
   * render, so close() needs no teardown; handlers re-check permission and
   * availability live (the marker may be stale mid-refresh). All availability
   * math routes through the shared `availFor` (same as the Handlebars wrapper,
   * the GM bridge, and the unit suite).
   */
  _cdxWireCritRecovery(root) {
    this._cdxCritInFlight ??= new Set();
    const currentDay = () => Math.floor(Number(game.settings.get("starwarsffg", "campaignDay")) || 0);
    const critItem = (ev) => {
      const card = ev.target.closest(".cdx-injury");
      const id = card?.dataset.itemId;
      return { id, item: id ? this.actor?.items?.get(id) : null };
    };

    // Resilience self-heal — owner-only, gated. Strict ordering: every locally
    // constructible prerequisite (permission, availability, skill, pool, roll)
    // runs BEFORE the reservation stamp so a stamp is never spent on a
    // pre-roll failure; a post-reservation toMessage failure KEEPS the stamp.
    root.querySelectorAll(".cdx-inj-resilience").forEach((btn) => {
      btn.addEventListener("click", async (ev) => {
        ev.preventDefault();
        ev.stopPropagation();
        const { id: itemId, item } = critItem(ev);
        if (!item) return;
        if (this._cdxCritInFlight.has(itemId)) return;     // 1. in-flight guard
        this._cdxCritInFlight.add(itemId);
        btn.disabled = true;
        try {
          if (!(item.parent?.isOwner || game.user.isGM)) return;   // 2. permission
          const day = currentDay();
          const stamp = item.system?.resilienceLastAttemptDay ?? item.system?.receivedDay ?? null;
          if (!availFor(stamp, day).attemptable) {                 // 3. availability
            ui.notifications.warn(game.i18n.localize("SWFFG.Codex.CritTrauma.AttemptUnavailable"));
            return;
          }
          // 4. ALL non-dice prerequisites BEFORE any stamp.
          const actor = this.actor;
          const skill = actor?.system?.skills?.["Resilience"];
          const characteristic = skill ? actor?.system?.characteristics?.[skill.characteristic] : null;
          if (!skill || !characteristic) {
            ui.notifications.warn(game.i18n.localize("SWFFG.Codex.CritTrauma.NoResilienceSkill"));
            return;   // no stamp
          }
          const pool = new DicePoolFFG({
            ability: Math.max(characteristic?.value ?? 0, skill?.rank ?? 0),
            boost: skill.boost, setback: skill.setback, remsetback: skill.remsetback,
            force: skill.force ?? 0, advantage: skill.advantage, dark: skill.dark, light: skill.light,
            failure: skill.failure, threat: skill.threat, success: skill.success,
            triumph: skill?.triumph ?? 0, despair: skill?.despair ?? 0,
          });
          pool.upgrade(Math.min(characteristic.value ?? 0, skill.rank ?? 0));
          const flavor = `${game.i18n.localize("SWFFG.Rolling")} ${game.i18n.localize("SWFFG.Codex.CritTrauma.RollResilience")}...`;
          const roll = new game.ffg.RollFFG(pool.renderDiceExpression());   // may throw here → BEFORE the stamp
          // 5. Stamp the reservation.
          await item.update({ "system.resilienceLastAttemptDay": day });
          // 6. Roll + read back, preserving the stamp on any post-reservation failure.
          let message;
          try {
            message = await roll.toMessage({
              speaker: { actor }, flavor,
              flags: { starwarsffg: { critTraumaRecovery: { actorUuid: actor.uuid, itemId, path: "resilience" } } },
            });
          } catch (err) {
            CONFIG.logger?.warn?.("Crit-trauma: resilience roll message failed post-reservation", err);
            ui.notifications.warn(game.i18n.localize("SWFFG.Codex.CritTrauma.RollFailedNoMessage"));
            return;   // KEEP the stamp — a genuine attempt occurred, no free reroll
          }
          const net = message.rolls?.[0]?.ffg?.success ?? 0;   // net of failures
          // 7. Resolve — no equality-based rollback anywhere.
          if (net >= 1) await item.delete();
        } finally {
          this._cdxCritInFlight.delete(itemId);
          btn.disabled = false;
        }
      });
    });

    // Medicine failure marker — always shown to permitted viewers. Owner stamps
    // locally; a permitted non-owner forwards to the GM.
    root.querySelectorAll(".cdx-inj-medfail").forEach((btn) => {
      btn.addEventListener("click", async (ev) => {
        ev.preventDefault();
        ev.stopPropagation();
        const { id: itemId, item } = critItem(ev);
        if (!item) return;
        const day = currentDay();
        if (!availFor(item.system?.medicineLastAttemptDay ?? null, day).attemptable) return;
        if (item.isOwner) await item.update({ "system.medicineLastAttemptDay": day });
        else await applyCritRecoveryAttempt(this.actor, itemId, "medicine");
      });
    });

    // Vehicle Mechanics failure marker — house-rule + type gated (the owner-local
    // path bypasses the GM bridge, and the button can be stale mid-refresh).
    root.querySelectorAll(".cdx-inj-mechfail").forEach((btn) => {
      btn.addEventListener("click", async (ev) => {
        ev.preventDefault();
        ev.stopPropagation();
        const { id: itemId, item } = critItem(ev);
        if (!item) return;
        if (game.settings.get("starwarsffg", "vehicleCritWeeklyLimit") !== true) return;
        if (item.type !== "criticaldamage") return;
        const day = currentDay();
        if (!availFor(item.system?.mechanicsLastAttemptDay ?? null, day).attemptable) return;
        if (item.isOwner) await item.update({ "system.mechanicsLastAttemptDay": day });
        else await applyCritRecoveryAttempt(this.actor, itemId, "mechanics");
      });
    });
  }
};

/** Codex sheet for character / rival / nemesis / minion / vehicle. */
export class CodexActorSheet extends CodexSchemeMixin(ActorSheetFFG) {
  /** @override */
  get template() {
    const t = this.actor.type;
    const name = ["character", "rival", "nemesis"].includes(t) ? "character" : t;
    return `${CDX_TEMPLATES}/codex-${name}.html`;
  }
}

/**
 * Codex Adversary sheet — the system's "Adversary Sheet" is a character-type
 * actor sheet (used to build NPCs for compendium export), structurally the same
 * as the character sheet, so it reuses codex-character.html. We keep it as a
 * separate selectable class so a GM can pick it via the ⚙ Sheet picker; it
 * inherits AdversarySheetFFG's adversary-specific getData (sizing, specialization
 * refresh).
 */
export class CodexAdversarySheet extends CodexSchemeMixin(AdversarySheetFFG) {
  /** @override */
  get template() {
    return `${CDX_TEMPLATES}/codex-character.html`;
  }
}

/**
 * Re-render every open Codex sheet — used by the campaignDay / vehicleCritWeeklyLimit
 * setting onChange handlers (live-refresh path 1) so open crit cards recompute their
 * availability countdowns. Self-contained; imported by settings-helpers.js (cycle-safe
 * direction — settings-helpers is not imported here).
 */
export function refreshOpenCodexSheets() {
  for (const app of foundry.applications.instances.values()) {
    if (app.rendered && (app instanceof CodexActorSheet || app instanceof CodexAdversarySheet)) app.render();
  }
}

import { FFGDocumentSheet } from "./ffg-document-sheet.js";

/**
 * Native shared base for the system's actor sheets (`ActorSheetFFG` and its
 * `AdversarySheetFFG` variant) on top of the document-sheet base
 * `FFGDocumentSheet`. Adds the actor-specific machinery: token-aware title,
 * the `actor`/`token` accessors, the item/effect/actor/folder drag-drop suite
 * (`_onDrop*` / `_onSortItem` / `_onDragStart`), the configure-(prototype-)token
 * header controls, and the `_getSubmitData` AE-override stripping. The
 * `dragDrop` selector here is wired by `FFGDocumentSheet._activateCoreListeners`.
 *
 * Subclasses provide their data via `getData()` and listeners via
 * `activateListeners(html)` (bridged to native `_prepareContext`/`_onRender` by
 * the base). See docs/superpowers/plans/2026-05-31-v2-full-migration.md.
 */
export class FFGActorSheet extends FFGDocumentSheet {
  static DEFAULT_OPTIONS = {
    position: { width: 800, height: 720 },
    window: { resizable: true },
    // V1-parity submit flags read by the manual submit pipeline in the base.
    submitOnChange: true,
    submitOnClose: true,
    closeOnSubmit: false,
    baseApplication: "ActorSheet",
    dragDrop: [{ dragSelector: ".items-list .item, .cdx-card" }],
    secrets: [{ parentSelector: ".editor" }],
  };

  get title() {
    if (!this.actor.isToken) return this.actor.name;
    return `[${game.i18n.localize(TokenDocument.metadata.label)}] ${this.actor.name}`;
  }

  get actor() {
    return this.object;
  }

  get token() {
    return this.object.token || this._token || null;
  }

  async close(options = {}) {
    this._token = null;
    return super.close(options);
  }

  /**
   * Re-fire the conventional `renderActorSheetV2` hook.
   *
   * FFG actor sheets extend `DocumentSheetV2` directly rather than
   * `foundry.applications.sheets.ActorSheetV2`, so `ActorSheetV2` is never in the
   * inheritance chain. Foundry fires `render<ClassName>` for each class in that
   * chain (ApplicationV2#_doEvent), which means it fires `renderDocumentSheetV2`
   * and `renderApplicationV2` but NOT `renderActorSheetV2`. Modules that inject
   * actor-sheet header controls hook the standard `renderActorSheetV2` anchor (the
   * V2 successor to V1's `renderActorSheet`), so the migration silently dropped it.
   *
   * Re-emit it here for every FFG actor sheet, matching Foundry's render-hook
   * signature: (application, element, context, options). Runs after super so the
   * frame/header DOM and our own listeners are already in place.
   */
  async _onRender(context, options) {
    await super._onRender(context, options);
    Hooks.callAll("renderActorSheetV2", this, this.element, context, options);
  }

  /** Actor popout editors use a smaller height floor than item sheets (base = 400). */
  get _popoutEditorMinHeight() { return 200; }

  getData(options = {}) {
    const context = super.getData(options);
    context.actor = this.object;
    context.items = context.data.items;
    context.items.sort((a, b) => (a.sort || 0) - (b.sort || 0));
    context.effects = context.data.effects;
    return context;
  }

  _getLegacyRootClasses(context = {}) {
    const classes = super._getLegacyRootClasses(context);
    const sheetClass = {
      character: "character",
      rival: "character",
      nemesis: "character",
      minion: "minion",
      vehicle: "vehicle",
      homestead: "homestead",
    }[this.actor.type];

    if (sheetClass) classes.push(sheetClass);
    return classes;
  }

  _getHeaderControls() {
    const controls = super._getHeaderControls();
    if (!this.isEditable) return controls;

    if (this.actor.isToken) {
      controls.push({
        action: "configureToken",
        icon: "fa-regular fa-circle-user",
        label: "DOCUMENT.Token",
        onClick: this._onConfigureToken.bind(this),
      });
    } else {
      controls.push({
        action: "configurePrototypeToken",
        icon: "fa-solid fa-circle-user",
        label: "TOKEN.TitlePrototype",
        onClick: this._onConfigurePrototypeToken.bind(this),
      });
    }

    return controls;
  }

  _onConfigurePrototypeToken() {
    new CONFIG.Token.prototypeSheetClass({
      prototype: this.actor.prototypeToken,
      position: {
        left: Math.max(this.position.left - 570, 10),
        top: this.position.top,
      },
    }).render({ force: true });
  }

  _onConfigureToken() {
    this.actor.token?.sheet?.render({ force: true });
  }

  _getSubmitData(updateData = {}) {
    const data = super._getSubmitData(updateData);
    // `overrides` can be undefined (no active effects applied yet); flattenObject
    // throws on Object.keys(undefined), which would abort submit-on-close and
    // leave the × button unable to close the sheet. Guard with {}.
    const overrides = foundry.utils.flattenObject(this.actor.overrides ?? {});
    for (const k of Object.keys(overrides)) delete data[k];
    return data;
  }

  _canDragStart(_selector) {
    return this.isEditable;
  }

  _canDragDrop(_selector) {
    return this.isEditable;
  }

  _onDragStart(event) {
    const li = event.currentTarget;
    if ("link" in event.target.dataset) return;

    let dragData;
    if (li.dataset.itemId) {
      const item = this.actor.items.get(li.dataset.itemId);
      dragData = item?.toDragData();
    }
    if (li.dataset.effectId) {
      const effect = this.actor.effects.get(li.dataset.effectId);
      dragData = effect?.toDragData();
    }
    if (!dragData) return;

    event.dataTransfer.setData("text/plain", JSON.stringify(dragData));
  }

  async _onDrop(event) {
    const data = foundry.applications.ux.TextEditor.implementation.getDragEventData(event);
    const actor = this.actor;
    const allowed = Hooks.call("dropActorSheetData", actor, this, data);
    if (allowed === false) return;

    switch (data.type) {
      case "ActiveEffect":
        return this._onDropActiveEffect(event, data);
      case "Actor":
        return this._onDropActor(event, data);
      case "Item":
        return this._onDropItem(event, data);
      case "Folder":
        return this._onDropFolder(event, data);
      case "Transfer":
        // The FFG cross-actor transfer payload. On codex sheets the transfer
        // DragDrop's drop target (.cdx-sheet, display:contents) never receives the
        // event, so the drop lands here on the native root handler instead. Route
        // it to the transfer handler; on stock sheets the transfer handler fires
        // first on .sheet-body and stopPropagation() keeps it from reaching here.
        return this._onTransferItemDrop(event);
      default:
        return undefined;
    }
  }

  async _onDropActiveEffect(_event, data) {
    const effect = await ActiveEffect.implementation.fromDropData(data);
    if (!this.actor.isOwner || !effect) return false;
    if (effect.target === this.actor) return false;
    return ActiveEffect.implementation.create(effect.toObject(), { parent: this.actor });
  }

  async _onDropActor(_event, _data) {
    if (!this.actor.isOwner) return false;
    return false;
  }

  async _onDropItem(event, data) {
    if (!this.actor.isOwner) return false;
    const item = await Item.implementation.fromDropData(data);
    const itemData = item.toObject();

    if (this.actor.uuid === item.parent?.uuid) return this._onSortItem(event, itemData);
    return this._onDropItemCreate(itemData, event);
  }

  async _onDropFolder(event, data) {
    if (!this.actor.isOwner) return [];
    const folder = await Folder.implementation.fromDropData(data);
    if (folder.type !== "Item") return [];
    const droppedItemData = await Promise.all(folder.contents.map(async (item) => {
      if (!(item instanceof Item)) item = await foundry.utils.fromUuid(item.uuid);
      return item.toObject();
    }));
    return this._onDropItemCreate(droppedItemData, event);
  }

  async _onDropItemCreate(itemData, _event) {
    itemData = Array.isArray(itemData) ? itemData : [itemData];
    // V14 replaced the core ActiveEffect `duration` model with {value, units,
    // expiry}; `value` must be an integer when `units` is set. Legacy effects
    // (e.g. the system's own "(inherent)" ones) migrate to {value: null,
    // units: "seconds"} -- the invalid "units but no value" state -- which makes
    // createEmbeddedDocuments throw a DataModelValidationError and aborts the drop.
    // This system tracks effect duration in `flags.starwarsffg.duration`, so the core
    // field is unused here; strip the malformed duration so Foundry applies a valid
    // (permanent) default. Integer values are left intact so real durations survive.
    for (const data of itemData) {
      for (const effect of data.effects ?? []) {
        if (effect?.duration && !Number.isInteger(effect.duration.value)) {
          delete effect.duration;
        }
      }
    }
    return this.actor.createEmbeddedDocuments("Item", itemData);
  }

  _onSortItem(event, itemData) {
    const items = this.actor.items;
    const source = items.get(itemData._id);
    const dropTarget = event.target.closest("[data-item-id]");
    if (!dropTarget) return;
    const target = items.get(dropTarget.dataset.itemId);
    if (!source || !target || source.id === target.id) return;

    const siblings = [];
    for (const el of dropTarget.parentElement.children) {
      const siblingId = el.dataset.itemId;
      if (siblingId && (siblingId !== source.id)) siblings.push(items.get(el.dataset.itemId));
    }

    const sortUpdates = foundry.utils.performIntegerSort(source, { target, siblings });
    const updateData = sortUpdates.map((u) => {
      const update = u.update;
      update._id = u.target._id;
      return update;
    });

    return this.actor.updateEmbeddedDocuments("Item", updateData);
  }
}

import PopoutEditor from "../popout-editor.js";

const { DocumentSheetV2, HandlebarsApplicationMixin, DialogV2 } = foundry.applications.api;

/**
 * Native shared base for the system's document sheets (item sheets as of the
 * V2-full migration Stage 3; actor sheets join in Stage 4). Extends Foundry's
 * ApplicationV2 `DocumentSheetV2` directly — no V1 compatibility shim.
 *
 * Provides the system-wide sheet machinery on top of `DocumentSheetV2`:
 *   - submit coalescing (`_onSubmit`) with change-stream batching,
 *   - the inline ProseMirror editor lifecycle (`_activateEditor` / `_saveEditor`),
 *   - a per-document active-tab cache, drag/drop wiring, header-control
 *     projection, dblclick-to-minimize, and the interactive-resize floor.
 *
 * Subclasses provide their data via `getData()` (bridged to native
 * `_prepareContext`) and their listeners via `activateListeners(html)` (bridged
 * to native `_onRender`). The native V2 form pipeline is intentionally neutered
 * (`form.handler = null`); submission flows through the manual `_onSubmit` so
 * the V1 submit-on-change / submit-on-close semantics and the coalescing loop
 * are preserved. See docs/superpowers/plans/2026-05-31-v2-full-migration.md.
 */
export class FFGDocumentSheet extends HandlebarsApplicationMixin(DocumentSheetV2) {
  /**
   * Per-document active-tab cache keyed by `${appName}:${documentUuid}`. Used
   * to persist the active sheet tab across close-and-reopen within a single
   * page session. We intentionally avoid `document.setFlag` here: writing a
   * flag triggers a re-render of the sheet, which re-runs `_activateCoreListeners`
   * and rebinds the `Tabs` instance — racing with the user's click. An
   * in-memory map sidesteps that loop and keeps ephemeral UI state out of the
   * persisted document data. Lost on full page reload, which is acceptable.
   */
  static _activeTabCache = new Map();

  static DEFAULT_OPTIONS = {
    tag: "div",
    // `app`/`window-app`/`sheet` are the V1-parity hooks; `application` is added
    // by ApplicationV2. `themed`/`theme-light` are hardcoded to match the compat
    // base (FFGDocumentSheetV2) exactly: the system has always shipped its sheets
    // forced to V13 light theme. Letting DocumentSheetV2 derive the theme natively
    // dropped both classes (no per-document theme is configured), which changed the
    // V13 CSS variables the skin/layout depend on — a visual regression (notably
    // the character/rival/nemesis tab-strip height). Keep them for identical output.
    classes: ["app", "window-app", "sheet", "themed", "theme-light"],
    window: {
      contentTag: "form",
      contentClasses: [],
      resizable: true,
    },
    // The native V2 form pipeline is neutered (`handler: null`) so the manual
    // `_onSubmit` is the single submission path; see _initializeApplicationOptions.
    // The *top-level* submit flags below are the V1-parity options the manual
    // pipeline reads via `this.options.*` — distinct from the nested `form.*`
    // framework flags. Subclasses set their own values.
    form: {
      handler: null,
      submitOnChange: false,
      closeOnSubmit: false,
    },
    editable: true,
    submitOnChange: false,
    submitOnClose: false,
    closeOnSubmit: false,
    sheetConfig: true,
    scrollY: [],
    tabs: [],
    dragDrop: [],
    secrets: [],
  };

  static PARTS = {
    sheet: {
      root: true,
      template: "",
    },
  };

  constructor(...args) {
    super(...args);
    this.appId = this.id;
    this._dragDrop = [];
    this._tabs = [];
    this._submitting = false;
    this.editors = {};
    this._token = this.options.token ?? null;
  }

  /**
   * Neuter V2's native form pipeline. Submission is handled manually by
   * `_onChangeInput` / `_onSubmit` to preserve V1 submit-on-change /
   * submit-on-close semantics and the submit-coalescing in `_onSubmit`.
   * Setting `handler: null` removes DocumentSheetV2's own form handler so the
   * manual submit listener bound in `_onRender` is the only submit path. We do
   * this defensively in addition to the DEFAULT_OPTIONS `form.handler: null`.
   */
  _initializeApplicationOptions(options) {
    const initialized = super._initializeApplicationOptions(options);
    initialized.form = {
      ...initialized.form,
      submitOnChange: false,
      closeOnSubmit: false,
      handler: null,
    };
    return initialized;
  }

  get object() {
    return this.document;
  }

  get form() {
    return this.element?.querySelector("form") ?? super.form;
  }

  get isEditable() {
    return (this.options.editable !== false) && super.isEditable;
  }

  /**
   * Disable/enable all form fields for non-editable sheets.
   *
   * DocumentSheetV2 calls this from `_onRender` whenever `!isEditable` (e.g. a
   * locked-compendium item, a limited-permission item, or `flags.readonly`).
   * The native implementation computes its content element as
   * `form.querySelector(".window-content")`, which assumes the form is a *child*
   * of `.window-content`. In our layout the content form element *is* the
   * `.window-content` (tag:"div" + window.contentTag:"form"), so that lookup
   * returns null and the native method throws on `contentEl.querySelectorAll`.
   * Override to fall back to the form itself. Without this, opening any
   * non-editable item/actor sheet crashes during render.
   * @override
   */
  _toggleDisabled(disabled) {
    const form = this.form;
    if (!form) return;
    const framed = this.options.window.frame;
    for (const element of form.elements) {
      if (!framed || element.closest(".window-content")) element.disabled = disabled;
    }
    const contentEl = (framed ? form.querySelector(".window-content") : form) ?? form;
    for (const input of contentEl.querySelectorAll("input[type=image]")) {
      input.disabled = disabled;
    }
    for (const img of contentEl.querySelectorAll("img[data-edit]")) {
      img.classList.toggle("disabled", disabled);
    }
  }

  get _activeTabCacheKey() {
    const uuid = this.document?.uuid;
    if (!uuid) return null;
    return `${this.constructor.name}:${uuid}`;
  }

  get template() {
    return this.options.template;
  }

  // NOTE: `toObject(false)` returns the raw source document data, not the
  // transformed view that ActiveEffects produce. This matches V1 ActorSheet
  // semantics and is required by edit-mode workflows that need unmodified
  // values (see ActorHelpers.beginEditMode).
  getData(_options = {}) {
    const data = this.document.toObject(false);
    const isEditable = this.isEditable;
    return {
      cssClass: isEditable ? "editable" : "locked",
      editable: isEditable,
      document: this.document,
      data,
      limited: this.document.limited,
      options: this.options,
      owner: this.document.isOwner,
      title: this.title,
    };
  }

  _configureRenderParts(options) {
    return {
      sheet: {
        root: true,
        template: this.template,
        scrollable: this.options.scrollY ?? [],
      },
    };
  }

  async _prepareContext(options) {
    return this.getData(options);
  }

  /**
   * Capture the content scroll BEFORE the re-render replaces it. ApplicationV2
   * reuses the content <form> but swaps its innerHTML, which resets scrollTop --
   * so e.g. ticking a tree node's "learned" checkbox (which submits + re-renders)
   * would jump the sheet back to the top. The old DOM is still mounted here, so we
   * read the current scroll; `_onRender` restores it once the new content is in
   * place and the form's overflow has been re-applied. @override
   */
  async _preRender(context, options) {
    await super._preRender(context, options);
    this._ffgScrollTop = this.form?.scrollTop || 0;
  }

  async _onRender(context, options) {
    await super._onRender(context, options);

    const form = this.form;
    if (form) {
      this._applyLegacyRootClasses(form, context);
      form.dataset.appid = this.appId;
      // ApplicationV2 reuses the content <form> element across re-renders
      // (only its innerHTML is replaced), so attaching submit/change handlers
      // on every _onRender stacks duplicate listeners. Each duplicate fires
      // its own submit; with submit-coalescing that becomes one redundant
      // document.update per accumulated render. Attach exactly once per form
      // element, guarded by a dataset flag.
      if (!form.dataset.ffgListenersBound) {
        form.dataset.ffgListenersBound = "1";
        form.addEventListener("submit", this._onSubmit.bind(this));
        form.addEventListener("change", this._onChangeInput.bind(this));
      }
    }
    this.element.dataset.appid = this.appId;

    this._projectLegacyHeaderControls();
    this.element.querySelector(":scope > .window-resize-handle")?.classList.add("window-resizable-handle");

    this._bindHeaderMinimize();

    const html = $(form ?? this.element);
    this._activateCoreListeners(html);
    this.activateListeners(html);
    this._callLegacyRenderHook(html, context);
    this._activateEditors();

    // --- Window size stability: no auto-resize on re-render ---
    // ApplicationV2 re-forces a position dimension back to "auto" on EVERY
    // re-render whenever the static `this.options.position` dimension is "auto"
    // (the base ApplicationV2 default for any dimension a subclass didn't pin in
    // DEFAULT_OPTIONS -- e.g. item sheets set only `width`, so `height` stays
    // "auto"). That re-measures the content and snaps the window to fit it on
    // any change (selecting an upgrade, editing a field...). We only want the
    // window to resize via the resize handle or minimize. Once the LIVE position
    // has a numeric dimension (the per-type sizing sets it), copy it into
    // `this.options.position` so the auto-forcing stops -- this mirrors what V13
    // itself does after a manual resize (#onResize writes options.position[dim]).
    // Skip while (un)minimizing so we don't freeze the collapsed-header height.
    if (!this.minimized && !this._minimizing && this.options?.position) {
      for (const dim of ["width", "height"]) {
        if (typeof this.position?.[dim] === "number" && this.options.position[dim] === "auto") {
          this.options.position[dim] = this.position[dim];
        }
      }
    }

    // Restore the pre-render content scroll (captured in _preRender) now that the
    // new content is in place and activateListeners has re-applied the form's
    // overflow, so a re-render (e.g. a tree checkbox submit) keeps the scroll.
    if (this._ffgScrollTop && this.form) this.form.scrollTop = this._ffgScrollTop;
  }

  _applyLegacyRootClasses(form, context = {}) {
    form.setAttribute("autocomplete", "off");
    form.classList.toggle("editable", this.isEditable);
    form.classList.toggle("locked", !this.isEditable);

    for (const cls of this._getLegacyRootClasses(context)) {
      if (cls) form.classList.add(cls);
    }
  }

  /**
   * Actions from V13's controls-dropdown that we mirror as inline,
   * V1-style labeled links in the window header. Empty by default: the
   * V13 `×` icon already covers Close, and every other dropdown entry
   * (Configure Sheet, Prototype Token, Copy Document ID, etc.) is fine
   * to stay inside the `⋮` menu. The only inline header link the user
   * actually wants is Sheet Options, which ActorOptions/ItemOptions
   * inject directly — not via this projection.
   */
  static LEGACY_HEADER_ACTIONS = new Set();

  /**
   * Lower bound for interactive resize. ApplicationV2's setPosition writes
   * width/height unconditionally, so without this a user can drag the resize
   * handle down to a few pixels and leave a sheet unusable. Subclasses with
   * type-specific floors override `_minDimensions()`.
   */
  static MIN_DIMENSIONS = { width: 300, height: 200 };

  _minDimensions() {
    return this.constructor.MIN_DIMENSIONS;
  }

  /**
   * Restore V1's dblclick-header-to-minimize toggle. V13's ApplicationV2 only
   * exposes minimize via the controls-dropdown; dblclicking the header
   * otherwise just selects the title text (visible as a black highlight).
   * Listen in the capture phase so we run before any V13 internal handler
   * that might stop propagation, and dedupe via a dataset flag.
   */
  _bindHeaderMinimize() {
    const header = this.element?.querySelector(":scope > .window-header");
    if (!header || header.dataset.ffgMinimizeBound) return;
    header.dataset.ffgMinimizeBound = "1";
    header.addEventListener("dblclick", (event) => {
      // V13's ApplicationV2 already binds its own #onWindowDoubleClick on
      // the same header in the bubble phase, and its filter only ignores
      // elements with a `data-action` attribute. So a dblclick on our
      // injected Sheet Options <a>, on legacy-header-action links, or on
      // anything else without data-action would still minimize via V13's
      // handler. Run in capture phase and, when the dblclick is on an
      // interactive control, stopImmediatePropagation to prevent V13's
      // handler from also firing.
      if (event.target.closest("button, a, [data-action], input, select, label, .ffg-sheet-options, .legacy-header-action")) {
        event.stopImmediatePropagation();
        return;
      }
      // Title-area dblclick: V13 will handle the actual minimize itself,
      // we just need to not interfere. Clear the text selection the first
      // click leaves behind.
      window.getSelection?.()?.removeAllRanges?.();
    }, true);
  }

  setPosition(position = {}) {
    // V13's _updatePosition reads `el.parentElement.offsetWidth` and only
    // guards against the element itself being null, not against the element
    // being detached. If setPosition fires before the element is inserted
    // into the DOM (race during initial render, especially when reopening a
    // sheet) it throws a "Cannot read properties of null (reading
    // 'offsetWidth')". Skip the call in that case -- V13 will reapply the
    // position via its render flow once the element is attached.
    if (!this.element?.parentElement) return position;
    // While the window is minimizing or already minimized, V13 calls
    // setPosition with header-only dimensions (~30px height). Clamping those
    // up to the interactive-resize minimum prevents the collapse and leaves
    // the window stuck at an awkward in-between size.
    if (this._minimizing || this.minimized) return super.setPosition(position);
    const min = this._minDimensions();
    const clamped = { ...position };
    if (typeof clamped.width === "number" && clamped.width < min.width) clamped.width = min.width;
    if (typeof clamped.height === "number" && clamped.height < min.height) clamped.height = min.height;
    return super.setPosition(clamped);
  }

  async minimize(...args) {
    this._minimizing = true;
    try {
      return await super.minimize(...args);
    } finally {
      this._minimizing = false;
    }
  }

  _projectLegacyHeaderControls() {
    const header = this.element.querySelector(":scope > .window-header");
    const dropdown = this.element.querySelector(":scope > menu.controls-dropdown");
    if (!header) return;

    header.querySelectorAll(":scope > .legacy-header-action").forEach((el) => el.remove());

    if (!dropdown) return;
    const allowed = this.constructor.LEGACY_HEADER_ACTIONS;
    const sources = [
      ...dropdown.querySelectorAll(":scope > .header-control[data-action]"),
      ...header.querySelectorAll(":scope > button.header-control[data-action='close']"),
    ].filter((source) => allowed.has(source.dataset.action));
    if (!sources.length) return;

    const anchor = header.querySelector(":scope > [data-action='toggleControls']") ?? header.lastElementChild;
    for (const source of sources) {
      const action = source.dataset.action;
      const button = source.matches("button") ? source : source.querySelector("button");
      const rawLabel = (source.querySelector(".control-label")?.textContent ?? source.dataset.tooltip ?? source.ariaLabel ?? button?.ariaLabel ?? "").trim();
      const label = this._getLegacyHeaderActionLabel(action, rawLabel);
      if (!action || !label) continue;

      const link = document.createElement("a");
      link.className = "legacy-header-action";
      link.dataset.action = action;
      link.innerHTML = `${source.querySelector("i")?.outerHTML ?? ""} <span>${label}</span>`;
      link.addEventListener("click", (event) => {
        event.preventDefault();
        event.stopPropagation();
        button?.click();
      });
      // Keep the header's window-drag (ApplicationV2 `#onWindowDragStart`) from
      // engaging on a press that begins on this link: a press with any cursor
      // movement otherwise triggers `header.setPointerCapture()`, which eats the
      // synthesized `click`. Same mechanism/fix as the Sheet Options button in
      // actor-ffg-options.js / item-ffg-options.js. (LEGACY_HEADER_ACTIONS is
      // empty today, so no links are projected -- this guards the path if it is
      // ever populated.)
      link.addEventListener("pointerdown", (event) => event.stopPropagation());
      header.insertBefore(link, anchor);
    }
  }

  _getLegacyHeaderActionLabel(action, fallback) {
    switch (action) {
      case "configureSheet":
        return "Sheet";
      case "close":
        return game.i18n.localize("SWFFG.ButtonClose") || "Close";
      default:
        return fallback;
    }
  }

  _getLegacyRootClasses(_context = {}) {
    return [];
  }

  _callLegacyRenderHook(html, context = {}) {
    const documentName = this.document?.documentName;
    if (!documentName) return;

    Hooks.callAll(`render${documentName}Sheet`, this, html, context);
  }

  _callLegacyCloseHook(html) {
    const documentName = this.document?.documentName;
    if (!documentName) return;

    Hooks.callAll(`close${documentName}Sheet`, this, html);
  }

  async close(options = {}) {
    const closeOptions = this.minimized && options.animate !== false ? { ...options, animate: false } : options;
    // Block any render attempts that fire while we're closing. The submit-on-
    // close path runs `document.update`, which can trigger BOTH Foundry's
    // auto-render-on-update hook AND an explicit `this.render(true)` from
    // legacy helpers (see ItemHelpers.itemUpdate / ActorHelpers.updateActor).
    // Either one will race with super.close and re-attach the DOM, leaving
    // the user feeling like × did nothing. The `_closing` flag is consulted
    // by our overridden `render()` to bail out cleanly.
    this._closing = true;
    try {
      if (this.options.submitOnClose && closeOptions.submit !== false && this.form && this.isEditable) {
        const event = new Event("submit", { cancelable: true });
        try {
          await this._onSubmit(event, { preventClose: true, render: false });
        } catch (err) {
          // A failed submit-on-close must NEVER trap the window open: the user
          // clicked × and expects it to close. Log and continue to tear down
          // (this matches Foundry's own close, which does not block on submit).
          // This was the minion close-button bug: submit-on-close threw and the
          // unguarded await aborted close() before super.close() ever ran.
          console.error("starwarsffg | submit-on-close failed; closing anyway", err);
        }
      }
      // Fire while the form is still in the DOM so legacy listeners can inspect it.
      const form = this.form;
      if (form) this._callLegacyCloseHook($(form));
      return await super.close(closeOptions);
    } catch (err) {
      console.error("starwarsffg | sheet failed to close (super.close threw)", err);
      throw err;
    } finally {
      this._closing = false;
    }
  }

  async render(options, _options) {
    if (this._closing) return this;
    return super.render(options, _options);
  }

  activateListeners(_html) {}

  _activateCoreListeners(html) {
    const root = html[0];
    if (!root) return;

    const cacheKey = this._activeTabCacheKey;
    this._tabs = (this.options.tabs ?? []).map((tabConfig) => {
      const cached = cacheKey ? this.constructor._activeTabCache.get(cacheKey) : undefined;
      const tabs = new foundry.applications.ux.Tabs({
        ...tabConfig,
        initial: cached ?? this._sheetTab ?? tabConfig.initial,
        callback: (_event, _tabs, active) => {
          this._sheetTab = active;
          if (cacheKey) this.constructor._activeTabCache.set(cacheKey, active);
        },
      });
      tabs.bind(root);
      return tabs;
    });

    this._dragDrop = (this.options.dragDrop ?? []).map((dragDropConfig) => {
      const dragDrop = new foundry.applications.ux.DragDrop({
        ...dragDropConfig,
        permissions: {
          dragstart: this._canDragStart.bind(this),
          drop: this._canDragDrop.bind(this),
          ...(dragDropConfig.permissions ?? {}),
        },
        callbacks: {
          dragstart: this._onDragStart.bind(this),
          dragover: this._onDragOver.bind(this),
          drop: this._onDrop.bind(this),
          ...(dragDropConfig.callbacks ?? {}),
        },
      });
      dragDrop.bind(root);
      return dragDrop;
    });

    if (this.isEditable) {
      html.find("img[data-edit]").on("click", this._onEditImage.bind(this));
      html.find("button.file-picker").on("click", this._activateFilePicker.bind(this));
    }
  }

  /**
   * Wire the V1 `{{editor}}` helper's Edit button to mount a ProseMirror
   * editor inline. V13's HandlebarsApplicationMixin does not auto-bind this;
   * the V1 FormApplication did. The helper emits
   * `.editor-content[data-edit="<name>"]` with a sibling `.editor-edit`
   * anchor inside a `.editor` container.
   */
  _activateEditors() {
    const root = this.element;
    if (!root) return;
    for (const content of root.querySelectorAll(".editor-content[data-edit]")) {
      const name = content.dataset.edit;
      if (!name) continue;
      const containerEl = content.closest(".editor");
      const button = containerEl?.querySelector(".editor-edit");
      if (!button || button.dataset.editorBound) continue;
      button.dataset.editorBound = "1";
      button.addEventListener("click", (event) => {
        event.preventDefault();
        this._activateEditor(name, content, containerEl, button);
      });
    }
  }

  async _activateEditor(name, contentEl, containerEl, buttonEl) {
    // A live editor is already open for this field — nothing to do.
    if (this.editors[name]?.instance?.view) return;
    // A stale/half-open entry (e.g. a prior save that failed to mount) would
    // otherwise permanently brick the edit button via the guard above. Clear
    // it so this click can mount a fresh editor.
    if (this.editors[name]) this._destroyEditor(name);
    const initial = foundry.utils.getProperty(this.document, name) ?? "";
    const { ProseMirrorEditor } = foundry.applications.ux;

    // Register a FormDataExtended-compatible entry BEFORE create() resolves.
    // FormDataExtended iterates `editors` and, for each entry whose
    // `options.engine === "prosemirror"`, serializes the live document out of
    // `instance.view`. Omitting this shape causes both the editor instance
    // AND the matching [data-edit] node to be skipped -- silently losing
    // unsaved content on submit-on-close.
    this.editors[name] = {
      instance: null,
      options: { engine: "prosemirror", target: name, button: true, owner: this.isEditable },
      active: true,
      button: buttonEl,
      container: containerEl,
    };

    const editor = await ProseMirrorEditor.create(contentEl, initial, {
      document: this.document,
      fieldName: name,
      relativeLinks: true,
      plugins: {
        // destroyOnSave:false -- our _saveEditor owns the teardown. If the menu
        // destroyed the view on "Save and Close", it would race _saveEditor's
        // _onSubmit, which reads the (now dead) view via FormDataExtended and
        // saves empty, and would leave this.editors[name] stale (bricking the
        // edit button). Letting our code destroy keeps the view alive until
        // after the value is read and the document updated.
        menu: ProseMirror.ProseMirrorMenu.build(ProseMirror.defaultSchema, {
          destroyOnSave: false,
          onSave: () => this._saveEditor(name, { remove: true }),
        }),
        keyMaps: ProseMirror.ProseMirrorKeyMaps.build(ProseMirror.defaultSchema, {
          onSave: () => this._saveEditor(name, { remove: true }),
        }),
      },
    });

    this.editors[name].instance = editor;
    // The `prosemirror` class on the container is what the change-handler
    // editor guard (_onChangeInput) looks for. Without it, every keystroke
    // inside the editor bubbles a `change` to the form and triggers a full
    // submit. V1 added the engine class to the .editor container on mount;
    // mirror that here.
    containerEl.classList.add("editor-active", "prosemirror");
    // Hide the "edit" pencil while editing: clicking it mid-edit re-enters
    // _activateEditor and breaks the live view. Inline style so it wins over
    // any theme CSS. The post-save re-render provides a fresh, visible button.
    if (buttonEl) buttonEl.style.display = "none";
  }

  async _saveEditor(name, { remove = true } = {}) {
    const state = this.editors[name];
    if (!state?.instance?.view || state._saving) return;
    state._saving = true;
    // Route through the normal submit pipeline so ItemHelpers.itemUpdate /
    // ActorHelpers.updateActor run AE sync, talent propagation, attribute
    // reshaping, and XP logging. FormDataExtended pulls the editor value out
    // of state.instance via the engine="prosemirror" entry on this.editors --
    // the view is still alive here because the menu no longer destroys on save.
    //
    // Submit with render:false and re-render explicitly afterwards. We cannot
    // rely on document.update's auto-render: if the content was unchanged the
    // update is a no-op that fires no hook and no render, leaving the editor
    // we just destroyed without its {{editor}} block restored (broken view).
    // The explicit render runs in finally so the block is always rebuilt, even
    // on an unchanged save or a failed submit.
    try {
      const event = new Event("submit", { cancelable: true });
      await this._onSubmit(event, { preventClose: true, render: false });
    } finally {
      if (remove) this._destroyEditor(name);
      this.render(true);
    }
  }

  _destroyEditor(name) {
    const state = this.editors[name];
    if (!state) return;
    try { state.instance?.destroy(); } catch (_e) { /* already torn down */ }
    state.container?.classList.remove("editor-active", "prosemirror");
    // Restore the edit button (hidden in _activateEditor). Harmless if this is
    // the now-detached pre-re-render button; required if teardown happens
    // without a re-render so the button doesn't stay hidden.
    if (state.button) state.button.style.display = "";
    delete this.editors[name];
  }

  async _onEditImage(event) {
    event.preventDefault();
    const target = event.currentTarget;
    const attr = target.dataset.edit;
    const current = foundry.utils.getProperty(this.document._source, attr);
    const fp = new foundry.applications.apps.FilePicker.implementation({
      current,
      type: "image",
      callback: (path) => {
        target.src = path;
        if (this.options.submitOnChange) {
          this._onSubmit(new Event("submit", { cancelable: true }));
        }
      },
      position: {
        top: this.position.top + 40,
        left: this.position.left + 10,
      },
    });
    return fp.browse();
  }

  _activateFilePicker(event) {
    event.preventDefault();
    const button = event.currentTarget;
    const field = button.dataset.target;
    const input = this.form?.elements[field];
    const fp = new foundry.applications.apps.FilePicker.implementation({
      type: button.dataset.type ?? "image",
      current: input?.value,
      callback: (path) => {
        if (input) input.value = path;
        if (this.options.submitOnChange) {
          this._onSubmit(new Event("submit", { cancelable: true }));
        }
      },
      position: {
        top: this.position.top + 40,
        left: this.position.left + 10,
      },
    });
    return fp.browse();
  }

  _onChangeInput(event) {
    // The change listener is bound to the form, so event.currentTarget is the
    // form itself -- never an editor. Guard on the actual changed element.
    const input = event.target;
    if (input?.closest?.(".editor.prosemirror, .editor.tinymce")) return;

    if (input?.type === "color" && input.dataset.edit && this.form?.elements[input.dataset.edit]) {
      this.form.elements[input.dataset.edit].value = input.value;
    } else if (input?.type === "range") {
      const field = input.parentElement?.querySelector(".range-value");
      if (field) {
        if (field.tagName === "INPUT") field.value = input.value;
        else field.innerHTML = input.value;
      }
    }

    if (this.options.submitOnChange) return this._onSubmit(event);
  }

  async _onSubmit(event, options = {}) {
    let { updateData = null, preventClose = false, render = false } = options;
    event?.preventDefault?.();
    if (!this.form || !this.isEditable) return false;

    // Coalesce concurrent submits. The previous `this._submitting` early-
    // return dropped a change that arrived mid-flight -- exactly the spec-tree
    // multi-click checkbox bug. Instead, record the pending request and return
    // the in-flight promise so callers (close / _saveEditor) still wait for the
    // flushed submit before tearing down DOM.
    if (this._submitting) {
      this._submitPending = { updateData, preventClose, render };
      return this._submitInFlight;
    }

    this._submitting = true;
    let formData;
    let currentRender = render;
    let currentPreventClose = preventClose;

    let resolveFlush;
    let rejectFlush;
    this._submitInFlight = new Promise((res, rej) => { resolveFlush = res; rejectFlush = rej; });

    let iter = 0;
    try {
      do {
        if (iter++ > 8) {
          console.warn("starwarsffg | _onSubmit coalesce loop exceeded 8 iterations; bailing");
          break;
        }
        this._submitPending = null;
        formData = this._getSubmitData(updateData);
        await this._updateObject(event, formData, { render: currentRender });
        // A pending submit registered while we awaited carries its intent
        // forward: render: true wins, preventClose: false wins.
        if (this._submitPending) {
          if (this._submitPending.render) currentRender = true;
          if (!this._submitPending.preventClose) currentPreventClose = false;
          updateData = this._submitPending.updateData ?? updateData;
        }
      } while (this._submitPending);

      if (this.options.closeOnSubmit && !currentPreventClose) {
        await this.close({ submit: false, force: true });
      }
      resolveFlush(formData);
      return formData;
    } catch (err) {
      rejectFlush(err);
      throw err;
    } finally {
      this._submitting = false;
      this._submitInFlight = null;
    }
  }

  _getSubmitData(updateData = {}) {
    if (!this.form) throw new Error("The sheet has no registered form element.");
    const fd = new foundry.applications.ux.FormDataExtended(this.form, { editors: this.editors });
    let data = fd.object;
    if (updateData) data = foundry.utils.mergeObject(data, updateData, { inplace: false });
    return foundry.utils.flattenObject(data);
  }

  async _updateObject(_event, formData, { render = false } = {}) {
    return this.document.update(formData, { render });
  }

  /**
   * Add/remove a source-book reference in `system.metadata.sources`. Shared by
   * item and actor sheets (this.object is the document either way).
   * @param event
   */
  async _handleSourceControl(event) {
    event.preventDefault();
    event.stopPropagation();
    const action = $(event.currentTarget).data("action");
    const sourceIndex = $(event.currentTarget).data("index");
    if (action === "add") {
      // Single-instance guard: a second click on `+` while an Add Source dialog
      // is open focuses it instead of stacking another. Sync flag set before any
      // async hop so a fast double-click can't slip through.
      if (this._addSourceDialogOpen) {
        this._addSourceDialog?.bringToFront?.();
        return;
      }
      this._addSourceDialogOpen = true;
      const addSource = new DialogV2({
        window: { title: game.i18n.localize("SWFFG.Meta.Sources.AddSource.Title") },
        classes: ["starwarsffg-dialog", "ffg-meta-dialog"],
        content: `
          <div class="ffg-meta-form">
            <label for="book">${game.i18n.localize("SWFFG.Meta.Sources.AddSource.Book")} :</label>
            <input type="text" id="book" name="book" value="Force and Destiny Core Rulebook" autofocus>
            <label for="page">${game.i18n.localize("SWFFG.Meta.Sources.AddSource.Page")}:</label>
            <input type="number" id="page" name="page" value="0">
          </div>
        `,
        buttons: [
          {
            action: "submit",
            icon: "fas fa-check",
            label: game.i18n.localize("SWFFG.Meta.Sources.AddSource.Submit"),
            default: true,
            callback: async (event, button, dialog) => {
              const bookName = dialog.element.querySelector("#book").value;
              const pageNum = dialog.element.querySelector("#page").value;
              await this.object.update({"system.metadata.sources": [...this.object.system.metadata.sources, `${bookName} pg. ${pageNum}`]});
            },
          },
          {
            action: "cancel",
            icon: "fas fa-x",
            label: game.i18n.localize("SWFFG.Meta.Sources.AddSource.Cancel"),
          },
        ],
      });
      const releaseSourceLock = () => {
        this._addSourceDialogOpen = false;
        if (this._addSourceDialog === addSource) this._addSourceDialog = null;
      };
      this._addSourceDialog = addSource;
      // Release the lock on any close path (submit, cancel, X, Esc all fire close).
      addSource.addEventListener("close", releaseSourceLock, { once: true });
      addSource.render({ force: true });
      // V13 dialogs sometimes render behind the parent sheet; force to front next paint.
      requestAnimationFrame(() => addSource.bringToFront?.());
    } else if (action === "remove") {
      const sources = foundry.utils.deepClone(this.object.system.metadata.sources);
      sources.splice(sourceIndex, 1);
      await this.object.update({"system.metadata.sources": sources});
      // Only render after a structural change; rendering on "add" too (before the
      // dialog submits) re-runs setPosition and snaps the window to default size.
      this.render(true);
    }
  }

  /**
   * Add/remove a free-text tag in `system.metadata.tags`. Shared by item and
   * actor sheets.
   * @param event
   */
  async _handleTagControl(event) {
    event.preventDefault();
    event.stopPropagation();
    const action = $(event.currentTarget).data("action");
    const tagIndex = $(event.currentTarget).data("index");
    if (action === "add") {
      if (this._addTagDialogOpen) {
        this._addTagDialog?.bringToFront?.();
        return;
      }
      this._addTagDialogOpen = true;
      const addTag = new DialogV2({
        window: { title: game.i18n.localize("SWFFG.Meta.Tags.AddTag.Title") },
        classes: ["starwarsffg-dialog", "ffg-meta-dialog"],
        content: `
          <div class="ffg-meta-form">
            <label for="tag">${game.i18n.localize("SWFFG.Meta.Tags.AddTag.Tag")} :</label>
            <input type="text" id="tag" name="tag" value="" autofocus>
          </div>
        `,
        buttons: [
          {
            action: "submit",
            icon: "fas fa-check",
            label: game.i18n.localize("SWFFG.Meta.Tags.AddTag.Submit"),
            default: true,
            callback: async (event, button, dialog) => {
              const tag = dialog.element.querySelector("#tag").value;
              const updatedTags = this.object.system.metadata.tags || [];
              updatedTags.push(tag);
              await this.object.update({"system.metadata.tags": updatedTags});
            },
          },
          {
            action: "cancel",
            icon: "fas fa-x",
            label: game.i18n.localize("SWFFG.Meta.Tags.AddTag.Cancel"),
          },
        ],
      });
      const releaseTagLock = () => {
        this._addTagDialogOpen = false;
        if (this._addTagDialog === addTag) this._addTagDialog = null;
      };
      this._addTagDialog = addTag;
      addTag.addEventListener("close", releaseTagLock, { once: true });
      addTag.render({ force: true });
      requestAnimationFrame(() => addTag.bringToFront?.());
    } else if (action === "remove") {
      const tags = foundry.utils.deepClone(this.object.system.metadata.tags);
      tags.splice(tagIndex, 1);
      await this.object.update({"system.metadata.tags": tags});
      this.render(true);
    }
  }

  /** Minimum popout-editor window height; actor sheets override to a smaller floor. */
  get _popoutEditorMinHeight() { return 400; }

  _onPopoutEditor(event) {
    event.preventDefault();
    const a = event.currentTarget.parentElement;
    const label = a.dataset.label;
    const key = a.dataset.target;

    const parent = $(a.parentElement);
    const parentPosition = $(parent).offset();

    const floor = this._popoutEditorMinHeight;
    const windowHeight = parseInt($(parent).height(), 10) + 100 < floor ? floor : parseInt($(parent).height(), 10) + 100;
    const windowWidth = parseInt($(parent).width(), 10) < 320 ? 320 : parseInt($(parent).width(), 10);
    const windowLeft = parseInt(parentPosition.left, 10);
    const windowTop = parseInt(parentPosition.top, 10);

    const title = a.dataset.label ? `Editor for ${this.object.name}: ${label}` : `Editor for ${this.object.name}`;

    new PopoutEditor(this.object, {
      name: key,
      title: title,
      height: windowHeight,
      width: windowWidth,
      left: windowLeft,
      top: windowTop,
    }).render(true);
  }

  _canDragStart(_selector) {
    return this.isEditable;
  }

  _canDragDrop(_selector) {
    return this.isEditable;
  }

  _onDragStart(_event) {}

  _onDragOver(_event) {}

  async _onDrop(_event) {}
}

const { ApplicationV2, HandlebarsApplicationMixin } = foundry.applications.api;

/**
 * Shared native base for the system's form-style windows (modifiers popout,
 * roll builder, group manager, importers, settings panels, embedded item
 * editors). This is NOT a V1 compatibility shim -- it is a purpose-built
 * ApplicationV2 form base. It keeps only the form behaviors those windows
 * actually rely on, expressed in native V2 terms:
 *
 *  - a real <form> (via `window.contentTag = "form"`) so handlers can read
 *    `this.form` and append/remove rows (e.g. ModifierHelpers.onClickAttributeControl);
 *  - the legacy `(object, options)` construction signature, mapping `title` and
 *    `width/height/left/top` onto native `window.title` / `position`;
 *  - a coalescing `_onSubmit` -> `_updateObject` pipeline, fed by the native form
 *    handler (submit + submit-on-change) and callable directly by handlers;
 *  - submit-on-close, a close-time render guard (subclasses re-render from
 *    `_updateObject`), and an interactive-resize floor.
 *
 * Subclasses provide `static DEFAULT_OPTIONS` (with `form.submitOnChange` /
 * `form.closeOnSubmit` and a top-level `submitOnClose` as needed), `static PARTS`,
 * `_prepareContext`, and `_updateObject`. The V1 cruft (legacyOptions merge,
 * `getData` shim, dual defaultOptions) is intentionally gone.
 */
export class FFGFormApplication extends HandlebarsApplicationMixin(ApplicationV2) {
  static DEFAULT_OPTIONS = {
    tag: "div",
    window: {
      contentTag: "form",
      resizable: false,
    },
    form: {
      // Native ApplicationV2 binds submit/change to the contentTag form and
      // calls this handler; we funnel both into the coalescing _onSubmit.
      handler: FFGFormApplication._formSubmitHandler,
      submitOnChange: false,
      closeOnSubmit: false,
    },
  };

  /** Interactive-resize floor; subclasses override via MIN_DIMENSIONS or _minDimensions(). */
  static MIN_DIMENSIONS = { width: 300, height: 200 };

  /**
   * @param {object} object    The legacy "form object" (a Document, or a plain
   *   wrapper such as the upgrade/talent modifier descriptor). Stored verbatim.
   * @param {object} [options] Legacy options: `title` and position hints
   *   (`width`/`height`/`left`/`top`); anything else passes through to V2.
   */
  constructor(object = {}, options = {}) {
    const { title, width, height, left, top, ...rest } = options;
    super({
      ...rest,
      window: { ...(rest.window ?? {}), ...(title ? { title } : {}) },
      position: {
        ...(rest.position ?? {}),
        ...(Number.isFinite(width) ? { width } : {}),
        ...(Number.isFinite(height) ? { height } : {}),
        ...(Number.isFinite(left) ? { left } : {}),
        ...(Number.isFinite(top) ? { top } : {}),
      },
    });
    this.object = object;
    this._submitting = false;
  }

  get isEditable() {
    return this.options.editable !== false;
  }

  _minDimensions() {
    return this.constructor.MIN_DIMENSIONS;
  }

  async minimize(...args) {
    this._minimizing = true;
    try {
      return await super.minimize(...args);
    } finally {
      this._minimizing = false;
    }
  }

  /** Clamp interactive resize to the form's usable minimum (skip while minimizing). */
  setPosition(position = {}) {
    if (!this.element?.parentElement) return position;
    if (this._minimizing || this.minimized) return super.setPosition(position);
    const min = this._minDimensions();
    const clamped = { ...position };
    if (typeof clamped.width === "number" && clamped.width < min.width) clamped.width = min.width;
    if (typeof clamped.height === "number" && clamped.height < min.height) clamped.height = min.height;
    return super.setPosition(clamped);
  }

  /**
   * Native form `handler`. Called with `this` bound to the instance for both a
   * real submit and (when `form.submitOnChange`) a change. Delegate to the
   * coalescing pipeline; native handles closeOnSubmit afterwards from form config.
   */
  static _formSubmitHandler(event, _form, _formData) {
    return this._onSubmit(event);
  }

  /**
   * Override native change handling to (a) never submit on embedded-editor edits
   * and (b) mirror a range slider's value into its `.range-value` readout, then
   * defer to native (which fires submit-on-change when configured).
   */
  _onChangeForm(formConfig, event) {
    const input = event.target;
    if (input?.closest?.(".editor.prosemirror, .editor.tinymce")) return;
    if (input?.type === "range") {
      const field = input.parentElement?.querySelector(".range-value");
      if (field) {
        if (field.tagName === "INPUT") field.value = input.value;
        else field.innerHTML = input.value;
      }
    }
    return super._onChangeForm(formConfig, event);
  }

  _getSubmitData(updateData = {}) {
    if (!this.form) throw new Error("The form application has no registered form element.");
    const fd = new foundry.applications.ux.FormDataExtended(this.form);
    let data = fd.object;
    if (updateData) data = foundry.utils.mergeObject(data, updateData, { inplace: false });
    return foundry.utils.flattenObject(data);
  }

  /**
   * Coalescing submit. Returns the in-flight promise to concurrent callers so
   * close / inner-editor save flows wait for the flushed update. Does NOT close
   * -- the native pipeline owns closeOnSubmit (from `form.closeOnSubmit`), and
   * direct callers (onClickAttributeControl, submit-on-close) must not close.
   */
  async _onSubmit(event, { updateData = null } = {}) {
    event?.preventDefault?.();
    if (!this.form || !this.isEditable) return false;
    if (this._submitting) {
      this._submitPending = { updateData };
      return this._submitInFlight;
    }
    this._submitting = true;
    let formData;
    let resolveFlush;
    let rejectFlush;
    this._submitInFlight = new Promise((res, rej) => { resolveFlush = res; rejectFlush = rej; });
    let iter = 0;
    try {
      do {
        if (iter++ > 8) {
          console.warn("starwarsffg | _onSubmit coalesce loop exceeded 8 iterations; bailing");
          break;
        }
        this._submitPending = null;
        formData = this._getSubmitData(updateData);
        await this._updateObject(event, formData);
        if (this._submitPending) updateData = this._submitPending.updateData ?? updateData;
      } while (this._submitPending);
      resolveFlush(formData);
      return formData;
    } catch (err) {
      rejectFlush(err);
      throw err;
    } finally {
      this._submitting = false;
      this._submitInFlight = null;
    }
  }

  async _updateObject(_event, _formData) {}

  /** Submit-on-close (opt-in) + block re-render races while tearing down. */
  async close(options = {}) {
    const closeOptions = this.minimized && options.animate !== false ? { ...options, animate: false } : options;
    this._closing = true;
    try {
      if (this.options.submitOnClose && closeOptions.submit !== false && this.form && this.isEditable) {
        await this._onSubmit(new Event("submit", { cancelable: true }));
      }
      return await super.close(closeOptions);
    } finally {
      this._closing = false;
    }
  }

  async render(options, _options) {
    if (this._closing) return this;
    return super.render(options, _options);
  }
}

import {DicePoolFFG, RollFFG} from "./dice-pool-ffg.js";
import PopoutEditor from "./popout-editor.js";

const { DialogV2 } = foundry.applications.api;

/**
 * Extend the base Combat entity.
 * @extends {Combat}
 * Note: slot claiming is in the following format:
 * {
 *   <round>: {
 *     <turnCombatantId>:<claimantCombatantId>,
 *   }
 * }
 *
 * for example, if we had two combatants:
 * combatant "hello" - ID 111
 * combatant "world" - ID 222
 * and "hello" claimed "world's" slot for round one, the structure would look like this:
 * {
 *   1: {
 *     222: 111,
 *   }
 * }
 * and the UI would show "hello" as the sole claimant for this round (the other slot would say "claim this slot")
 */
export class CombatFFG extends Combat {
  /**
   * Adds a generic slot to the combat (via a flag)
   * @param round - INT - the round to add the slot to
   * @param disposition - INT - the disposition of the slot
   * @param initiative - FLOAT - the initiative value of the slot
   * @returns {Promise<void>}
   */
  async addExtraSlot(round, disposition, initiative) {
    const data = {
      name: "__GENERIC_SLOT__",
      disposition: disposition,
      combatantId: foundry.utils.randomID(),
      hidden: false,
      visible: true,
      initiative: initiative,
      flags: {
        fake: true,
        disposition: disposition,
      },
    };

    const createdSlotId = (await this.createEmbeddedDocuments("Combatant", [data]))[0].id;
    const createdSlot = this.combatants.get(createdSlotId);
    await createdSlot.setFlag("starwarsffg", "fake", true);
    await createdSlot.setFlag("starwarsffg", "disposition", disposition);
    return createdSlotId;
  }

  /**
   * Adds a slot to the combat with a specific combatant ID
   * @param disposition - disposition to create the combatant with
   * @param initiative - initiative to create the combatant with
   * @param actorId - the ID of the existing actor to assign to the combatant
   * @param tokenId - the ID of the existing token to assign to the combatant
   * @param sceneId - the ID of the existing scene to assign to the combatant
   * @param claimantName - the name of the claimant to assign to the combatant
   * @returns {Promise<void>}
   */
  async addIDedExtraSlot(disposition, initiative, actorId, tokenId, sceneId, claimantName) {
    const data = {
      name: claimantName,
      disposition: disposition,
      actorId: actorId,
      tokenId: tokenId,
      sceneId: sceneId,
      hidden: false,
      visible: true,
      initiative: initiative,
    };

    const createdSlotId = (await this.createEmbeddedDocuments("Combatant", [data]))[0].id;
    return createdSlotId;
  }

  /**
   * Handler for clicking the "add extra slot" button. Creates a dialog to get the slot details,
   * then calls the function to create the slot
   * @returns {Promise<void>}
   */
  async addInitiativeSlot() {
    // ask the user which disposition and initiative they would like, so we can add a generic slot

    DialogV2.wait({
      window: { title: game.i18n.localize("SWFFG.Combats.Slots.Dialog.Title") },
      content: `
        <p>${game.i18n.localize("SWFFG.Combats.Slots.Dialog.Labels.Initiative")} :</p>
        <input type="number" id="initiative" name="initiative" value="0">
        <p>${game.i18n.localize("SWFFG.Combats.Slots.Dialog.Labels.Disposition")}:</p>
        <label><input type="radio" id="friendly" name="disposition" value="friendly">${game.i18n.localize("SWFFG.Combats.Slots.Dialog.Labels.Friendly")}</label>
        <label><input type="radio" id="neutral" name="disposition" value="neutral">${game.i18n.localize("SWFFG.Combats.Slots.Dialog.Labels.Neutral")}</label>
        <label><input type="radio" id="enemy" name="disposition" value="enemy">${game.i18n.localize("SWFFG.Combats.Slots.Dialog.Labels.Enemy")}</label>
      `,
      buttons: [
        {
          action: "submit",
          icon: "fas fa-check",
          label: game.i18n.localize("SWFFG.Combats.Slots.Dialog.Labels.Submit"),
          default: true,
          callback: async (event, button, dialog) => {
            const root = dialog.element;
            let disposition = undefined;
            if (root.querySelector("#friendly").checked) {
              disposition = CONST.TOKEN_DISPOSITIONS["FRIENDLY"];
            } else if (root.querySelector("#neutral").checked) {
              disposition = CONST.TOKEN_DISPOSITIONS["NEUTRAL"];
            } else if (root.querySelector("#enemy").checked) {
              disposition = CONST.TOKEN_DISPOSITIONS["HOSTILE"];
            }
            if (disposition === undefined) {
              ui.notifications.warn("You must select a disposition");
              return;
            }
            const initiative = root.querySelector("#initiative").value;
            if (initiative === "") {
              ui.notifications.warn("You must provide an initiative value");
              return;
            }
            this.debounceRender();
            await this.addExtraSlot(this.round, disposition, parseInt(initiative));
            this.setupTurns();
            game.socket.emit("system.starwarsffg", {event: "trackerRender", combatId: this.id});
          },
        },
      ],
      rejectClose: false,
    });
  }

  debounceRender = foundry.utils.debounce(() => {
    if (ui.combat.viewed === this) {
      ui.combat.render();
    }
  }, 200);

  /** @override */
  async _getInitiativeRoll(combatant, formula) {
    const cData = foundry.utils.duplicate(combatant.actor.system);

    if (combatant.actor.type === "vehicle") {
      return new RollFFG("0");
    }

    if (formula === "Vigilance") {
      formula = _getInitiativeFormula(cData.skills.Vigilance, parseInt(cData.characteristics.Willpower.value));
    } else if (formula === "Cool") {
      formula = _getInitiativeFormula(cData.skills.Cool, parseInt(cData.characteristics.Presence.value));
    }

    const rollData = combatant.actor ? combatant.actor.getRollData() : {};

    let roll = await new RollFFG(formula, rollData).roll();

    const total = roll.ffg.success + roll.ffg.advantage * 0.01;
    roll._result = total;
    roll._total = total;

    return roll;
  }

  /** @override */
  _getInitiativeFormula(combatant) {
    return CONFIG.Combat.initiative.formula || game.system.initiative;
  }

  /** @override */
  async rollInitiative(ids, { formula = null, updateTurn = true, messageOptions = {} } = {}) {
    let initiative = this;

    let promise = new Promise(async function (resolve, reject) {
      const id = foundry.utils.randomID();

      let whosInitiative = initiative.combatant?.name;
      let dicePools = [];
      let vigilanceDicePool = new DicePoolFFG({});
      let coolDicePool = new DicePoolFFG({});
      let addDicePool = new DicePoolFFG({});

      const defaultInitiativeFormula = formula || initiative._getInitiativeFormula();
      if (Array.isArray(ids) && ids.length > 1) {
        whosInitiative = "Multiple Combatants";
      } else {
        // Make sure we are dealing with an array of ids
        ids = typeof ids === "string" ? [ids] : ids;
        const c = initiative.getCombatantByToken(
            initiative.combatants.map(combatant => combatant)
            .filter(combatantData => combatantData._id == ids[0])[0]
            .tokenId);
        //const data = c.actor.system;
        const data = _findActorForInitiative(c);
        whosInitiative = c.actor.name;

        vigilanceDicePool = _buildInitiativePool(data, "Vigilance");
        coolDicePool = _buildInitiativePool(data, "Cool");

        const initSkills = Object.keys(data.skills).filter((skill) => data.skills[skill].useForInitiative);

        initSkills.forEach((skill) => {
          if (dicePools.find((p) => p.name === skill)) return;

          const skillPool = _buildInitiativePool(data, skill);
          skillPool.label = data.skills[skill].label;
          skillPool.name = skill;
          dicePools.push(skillPool);
        });
      }

      if (dicePools.findIndex((p) => p.name === "Vigilance") < 0) {
        vigilanceDicePool.label = "SWFFG.SkillsNameVigilance";
        vigilanceDicePool.name = "Vigilance";
        dicePools.push(vigilanceDicePool);
      }
      if (dicePools.findIndex((p) => p.name === "Cool") < 0) {
        coolDicePool.label = "SWFFG.SkillsNameCool";
        coolDicePool.name = "Cool";
        dicePools.push(coolDicePool);
      }

      const diceSymbols = {
        boost: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[BO]"),
        setback: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[SE]"),
        advantage: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[AD]"),
        success: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[SU]"),
        threat: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[TH]"),
        failure: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[FA]"),
        upgrade: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[PR]"),
        force: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[FO]"),
      };

      const title = game.i18n.localize("SWFFG.InitiativeRoll") + ` ${whosInitiative}...`;
      const content = await foundry.applications.handlebars.renderTemplate("systems/starwarsffg/templates/dialogs/ffg-initiative.html", {
        id,
        dicePools,
        addDicePool,
        defaultInitiativeFormula,
        diceSymbols,
      });

      DialogV2.wait({
        window: { title },
        classes: ["starwarsffg", "ffg-initiative-dialog"],
        content,
        // The dice-pool +/- buttons were wired by an inline <script> in
        // ffg-initiative.html. jQuery's .html() eval'd that under V1 Dialog,
        // but DialogV2 injects content via innerHTML, which never runs inline
        // scripts -- so the buttons were dead. Wire them here instead: left
        // click increments, right click decrements, clamped to a minimum of 0.
        render: (event, dialog) => {
          const scope = dialog.element.querySelector(".addDicePool");
          if (!scope) return;
          for (const type of ["boost", "setback", "advantage", "success", "threat", "failure", "upgrades", "force"]) {
            const input = scope.querySelector(`[name="${type}"]`);
            if (!input) continue;
            if (!input.value) input.value = "0";
            input.addEventListener("click", (ev) => {
              ev.preventDefault();
              input.value = String((parseInt(input.value, 10) || 0) + 1);
            });
            input.addEventListener("contextmenu", (ev) => {
              ev.preventDefault();
              const cur = parseInt(input.value, 10) || 0;
              if (cur > 0) input.value = String(cur - 1);
            });
          }
        },
        buttons: [
          {
            action: "one",
            icon: "fas fa-check",
            label: game.i18n.localize("SWFFG.InitiativeRoll"),
            default: true,
            callback: async () => {
              const container = document.getElementById(id);
              const currentId = initiative.combatant?.id;

              const baseFormulaType = container.querySelector('input[name="skill"]:checked').value;

              // Iterate over Combatants, performing an initiative roll for each
              const [updates, messages] = await ids.reduce(
                async (results, id, i) => {
                  let [updates, messages] = await results;
                  // Get Combatant data
                  const c = initiative.getCombatantByToken(
                    initiative.combatants.map(combatant => combatant)
                    .filter(combatantData => combatantData._id == id)[0]
                    .tokenId);
                  if (!c || !c.isOwner) return resolve(results);

                  // Detemine Formula
                  const data = _findActorForInitiative(c);
                  let pool = _buildInitiativePool(data, baseFormulaType);

                  const addPool = DicePoolFFG.fromContainer(container.querySelector(`.addDicePool`));
                  pool.success += +addPool.success;
                  pool.advantage += +addPool.advantage;
                  pool.failure += +addPool.failure;
                  pool.threat += +addPool.threat;
                  pool.boost += +addPool.boost;
                  pool.setback += +addPool.setback;
                  pool.force = +addPool.force;
                  pool.upgrade(addPool.upgrades)

                  const rollData = c.actor ? c.actor.getRollData() : {};
                  let roll = await new RollFFG(pool.renderDiceExpression(), rollData, { success: pool.success, advantage: pool.advantage, failure: pool.failure, threat: pool.threat }).roll();
                  const total = roll.ffg.success + roll.ffg.advantage * 0.01;
                  roll._result = total;
                  roll._total = total;

                  // Roll initiative
                  updates.push({ _id: id, initiative: roll.total });

                  // Determine the roll mode. V14 renamed core.rollMode ->
                  // core.messageMode with a new value vocabulary (public/gm/blind/
                  // self) and applies it via ChatMessage#applyMode; feature-detect so
                  // hidden combatants still roll privately on both V13 and V14, and
                  // map any legacy caller-supplied rollMode.
                  const isV14 = game.release.generation >= 14;
                  const modeKey = isV14 ? "messageMode" : "rollMode";
                  let rollMode;
                  if (isV14) {
                    rollMode = messageOptions.messageMode
                      ?? (messageOptions.rollMode ? Roll._mapLegacyRollMode(messageOptions.rollMode) : game.settings.get("core", "messageMode"));
                    if ((c.token.hidden || c.hidden) && (rollMode === "public" || rollMode === "ic")) rollMode = "gm";
                  } else {
                    rollMode = messageOptions.rollMode || game.settings.get("core", "rollMode");
                    if ((c.token.hidden || c.hidden) && rollMode === "roll") rollMode = "gmroll";
                  }

                  // Construct chat message data
                  let messageData = foundry.utils.mergeObject(
                    {
                      speaker: {
                        scene: canvas.scene.id,
                        actor: c.actor ? c.actor.id : null,
                        token: c.token.id,
                        alias: c.token.name,
                      },
                      flavor: `${c.token.name} ${game.i18n.localize("SWFFG.InitiativeRoll")} (${game.i18n.localize(`SWFFG.SkillsName${baseFormulaType.replace(/[: ]/g, "")}`)})`,
                      flags: { "core.initiativeRoll": true },
                    },
                    messageOptions
                  );
                  const chatData = await roll.toMessage(messageData, { create: false, [modeKey]: rollMode });

                  // Play 1 sound for the whole rolled set
                  if (i > 0) chatData.sound = null;
                  messages.push(chatData);

                  // Return the Roll and the chat data
                  return results;
                },
                [[], []]
              );
              if (!updates.length) return initiative;

              // Update multiple combatants
              await initiative.updateEmbeddedDocuments("Combatant", updates);

              // Ensure the turn order remains with the same combatant if there was one active
              if (updateTurn && !!currentId) {
                await initiative.update({ turn: initiative.turns.findIndex((t) => t.id === currentId) });
              }

              // Create multiple chat messages. Pass chatBubble:false so these initiative rolls
              // don't pop a chat bubble over each combatant's token and pan the camera to it:
              // core styles speaker'd messages as in-character, and ChatMessage._preCreate then
              // auto-enables chatBubble for IC/EMOTE, whose sayBubble -> bubbles.say defaults
              // pan:true (with the chatBubblesPan setting also defaulting on). The `??=` in core
              // means an explicit false here is preserved.
              await CONFIG.ChatMessage.documentClass.create(messages, { chatBubble: false });

              resolve(initiative);
            },
          },
          {
            action: "two",
            icon: "fas fa-times",
            label: game.i18n.localize("SWFFG.Cancel"),
          },
        ],
        rejectClose: false,
      });
    });

    return await promise;
  }

  /**
   * Given an original combatant's ID, look up claims for that slot
   * Note: this is a key lookup
   * @param round - INT - the round
   * @param slot_id - STRING - the ID of the native combatant for this turn
   * @returns {undefined|*}
   */
  getSlotClaims(round, slot_id) {
    const claims = this.getFlag('starwarsffg', 'combatClaims') || undefined;
    if (!claims) {
      return undefined;
    }
    return claims[round]?.[slot_id];
  }

  /**
   * Given a claimant's ID, look up the slot they've claimed
   * Note: This is a search-by-value
   * @param round - INT - the round
   * @param combatantId - STRING - the ID of the native combatant for this turn
   * @returns {string|undefined} - an array of
   */
  findSlotClaims(round, combatantId) {
    const claims = this.getFlag('starwarsffg', 'combatClaims') || undefined;
    if (!claims) {
      return undefined;
    }
    const roundClaims = claims[round];
    try {
      return Object.keys(roundClaims).find(key => roundClaims[key] === combatantId) || undefined;
    } catch (error) {
      // we get an exception if there have been no claims in the round yet
      return undefined;
    }
  }

  /**
   * gets any existing initiative claims for this round of a given combat
   * @param round - INT - the round
   * @returns {*|*[]} - a list of combatant IDs (NOT token IDs, NOT actor IDs)
   */
  getClaims(round) {
    const combatClaims = this.getFlag('starwarsffg', 'combatClaims');
    if (combatClaims) {
      return combatClaims[round] || [];
    }
    return [];
  }

  /**
   * Check if a given combatant has any claims in the current combat round
   * @param combatantId - STRING - the combatant ID (NOT token ID, NOT actor ID)
   * @returns {boolean|string} - false if no claims, otherwise the round of the claimant
   */
  hasClaims(combatantId) {
    const claims = this.getClaims(this.round);
    if (!claims) {
      return false;
    }
    if (Object.values(claims).includes(combatantId)) {
      return Object.keys(claims).find(key => claims[key] === combatantId);
    } else {
      return false;
    }
  }

  async handleCombatantRemoval(combatant, options, userId) {
    const claimedSlot = this.findSlotClaims(this.round, combatant.id);
    if (!combatant.combat.started) {
      // the combat hasn't started, remove the actual initiative slot
      await this.removeCombatantOnly(combatant.id);
    }

    let action = game.settings.get("starwarsffg", "removeCombatantAction")
    if (action === "prompt") {
      DialogV2.wait({
        window: { title: game.i18n.localize("SWFFG.CombatantRemoval.Title") },
        content: game.i18n.localize("SWFFG.CombatantRemoval.Body"),
        buttons: [
          {
            action: "one",
            label: game.i18n.localize("SWFFG.CombatantRemoval.CombatantOnly"),
            default: true,
            callback: async () => {
              await this.doRemoval(combatant, "combatant_only");
            },
          },
          {
            action: "two",
            label: game.i18n.localize("SWFFG.CombatantRemoval.LastSlot"),
            callback: async () => {
              await this.doRemoval(combatant, "last_slot");
            },
          },
          {
            action: "three",
            icon: "fas fa-times",
            label: game.i18n.localize("SWFFG.Cancel"),
          },
        ],
        rejectClose: false,
      });
    } else {
      await this.doRemoval(combatant, action);
    }
  }

  async doRemoval(combatant, action) {
    switch (action) {
      case "combatant_only": {
        await this.removeCombatantOnly(combatant.id);
        break;
      }
      case "last_slot": {
        await this.removeLastSlot(combatant.id);
        break;
      }
    }
  }

  async handleCombatantAddition(combatant, context, options, combatantI) {
    // there may be cases when this is needed, but for now, we don't need to do anything
    // (leaving as a placeholder until we know for sure)
  }

  async removeCombatantOnly(combatantId) {
    CONFIG.logger.debug("Removing combatant from combat");
    const round = this.round;
    const combatant = this.combatants.get(combatantId);
    const disposition = combatant.disposition;
    const initiative = combatant.initiative;
    CONFIG.logger.debug(`Initial information: combatantId - ${combatantId}, combatantName - ${combatant.name}`);

    const originalCombatantId = $('.combatant.actor[data-combatant-id="' + combatant.id + '"]').data('alt-id');

    // find if the combatant has any slots claimed
    const claimedSlot = this.getSlotClaims(round, originalCombatantId);
    // prevent constant re-rendering of the tracker
    this.debounceRender();
    if (claimedSlot) {
      // un-claim the slot
      CONFIG.logger.debug("Someone claimed the actors slot, un-claiming it");
      await this.unclaimSlot(round, originalCombatantId);
    }
    await this.unclaimSlot(round, combatantId);
    // now delete the toRemoveCombatantId slot
    Hooks.off("preDeleteCombatant", CONFIG.FFG.preCombatDelete);
    CONFIG.FFG.preCombatDelete = undefined;
    await this.combatants.get(combatantId).delete();
    if (CONFIG.FFG.preCombatDelete === undefined) {
      CONFIG.FFG.preCombatDelete = Hooks.on("preDeleteCombatant", registerHandleCombatantRemoval);
    }
    // now create a new slot to replace it
    if (combatant.combat.started) {
      CONFIG.logger.debug("Re-creating the slot with the same disposition and initiative");
      const replacementTurnId = await this.addExtraSlot(round, disposition, initiative);
    }

    // if there was a claim on the slot replaced, add it back
    if (claimedSlot && claimedSlot !== combatantId) {
      CONFIG.logger.debug(`Since this slot was originally claimed by ${claimedSlot}, we are re-claiming it for them`);
      await this.claimSlot(round, replacementTurnId, claimedSlot);
    }
    // re-render the tracker / re-order the turns
    CONFIG.logger.debug("Re-rendering the tracker and emitting a socket event for other clients");
    // force re-checking slots before reordering
    this.prepareDerivedData();
    this.setupTurns();
    // emit a socket event
    game.socket.emit("system.starwarsffg", {event: "trackerRender", combatId: combat.id});
  }

  async removeLastSlot(combatantId) {
    CONFIG.logger.debug("Removing last slot of combat...");
    const round = this.round;

    /*
      Steps
        1 - Gather information about the actor being removed
        2 - Gather information about the last slot (of the same disposition)
        3 - Check if the results of steps 1 and 2 are the same or not. if they are different, proceed to step 4a. otherwise, go to 4b
        4a - Locate, record, and remove any claims on the slot of the actor being removed
        5 - Locate, record, and remove any claims on the last slot
        6 - Delete the actor being removed from the combat
        7 - Add a new slot with the last slot data (except Initiative, which is copied from the slot being removed)
        8 - Delete the last slot
        9 - Re-claim slots as needed
        4b - Delete the actor being removed; no further steps are needed
    */

    // Step 1 - Gather information about the actor being removed
    const removedCombatant = this.combatants.get(combatantId);
    let removedCombatantId = removedCombatant.id;
    const removedDisposition = removedCombatant.disposition;
    const removedInitiative = removedCombatant.initiative;

    // Step 2 - Gather information about the last slot (of the same disposition)
    let lowestInitiativeValue;
    let lastSlotId;
    for (const combatant of this.combatants) {
      if (combatant.disposition === removedDisposition) {
        if (!lowestInitiativeValue || combatant.initiative < lowestInitiativeValue) {
          lowestInitiativeValue = combatant.initiative;
          lastSlotId = combatant.id;
        }
      }
    }
    const lastSlotCombatant = this.combatants.get(lastSlotId);
    const lastSlotCombatantId = lastSlotId;
    const lastSlotActorId = lastSlotCombatant.actorId;
    const lastSlotSceneId = lastSlotCombatant.sceneId;
    const lastSlotTokenId = lastSlotCombatant.tokenId;
    const lastSlotName = lastSlotCombatant.name;
    let lastSlotActorClaimedRemovedCombatant;

    // prevent constant re-rendering of the tracker
    this.debounceRender();
    // prevent an infinite loop as we delete actors
    Hooks.off("preDeleteCombatant", CONFIG.FFG.preCombatDelete);

    // Step 3 - Check if the results of steps 1 and 2 are the same or not. if they are different, proceed to step 4a. otherwise, go to 4b
    if (removedCombatantId !== lastSlotCombatantId) {
      // Step 4a - Locate, record, and remove any claims on the slot of the actor being removed
      let removedClaimantId = this.getSlotClaims(round, removedCombatantId);
      // we should only reclaim the slot if the claimant is not the one being removed
      const removedClaimantIsRemovedCombatant = removedClaimantId === removedCombatantId;
      if (removedClaimantId) {
        lastSlotActorClaimedRemovedCombatant = lastSlotCombatantId === removedClaimantId;
        // revoke the claim on the removedCombatant slot
        await this.unclaimSlot(round, removedCombatantId);
      }

      // Step 5 - Locate, record, and remove any claims on the last slot
      const lastClaimantId = this.getSlotClaims(round, lastSlotCombatantId);
      const lastClaimantIsRemovedCombatant = lastClaimantId === removedCombatantId;
      if (lastClaimantId) {
        // revoke the claim on the removedCombatant slot
        await this.unclaimSlot(round, lastSlotCombatantId);
      }

      // Step 6 - Delete the actor being removed from the combat
      await this.combatants.get(removedCombatantId).delete();

      // Step 7 - Add a new slot with the last slot data (except Initiative, which is copied from the slot being removed)
      const removedCombatantReplacementId = await this.addIDedExtraSlot(
          removedDisposition,
          removedInitiative,
          lastSlotActorId,
          lastSlotTokenId,
          lastSlotSceneId,
          lastSlotName,
      );

      // Step 8 - Delete the last slot
      await this.combatants.get(lastSlotCombatantId).delete();

      // Step 9 - Re-claim slots as needed
      if (removedClaimantId && !removedClaimantIsRemovedCombatant) {
        if (lastSlotActorClaimedRemovedCombatant) {
          // the last actor had the removed slot claimed
          await this.claimSlot(round, removedCombatantReplacementId, removedCombatantReplacementId);
        } else {
          // a different actor had the removed slot claimed
          await this.claimSlot(round, removedCombatantReplacementId, removedClaimantId);
        }
      } else if (lastClaimantId && !lastClaimantIsRemovedCombatant) {
        await this.claimSlot(round, removedCombatantReplacementId, removedCombatantReplacementId);
      }
    } else {
      // Step 4b - Delete the actor being removed; no further steps are needed
      await this.combatants.get(removedCombatantId).delete();
    }
    // re-enable the hooks we disabled
    CONFIG.FFG.preCombatDelete = Hooks.on("preDeleteCombatant", registerHandleCombatantRemoval);
    this.setupTurns();
  }

  /**
   * Claim a slot for a given combatant
   * @param round - INT - the round
   * @param slot_id - STRING - the ID of the native combatant for this turn
   * @param combatantId - STRING - the combatant ID (NOT token ID, NOT actor ID)
   * @returns {Promise<void>}
   */
  async claimSlot(round, slot_id, combatantId) {
    if (!game.user.isGM) {
      const data = {
        combatId: this.id,
        round: round,
        slot: slot_id,
        combatantId: combatantId,
      }
      game.socket.emit("system.starwarsffg", {event: "combat", data: data});
      return;
    }
    const claims = {
      ...this.getFlag('starwarsffg', 'combatClaims')
    };
    if (!claims[round]) {
      claims[round] = {};
    }
    claims[round][slot_id] = combatantId;
    await this.setFlag('starwarsffg', 'combatClaims', claims);
  }

  /**
   * Un-claim a slot for a given combatant
   * @param round - INT - the round
   * @param slot_id - STRING - the ID of the native combatant for this turn
   * @returns {Promise<void>}
   */
  async unclaimSlot(round, slot_id) {
    if (!game.user.isGM) {
      // only the GM can un-claim a slot
      return;
    }
    await this.unsetFlag('starwarsffg', `combatClaims.${round}.${slot_id}`);
  }

  /**
   * Used by the Combat Tracker to update the initiative of a single slot
   * @param el
   * @returns {Promise<void>}
   */
  async updateCombatant(el) {
    const slotId = el.getAttribute("data-alt-id");
    const combatant = this.combatants.get(slotId);
    const currentInitiative = combatant.initiative;
    DialogV2.wait({
      window: { title: game.i18n.localize("SWFFG.Combats.Slots.Dialog.Title") },
      content: `
        <p>${game.i18n.localize("SWFFG.Combats.Slots.Dialog.Labels.Initiative")} :</p>
        <input type="number" id="initiative" name="initiative" value="${currentInitiative}">
      `,
      buttons: [
        {
          action: "submit",
          icon: "fas fa-check",
          label: game.i18n.localize("SWFFG.Combats.Slots.Dialog.Labels.Submit"),
          default: true,
          callback: async (event, button, dialog) => {
            const initiative = +dialog.element.querySelector("#initiative").value;
            if (initiative === "") {
              ui.notifications.warn("You must provide an initiative value");
              return;
            }
            await combatant.update({initiative: initiative});
            game.socket.emit("system.starwarsffg", {event: "trackerRender", combatId: this.id});
          },
        },
      ],
      rejectClose: false,
    });
  }

  async removeCombatant(el) {
    const round = this.round;
    // find the combatant being right-clicked
    const clickedCombatantId = el.getAttribute("data-alt-id");
    const clickedCombatantName = this.combatants.get(clickedCombatantId)?.name;
    CONFIG.logger.debug("Detected combatant removal on custom combat tracker, working...");
    CONFIG.logger.debug(`Right clicked original actor was ${clickedCombatantName} (${clickedCombatantId})`);
    // find the claimant on the slot being right-clicked
    const toRemoveCombatantId = this.getSlotClaims(round, clickedCombatantId);
    if (!toRemoveCombatantId) {
      return ui.notifications.warn(game.i18n.localize("SWFFG.Notifications.Combat.Remove.Slot"));
    }
    const toRemoveCombatantName = this.combatants.get(toRemoveCombatantId)?.name;
    CONFIG.logger.debug(`Actor actually being removed is ${toRemoveCombatantName} (${toRemoveCombatantId})`);
    // pull disposition and initiative from the actor being removed (so we can re-create the slot with those values)
    const disposition = CONST.TOKEN_DISPOSITIONS[el.getAttribute("data-disposition").replace('Enemy', 'Hostile').toUpperCase()];
    const initiative = this.combatants.get(toRemoveCombatantId).initiative;

    // see if there is a claim on the slot for the actor being removed (which may not have been the one right-clicked)
    const toRemoveClaimantId = this.getSlotClaims(round, toRemoveCombatantId);
    const toRemoveClaimantName = this.combatants.get(toRemoveClaimantId)?.name;
    // prevent constant re-rendering of the tracker
    this.debounceRender();
    if (toRemoveClaimantId) {
      CONFIG.logger.debug(`Located claim on actor's slot by ${toRemoveClaimantName} (${toRemoveClaimantId}), un-claiming it`);
      // if there is a claim on the slot being removed, un-claim it
      await this.unclaimSlot(round, toRemoveCombatantId);
    }

    // un-claim the slot we're removing the actor from
    CONFIG.logger.debug("Releasing the claim of the actor being removed");
    await this.unclaimSlot(round, clickedCombatantId);
    // now delete the toRemoveCombatantId slot
    CONFIG.logger.debug("Ok, actually removing the actor");
    Hooks.off("preDeleteCombatant", CONFIG.FFG.preCombatDelete);
    await this.combatants.get(toRemoveCombatantId).delete();
    CONFIG.FFG.preCombatDelete = Hooks.on("preDeleteCombatant", registerHandleCombatantRemoval);
    // now create a new slot to replace it
    CONFIG.logger.debug("Re-creating the slot with the same disposition and initiative");
    const replacementTurnId = await this.addExtraSlot(round, disposition, initiative);

    // if there was a claim on the slot replaced, add it back
    if (toRemoveClaimantId && toRemoveClaimantId !== toRemoveCombatantId) {
      CONFIG.logger.debug(`Since this slot was originally claimed by ${toRemoveClaimantName}, we are re-claiming it for them`);
      await this.claimSlot(round, replacementTurnId, toRemoveClaimantId);
    }
    // re-render the tracker / re-order the turns
    CONFIG.logger.debug("Re-rendering the tracker and emitting a socket event for other clients");
    this.setupTurns();
    // emit a socket event
    game.socket.emit("system.starwarsffg", {event: "trackerRender", combatId: combat.id});
  }

  /** @override */
  async delete() {
    for (const combatant of this.combatants.contents) {
      await combatant.removeCombatEffects();
    }
    await super.delete();
  }

  /** @override */
  async prepareDerivedData() {
    super.prepareDerivedData();
    CONFIG.logger.debug("Preparing combat data for custom tracker!");

    const newInitiatives = {
      [CONST.TOKEN_DISPOSITIONS.FRIENDLY]: this.combatants.filter(i => i.disposition === CONST.TOKEN_DISPOSITIONS.FRIENDLY).map(i => i.initiative),
      [CONST.TOKEN_DISPOSITIONS.NEUTRAL]: this.combatants.filter(i => i.disposition === CONST.TOKEN_DISPOSITIONS.NEUTRAL).map(i => i.initiative),
      [CONST.TOKEN_DISPOSITIONS.SECRET]: this.combatants.filter(i => i.disposition === CONST.TOKEN_DISPOSITIONS.SECRET).map(i => i.initiative),
      [CONST.TOKEN_DISPOSITIONS.HOSTILE]: this.combatants.filter(i => i.disposition === CONST.TOKEN_DISPOSITIONS.HOSTILE).map(i => i.initiative),
    }

    // sort the initiatives
    newInitiatives[CONST.TOKEN_DISPOSITIONS.FRIENDLY].sort(sortInit);
    newInitiatives[CONST.TOKEN_DISPOSITIONS.NEUTRAL].sort(sortInit);
    newInitiatives[CONST.TOKEN_DISPOSITIONS.SECRET].sort(sortInit);
    newInitiatives[CONST.TOKEN_DISPOSITIONS.HOSTILE].sort(sortInit);

    // used to track how many slots have occurred per side - we care to mark slots as "unused" if they're past the number of alive combatants
    let turnTracker = {
      [CONST.TOKEN_DISPOSITIONS.FRIENDLY]: 0,
      [CONST.TOKEN_DISPOSITIONS.NEUTRAL]: 0,
      [CONST.TOKEN_DISPOSITIONS.SECRET]: 0,
      [CONST.TOKEN_DISPOSITIONS.HOSTILE]: 0,
    };

    if (!this.turns) {
      CONFIG.logger.debug("skipping due to lack of turns");
      return;
    }

    const turns = await Promise.all(this.turns.map(async (turn, index) => {
      CONFIG.logger.debug(`Processing turn for ${turn?.name}`);
      turn.owner = turn?.isOwner || false;
      // combatant ID of the claimant of this slot, if it exists
      const claimantId = this.getSlotClaims(this.round, turn.id);
      // actor data of the claimant
      const claimant = claimantId ? (this.combatants.get(claimantId)) : undefined;
      // true if if there's a claim on the slot and combat has started
      const claimed = this.started ? claimantId !== undefined : true;
      // the normal actor for this slot. may or may not match the claimant
      const combatant = foundry.utils.deepClone(this.combatants.get(turn.id));
      if (!combatant) {
        CONFIG.logger.debug("No combatant found, skipping");
        return turn;
      }
      // track the disposition: the token, if it exists, then the actor, if it exists, then turn.defeated (which is where we stash extra slot initiative)
      const disposition = combatant.disposition;
      // can the user claim this slot?
      const canClaim = (disposition === CONST.TOKEN_DISPOSITIONS.FRIENDLY && !claimed) || game.user.isGM;

      // the highest possible initiative for this combatant
      let slotInitiative;
      try {
        slotInitiative = newInitiatives[disposition].pop();
      } catch (e) {
        CONFIG.logger.warn(`caught disposition issue: ${e}, skipping processing turn (this is normal when removing combatants)`);
        return turn;
      }

      let claim = {};
      let hasRolled = true;

      if (this.started && claimant) {
        // the slot is claimed
        CONFIG.logger.debug(`slot ${index} has been claimed by ${claimant.name}`);
        const hidden = this._getTokenHidden(claimant.tokenId);
        let defeated = claimant.isDefeated;

        const effects = new Set();
        if (claimant.token) {
          // V14 removed the legacy TokenDocument#effects icon array and #overlayEffect;
          // token status icons now derive from the actor's active effects (handled below).
          // Guard both so worlds/modules that still expose them keep working.
          claimant.token.effects?.forEach((e) => effects.add(e));
          if (claimant.token.overlayEffect) {
            effects.add(claimant.token.overlayEffect);
          }
        }

        if (claimant.actor) {
          if (claimant.isDefeated) {
            defeated = true;
          }
          for (const effect of claimant.actor.temporaryEffects) {
            // V14: ActiveEffect#icon was replaced by #img
            const effectImg = effect?.img ?? effect?.icon;
            if (effectImg) {
              effects.add(effectImg);
            }
          }
        }

        if (!hidden && turn.css) {
          turn.css = turn?.css?.replace('hidden', '');
        }

        if (claimant.initiative === null || claimant.initiative === undefined) {
          CONFIG.logger.debug("setting hasRolled to false (no initiative for claimant)");
          hasRolled = false;
        }

        claim = {
          id: claimant.id,
          combatantId: combatant.id,
          name: claimant.name,
          img: claimant.img ?? CONST.DEFAULT_TOKEN,
          owner: claimant.isOwner,
          defeated,
          hidden: hidden,
          canPing: claimant.sceneId === canvas.scene?.id && game.user.hasPermission("PING_CANVAS"),
          effects,
          initiative: claimant.initiative,
          claimantToken: claimant.token,
        };

        turn.hidden = hidden;
        // trigger the turnActive marker to be refreshed
        turn.claimed = claimantId;
        claimant?.token?.object?._refreshTurnMarker();
      } else {
        CONFIG.logger.debug(`slot ${index} is unclaimed`);
        if (combatant) {
          turn.combatantId = combatant.id;

          if (combatant && Object.keys(combatant).includes("tokenId")) {
            combatant.hidden = this._getTokenHidden(combatant.tokenId);
          } else {
            combatant.hidden = false;
          }

          // sync the turn state to the token state
          turn.hidden = combatant.hidden;
          if (combatant.initiative === null || combatant.initiative === undefined) {
            hasRolled = false;
          }
        }

        // trigger the turnActive marker to be refreshed
        turn.token?.object?._refreshTurnMarker();
      }

      if (combatant.css === undefined || combatant.css === null) {
        combatant.css = "";
      }
      if (this.turn === index) {
        combatant.active = true;
        combatant.css += " active";
      } else {
        combatant.active = false;
        combatant.css = "";
      }

      let slotType;
      if (disposition === CONST.TOKEN_DISPOSITIONS.FRIENDLY) {
        slotType = 'Friendly';
      } else if (disposition === CONST.TOKEN_DISPOSITIONS.HOSTILE) {
        slotType = 'Enemy';
      } else if (disposition === CONST.TOKEN_DISPOSITIONS.SECRET) {
        slotType = 'Secret';
      } else {
        slotType = 'Neutral';
      }

      // determine if we should mark the slot as unneeded
      const aliveCount = this._getCombatantStateCount(disposition);
      let unused = false;
      turnTracker[disposition]++;

      // we do not care about the defeated status since defeated units get their slot marked unused
      if (turn.css) {
        turn.css = turn.css.replace('defeated', '');
      }

      // extract the initiative information into icons for rendering on the combat tracker
      const initiativeImage = {
        "successes": "",
        "advantages": "",
        "triumphs": "",
      }
      if (slotInitiative) {
        const initiativeParts = slotInitiative.toFixed(2);
        const decimalPosition = initiativeParts.indexOf(".");
        const successes = initiativeParts.substring(0, decimalPosition);
        const triumphs = initiativeParts.substring(decimalPosition + 1, decimalPosition + 2);
        const advantages = initiativeParts.substring(decimalPosition + 2, decimalPosition + 3);

        for (let x = 0; x < successes; x++) {
          initiativeImage['successes'] += await foundry.applications.ux.TextEditor.implementation.enrichHTML("[su]");
        }
        for (let x = 0; x < advantages; x++) {
          initiativeImage['advantages'] += await foundry.applications.ux.TextEditor.implementation.enrichHTML("[ad]");
        }
        for (let x = 0; x < triumphs; x++) {
          initiativeImage['triumphs'] += await foundry.applications.ux.TextEditor.implementation.enrichHTML("[tr]");
        }
      }

      return {
        ...turn,
        ...claim,
        slotType: slotType,
        initiative: slotInitiative,
        hasRolled: hasRolled,
        claimed,
        canClaim,
        activationId: slotInitiative ? slotInitiative.activationId : undefined,
        unused: unused,
        initiativeImage,
      }
    }));

    // write to customTurns to avoid permanent changes
    this.customTurns = turns;
  }

  /**
   * Determine the hidden status of a token, since the state in the combat tracker seems to lag
   * @param tokenId
   * @returns {boolean}
   * @private
   */
  _getTokenHidden(tokenId) {
    let hidden = true;
    const scene = game.scenes.find(i => i.isView);
    if (!scene) {
      return false;
    }
    const token = scene.tokens.get(tokenId);
    if (token) {
      hidden = token.hidden;
    }
    CONFIG.logger.debug(`looked up hidden state for ${token?.name}/${tokenId} on scene ${scene.id}: ${hidden}`);
    return hidden;
  }

    /**
   * get the number of alive combatants on a given side, including any who have claimed a slot and died
   * essentially, the claimed and dead ones need to be included to get an accurate count to determine unused slots
   * @param disposition
   * @returns {number}
   * @private
   */
  _getCombatantStateCount(disposition) {
    const total =  this.combatants.filter(i => i.disposition === disposition);
    const defeated = this.combatants.filter(i => i.disposition === disposition && i.isDefeated);
    CONFIG.logger.debug(`getting combatant state count for ${disposition}`)
    CONFIG.logger.debug(`detected ${total.length} real slots, and ${defeated.length} defeated slots`);
    return total.length - defeated.length;
  }
}

function _getInitiativeFormula(skill, ability) {
  const dicePool = new DicePoolFFG({
    ability: ability,
    boost: parseInt(skill.boost),
    setback: parseInt(skill.setback),
    force: parseInt(skill.force),
  });
  dicePool.upgrade(parseInt(skill.rank));
  return dicePool.renderDiceExpression();
}

function _findActorForInitiative(c) {
  let data = c.actor.system;
  const initiativeRole = game.settings.get('starwarsffg', 'initiativeCrewRole');
  CONFIG.logger.debug("Attempting to find initiative data for actor in combat");
  if (c.actor.type === "vehicle") {
    CONFIG.logger.debug("Actor is a vehicle, looking for initiative crew role.");
    const crew = c.actor.getFlag("starwarsffg", "crew");
    if (crew !== undefined && crew !== []) {
      const initiativeCrew = crew.find((c) => c.role === "Pilot");
      if (initiativeCrew) {
        CONFIG.logger.debug("Found initiative crew role, swapping data to crew member");
        const realActor = game.actors.get(initiativeCrew.actor_id);
        if (realActor?.system) {
          data = realActor.system;
        }
      }
    } else {
      CONFIG.logger.warn("You must set a crew member with the pilot role to roll initiative for a vehicle");
    }
  }
  CONFIG.logger.debug("Finished checking");
  return data;
}

function _buildInitiativePool(data, skill) {
  const pool = new DicePoolFFG({
    ability: Math.max(data.characteristics[data.skills[skill].characteristic].value, data.skills[skill].rank),
    boost: data.skills[skill].boost,
    advantage: data.skills[skill].advantage,
    success: data.skills[skill].success,
  });
  pool.upgrade(Math.min(data.characteristics[data.skills[skill].characteristic].value, data.skills[skill].rank));

  return pool;
}

export class CombatTrackerFFG extends foundry.applications.sidebar.tabs.CombatTracker {

  /** @inheritdoc */
  static PARTS = {
    header: {
      template: "systems/starwarsffg/templates/combat/ffg-combat-tracker-header.html",
    },
    tracker: {
      template: "systems/starwarsffg/templates/combat/ffg-combat-tracker-body.html",
    },
    footer: {
      template: "systems/starwarsffg/templates/combat/ffg-combat-tracker-footer.html",
    },
  };

  /** @override */
  async _onRender(context, options) {
    try {
      await super._onRender(context, options);
    } catch (error) {
      CONFIG.logger.debug(`Custom combat tracker caught semi-expected render error: ${error}`)
    }
    const claimElement = this.element.querySelector('a[data-claim-slot]');
    if (claimElement) {
      claimElement.addEventListener("click", this._claimInitiativeSlot.bind(this));
    }
  }

  /**
   * Initial JS handler for the "claim slot" button on the combat tracker
   * @param event
   * @returns {Promise<void>}
   * @private
   */
  async _claimInitiativeSlot(event) {
    const slot = $(event.currentTarget).data('claim-slot');
    const slotId = this.viewed.turns[slot].id;
    const tokenCount = canvas.tokens.controlled.length;
    const ownedTokenCount = canvas.tokens.ownedTokens.length;
    // you must have a single token selected to claim a slot
    if (tokenCount !== 1 && ownedTokenCount !== 1) {
      ui.notifications.warn(game.i18n.localize("SWFFG.Notifications.Combat.Claim.OneToken"));
      return;
    }
    const token = ownedTokenCount === 1 ? canvas.tokens.ownedTokens[0] : canvas.tokens.controlled[0];
    const combatant = this.viewed.combatants.find(i => i.actorId === token.actor.id);
    if (!combatant) {
      ui.notifications.warn(game.i18n.localize("SWFFG.Notifications.Combat.Claim.Combatant"));
      return;
    }
    // ensure combatant is permitted in this type of slot
    const combatantDisposition = combatant?.token?.disposition ?? combatant?.actor?.token?.disposition ?? token?.document?.disposition ?? 0;
    const slotDisposition = this.viewed.turns[slot]?.token?.disposition ?? this.viewed.turns[slot]?.actor?.token?.disposition ?? this.viewed.turns[slot]?.disposition ?? 0;
    if (slotDisposition !== combatantDisposition) {
      ui.notifications.warn(game.i18n.localize("SWFFG.Notifications.Combat.Claim.SlotType"));
      return;
    }
    await this.viewed.claimSlot(this.viewed.round, slotId, combatant.id);
  }

  /** @override */
  async _prepareContext(options) {
    const combat = this.viewed;
    if (!combat) {
      return await super._prepareContext(options);
    }

    // create a copy of the turn data, then set hidden to false so non-GMs can view all turns, then set the data back
    const tempData = foundry.utils.deepClone(this.viewed.turns);
    for (const turn of this.viewed.turns) {
      turn.hidden = false;
    }
    const data = await super._prepareContext(options);
    const turnData = {
      Friendly: this.viewed.turns.filter(i => combat.combatants.get(i.id)?.token?.disposition === CONST.TOKEN_DISPOSITIONS.FRIENDLY),
      Enemy: this.viewed.turns.filter(i => combat.combatants.get(i.id)?.token?.disposition === CONST.TOKEN_DISPOSITIONS.HOSTILE),
      Neutral: this.viewed.turns.filter(i => combat.combatants.get(i.id)?.token?.disposition === CONST.TOKEN_DISPOSITIONS.NEUTRAL),
      Secret: this.viewed.turns.filter(i => combat.combatants.get(i.id)?.token?.disposition === CONST.TOKEN_DISPOSITIONS.SECRET),
    };

    // update visibility state for each token
    for (const turn of turnData['Friendly']) {
      const combatant = combat.combatants.get(turn.id);
      turn.hidden = this._getTokenHidden(combatant.tokenId);
      turn.slotClaimed = combat.hasClaims(combatant.id);
    }

    for (const turn of turnData['Enemy']) {
      const combatant = combat.combatants.get(turn.id);
      turn.hidden = this._getTokenHidden(combatant.tokenId);
      turn.slotClaimed = combat.hasClaims(combatant.id);
    }

    for (const turn of turnData['Neutral']) {
      const combatant = combat.combatants.get(turn.id);
      turn.hidden = this._getTokenHidden(combatant.tokenId);
      turn.slotClaimed = combat.hasClaims(combatant.id);
    }

    for (const turn of turnData['Secret']) {
      const combatant = combat.combatants.get(turn.id);
      turn.hidden = this._getTokenHidden(combatant.tokenId);
      turn.slotClaimed = combat.hasClaims(combatant.id);
    }

    // the current custom turn
    await this.viewed.prepareDerivedData();
    const currentTurn = this.viewed.customTurns[this.viewed.turn];
    // if the current user is an owner of the current turn (true is claimed, or they're a GM)
    const customControl = currentTurn ? currentTurn.owner : false;

    return {
      ...data,
      hasCombat: this.viewed?.started,
      round: this.viewed?.round,
      custom_turns: this.viewed.customTurns,
      customControl: customControl,
      turnData,
    };
  }

  /**
   * get the total number of slots for a given disposition, including any extra slots
   * @param combat
   * @param disposition
   * @returns {number}
   * @private
   */
  _getDispositionSlotCount(combat, disposition) {
    return combat.combatants.filter(i => i.disposition === disposition).length;
  }

  /** @override */
  _getEntryContextOptions() {
    const baseEntries = super._getEntryContextOptions();
    // replace the default remove combatant entry with our custom one, which allows us to detect and remove extra slots
    const updateCombatantEntry = baseEntries.find(i => i.name === "COMBAT.CombatantUpdate");
    if (updateCombatantEntry) {
      updateCombatantEntry.name = "SWFFG.Notifications.Combat.Initiative.Update";
      updateCombatantEntry.callback = async el => {
        await this.viewed.updateCombatant(el);
      };
      baseEntries[0] = updateCombatantEntry;
    }

    const removeCombatantEntry = baseEntries.find(i => i.name === "COMBAT.CombatantRemove");
    if (removeCombatantEntry) {
      removeCombatantEntry.callback = async el => {
        await this.viewed.removeCombatant(el);
      };
      baseEntries[4] = removeCombatantEntry;
    }

    const removeSlot = {
      name: 'SWFFG.Notifications.Combat.Claim.RemoveSlot',
      icon: '<i class="fa-regular fa-trash-alt"></i>',
      callback: async (el) => {
        const index = +el.getAttribute("data-slot-index");
        if (!isNaN(index)) {
          await this._removeSlot(this.viewed.round, el);
        }
      },
    };

    // Allow GMs to revoke an initiative slot claim.
    const unClaimSlot = {
      name: 'SWFFG.Notifications.Combat.Claim.UnClaim',
      icon: '<i class="fa-regular fa-xmark"></i>',
      callback: async (el) => {
        const li = $(el);
        const index = +li.data('slot-index');
        if (!isNaN(index)) {
          await this.viewed.unclaimSlot(this.viewed.round, this.viewed.turns[index].id);
        }
      },
    };

    // remove reroll initiative
    baseEntries.splice(2, 1);

    return [...baseEntries, removeSlot, unClaimSlot];
  }

  async _removeSlot(tracker, el) {
    CONFIG.logger.debug("Removing slot from combat");
    const combat = this.viewed;
    if (!combat) {
      ui.notifications.error("Error detecting combat, try starting/ending combat?");
    }
    const round = combat.round;
    const turn = el.getAttribute("data-slot-index");
    const combatant = combat.turns[turn];
    const claim = combat.getSlotClaims(round, combatant.id);
    const claimed = claim !== undefined;
    const disposition = CONST.TOKEN_DISPOSITIONS[el.getAttribute("data-disposition").replace('Enemy', 'Hostile').toUpperCase()];

    if (claimed) {
      ui.notifications.warn("You must un-claim the slot before removing it");
      return;
    }
    const slotCount = this._getDispositionSlotCount(combat, disposition)
    const presentCount = combat.combatants.filter(i => i?.token?.disposition === disposition).length;

    CONFIG.logger.debug(`detected ${presentCount} total combatants for disposition ${disposition}, along with ${slotCount} total slots`);

    if (slotCount - 1 < presentCount) {
      ui.notifications.warn(`You must retain enough slots for all actors in the combat (${presentCount})`);
      return;
    }

    const fakeTurn = combatant?.flags?.fake || false;
    if (fakeTurn) {
      // if it's a fake slot, delete it
      CONFIG.logger.debug("This is a non-actor turn, deleting");
      Hooks.off("preDeleteCombatant", registerHandleCombatantRemoval);
      await combatant.delete();
      CONFIG.FFG.preCombatDelete = Hooks.on("preDeleteCombatant", registerHandleCombatantRemoval);
    } else {
      // this is a real slot, we need to find a replacement
      // the approach is to pick another slot, copy data from that slot to our slot, copy claims to our slot (as needed)
      //   and then delete that fake slot
      // locate a fake turn
      CONFIG.logger.debug("This slot is owned by a real actor, doing some magic");
      const replacementTurn = combat.turns.find(i => i.flags?.fake && i.disposition === combatant.disposition);
      if (!replacementTurn) {
        CONFIG.logger.warn("Unable to find a replacement turn, likely concurrency issues");
        return;
      }
      CONFIG.logger.debug(`Replacement turn is ${replacementTurn.name} / ${replacementTurn.id}`);
      await combatant.update({initiative: replacementTurn.initiative});
      const replacementClaimed = combat.getSlotClaims(round, replacementTurn.id);
      CONFIG.logger.debug(`Claims on replacement slot: ${replacementClaimed}`);
      if (replacementClaimed) {
        await combat.unclaimSlot(round, replacementTurn.id);
        await combat.claimSlot(round, combatant.id, replacementClaimed);
      }
      Hooks.off("preDeleteCombatant", registerHandleCombatantRemoval);
      await replacementTurn.delete();
      CONFIG.FFG.preCombatDelete = Hooks.on("preDeleteCombatant", registerHandleCombatantRemoval);
    }
  }

  /** @override */
  _attachFrameListeners() {
    super._attachFrameListeners();
    // allow clicking the custom combat stuff and zooming to the combatant
    this.element.addEventListener("click", this._onCombatantMouseDown.bind(this));
  }

  /** @override */
  async _onCombatantMouseDown(event) {
    CONFIG.logger.debug("Caught click on custom combat tracker");
    if ( (event.target instanceof HTMLInputElement) || (event.target instanceof HTMLButtonElement) ) {
      CONFIG.logger.debug("Rejected click due to wrong place");
      return;
    }
    if (event.target.classList.contains("roll")) {
      CONFIG.logger.debug("rejecting click as this is an initiative roll");
      return;
    }

    const { combatantId } = event.target?.dataset ?? {};
    const combatant = this.viewed?.combatants?.get(combatantId);
    if ( !combatant ) {
      CONFIG.logger.debug("Unable to find combatant");
      return;
    }
    if ( event.type === "dblclick" ) {
      if ( combatant.actor?.testUserPermission(game.user, "OBSERVER") ) combatant.actor?.sheet.render(true);
      return;
    }
    const token = combatant.token?.object;
    if ( !token ) {
      CONFIG.logger.debug("Unable to find token");
      return;
    }
    CONFIG.logger.debug("Accepted, should be animating");
    canvas.animatePan(token.center);
  }

  /**
   * Determine the hidden status of a token, since the state in the combat tracker seems to lag
   * @param tokenId
   * @returns {boolean}
   * @private
   */
  _getTokenHidden(tokenId) {
    let hidden = true;
    const scene = game.scenes.find(i => i.isView);
    if (!scene) {
      return false;
    }
    const token = scene.tokens.get(tokenId);
    if (token) {
      hidden = token.hidden;
    }
    CONFIG.logger.debug(`looked up hidden state for ${token?.name}/${tokenId} on scene ${scene.id}: ${hidden}`);
    return hidden;
  }
}

export default class CombatantFFG extends Combatant {
  get disposition() {
    if (this.getFlag("starwarsffg", "fake")) {
      return this.getFlag("starwarsffg", "disposition");
    } else {
      return this?.token ? this.token?.disposition : this?.actor?.prototypeToken?.disposition;
    }
  }

  /** @override  */
  async delete() {
    await this.removeCombatEffects();
    await super.delete();
  }

  /**
   * Delete any status effects which have a duration of a "combat" when the actor is removed from combat
   * @returns {Promise<void>}
   */
  async removeCombatEffects() {
    if (!this.actor) {
      // no actor exists for this slot
      return;
    }
    CONFIG.logger.debug(`Removing combat-length status effects from ${this.actor.name} on combatant removal`);
    const effects = this.actor.getEmbeddedCollection("ActiveEffect");
    // duration marker moved to flags: V14's strict ActiveEffect system model strips unknown
    // `system` keys. Fall back to the legacy location for safety.
    const toDelete = effects.filter(e => (e?.flags?.starwarsffg?.duration ?? e?.system?.duration) === "combat");
    if (toDelete) {
      await this.actor.deleteEmbeddedDocuments("ActiveEffect", toDelete.map(i => i.id));
    }
  }
}

/**
 * Force the combat tracker to re-render, which picks up "hidden" state changes of tokens
 */
export function updateCombatTracker() {
  // Used to force the tracker to re-render based on updated visibility state
  if (game.combat && game.settings.get("starwarsffg", "useGenericSlots")) {
    ui.combat.render(true);
  }
}

/**
 * Sort function for initiatives. Puts NULL to the end.
 * @param a
 * @param b
 * @returns {number|number}
 */
function sortInit(a, b) {
  // equal items sort equally
  if (a === b) {
      return 0;
  }
  // nulls sort before anything else
  if (a === null) {
      return -1;
  }
  if (b === null) {
      return 1;
  }
  return a < b ? -1 : 1;
}

export function registerHandleCombatantRemoval(combatant, options, userId) {
  game.combat.handleCombatantRemoval(combatant, options, userId);
  return false;
}

export class AbilityDie extends foundry.dice.terms.DiceTerm {
  constructor(termData) {
    super(termData);
    this.faces = 8;
  }
  /* -------------------------------------------- */
  /** @override */
  static DENOMINATION = "a";

  /* -------------------------------------------- */
  /** @override */
  get formula() {
    return `${this.number}${this.constructor.DENOMINATION}${this.modifiers.join("")}`;
  }

  /* -------------------------------------------- */
  /** @override */
  async evaluate({ minimize = false, maximize = false } = {}) {
    if (this._evaluated) {
      throw new Error(`This ${this.constructor.name} has already been evaluated and is immutable`);
    }

    // Roll the initial number of dice
    for (let n = 1; n <= this.number; n++) {
      await this.roll({ minimize, maximize });
    }

    // Apply modifiers
    await this._evaluateModifiers();

    // Combine all FFG results.
    this.ffg = { success: 0, failure: 0, advantage: 0, threat: 0, triumph: 0, despair: 0, light: 0, dark: 0 };
    this.results.forEach((result) => {
      this.ffg.success += parseInt(result.ffg.success);
      this.ffg.failure += parseInt(result.ffg.failure);
      this.ffg.advantage += parseInt(result.ffg.advantage);
      this.ffg.threat += parseInt(result.ffg.threat);
      this.ffg.triumph += parseInt(result.ffg.triumph);
      this.ffg.despair += parseInt(result.ffg.despair);
      this.ffg.light += parseInt(result.ffg.light);
      this.ffg.dark += parseInt(result.ffg.dark);
    });

    // Return the evaluated term
    this._evaluated = true;
    this._isFFG = true;
    return this;
  }

  /* -------------------------------------------- */
  /** @override */
  async roll(options) {
    const roll = await super.roll(options);
    roll.ffg = CONFIG.FFG.ABILITY_RESULTS[roll.result];
    return roll;
  }

  /* -------------------------------------------- */
  /** @override */
  getResultLabel(result) {
    const die = CONFIG.FFG.ABILITY_RESULTS[result.result];
    return `<img src='${die.image}' title='${game.i18n.localize(die.label)}' alt=''/>`;
  }
}

