    }

    // Restore any already-rendered lines the blocks above just emptied (see `rendered`).
    Object.assign(this.source, rendered);
  }

  /**
   * Upgrade the dice pool, converting any remaining ability dice into proficiency
   * dice or adding an ability die if none remain.
   * @param times the number of times to perform this operation, defaults to 1
   */
  upgrade(times) {
    if (times === undefined) {
      times = 1;
    }

    let downgrade = false;
    if (times < 0) {
      downgrade = true;
      times = Math.abs(times);
    }

    for (let i = 0; i < times; i++) {
      if (downgrade) {
        if (this.proficiency > 0) {
          this.proficiency--;
          this.ability++;
        }
      } else {
        if (this.ability > 0) {
          this.ability--;
          this.proficiency++;
        } else {
          this.ability++;
        }
      }
    }
  }
  /**
   * Upgrade the dice pool's difficulty, converting any remaining difficulty dice
   * into challenge dice or adding an difficulty die if none remain.
   * @param times the number of times to perform this operation, defaults to 1
   */
  upgradeDifficulty(times) {
    if (times === undefined) {
      times = 1;
    }
    let downgrade = false;
    if (times < 0) {
      downgrade = true;
      times = Math.abs(times);
    }

    for (let i = 0; i < times; i++) {
      if (downgrade) {
        if (this.challenge > 0) {
          this.challenge--;
          this.difficulty++;
        }
      } else {
        if (this.difficulty > 0) {
          this.difficulty--;
          this.challenge++;
        } else {
          this.difficulty++;
        }
      }
    }
  }

  /**
   * Transform the dice pool into a rollable expression
   * @returns {string} a dice expression that can be used to roll the dice pool
   */
  renderDiceExpression() {
    let setbackDice = game.settings.get("starwarsffg", "ApplyRemoveSetbackMods")
      ? Math.max(0, this.setback - this.remsetback)
      : this.setback;

    let dicePool = [
      this.proficiency + "dp",
      this.ability + "da",
      this.challenge + "dc",
      this.difficulty + "di",
      this.boost + "db",
      setbackDice + "ds",
      this.force + "df",
    ];
    let finalPool = dicePool.filter((d) => {
      const test = d.split(/([0-9]+)/);
      return test[1] > 0;
    });
    return finalPool.join("+");
  }

  /**
   * Create a preview of the dice pool using images
   * @param container {HTMLElement} where to place the preview. A container will be generated if this is undefined
   * @returns {HTMLElement}
   */
  renderPreview(container) {
    if (container === undefined) {
      container = document.createElement("div");
      container.classList.add("dice-pool");
    }

    const totalDice = +this.proficiency + +this.ability + +this.challenge + +this.difficulty + +this.boost + +this.setback + +this.force;

    let height = 36;
    let width = 36;
    if (totalDice > 8) {
      height = 24;
      width = 24;
    }
    if (totalDice > 24) {
      height = 12;
      width = 12;
    }

    this._addIcons(container, CONFIG.FFG.PROFICIENCY_ICON, this.proficiency, height, width);
    this._addIcons(container, CONFIG.FFG.ABILITY_ICON, this.ability, height, width);
    this._addIcons(container, CONFIG.FFG.CHALLENGE_ICON, this.challenge, height, width);
    this._addIcons(container, CONFIG.FFG.DIFFICULTY_ICON, this.difficulty, height, width);
    this._addIcons(container, CONFIG.FFG.BOOST_ICON, this.boost, height, width);
    this._addIcons(container, CONFIG.FFG.SETBACK_ICON, this.setback, height, width);
    this._addIcons(container, CONFIG.FFG.REMOVESETBACK_ICON, this.remsetback, height, width);
    this._addIcons(container, CONFIG.FFG.FORCE_ICON, this.force, height, width);
    this._addIcons(container, CONFIG.FFG.SUCCESS_ICON, this.success, height, width);
    this._addIcons(container, CONFIG.FFG.ADVANTAGE_ICON, this.advantage, height, width);
    this._addIcons(container, CONFIG.FFG.TRIUMPH_ICON, this.triumph, height, width);
    this._addIcons(container, CONFIG.FFG.LIGHT_ICON, this.light, height, width);
    this._addIcons(container, CONFIG.FFG.FAILURE_ICON, this.failure, height, width);
    this._addIcons(container, CONFIG.FFG.THREAT_ICON, this.threat, height, width);
    this._addIcons(container, CONFIG.FFG.DESPAIR_ICON, this.despair, height, width);
    this._addIcons(container, CONFIG.FFG.DARK_ICON, this.dark, height, width);

    this._addSourceToolTip(container);

    return container;
  }

  renderAdvancedPreview(container) {
    let advanceContainer = this.renderPreview(container);

    let additionalSymbols = [];
    ["advantage", "success", "threat", "failure", "light", "dark", "triumph", "despair"].forEach((symbol) => {
      let diceSymbol = "";
      switch (symbol) {
        case "advantage": {
          diceSymbol = "[AD]";
          break;
        }
        case "success": {
          diceSymbol = "[SU]";
          break;
        }
        case "threat": {
          diceSymbol = "[TH]";
          break;
        }
        case "failure": {
          diceSymbol = "[FA]";
          break;
        }
        case "light": {
          diceSymbol = "[LI]";
          break;
        }
        case "dark": {
          diceSymbol = "[DA]";
          break;
        }
        case "triumph": {
          diceSymbol = "[TR]";
          break;
        }
        case "despair": {
          diceSymbol = "[DE]";
          break;
        }
      }

      if (this[symbol] !== 0) {
        additionalSymbols.push(`${this[symbol] < 0 ? "-" : "+"} ${this[symbol]} ${diceSymbol}`);
      }
    });

    $(advanceContainer).append(`<div>${additionalSymbols.join(", ")}</div>`);

    return advanceContainer;
  }

  _addIcons(container, icon, times, height = 36, width = 36) {
    for (let i = 0; i < times; i++) {
      const img = document.createElement("img");
      img.src = icon;
      img.width = width;
      img.height = height;

      const die = document.createElement("span");
      die.classList.add("ffg-die-icon");
      // A relative url() in an inline custom property resolves against the
      // stylesheet that consumes it (cdx.css, under /styles/) rather than the
      // document, so a raw `icon` path 404s. Reuse the browser-resolved absolute
      // src so the grain mask points at the image that actually loaded.
      die.style.setProperty("--ffg-die-mask", `url("${img.src}")`);
      die.appendChild(img);
      container.appendChild(die);
    }
  }

  _addSourceToolTip(container) {
    const createToolTip = this.source?.skill?.length || this.source?.boost?.length || this.source?.remsetback?.length || this.source?.setback?.length || this.source?.difficulty?.length || this.source?.upgradeDifficulty?.length || this.source?.upgrades?.length || this.source?.success?.length || this.source?.advantage?.length || this.source?.light?.length || this.source?.failure?.length || this.source?.threat?.length || this.source?.dark?.length || this.source?.triumph?.length || this.source?.despair?.length;

    if (createToolTip) {
      const mapDataToString = (values) => {
        const item = document.createElement("div");
        item.innerHTML = values.map((i) => `<li class="">${i}</li>`).join("");
        tooltip.append(item);
      };

      const tooltip = document.createElement("div");
      tooltip.classList.add("tooltip2");
      if (this.source?.skill?.length) {
        mapDataToString(this.source.skill);
      }
      if (this.source?.boost?.length) {
        mapDataToString(this.source.boost);
      }
      if (this.source?.remsetback?.length) {
        mapDataToString(this.source.remsetback);
      }
      if (this.source?.setback?.length) {
        mapDataToString(this.source.setback);
      }
      if (this.source?.difficulty?.length) {
        mapDataToString(this.source.difficulty);
      }
      if (this.source?.upgradeDifficulty?.length) {
        mapDataToString(this.source.upgradeDifficulty);
      }
      if (this.source?.upgrades?.length) {
        mapDataToString(this.source.upgrades);
      }
      if (this.source?.success?.length) {
        mapDataToString(this.source.success);
      }
      if (this.source?.advantage?.length) {
        mapDataToString(this.source.advantage);
      }
      if (this.source?.light?.length) {
        mapDataToString(this.source.light);
      }
      if (this.source?.failure?.length) {
        mapDataToString(this.source.failure);
      }
      if (this.source?.threat?.length) {
        mapDataToString(this.source.threat);
      }
      if (this.source?.dark?.length) {
        mapDataToString(this.source.dark);
      }
      if (this.source?.despair?.length) {
        mapDataToString(this.source.despair);
      }
      if (this.source?.triumph?.length) {
        mapDataToString(this.source.triumph);
      }

      container.classList.add("hover");
      container.append(tooltip);
    }
  }

  /**
   * Search the passed container for inputs that contain dice pool information
   * @param container the container where the inputs are located
   * @returns {DicePoolFFG}
   */
  static fromContainer(container) {
    return new DicePoolFFG({
      proficiency: container.querySelector('[name="proficiency"]')?.value ? container.querySelector('[name="proficiency"]').value : 0,
      ability: container.querySelector('[name="ability"]')?.value ? container.querySelector('[name="ability"]').value : 0,
      challenge: container.querySelector('[name="challenge"]')?.value ? container.querySelector('[name="challenge"]').value : 0,
      difficulty: container.querySelector('[name="difficulty"]')?.value ? container.querySelector('[name="difficulty"]').value : 0,
      boost: container.querySelector('[name="boost"]')?.value ? container.querySelector('[name="boost"]').value : 0,
      setback: container.querySelector('[name="setback"]')?.value ? container.querySelector('[name="setback"]').value : 0,
      force: container.querySelector('[name="force"]')?.value ? container.querySelector('[name="force"]').value : 0,
      advantage: container.querySelector('[name="advantage"]')?.value ? container.querySelector('[name="advantage"]').value : 0,
      success: container.querySelector('[name="success"]')?.value ? container.querySelector('[name="success"]').value : 0,
      threat: container.querySelector('[name="threat"]')?.value ? container.querySelector('[name="threat"]').value : 0,
      failure: container.querySelector('[name="failure"]')?.value ? container.querySelector('[name="failure"]').value : 0,
      light: container.querySelector('[name="light"]')?.value ? container.querySelector('[name="light"]').value : 0,
      dark: container.querySelector('[name="dark"]')?.value ? container.querySelector('[name="dark"]').value : 0,
      triumph: container.querySelector('[name="triumph"]')?.value ? container.querySelector('[name="triumph"]').value : 0,
      despair: container.querySelector('[name="despair"]')?.value ? container.querySelector('[name="despair"]').value : 0,
      upgrades: container.querySelector('[name="upgrades"]')?.value ? container.querySelector('[name="upgrades"]').value : 0,
    });
  }
}

import { MonteCarlo } from "../../lib/@swrpg-online/monte-carlo/dist/index.esm.js";
import { DicePoolFFG } from "./pool.js";

const { ApplicationV2, HandlebarsApplicationMixin } = foundry.applications.api;

export default class RollBuilderFFG extends HandlebarsApplicationMixin(ApplicationV2) {
  constructor(rollData, rollDicePool, rollDescription, rollSkillName, rollItem, rollAdditionalFlavor, rollSound) {
    super();
    this.roll = {
      data: rollData,
      skillName: rollSkillName,
      item: rollItem,
      sound: rollSound,
      flavor: rollAdditionalFlavor,
    };
    this.dicePool = rollDicePool;
    this.description = rollDescription;
    this.adversaryRanks = RollBuilderFFG._computeAdversaryRanks();
    // Which pool the dialog shows/rolls when an Adversary is targeted. Defaults
    // to the Adversary pool so the upgrade is applied by default (mirrors the old
    // checkbox defaulting to checked). Only takes effect while adversaryRanks > 0.
    this._adversaryMode = true;
  }

  /**
   * Snapshot the max Adversary rank sum across the user's targeted tokens.
   * Mirrors the rank-counting logic in modules/helpers/token.js drawAdversaryCount.
   * Returns 0 if no targets, no actors, or no Adversary items.
   */
  static _computeAdversaryRanks() {
    try {
      // When the GM disables the feature, report 0 ranks. This single gate hides
      // the Adversary controls (_refreshAdversary keys visibility off ranks > 0)
      // and skips the difficulty upgrade at roll time.
      if (!game.settings.get("starwarsffg", "enableAdversaryCalc")) return 0;
      const itemName = game.settings.get("starwarsffg", "adversaryItemName");
      const targets = Array.from(game.user?.targets ?? []);
      if (!targets.length) return 0;
      let max = 0;
      for (const token of targets) {
        const items = token?.actor?.items?.filter((i) => i.name === itemName) ?? [];
        let sum = 0;
        for (const item of items) {
          sum += item?.system?.ranks?.current || 0;
        }
        if (sum > max) max = sum;
      }
      return max;
    } catch (err) {
      CONFIG.logger?.debug?.("Adversary rank detection failed", err);
      return 0;
    }
  }

  /** System-socket event used to forward adversary-roll diagnostics to the GM. */
  static LOG_EVENT = "ffgAdversaryRollLog";

  /** A compact, loggable dice breakdown of a pool. */
  static _poolSummary(pool) {
    return {
      proficiency: pool.proficiency,
      ability:     pool.ability,
      boost:       pool.boost,
      challenge:   pool.challenge,
      difficulty:  pool.difficulty,
      setback:     pool.setback,
      force:       pool.force,
      expression:  pool.renderDiceExpression(),
    };
  }

  /**
   * Log an adversary roll's pool data locally and forward it to the GM machine.
   * `game.socket.emit` does not echo back to the sender, so the rolling client
   * logs locally here while the active GM logs the forwarded copy in
   * {@link registerRollLogBridge}.
   */
  static _logRoll(payload) {
    CONFIG.logger?.log?.("Client -> GM Server | Dice Roll", payload);
    game.socket.emit("system.starwarsffg", { event: RollBuilderFFG.LOG_EVENT, payload });
  }

  /**
   * GM-side listener that logs adversary-roll diagnostics forwarded by players.
   * Safe to call on every client; only GMs act on it. Call once at "ready".
   */
  static registerRollLogBridge() {
    game.socket.on("system.starwarsffg", (data) => {
      if (data?.event !== RollBuilderFFG.LOG_EVENT) return;
      if (!game.user.isGM) return;
      CONFIG.logger?.log?.("Client -> GM Server | Dice Roll", data.payload);
    });
  }

  static DEFAULT_OPTIONS = {
    id: "roll-builder",
    classes: ["starwarsffg", "roll-builder-dialog"],
    tag: "div",
    window: {
      resizable: true,
    },
    position: {
      width: 350,
    },
  };

  static PARTS = {
    content: {
      root: true,
      template: "systems/starwarsffg/templates/dice/roll-options-ffg.html",
    },
  };

  /** @override */
  get title() {
    return this.description || game.i18n.localize("SWFFG.RollingDefaultTitle");
  }

  /** @override */
  async _prepareContext(_options) {
    //get all possible sounds
    let sounds = [];
    const diceSymbols = {
      advantage: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[AD]"),
      success: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[SU]"),
      threat: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[TH]"),
      failure: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[FA]"),
      upgrade: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[PR]"),
      triumph: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[TR]"),
      despair: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[DE]"),
      light: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[LI]"),
      dark: await foundry.applications.ux.TextEditor.implementation.enrichHTML("[DA]"),
    };

    let canUserAddAudio = await game.settings.get("starwarsffg", "allowUsersAddRollAudio");
    let canUserAddFlavor = game.user.isGM || !this?.roll?.flavor;

    if (game.user.isGM) {
      game.playlists.contents.forEach((playlist) => {
        playlist.sounds.forEach((sound) => {
          let selected = false;
          const s = this.roll?.sound ?? this.roll?.item?.flags?.starwarsffg?.ffgsound;
          if (s === sound.path) {
            selected = true;
          }
          sounds.push({ name: sound.name, path: sound.path, selected });
        });
      });
    } else if (canUserAddAudio) {
      const playlistId = await game.settings.get("starwarsffg", "allowUsersAddRollAudioPlaylist");
      const playlist = await game.playlists.get(playlistId);

      if (playlist) {
        playlist.sounds.forEach((sound) => {
          let selected = false;
          const s = this.roll?.sound ?? this.roll?.item?.flags?.starwarsffg?.ffgsound;
          if (s === sound.path) {
            selected = true;
          }
          sounds.push({ name: sound.name, path: sound.path, selected });
        });
      } else {
        CONFIG.logger.warn(`Playlist for players does not exist, disabling audio`);
        canUserAddAudio = false;
      }
    }

    let users = [{ name: "Send To All", id: "all" }];
    if (game.user.isGM) {
      game.users.contents.forEach((user) => {
        if (user.visible && user.id !== game.user.id) {
          users.push({ name: user.name, id: user.id });
        }
      });
    }

    const enableForceDie = game.settings.get("starwarsffg", "enableForceDie");
    const labels = {
      light: game.settings.get("starwarsffg", "destiny-pool-light"),
      dark: game.settings.get("starwarsffg", "destiny-pool-dark"),
    };

    let display = false;
    const displaySimulation = game.settings.get("starwarsffg", "displaySimulation");
    if (displaySimulation === "GM" && game.user.isGM || displaySimulation === "All") {
      display = true;
    }

    return {
      sounds,
      isGM: game.user.isGM,
      canUserAddAudio,
      flavor: this.roll.flavor,
      users,
      enableForceDie,
      labels,
      diceSymbols,
      simDisplay: display,
      simCount: game.settings.get("starwarsffg", "rollSimulation"),
    };
  }

  /** @override */
  async _onRender(context, options) {
    await super._onRender(context, options);
    const html = $(this.element);

    // Codex-style the dice window (drop the white pool background + apply the
    // dark-scheme glyph/icon treatment, see `.cdx-dice` in cdx.css) ONLY when the
    // rolling actor uses a Codex sheet. Gate via a DEDICATED marker class, not
    // `.cdx` — the broad `.cdx form input,…button` rules would otherwise restyle
    // the stock dialog controls.
    try {
      const rollActor = this.roll?.item?.actor
        ?? (this.roll?.data?.actor?._id ? game.actors.get(this.roll.data.actor._id) : null);
      const sheetClass = rollActor?.getFlag?.("core", "sheetClass") ?? "";
      const isCodex = sheetClass.includes("Codex")
        || (rollActor?._sheet?.constructor?.name ?? "").startsWith("Codex");
      this.element?.classList?.toggle("cdx-dice", !!isCodex);
    } catch (e) { /* on any detection error, leave the stock dialog styling */ }

    this._initializeInputs(html);
    this._activateInputs(html);

    html.find(".adversary-mode-btn").on("click", (event) => {
      event.preventDefault();
      this._adversaryMode = event.currentTarget.dataset.mode === "adversary";
      this._syncAdversaryButtons(html);
      this._updatePreview(html);
    });

    this._refreshAdversary(html);
    this._adversaryHookId = Hooks.on("targetToken", (user) => {
      if (user?.id !== game.user.id) return;
      this._refreshAdversary(html);
    });

    html.find(".btn").click(async (event) => {
      // The Roll button is a <button> inside the template's <form>, so it
      // defaults to type="submit". Under the V1 FormApplication that native
      // submit is what closed the dialog (closeOnSubmit); the native
      // ApplicationV2 port no longer wires form submission, so stop the
      // default submit and close the dialog explicitly once the roll is sent.
      event.preventDefault();
      // Snapshot the pool to roll NOW, synchronously, before any of the awaits
      // below. In Adversary mode this returns a clone of the base pool upgraded by
      // the targeted Adversary's ranks; in Base mode it returns this.dicePool as-is.
      // `this.adversaryRanks` is recomputed from the LIVE game.user.targets by the
      // `targetToken` hook (see _onRender), so capturing the resolved pool here --
      // rather than reading ranks after the awaits (status-effect cleanup, ammo/item
      // updates) -- keeps the executed roll consistent with the on-screen preview.
      const rollPool = this._effectivePool();
      // Forward roll diagnostics to the GM machine (and log locally) so the table
      // can audit what each player's client computed -- on every roll. The
      // adversary pool is only meaningful when an Adversary is targeted (ranks > 0).
      let adversaryPool = null;
      if (this.adversaryRanks > 0) {
        const adversaryClone = this._clonePool();
        if (this.dicePool.difficulty > 0) adversaryClone.upgradeDifficulty(this.adversaryRanks);
        adversaryPool = RollBuilderFFG._poolSummary(adversaryClone);
      }
      RollBuilderFFG._logRoll({
        user: game.user.name,
        actor: this.roll.data?.token?.name ?? this.roll.data?.actor?.name ?? null,
        skill: this.roll.skillName ?? null,
        selected: this.adversaryRanks > 0 && this._adversaryMode ? "adversary" : "base",
        adversaryRanks: this.adversaryRanks,
        basePool: RollBuilderFFG._poolSummary(this.dicePool),
        adversaryPool,
      });
      // if sound was not passed search for sound dropdown value
      if (!this.roll.sound) {
        const sound = html.find(".sound-selection")?.[0]?.value;
        if (sound) {
          this.roll.sound = sound;
          if (this?.roll?.item) {
            let entity;
            let entityData;
            if (!this?.roll?.item?.flags?.starwarsffg?.uuid) {
              entity = game.actors.get(this.roll.data.actor._id);
              entityData = {
                _id: this.roll.item.id,
              };
            } else {
              const parts = this.roll.item.flags.starwarsffg?.uuid.split(".");
              const [sceneName, sceneId, entityName, entityId, embeddedName, embeddedId] = parts;
              entity = game.actors.tokens[entityId].items.get(embeddedId);
              if (parts.length === 6) {
                entityData = {
                  _id: entity.id,
                };
              }
            }
            foundry.utils.setProperty(entityData, "flags.starwarsffg.ffgsound", sound);
            entity.update(entityData);
          }
        }
      }

      if (!this.roll.flavor) {
        const flavor = html.find(".flavor-text")?.[0]?.value;
        if (flavor) {
          this.roll.flavor = flavor;
        }
      }

      // validate that required data is present
      if (this.roll.item?.uuid && this.roll.item.flags?.starwarsffg?.uuid !== this.roll.item.uuid) {
        // The cached uuid flag is missing OR stale (e.g. the actor/item was duplicated or
        // imported from another actor, leaving the flag pointing at the source item). Repair
        // it so getItemDetails() resolves qualities from THIS item on every render.
        const tmp_item = await fromUuid(this.roll.item.uuid);
        await tmp_item.setFlag("starwarsffg", "uuid", this.roll.item.uuid);
        foundry.utils.setProperty(this.roll.item, "flags.starwarsffg.uuid", this.roll.item.uuid);
      }


      try {
        // remove one-time status effects
        CONFIG.logger.debug("Removing one-time status effects from actor");
        const actorData = this.roll.data.document;
        if (actorData) {
          if (actorData) {
            const actorEffects = actorData.getEmbeddedCollection("ActiveEffect");
            if (actorEffects) {
              const toDelete = [];
              for (const activeEffect of actorEffects.contents) {
                // duration marker moved to flags: V14's strict ActiveEffect system model
                // strips unknown `system` keys. Fall back to the legacy location for safety.
                const duration = activeEffect?.flags?.starwarsffg?.duration ?? activeEffect?.system?.duration;
                if (duration === "once") {
                  toDelete.push(activeEffect._id);
                }
              }
              if (toDelete.length > 0) {
                await actorData.deleteEmbeddedDocuments("ActiveEffect", toDelete);
              }
            }
          }
        }
      } catch (error) {
        CONFIG.logger.warn(`Caught error in roller: ${error}`);
      }

      try {
        if (this?.roll?.item && this.roll.item.type === "weapon") {
          const item = await foundry.utils.fromUuid(this.roll.item.uuid);
          if (item) {
            const ammoEnabled = item.getFlag("starwarsffg", "config.enableAmmo");
            if (ammoEnabled) {
              await item.update({"system.ammo.value": item.system.ammo.value - 1});
            }
          }
        }
      } catch (error) {
        CONFIG.logger.warn(`Caught ammo error in roller: ${error}`);
      }

      const sentToPlayer = html.find(".user-selection")?.[0]?.value;
      if (sentToPlayer) {
        let container = $(`<div class='dice-pool'></div>`)[0];
        rollPool.renderAdvancedPreview(container);

        const messageText = `<div>
          <div>${game.i18n.localize("SWFFG.SentDicePoolRollHint")}</div>
          ${$(container).html()}
          <button class="ffg-pool-to-player">${game.i18n.localize("SWFFG.SentDicePoolRoll")}</button>
        </div>`;

        let chatOptions = {
          user: game.user.id,
          content: messageText,
          flags: {
            starwarsffg: {
              roll: this.roll,
              dicePool: rollPool,
              description: this.description,
            },
          },
        };

        if (sentToPlayer !== "all") {
          chatOptions.whisper = [sentToPlayer];
        }

        ChatMessage.create(chatOptions);
        await this.close();
      } else {
        if (this.roll.crew) {
          this.roll.item['crew'] = this.roll.crew
        }
        // Roll the pool snapshotted at click time (above) so the executed roll
        // matches the on-screen preview even if targeting changed during the awaits.
        const roll = new game.ffg.RollFFG(rollPool.renderDiceExpression(), this.roll.item, rollPool, this.roll.flavor);
        // check if this is a crew roll - and it's a roll for a weapon
        if (this.roll.item && this.roll.item.hasOwnProperty('crew') && Object.keys(this.roll.item).length > 1) {
          await this.roll.item.update({"flags": {"starwarsffg": {"crew": this.roll.item.crew}}})
        }
        await roll.toMessage({
          user: game.user.id,
          speaker: {
            actor: game.actors.get(this.roll.data?.actor?._id),
            alias: this.roll.data?.token?.name,
            token: this.roll.data?.token?._id,
          },
          flavor: `${game.i18n.localize("SWFFG.Rolling")} ${game.i18n.localize(this.roll.skillName)}...`,
        });
        if (this.roll?.sound) {
          AudioHelper.play({ src: this.roll.sound }, true);
        }

        await this.close();
        return roll;
      }
    });

    html.find(".extend-button").on("click", (event) => {
      event.preventDefault();
      event.stopPropagation();

      $(event.currentTarget).toggleClass("minimize");

      const selector = $(event.currentTarget).next();
      $(selector).toggleClass("hide");
      $(selector).toggleClass("maximize");

      if (!$(event.currentTarget).hasClass("minimize")) {
        $(selector).val("");
      }
    });
  }

  _updatePreview(html) {
    const poolDiv = html.find(".dice-pool-dialog .dice-pool")[0];
    poolDiv.innerHTML = "";
    const pool = this._effectivePool();
    pool.renderPreview(poolDiv);
    this._updateSimulationPreview(pool);
  }

  _refreshAdversary(html) {
    this.adversaryRanks = RollBuilderFFG._computeAdversaryRanks();
    // Show the Base/Adversary toggle only while an Adversary is targeted (ranks > 0).
    const toggle = html.find(".adversary-pool-toggle")[0];
    if (toggle) toggle.style.display = this.adversaryRanks > 0 ? "" : "none";
    const label = html.find(".adversary-pool-label")[0];
    if (label) label.textContent = game.i18n.format("SWFFG.Adversary.AdversaryPool", { ranks: this.adversaryRanks });
    this._syncAdversaryButtons(html);
    this._updatePreview(html);
  }

  /** Highlight the active Base/Adversary pool button and label the Roll button. */
  _syncAdversaryButtons(html) {
    const adversaryAvailable = this.adversaryRanks > 0;
    const mode = adversaryAvailable && this._adversaryMode ? "adversary" : "base";
    html.find(".adversary-mode-btn").each((i, btn) => {
      btn.classList.toggle("active", btn.dataset.mode === mode);
    });
    const rollBtn = html.find(".roll-button .btn")[0];
    if (rollBtn) {
      rollBtn.textContent = !adversaryAvailable
        ? game.i18n.localize("SWFFG.SkillsRoll")
        : mode === "adversary"
          ? game.i18n.localize("SWFFG.Adversary.RollAdversaryPool")
          : game.i18n.localize("SWFFG.Adversary.RollBasePool");
    }
  }

  /** A field-for-field copy of the working (base) pool. */
  _clonePool() {
    return new DicePoolFFG({
      proficiency: this.dicePool.proficiency,
      ability:     this.dicePool.ability,
      challenge:   this.dicePool.challenge,
      difficulty:  this.dicePool.difficulty,
      boost:       this.dicePool.boost,
      setback:     this.dicePool.setback,
      remsetback:  this.dicePool.remsetback,
      force:       this.dicePool.force,
      advantage:   this.dicePool.advantage,
      success:     this.dicePool.success,
      threat:      this.dicePool.threat,
      failure:     this.dicePool.failure,
      light:       this.dicePool.light,
      dark:        this.dicePool.dark,
      triumph:     this.dicePool.triumph,
      despair:     this.dicePool.despair,
      upgrades:    this.dicePool.upgrades,
    });
  }

  /**
   * The pool to display and roll. In Base mode -- or when no Adversary is targeted
   * or there is no difficulty to upgrade -- this is the live base pool that manual
   * edits mutate. In Adversary mode it is a clone of the base pool with its
   * difficulty upgraded once per Adversary rank, leaving the base pool untouched so
   * the two modes can be toggled back and forth freely.
   */
  _effectivePool() {
    const adversaryActive = this._adversaryMode && this.adversaryRanks > 0 && this.dicePool.difficulty > 0;
    if (!adversaryActive) return this.dicePool;
    const clone = this._clonePool();
    clone.upgradeDifficulty(this.adversaryRanks);
    return clone;
  }

  _initializeInputs(html) {
    html.find(".pool-value input").each((key, value) => {
      const name = $(value).attr("name");
      value.value = this.dicePool[name];
    });

    html.find(".pool-additional input").each((key, value) => {
      const name = $(value).attr("name");
      value.value = this.dicePool[name];
      $(value).attr("allowNegative", true);
    });

    this._updatePreview(html);
  }

  _activateInputs(html) {
    html.find(".upgrade-buttons button").on("click", (event) => {
      event.preventDefault();
      event.stopPropagation();

      const id = $(event.currentTarget).attr("id");

      switch (id.toLowerCase()) {
        case "upgrade-ability": {
          this.dicePool.upgrade(1);
          break;
        }
        case "downgrade-ability": {
          this.dicePool.upgrade(-1);
          break;
        }
        case "upgrade-difficulty": {
          this.dicePool.upgradeDifficulty(1);
          break;
        }
        case "downgrade-difficulty": {
          this.dicePool.upgradeDifficulty(-1);
          break;
        }
      }
      this._initializeInputs(html);
    });

    html.find(".pool-container, .pool-additional").on("click", (event) => {
      let input;

      if ($(event.currentTarget).hasClass(".pool-container")) {
        input = $(event.currentTarget).find(".pool-value input")[0];
      } else {
        input = $(event.currentTarget).find("input")[0];
        if(!input) {
          input = $(event.currentTarget.nextElementSibling).find("input")[0];
        }
      }

      input.value++;
      this.dicePool[input.name] = parseInt(input.value);
      this._updatePreview(html);
    });

    html.find(".pool-container, .pool-additional").on("contextmenu", (event) => {
      let input;

      if ($(event.currentTarget).hasClass(".pool-container")) {
        input = $(event.currentTarget).find(".pool-value input")[0];
      } else {
        input = $(event.currentTarget).find("input")[0];
        if(!input) {
          input = $(event.currentTarget.nextElementSibling).find("input")[0];
        }
      }

      const allowNegative = $(input).attr("allowNegative");

      if (input.value > 0 || allowNegative) {
        input.value--;
        this.dicePool[input.name] = parseInt(input.value);
      }
      this._updatePreview(html);
    });
  }

  /** @override */
  async close(options = {}) {
    const closeOptions = this.minimized && options.animate !== false ? { ...options, animate: false } : options;
    if (this._adversaryHookId) {
      Hooks.off("targetToken", this._adversaryHookId);
      this._adversaryHookId = null;
    }
    return super.close(closeOptions);
  }

  /**
   * Add the results of the dice simulation
   * @private
   */
  _updateSimulationPreview(pool = this.dicePool) {
    try {
      const simPool = new MonteCarlo({
        dicePool: {
          abilityDice: pool.ability,
          difficultyDice: pool.difficulty,
          proficiencyDice: pool.proficiency,
          challengeDice: pool.challenge,
          boostDice: pool.boost,
          setbackDice: pool.setback,
        },
        iterations: game.settings.get("starwarsffg", "rollSimulation"),
        runSimulate: false,
        modifiers: {
          automaticSuccesses: pool.success,
          automaticFailures: pool.failure,
          automaticAdvantages: pool.advantage,
          automaticThreats: pool.threat,
          automaticTriumphs: pool.triumph,
          automaticDespairs: pool.despair,
        },
      });
      const simResults = simPool.simulate();

      let newClass = "";
      if (simResults.successProbability < .25) {
        newClass = "unlikely";
      } else if (simResults.successProbability > .75) {
        newClass = "likely";
      }

      $("#success_chance").text(
        `${(simResults.successProbability * 100).toLocaleString(undefined, {maximumFractionDigits: 0})}%`
      ).removeClass("likely unlikely").addClass(newClass);
    } catch (e) {

    }
  }
}

import PopoutEditor from "../popout-editor.js";
import { ForceDie } from "./dietype/ForceDie.js";
import {migrateDataToSystem} from "../helpers/migration.js";
import {ItemFFG} from "../items/item-ffg.js";

/**
 * New extension of the core DicePool class for evaluating rolls with the FFG DiceTerms
 */
export class RollFFG extends Roll {
  constructor(...args) {
    super(...args);
    this.ffg = { success: 0, failure: 0, advantage: 0, threat: 0, triumph: 0, despair: 0, light: 0, dark: 0 };
    this.hasFFG = false;
    this.hasStandard = false;
    this.addedResults = [];
    this.modifications = [];

    this.terms = this.parseShortHand(this.terms);

    if (args[2]?.success) {
      this.ffg.success += +args[2].success;
      this.addedResults.push({
        type: "Success",
        symbol: "[SU]",
        value: Math.abs(+args[2].success),
        negative: +args[2].success < 0,
      });
    }
    if (args[2]?.failure) {
      this.ffg.failure += +args[2].failure;
      this.addedResults.push({
        type: "Failure",
        symbol: "[FA]",
        value: Math.abs(+args[2].failure),
        negative: +args[2].failure < 0,
      });
    }
    if (args[2]?.advantage) {
      this.ffg.advantage += +args[2].advantage;
      this.addedResults.push({
        type: "Advantage",
        symbol: "[AD]",
        value: Math.abs(+args[2].advantage),
        negative: +args[2].advantage < 0,
      });
    }
    if (args[2]?.threat) {
      this.ffg.threat += +args[2].threat;
      this.addedResults.push({
        type: "Threat",
        symbol: "[TH]",
        value: Math.abs(+args[2].threat),
        negative: +args[2].threat < 0,
      });
    }
    if (args[2]?.light) {
      this.ffg.light += +args[2].light;
      this.addedResults.push({
        type: "Light",
        symbol: "[LI]",
        value: Math.abs(+args[2].light),
        negative: +args[2].light < 0,
      });
    }
    if (args[2]?.dark) {
      this.ffg.dark += +args[2].dark;
      this.addedResults.push({
        type: "Dark",
        symbol: "[DA]",
        value: Math.abs(+args[2].dark),
        negative: +args[2].dark < 0,
      });
    }
    if (args[2]?.triumph) {
      this.ffg.triumph += +args[2].triumph;
      this.ffg.success += +args[2].triumph;
      this.addedResults.push({
        type: "Triumph",
        symbol: "[TR]",
        value: Math.abs(+args[2].triumph),
        negative: +args[2].triumph < 0,
      });
    }
    if (args[2]?.despair) {
      this.ffg.despair += +args[2].despair;
      this.ffg.failure += +args[2].despair;
      this.addedResults.push({
        type: "Despair",
        symbol: "[DE]",
        value: Math.abs(+args[2].despair),
        negative: +args[2].despair < 0,
      });
    }

    if (args[3]) {
      this.flavorText = args[3];
    }
  }

  static CHAT_TEMPLATE = "systems/starwarsffg/templates/dice/roll-ffg.html";

  static TOOLTIP_TEMPLATE = "systems/starwarsffg/templates/dice/tooltip-ffg.html";

  async updateSymbols() {
    for (const addedResult of this.addedResults) {
      addedResult.symbol = await foundry.applications.ux.TextEditor.implementation.enrichHTML(addedResult.symbol);
    }
  }

  /* -------------------------------------------- */

  /* -------------------------------------------- */
  /** @override */
  async evaluate({ minimize = false, maximize = false } = {}) {
    if (this._evaluated) throw new Error("This Roll object has already been rolled.");

    // Step 0 - is this rolling nothing?
    if(this.terms.length == 0) {
      this._evaluated = true
      this._total = 0
      return this
    }

    // Step 1 - evaluate any inner Rolls and recompile the formula
    let hasInner = false;
    this.terms = await Promise.all(this.terms.map(async (t) => {
      if (t instanceof RollFFG) {
        hasInner = true;
        await t.evaluate({ minimize, maximize });
        this._dice = this._dice.concat(t.dice);
        return `${t.total}`;
      }
      return t;
    }));

    // Step 2 - if inner rolls occurred, re-compile the formula and re-identify terms
    if (hasInner) {
      const formula = this.constructor.cleanFormula(this.terms);
      this.terms = this._identifyTerms(formula);
    }

    // Step 3 - evaluate any remaining terms and return any non-FFG dice to the total.
    this.results = await Promise.all(this.terms.map(async (term) => {
      if (!game.ffg.diceterms.includes(term.constructor)) {
        if (term.evaluate && !(term instanceof foundry.dice.terms.OperatorTerm)) {
          this.hasStandard = true;
          let result = await term.evaluate({ minimize, maximize });
          return result.total;
        } else if (term instanceof foundry.dice.terms.OperatorTerm) {
          // in APIv13+ OperatorTerm cannot be evaluated again once it it has been evaluated. Just return its operator
          return term.operator;
        } else {
          return term;
        }
      } else {
        if (term.evaluate) await term.evaluate({ minimize, maximize });
        this.hasFFG = true;
        return 0;
      }
    }));

    // Step 3.5 - if non-FFG dice are roll, skip our custom logic
    if (!this?.hasFFG) {
      return super.evaluate({ minimize, maximize });
    }

    // Step 4 - safely evaluate the final total
    const total = Roll.safeEval(this.results.join(" "));
    if (!Number.isNumeric(total)) {
      throw new Error(game.i18n.format("DICE.ErrorNonNumeric", { formula: this.formula }));
    }

    // Step 5 - Retrieve all FFG results and combine into a single total.
    if (this.hasFFG) {
      this.terms.forEach((term) => {
        if (game.ffg.diceterms.includes(term.constructor)) {
          this.ffg.success += parseInt(term.ffg.success);
          this.ffg.failure += parseInt(term.ffg.failure);
          this.ffg.advantage += parseInt(term.ffg.advantage);
          this.ffg.threat += parseInt(term.ffg.threat);
          this.ffg.triumph += parseInt(term.ffg.triumph);
          this.ffg.despair += parseInt(term.ffg.despair);
          this.ffg.light += parseInt(term.ffg.light);
          this.ffg.dark += parseInt(term.ffg.dark);
        }
      });

      // Step 6 - Calculate actual results by cancelling out success with failure, advantage with threat etc.
      if (this.ffg.success < this.ffg.failure) {
        this.ffg.failure -= parseInt(this.ffg.success);
        this.ffg.success = 0;
      } else {
        this.ffg.success -= parseInt(this.ffg.failure);
        this.ffg.failure = 0;
      }
      if (this.ffg.advantage < this.ffg.threat) {
        this.ffg.threat -= parseInt(this.ffg.advantage);
        this.ffg.advantage = 0;
      } else {
        this.ffg.advantage -= parseInt(this.ffg.threat);
        this.ffg.threat = 0;
      }
    }

    // Store final outputs
    this._total = total;
    this._evaluated = true;
    return this;
  }

  /* -------------------------------------------- */
  /** @override */
  async roll() {
    return await this.evaluate();
  }

  /* -------------------------------------------- */
  /** @override */
  async getTooltip() {
    const parts = this.dice.map((d) => {
      const cls = d.constructor;
      let isFFG = "notFFG";
      if (game.ffg.diceterms.includes(cls)) isFFG = "isFFG";
      return {
        formula: d.formula,
        total: d.total,
        faces: d.faces,
        flavor: d.options.flavor,
        isFFG: game.ffg.diceterms.includes(cls),
        notFFG: !game.ffg.diceterms.includes(cls),
        rolls: d.results.map((r) => {
          return {
            result: d.getResultLabel(r),
            classes: [cls.name.toLowerCase(), isFFG, "d" + d.faces, r.rerolled ? "rerolled" : null, r.exploded ? "exploded" : null, r.discarded ? "discarded" : null].filterJoin(" "),
          };
        }),
      };
    });
    parts.addedResults = this.addedResults;
    parts.flavorText = this.flavorText;
    return foundry.applications.handlebars.renderTemplate(this.constructor.TOOLTIP_TEMPLATE, { parts });
  }

  /* -------------------------------------------- */
  /** @override */
  async render(chatOptions = {}) {
    chatOptions = foundry.utils.mergeObject(
      {
        user: game.user.id,
        flavor: null,
        template: this.constructor.CHAT_TEMPLATE,
        blind: false,
      },
      chatOptions
    );
    const isPrivate = chatOptions.isPrivate;

    // Execute the roll, if needed
    if (!this._evaluated) await this.roll();
    await this.updateSymbols();

    // Define chat data
    if (this?.data) {
      if (this.data.flags?.starwarsffg?.uuid) {
        const item = await fromUuid(this.data.flags.starwarsffg.uuid);
        if (item) {
          const details = await item.getItemDetails();
          this.data = Object.assign(item.toObject(false), { system: details, flags: item.flags });
        }
      }
      else if (this.data.flags?.starwarsffg?.ffgUuid) {
        const item = await fromUuid(this.data.flags.starwarsffg.ffgUuid);
        if (item) {
          const details = await item.getItemDetails();
          this.data = Object.assign(item.toObject(false), { system: details, flags: item.flags });
        }
      }
      this.data.additionalFlavorText = this.flavorText;
    } else {
      this.data = {
        additionalFlavorText: this.flavorText,
      };
    }

    const chatData = {
      formula: isPrivate ? "???" : this._formula,
      flavor: isPrivate ? null : chatOptions.flavor,
      user: chatOptions.user,
      tooltip: isPrivate ? "" : await this.getTooltip(),
      total: isPrivate ? "?" : Math.round(this.total * 100) / 100,
      ffg: isPrivate ? {} : this.ffg,
      ffgDice: isPrivate
        ? {}
        : this.dice.map((d, dieIndex) => {
            const cls = d.constructor;
            return {
              isFFG: game.ffg.diceterms.includes(cls),
              dieIndex,
              denom: cls.DENOMINATION,
              rolls: d.results.map((r, resultIndex) => {
                return {
                  result: d.getResultLabel(r),
                  resultIndex,
                };
              }),
            };
          }),
      hasFFG: this.hasFFG,
      hasStandard: this.hasStandard,
      hasSuccess: this.dice.filter((i) => i.constructor !== ForceDie).length > 0,
      diceresults: CONFIG.FFG.diceresults,
      data: this.data,
      addedResults: this.addedResults,
      modified: (this.modifications?.length ?? 0) > 0,
      modifications: this.modifications,
      publicRoll: !chatOptions.isPrivate,
    };
    if (chatData?.data?.flags?.starwarsffg.hasOwnProperty('crew')) {
      chatData.data.crew = chatData.data.flags.starwarsffg.crew;
    }
    if (chatData.data.hasOwnProperty('data') && (chatData.data.data.adjusteditemmodifier === undefined || chatData.data.data.adjusteditemmodifier.length === 0)) {
      // extended metadata is missing, lookup the actor ID so we can embed it for future lookups
      let candidate_actors = game.actors.filter(actor => actor.items.filter(item => item.id === chatData.data._id).length > 0);
      if (candidate_actors.length > 0) {
        if (game.settings.get("starwarsffg", "oldWorldCompatability")) {
          let test_item = game.actors.get(candidate_actors[0].id).items.get(chatData.data._id);
          // for whatever reason, sometimes the item we read doesn't have modifiers even though the chat item does
          // check if this is the case and correct it if it is
          try {
            if (test_item.data?.data?.itemmodifier.length === 0 && chatData.data?.data?.itemmodifier) {
              // there aren't any modifiers on the object, try copying the temp object to it so the link works
              test_item.data.data.itemmodifier = chatData.data.data.itemmodifier;
            }
          } catch (exception) {
            // required data was missing - best to just move along, citizen
          }
        }
        // fake the UUID flag so we can do the lookup within chat messages
        chatData.data.flags.starwarsffg.ffgUuid = 'Actor.' + candidate_actors[0].id + '.Item.' + chatData.data._id;
      }
    }

    const v12ChatData = migrateDataToSystem(chatData);

    // Render the roll display template
    return foundry.applications.handlebars.renderTemplate(chatOptions.template, v12ChatData);
  }

  /* -------------------------------------------- */
  /** @override */
  async toMessage(messageData = {}, { messageMode = null, rollMode = null, create = true } = {}) {
    // Perform the roll, if it has not yet been rolled
    if (!this._evaluated) await this.evaluate();

    // V14 renamed the roll-visibility concept: the legacy `rollMode`
    // (publicroll/gmroll/blindroll/selfroll) + `core.rollMode` setting became the
    // string `messageMode` (public/gm/blind/self) + `core.messageMode`, and the
    // whisper/blind handling moved from ChatMessage#applyRollMode to #applyMode.
    // Both the setting read and applyRollMode log deprecation warnings on V14
    // (removed in V16). Feature-detect so the system keeps working on its declared
    // minimum (V13), and delegate whisper/blind entirely to the core handler rather
    // than reimplementing visibility (a leaked private/blind roll would be a bug).
    const isV14 = game.release.generation >= 14;

    // Prepare chat data
    messageData = foundry.utils.mergeObject(
      {
        user: game.user.id,
        content: this.total,
        sound: CONFIG.sounds.dice,
      },
      messageData
    );
    messageData.rolls = [this];

    Hooks.call("ffgDiceMessage", this);

    // Either create the message or just return the chat data
    const cls = getDocumentClass("ChatMessage");
    const msg = new cls(messageData);
    if (isV14) {
      // Accept an explicit messageMode; fall back to a caller-supplied legacy
      // rollMode (mapped) or the configured default.
      let mMode = messageMode ?? messageData.messageMode;
      const legacy = rollMode ?? messageData.rollMode;
      if (!mMode) mMode = legacy ? this.constructor._mapLegacyRollMode(legacy) : game.settings.get("core", "messageMode");
      if (mMode) msg.applyMode(mMode);
    } else {
      const rMode = rollMode ?? messageData.rollMode ?? game.settings.get("core", "rollMode");
      if (rMode) msg.applyRollMode(rMode);
    }

    // Either create or return the data. Pass chatBubble:false so a token-speaker'd roll
    // doesn't pop a chat bubble over the token and pan the camera to it (core's sayBubble ->
    // ChatBubbles.say defaults pan:true, with the chatBubblesPan setting also defaulting on).
    // The `??=` in ChatMessage._preCreate preserves an explicit false. Matches the initiative
    // path, which sets the same option on its own message creation downstream.
    return create ? await cls.create(msg, { chatBubble: false }) : msg;
  }

  /** @override */
  toJSON() {
    const json = super.toJSON();
    json.ffg = this.ffg;
    json.hasFFG = this.hasFFG;
    json.hasStandard = this.hasStandard;
    json.data = this.data;
    json.addedResults = this.addedResults;
    json.flavorText = this.flavorText;
    json.modifications = this.modifications ?? [];
    return json;
  }

  /** @override */
  static fromData(data) {
    const roll = super.fromData(data);
    roll.ffg = data.ffg;
    roll.hasFFG = data.hasFFG;
    roll.hasStandard = data.hasStandard;
    roll.data = data.data;
    roll.addedResults = data.addedResults;
    roll.flavorText = data.flavorText;
    roll.modifications = data.modifications ?? [];
    return roll;
  }

  //If the main parser hands back a StringTerm attempt to turn it into a die.
  parseShortHand(terms) {
    return terms
      .flatMap(t => {
        if(!(t instanceof foundry.dice.terms.StringTerm) || /\d/.test(t.term))
          return t;

        return t.term.replaceAll('d', 'i').split('').reduce((acc, next) => {
          if(next in CONFIG.Dice.terms)
          {
            let cls = CONFIG.Dice.terms[next];
            acc.push(new cls(1));
          }
          else throw new Error(`Unknown die type '${next}'`)

          return acc;
        }, [])
      })
      .flatMap((value, index, array) => {   //Put addition operators between each die, but not before or after another Operator
        if (array.length - 1 !== index && !(array[index] instanceof foundry.dice.terms.OperatorTerm) && !(array[index + 1] instanceof foundry.dice.terms.OperatorTerm)) {
          return [value, new foundry.dice.terms.OperatorTerm({operator: '+'})]
        } else {
          return value
        }
      })
  }
}

import { GroupManager } from "./groupmanager-ffg.js";

const { ApplicationV2, HandlebarsApplicationMixin } = foundry.applications.api;

/**
 * The floating Destiny Tracker chrome widget: shows the light/dark destiny
 * pool, lets users flip points, and (for the GM) exposes the group-manager
 * menu. A native ApplicationV2 -- not a form. It is draggable by its body and
 * remembers its position per-user, and never closes via the UI.
 *
 * Rendered exactly once at ready (`dTracker.render(true)` in swffg-main); the
 * pool display is updated in place by the dPool settings' onChange (which
 * rewrites #destinyLight/#destinyDark directly), not by re-rendering -- so the
 * one-time _onRender binding of socket / chat hooks below does not accumulate.
 * @extends {ApplicationV2}
 */
export default class DestinyTracker extends HandlebarsApplicationMixin(ApplicationV2) {
  constructor(object = {}, options = {}) {
    super(options);
    this.object = object;
    this.destinyQueue = [];
    this.isRunningQueue = false;
    if (options?.menu) {
      this.menu = options.menu;
    }
  }

  static DEFAULT_OPTIONS = {
    id: "destiny-tracker",
    classes: ["starwarsffg"],
    tag: "div",
    window: {
      title: "Destiny Tracker",
    },
  };

  static PARTS = {
    content: {
      root: true,
      template: "systems/starwarsffg/templates/ffg-destiny-tracker.html",
    },
  };

  /**
   * Persistent chrome: the window header is hidden and the widget is never torn
   * down during a session, so close is a no-op to keep stray calls from
   * removing it. (Natively there is no 300x200 minimum to override anymore --
   * the frame shrinks to the widget; CSS provides the 10px gap.)
   * @override
   */
  async close(_options = {}) {
    return this;
  }

  /** @override */
  async _prepareContext(_options) {
    // Get current value
    let destinyPool = { light: game.settings.get("starwarsffg", "dPoolLight"), dark: game.settings.get("starwarsffg", "dPoolDark") };
    let destinyPoolLabel = { light: game.settings.get("starwarsffg", "destiny-pool-light"), dark: game.settings.get("starwarsffg", "destiny-pool-dark") };

    // filter menu based on role.
    const menu = this.menu.filter((m) => game.user.hasRole(m.minimumRole) || !m.minimumRole);

    // Return data
    return {
      destinyPool,
      destinyPoolLabel,
      isGM: game.user.isGM,
      menu,
      theme: game.settings.get("starwarsffg", "dicetheme"),
      campaignDay: game.settings.get("starwarsffg", "campaignDay"),
    };
  }

  /** @override */
  async _onRender(context, options) {
    await super._onRender(context, options);

    // Restore this user's saved widget position, or default to the lower-left
    // corner (above the players list). The old `innerWidth - screen.width`
    // formula produced a negative left on any window narrower than the screen,
    // rendering the widget off-screen. Clamp so at least a corner stays visible
    // if the window shrank since the position was saved.
    const vw = $(window).width() || 0;
    const vh = $(window).height() || 0;
    const saved = game.settings.get("starwarsffg", "destinyTrackerPosition");
    let left = 10;
    let top = vh - 300;
    if (saved && Number.isFinite(saved.left) && Number.isFinite(saved.top)) {
      left = saved.left;
      top = saved.top;
    }
    this.setPosition({
      left: Math.min(Math.max(0, left), Math.max(0, vw - 50)),
      top: Math.min(Math.max(0, top), Math.max(0, vh - 50)),
    });

    this._activateListeners($(this.element));
  }

  _activateListeners(html) {
    // Make the widget draggable by its body and remember the position per-user.
    this._setupDragging(html);

    // future functionality to allow multiple menu items to be passed in

    $.expr.filters.offscreen = function (el) {
      var rect = el.getBoundingClientRect();
      return rect.x + rect.width < 0 || rect.y + rect.height < 0 || rect.y + rect.height > window.innerHeight || rect.x + rect.width > window.innerWidth || rect.x > window.innerWidth || rect.y > window.innerHeight;
    };

    html.find(".dropbtn").click((event) => {
      const id = `#${$(event.currentTarget).attr("id")}Content`;
      $(html.find(id)).toggleClass("show");

      if ($(".dropdown-content").is(":offscreen")) {
        $(html.find(id)).addClass("vertical");
      } else {
        $(html.find(id)).removeClass("vertical");
      }
    });

    html.find(".dropdown-content a").click((event) => {
      event.preventDefault();
      event.stopPropagation();

      const index = event.currentTarget.dataset.value;
      this.menu[index].callback();
    });

    html.find(".destiny-points").click(async (event) => {
      // Ignore the click that fires at the end of a drag (see _setupDragging).
      if (this._suppressFlip) { this._suppressFlip = false; return; }
      const pointType = event.currentTarget.dataset.group;
      var typeName = null;
      const add = event.shiftKey;
      const remove = event.ctrlKey || event.metaKey;
      var flipType = null;
      var actionType = null;
      if (pointType == "dPoolLight") {
        flipType = "dPoolDark";
        typeName = game.i18n.localize(game.settings.get("starwarsffg", "destiny-pool-light"));
      } else {
        flipType = "dPoolLight";
        typeName = game.i18n.localize(game.settings.get("starwarsffg", "destiny-pool-dark"));
      }
      var messageText;

      if (!add && !remove) {
        if (game.settings.get("starwarsffg", pointType) == 0) {
          ui.notifications.warn(`Cannot flip a ${typeName} point; 0 remaining.`);
          return;
        } else {
          let pool = { light: 0, dark: 0 };
          if (flipType == "dPoolLight") {
            pool.light = game.settings.get("starwarsffg", flipType) + 1;
            pool.dark = game.settings.get("starwarsffg", pointType) - 1;
          } else if (flipType == "dPoolDark") {
            pool.dark = game.settings.get("starwarsffg", flipType) + 1;
            pool.light = game.settings.get("starwarsffg", pointType) - 1;
          }

          if (game.user.isGM) {
            game.settings.set("starwarsffg", "dPoolLight", pool.light);
            game.settings.set("starwarsffg", "dPoolDark", pool.dark);
          } else {
            await game.socket.emit("system.starwarsffg", { pool });
          }

          messageText = `<div class="destiny-flip ${flipType}">
          <div class="destiny-title">${game.i18n.localize("SWFFG.DestinyFlipMessage")}: <span class="${typeName}">${typeName}</span></div>
          <div class="destiny-left ${flipType !== "dPoolDark"} dark">${game.i18n.localize(game.settings.get("starwarsffg", "destiny-pool-dark"))} ${game.i18n.localize("SWFFG.DestinyFlipRemaining")}: ${pool.dark}</div>
          <div class="destiny-left ${flipType !== "dPoolLight"} light">${game.i18n.localize(game.settings.get("starwarsffg", "destiny-pool-light"))} ${game.i18n.localize("SWFFG.DestinyFlipRemaining")}: ${pool.light}</div>
          </div>`;
        }
      } else if (add) {
        if (!game.user.isGM) {
          ui.notifications.warn("Only GMs can add or remove points from the Destiny Pool.");
          return;
        }
        const setting = game.settings.settings.get(`starwarsffg.${pointType}`);
        game.settings.set("starwarsffg", pointType, game.settings.get("starwarsffg", pointType) + 1);
        messageText = "Added a " + typeName + " point.";
      } else if (remove) {
        if (!game.user.isGM) {
          ui.notifications.warn("Only GMs can add or remove points from the Destiny Pool.");
          return;
        }
        const setting = game.settings.settings.get(`starwarsffg.${pointType}`);
        game.settings.set("starwarsffg", pointType, game.settings.get("starwarsffg", pointType) - 1);
        messageText = "Removed a " + typeName + " point.";
      }

      ChatMessage.create({
        user: game.user.id,
        content: messageText,
      });
    });

    // Campaign-day advance ([+], GM only): bump the world day by 1 directly, no
    // prompt. The setting's onChange rewrites the .ffg-campaign-day-value span in
    // place (live-refresh path 2), so this handler never touches the DOM — leaving
    // the [+] node and its listener intact (no widget re-render).
    html.find(".ffg-campaign-day-advance").click(async (event) => {
      event.preventDefault();
      event.stopPropagation();
      const current = Math.floor(Number(game.settings.get("starwarsffg", "campaignDay")) || 0);
      await game.settings.set("starwarsffg", "campaignDay", current + 1);
    });

    // Campaign-day edit (GM only): right-click the readout for a one-item "Edit"
    // context menu that opens a dialog to OVERRIDE the current day with any value.
    // Delegated from the widget root so it survives any re-query of the readout.
    if (game.user.isGM) {
      html.on("contextmenu", "#ffg-campaign-day", (event) => {
        event.preventDefault();
        event.stopPropagation();
        const oe = event.originalEvent || event;
        this._openCampaignDayMenu(oe.clientX, oe.clientY);
      });
    }

    // handle previously created roll destiny chat messages
    $(".ffg-destiny-roll").on("click", this.OnClickRollDestiny.bind(this));

    // setup chat hook for destiny roll
    Hooks.on("renderChatMessageHTML", (...args) => {
      const html = args[1];
      $(html).on("click", ".ffg-destiny-roll", this.OnClickRollDestiny.bind(this));
    });

    // setup socket handler for checking destiny roll
    game.socket.on("system.starwarsffg", async (...args) => {
      if (args[0]?.canIRollDestinyResponse === game.user.id && !game.user.isGM) {
        if (!args[0]?.rolled) {
          const roll = await this._rollDestiny();
          await game.socket.emit("system.starwarsffg", { destiny: game.user.id, light: roll.ffg.light, dark: roll.ffg.dark });
        } else {
          ui.notifications.error(`${game.i18n.localize("SWFFG.DestinyAlreadyRolled")}`);
        }
      }
    });

    if (game.user.isGM) {
      // socket handler for GM
      game.socket.on("system.starwarsffg", async (...args) => {
        // check if this is the GM intended to answer the question or not
        if (game.user.id !== game.users.activeGM?.id) {
          // limit rolling to a single GM
          return;
        }
        // Can user roll destiny? Or have they already rolled
        if (args[0]?.canIRollDestiny) {
          let rolled = false;

          try {
            rolled = await game.settings.get("starwarsffg", `destinyrollers${args[0]?.canIRollDestiny}`);
          } catch (err) {
            game.settings.register("starwarsffg", `destinyrollers${args[0].canIRollDestiny}`, {
              name: "DestinyRoll",
              scope: "client",
              default: false,
              config: false,
              type: Boolean,
            });
          }

          await game.socket.emit("system.starwarsffg", { canIRollDestinyResponse: args[0]?.canIRollDestiny, rolled });
        }

        // Handle user initiated destiny pool flips
        if (args[0]?.pool) {
          const light = await game.settings.get("starwarsffg", "dPoolLight");
          const dark = await game.settings.get("starwarsffg", "dPoolDark");

          const request = {
            id: "player",
            type: "destiny-flip",
            light: +light - +args[0].pool.light,
            dark: +dark - +args[0].pool.dark,
          };

          // only allow one player flip at a time.
          if (!this.destinyQueue.find((q) => q.id === args[0].destiny)) {
            this.destinyQueue.push(request);
          }
        }

        // Handle user report for initial Destiny roll
        if (args[0]?.destiny) {
          const request = {
            id: args[0].destiny,
            type: "destiny-roll",
            light: args[0].light,
            dark: args[0].dark,
          };

          // make sure only one player destiny roll is queued.
          if (!this.destinyQueue.find((q) => q.id === args[0].destiny) && CONFIG.FFG.DestinyGM === game.user.id) {
            this.destinyQueue.push(request);
          }
        }

        if (!this.isRunningQueue) {
          this._processDestinyRequests();
        }
      });
    }
  }

  /**
   * Show a tiny one-item ("Edit") context menu at the cursor for the campaign-day
   * readout. Appended to <body> (the widget body is pointer-events:none), and
   * dismissed on the next click/right-click/scroll/Escape anywhere.
   * @param {number} x  clientX
   * @param {number} y  clientY
   */
  _openCampaignDayMenu(x, y) {
    document.querySelector(".ffg-campaign-day-menu")?.remove();
    const menu = document.createElement("div");
    menu.className = "ffg-campaign-day-menu";
    // Position pinned inline so the menu is cursor-anchored even if the stylesheet
    // rule is absent for the active theme.
    menu.style.position = "fixed";
    menu.style.zIndex = "1000";
    menu.style.left = `${x}px`;
    menu.style.top = `${y}px`;
    const edit = document.createElement("a");
    edit.className = "ffg-campaign-day-edit";
    edit.innerHTML = `<i class="fas fa-pen"></i> ${game.i18n.localize("SWFFG.Codex.CritTrauma.EditDay")}`;
    menu.appendChild(edit);
    document.body.appendChild(menu);

    // Keep it on-screen if opened near the right/bottom edge.
    const r = menu.getBoundingClientRect();
    if (r.right > window.innerWidth) menu.style.left = `${Math.max(0, window.innerWidth - r.width - 4)}px`;
    if (r.bottom > window.innerHeight) menu.style.top = `${Math.max(0, window.innerHeight - r.height - 4)}px`;

    const cleanup = () => {
      menu.remove();
      document.removeEventListener("pointerdown", onDoc, true);
      document.removeEventListener("wheel", cleanup, true);
      window.removeEventListener("blur", cleanup);
      document.removeEventListener("keydown", onKey, true);
    };
    // A click inside the menu (i.e. on "Edit") must NOT dismiss before its own
    // handler runs — only outside interactions dismiss.
    const onDoc = (ev) => { if (!menu.contains(ev.target)) cleanup(); };
    const onKey = (ev) => { if (ev.key === "Escape") cleanup(); };
    edit.addEventListener("click", (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      cleanup();
      this._openSetDayDialog();
    });
    // Defer so the right-click that opened the menu doesn't immediately dismiss it.
    setTimeout(() => {
      document.addEventListener("pointerdown", onDoc, true);
      document.addEventListener("wheel", cleanup, true);
      window.addEventListener("blur", cleanup);
      document.addEventListener("keydown", onKey, true);
    }, 0);
  }

  /**
   * Dialog to OVERRIDE the campaign day with an explicit value (GM only). Sets the
   * world setting directly; its onChange refreshes the readout + open Codex sheets.
   */
  async _openSetDayDialog() {
    const current = Math.floor(Number(game.settings.get("starwarsffg", "campaignDay")) || 0);
    const n = await foundry.applications.api.DialogV2.wait({
      window: { title: game.i18n.localize("SWFFG.Codex.CritTrauma.EditDayTitle") },
      content: `<form class="form"><div class="form-group"><label>${game.i18n.localize("SWFFG.Codex.CritTrauma.EditDayLabel")}</label><input type="number" name="day" value="${current}" min="0" step="1" autofocus /></div></form>`,
      rejectClose: false,
      buttons: [{
        action: "set",
        label: game.i18n.localize("SWFFG.Codex.CritTrauma.EditDaySet"),
        default: true,
        callback: (ev, button) => Math.floor(Number(button.form.elements.day.value)),
      }],
    });
    if (n === null || n === undefined || Number.isNaN(n)) return;
    await game.settings.set("starwarsffg", "campaignDay", Math.max(0, n));
  }

  /**
   * Make the floating widget draggable by its body and persist the position
   * per-user. The window header is hidden (this is a chrome widget), so V2's
   * built-in header drag is unavailable. A custom pointer-drag is used so it can
   * coexist with the flip-on-click handlers on the destiny points: a click flips
   * a point, a drag (movement past a small threshold) moves the widget.
   * @param {JQuery} html
   */
  _setupDragging(html) {
    const root = this.element;
    const handle = html.find(".swffg-destiny")[0];
    if (!root || !handle) return;
    // The widget body is pointer-events:none by default (so clicks fall through
    // to the canvas); enable it on the drag handle so it can be grabbed.
    handle.style.pointerEvents = "auto";
    handle.style.cursor = "move";

    let active = false;
    let moved = false;
    let sx = 0, sy = 0, startLeft = 0, startTop = 0;

    const onDown = (event) => {
      if (event.button !== 0) return;
      active = true;
      moved = false;
      sx = event.clientX;
      sy = event.clientY;
      const r = root.getBoundingClientRect();
      startLeft = r.left;
      startTop = r.top;
      // Do NOT setPointerCapture here. Capturing on pointerdown retargets the
      // matching pointerup to this handle and suppresses the synthesized `click`
      // on the actual child that was pressed -- so clicks on .destiny-points (the
      // pool flip) and the group-manager menu links (.dropdown-content a) never
      // fire their handlers. Capture is acquired lazily in onMove, only once an
      // actual drag is detected, so a plain click is never swallowed.
    };

    const onMove = (event) => {
      if (!active) return;
      const dx = event.clientX - sx;
      const dy = event.clientY - sy;
      if (!moved && (Math.abs(dx) > 4 || Math.abs(dy) > 4)) {
        moved = true;
        // This is now a real drag: capture the pointer so movement keeps tracking
        // even if it leaves the handle. (A plain click never reaches here, so its
        // `click` event is left intact -- see onDown.)
        try { handle.setPointerCapture(event.pointerId); } catch (e) { /* ignore */ }
      }
      if (!moved) return;
      const vw = window.innerWidth;
      const vh = window.innerHeight;
      const w = root.offsetWidth;
      const h = root.offsetHeight;
      const left = Math.min(Math.max(0, startLeft + dx), Math.max(0, vw - w));
      const top = Math.min(Math.max(0, startTop + dy), Math.max(0, vh - h));
      this.setPosition({ left, top });
    };

    const onUp = (event) => {
      if (!active) return;
      active = false;
      try { handle.releasePointerCapture(event.pointerId); } catch (e) { /* ignore */ }
      if (moved) {
        // A click is synthesized at the end of a drag; suppress the next flip so
        // dragging across a destiny point does not also flip it. Auto-clear in
        // case the browser does not emit that click (large drags often do not).
        this._suppressFlip = true;
        setTimeout(() => { this._suppressFlip = false; }, 0);
        game.settings.set("starwarsffg", "destinyTrackerPosition", {
          left: this.position.left,
          top: this.position.top,
        });
      }
    };

    handle.addEventListener("pointerdown", onDown);
    handle.addEventListener("pointermove", onMove);
    handle.addEventListener("pointerup", onUp);
    handle.addEventListener("pointercancel", onUp);
  }

  // Click event for Roll Destiny Chat Message
  async OnClickRollDestiny(event) {
    event.preventDefault();
    event.stopPropagation();
    if (!game.user.isGM) {
      await game.socket.emit("system.starwarsffg", { canIRollDestiny: game.user.id });
    }

    if (game.user.isGM) {
      const roll = await this._rollDestiny();

      const light = await game.settings.get("starwarsffg", "dPoolLight");
      const dark = await game.settings.get("starwarsffg", "dPoolDark");

      await game.settings.set("starwarsffg", "dPoolLight", light + roll.ffg.light);
      await game.settings.set("starwarsffg", "dPoolDark", dark + roll.ffg.dark);
    }
  }

  async _processDestinyRequests() {
    CONFIG.logger.debug(`Processing ${this.destinyQueue.length} Destiny Requests`);

    while (this.destinyQueue.length > 0) {
      const request = this.destinyQueue.shift();
      CONFIG.logger.debug(`Processing Destiny Request (${request.type}) from User ${request.id}`, request);

      const light = await game.settings.get("starwarsffg", "dPoolLight");
      const dark = await game.settings.get("starwarsffg", "dPoolDark");

      switch (request.type) {
        case "destiny-roll": {
          game.settings.set("starwarsffg", `destinyrollers${request.id}`, true);
          await game.settings.set("starwarsffg", "dPoolLight", light + request.light);
          await game.settings.set("starwarsffg", "dPoolDark", dark + request.dark);
          break;
        }
        case "destiny-flip": {
          await game.settings.set("starwarsffg", "dPoolLight", light - request.light);
          game.settings.set("starwarsffg", "dPoolDark", dark - request.dark);
          break;
        }
      }
    }

    CONFIG.logger.debug(`Done Processing Destiny Requests`);
    this.isRunningQueue = false;
  }

  async _rollDestiny() {
    const pool = new DicePoolFFG({
      force: 1,
    });

    const roll = new game.ffg.RollFFG(pool.renderDiceExpression());
    await roll.toMessage({
      user: game.user.id,
      flavor: `${game.i18n.localize("SWFFG.Rolling")} ${game.i18n.localize("SWFFG.DestinyPool")}...`,
    });

    return roll;
  }
}

import {xpLogEarn} from "./helpers/actor-helpers.js";
import ActorHelpers from "./helpers/actor-helpers.js";
import { FFGFormApplication } from "./apps/ffg-form-application.js";

const { DialogV2 } = foundry.applications.api;

export class GroupManager extends FFGFormApplication {
  constructor(object = {}, options = {}) {
    super(object, options);
    this.obligations = [];
    this.duties = [];
  }

  static DEFAULT_OPTIONS = {
    id: "group-manager",
    classes: ["starwarsffg", "form", "group-manager"],
    window: {
      title: "Group Manager",
      resizable: true,
    },
    position: {
      width: 500,
      height: 900,
    },
    form: {
      submitOnChange: true,
      closeOnSubmit: false,
    },
    submitOnClose: true,
  };

  static PARTS = {
    content: {
      root: true,
      template: "systems/starwarsffg/templates/group-manager.html",
    },
  };

  /**
   * GM-only editable. Computed live -- it cannot live in the static
   * DEFAULT_OPTIONS field, which is evaluated at class-definition time (module
   * load), before `game.user` exists.
   * @override
   */
  get isEditable() {
    return game.user.isGM;
  }

  /**
   * Lower bound for interactive resize. The Player Characters table needs
   * ~500px to show all columns (Name / Wounds / Strain / Soak / Combat / XP)
   * without clipping; don't let the user drag the window narrower than that.
   * Enforced by the base setPosition.
   * @override
   */
  _minDimensions() {
    return { width: 500, height: 200 };
  }

  /* -------------------------------------------- */

  /**
   * Obtain module metadata and merge it with game settings which track current module visibility
   * @return {Object}   The data provided to the template when rendering the form
   */
  async _prepareContext(_options) {
    const pcListMode = game.settings.get("starwarsffg", "pcListMode");
    const players = game.users.contents.filter((u) => {
      const isValidUser = !u.isGM || game.settings.get("starwarsffg", "GMCharactersInGroupManager");
      // if active mode is selected, only return users actively playing a character, otherwise return all valid users
      if (pcListMode === "active") {
        return isValidUser && u.active;
      }
      return isValidUser;
    });
    if (players.length > 0) {
      players.connected = true;
    }
    const characters = [];
    let obligationRangeStart = 0;
    let dutyRangeStart = 0;
    if (pcListMode === "active") {
      players.forEach((player) => {
        if (player.character) {
          try {
            obligationRangeStart = this._addCharacterObligationDuty(player.character, obligationRangeStart, player.character.system.obligationlist, "obligations");
            dutyRangeStart = this._addCharacterObligationDuty(player.character, dutyRangeStart, player.character.system.dutylist, "duties");
            //obligationRangeStart = this._addCharacterObligations(player.character, obligationRangeStart);
            //dutyRangeStart = this._addCharacterDuties(player.character, dutyRangeStart);
            characters.push(player.character);
          } catch (err) {
            CONFIG.logger.warn(`Unable to add player (${player.character.name}) to obligation/duty table`, err);
          }
        }
      });
    } else if (pcListMode === "owned") {
      game.actors.filter((actor) => {
      // filter to characters only
  if (actor.type !== "character") {
    return false;
  }
  for (let player of players) {
    if (actor.testUserPermission(player, "OWNER")) {
      // use actor if any player has ownership
      return true;
    }
  }
  return false;
})
      .forEach((c) => {
        try {
          obligationRangeStart = this._addCharacterObligationDuty(c, obligationRangeStart, c.system.obligationlist, "obligations");
          dutyRangeStart = this._addCharacterObligationDuty(c, dutyRangeStart, c.system.dutylist, "duties");
          characters.push(c);
          // obligationRangeStart = this._addCharacterObligations(c, obligationRangeStart);
          // dutyRangeStart = this._addCharacterDuties(c, dutyRangeStart);
        } catch (err) {
          CONFIG.logger.warn(`Unable to add player (${c.name}) to obligation/duty table`, err);
        }
      });
    }

    const dPool = { light: game.settings.get("starwarsffg", "dPoolLight"), dark: game.settings.get("starwarsffg", "dPoolDark") };
    const initiative = CONFIG.Combat.initiative.formula;
    const isGM = game.user.isGM;
    const theme = CONFIG.FFG.theme;
    players.hasObligation = this.obligations?.length;
    let obligations = this.obligations;
    players.hasDuty = this.duties?.length;
    let duties = this.duties;

    const labels = {
      light: game.settings.get("starwarsffg", "destiny-pool-light"),
      dark: game.settings.get("starwarsffg", "destiny-pool-dark"),
    };

    return { dPool, players, initiative, isGM, pcListMode, characters, obligations, duties, theme, labels };
  }

  /* -------------------------------------------- */

  /** @override */
  async _onRender(context, options) {
    await super._onRender(context, options);
    const html = $(this.element);

    // The PC table is shorter for non-GMs (no editable destiny/XP controls).
    if (!game.user.isGM) this.setPosition({ height: 470 });

    // Everything below here is only needed if the sheet is editable
    if (!this.isEditable) return;

    // Flip destiny pool DARK to LIGHT
    html.find(".destiny-flip-dtl").click((ev) => {
      let LightPool = this.form.elements["dPool.light"].value;
      let DarkPool = this.form.elements["dPool.dark"].value;
      if (DarkPool > 0) {
        LightPool++;
        DarkPool--;
        this.form.elements["dPool.light"].value = LightPool;
        this.form.elements["dPool.dark"].value = DarkPool;
      }
    });

    // Flip destiny pool LIGHT to DARK
    html.find(".destiny-flip-ltd").click((ev) => {
      let LightPool = this.form.elements["dPool.light"].value;
      let DarkPool = this.form.elements["dPool.dark"].value;
      if (LightPool > 0) {
        LightPool--;
        DarkPool++;
        this.form.elements["dPool.light"].value = LightPool;
        this.form.elements["dPool.dark"].value = DarkPool;
      }
    });

    // Listen for initiative dropdown change and update initiative formula accordingly.
    html.find(".initiative-mode").change((ev) => {
      const init_value = ev.target.value.charAt(0).toLowerCase();
      game.settings.set("starwarsffg", "initiativeRule", init_value);
      ui.notifications.info(`Initiative mode changed to: ${ev.target.value}`);
    });

    // Add individual character to combat tracker.
    html.find(".add-to-combat").click((ev) => {
      const character = ev.currentTarget.dataset.character;
      this._addCharacterToCombat(character, game.combat);
    });
    // Add all characters to combat tracker.
    html.find(".group-to-combat").click((ev) => {
      const characters = [];
      const groupmanager = document.getElementById("group-manager");
      const charlist = groupmanager.querySelectorAll('tr[class="player-character"]');
      const tokens = canvas.tokens.controlled;
      charlist.forEach((element) => {
        characters.push(element.dataset["character"]);
      });
      this._addGroupToCombat(characters, tokens, game.combat);
    });

    // Add XP to individual character.
    html.find(".add-XP").click((ev) => {
      const character = ev.currentTarget.dataset.character;
      const c = game.actors.get(character);
      this._grantXP(c);
    });
    // Add XP to all characters.
    html.find(".bulk-XP").click((ev) => {
      const characters = [];
      const groupmanager = document.getElementById("group-manager");
      const charlist = groupmanager.querySelectorAll('tr[class="player-character"]');
      charlist.forEach((element) => {
        characters.push(element.dataset["character"]);
      });
      this._bulkXP(characters);
    });

    html.find(".obligation-button").click((ev) => {
      this._rollObligation();
    });

    html.find(".duty-button").click((ev) => {
      this._rollDuty();
    });

    // Open character sheet on row click.
    html.find(".player-character").click((ev) => {
      if (!$(ev.target).hasClass("fas") && ev.target.localName !== "button") {
        const li = $(ev.currentTarget);
        const actorId = li.data("character");
        const actor = game.actors.get(actorId);
        if (actor?.sheet) {
          actor.sheet.render(true);
        }
      }
    });
  }

  /**
   * This method is called upon form submission after form data is validated
   * @param event {Event}       The initial triggering submission event
   * @param formData {Object}   The object of validated form data with which to update the object
   * @private
   */
  _updateObject(event, formData) {
    const formDPool = foundry.utils.expandObject(formData).dPool || {};
    game.settings.set("starwarsffg", "dPoolLight", formDPool.light);
    game.settings.set("starwarsffg", "dPoolDark", formDPool.dark);
    return formData;
  }

  _addCharacterObligationDuty(character, rangeStart, list, type) {
    try {
      Object.values(list).forEach((item) => {
        let rangeEnd = rangeStart + parseInt(item.magnitude);
        this[type].push({
          playerId: character.id,
          name: character.name,
          type: item.type,
          magnitude: item.magnitude,
          rangeStart: rangeStart + 1,
          rangeEnd: rangeEnd,
        });
        rangeStart = rangeEnd;
      });
    } catch (err) {
      CONFIG.logger.warn(`Unable to add player ${character.name} `);
    }
    return rangeStart;
  }

  async _rollObligation() {
    this._rollTable(this.obligations, game.i18n.localize("SWFFG.DescriptionObligation"));
  }

  async _rollDuty() {
    this._rollTable(this.duties, game.i18n.localize("SWFFG.DescriptionDuty"));
  }

  async _rollTable(table, type) {
    let r = new Roll("1d100");
    await r.evaluate();
    let rollOptions = game.settings.get("starwarsffg", "privateTriggers") ? { rollMode: "gmroll" } : {};
    r.toMessage(
      {
        flavor: `${game.i18n.localize("SWFFG.Rolling")} ${type}...`,
      },
      rollOptions
    );
    let filteredTable = table.filter((entry) => entry.rangeStart <= r.total && r.total <= entry.rangeEnd);
    let tableResult = filteredTable?.length ? `${filteredTable[0].type} ${type} ${game.i18n.localize("SWFFG.Triggered")} ${game.i18n.localize("SWFFG.For")} @Actor[${filteredTable[0].playerId}]{${filteredTable[0].name}}` : `${game.i18n.localize("SWFFG.OptionValueNo")} ${type} ${game.i18n.localize("SWFFG.Triggered")}`;
    let messageOptions = {
      user: game.user.id,
      content: tableResult,
    };
    if (game.settings.get("starwarsffg", "privateTriggers")) {
      messageOptions.whisper = ChatMessage.getWhisperRecipients("GM");
    }
    ChatMessage.create(messageOptions);
  }

  async _addGroupToCombat(characters, targets, cbt) {
    await this._setupCombat(cbt);
    let tokens = targets.filter((t) => !t.inCombat);
    await Promise.all(
      characters.map(async (c) => {
        let token = await this._getCharacterToken(game.actors.get(c));
        if (token) {
          if (!token._controlled && !token.inCombat) {
            tokens.push(token);
          }
        } else {
          ui.notifications.warn(`${c.name} has no active Token in the current scene.`);
        }
      })
    );
    const createData = tokens.map((t) => {
      return { tokenId: t.id };
    });
    await game.combat.createEmbeddedDocuments('Combatant', createData);
  }

  async _addCharacterToCombat(character, cbt) {
    await this._setupCombat(cbt);
    let token = await this._getCharacterToken(game.actors.get(character));
    if (token && !token.inCombat) {
        await game.combat.createEmbeddedDocuments('Combatant', [{ tokenId: token.id }]);
      //await game.combat.createCombatant({ tokenId: token.id });
    } else {
      ui.notifications.warn(`User has no active Token in the current scene.`);
    }
  }

  async _getCharacterToken(character) {
    let activeTokens = character.getActiveTokens();
    return activeTokens.length ? activeTokens[0] : null;
  }

  async _setupCombat(cbt) {
    // If no combat encounter is active, create one.
    if (!cbt) {
      cbt = await Combat.create({scene: canvas.scene.id, active: true});
    }
  }

  async _grantXP(character) {
    if (character?.type !== "character") {
      return;
    }
    const id = foundry.utils.randomID();
    const description = game.i18n.localize("SWFFG.GrantXPTo") + ` ${character.name}...`;
    const content = await foundry.applications.handlebars.renderTemplate("systems/starwarsffg/templates/grant-xp.html", {
      id,
    });

    DialogV2.wait({
      window: { title: description },
      content,
      buttons: [
        {
          action: "one",
          icon: "fas fa-check",
          label: game.i18n.localize("SWFFG.GrantXP"),
          default: true,
          callback: async () => {
            const state = await ActorHelpers.beginEditMode(character, true);
            const container = document.getElementById(id);
            const amount = container.querySelector('input[name="amount"]');
            const note = container.querySelector('input[name="note"]').value;
            const available = +character.system.experience.available + +amount.value;
            const total = +character.system.experience.total + +amount.value;
            character.update({ ["system.experience.total"]: +character.system.experience.total + +amount.value });
            character.update({ ["system.experience.available"]: +character.system.experience.available + +amount.value });
            await xpLogEarn(character, amount.value, available, total, note);
            await ActorHelpers.endEditMode(character, state, true);
            ui.notifications.info(`Granted ${amount.value} XP to ${character.name}.`);
          },
        },
        {
          action: "two",
          icon: "fas fa-times",
          label: game.i18n.localize("SWFFG.Cancel"),
        },
      ],
      rejectClose: false,
    });
  }

  async _bulkXP(characters) {
    const id = foundry.utils.randomID();
    const description = game.i18n.localize("SWFFG.GrantXPToAllCharacters");
    const content = await foundry.applications.handlebars.renderTemplate("systems/starwarsffg/templates/grant-xp.html", {
      id,
    });

    DialogV2.wait({
      window: { title: description },
      content,
      buttons: [
        {
          action: "one",
          icon: "fas fa-check",
          label: game.i18n.localize("SWFFG.GrantXP"),
          default: true,
          callback: async () => {
            const container = document.getElementById(id);
            const amount = container.querySelector('input[name="amount"]');
            const note = container.querySelector('input[name="note"]').value;
            for (const c of characters) {
              const character = game.actors.get(c);
              if (character?.type !== "character") {
                continue;
              }
              const state = await ActorHelpers.beginEditMode(character, true);
              const available = +character.system.experience.available + +amount.value;
              const total = +character.system.experience.total + +amount.value;
              character.update({ ["system.experience.total"]: +character.system.experience.total + +amount.value });
              character.update({ ["system.experience.available"]: +character.system.experience.available + +amount.value });
              await xpLogEarn(character, amount.value, available, total, note);
              await ActorHelpers.endEditMode(character, state, true);
              ui.notifications.info(`Granted ${amount.value} XP to ${character.name}.`);
            }
          },
        },
        {
          action: "two",
          icon: "fas fa-times",
          label: game.i18n.localize("SWFFG.Cancel"),
        },
      ],
      rejectClose: false,
    });
  }
}

