  async createActor(actorId) {
    CONFIG.logger.debug("Creating new actor...");
    const newActor = game.actors.get(actorId);
    if (!newActor) {
      ui.notifications.error("Actor not found.");
      return;
    }

    const xp = await this.calcXp();
    const totalXp = xp.total;
    const availableXp = xp.available;

    // grant XP
    await newActor.update({
      "system.experience": {
        total: totalXp,
        available: availableXp,
      }
    });

    // apply XP purchases
    for (const characteristicPurchase of this.data.purchases.xp.characteristics) {
      const updateKey = `system.characteristics.${characteristicPurchase.key}.value`;
      const newValue = newActor.system.characteristics[characteristicPurchase.key].value + 1;
      await newActor.update({[updateKey]: newValue})
    }
    for (const skillPurchase of this.data.purchases.xp.skills) {
      const updateKey = `system.skills.${skillPurchase.key}.rank`;
      const newValue = newActor.system.skills[skillPurchase.key].rank + 1;
      await newActor.update({[updateKey]: newValue})
    }

    // add actor items to the actor
    const items = [];
    // the various item types are in slightly different formats, so let's add them explicitly
    // backgrounds
    for (const backKey of Object.keys(this.data.selected.background)) {
      if (this.data.selected.background[backKey]?.uuid) {
        items.push(this.data.selected.background[backKey]);
      }
    }
    // obligations
    for (const item of this.data.selected.obligations) {
      if (item?.uuid) {
        items.push(item);
      }
    }
    // species
    if (this.data.selected.species?.uuid) {
      items.push(this.data.selected.species);
    }
    // career (skill ranks are later)
    if (this.data.selected.career?.uuid) {
      items.push(this.data.selected.career);
    }
    // specialization (skill ranks are later)
    if (this.data.selected.specialization?.uuid) {
      items.push(this.data.selected.specialization);
    }
    // motivations
    for (const item of this.data.selected.motivations) {
      if (item?.item?.uuid) {
        items.push(item);
      }
    }

    CONFIG.logger.debug(`Granting the following items: ${JSON.stringify(items)}`);
    await newActor.createEmbeddedDocuments("Item", items);

    // apply credit purchases
    const credits = await this.calcCredits();
    const creditItems = [];
    for (const creditItem of this.data.purchases.credits) {
      creditItems.push(creditItem.item);
    }
    CONFIG.logger.debug(`Processed the following credit purchases: ${JSON.stringify(creditItems)}`);

    await newActor.createEmbeddedDocuments("Item", creditItems);
    await newActor.update({
      "system.stats.credits": {
        value: credits.available + this.data.spendingCredits,
      }
    });

    // apply XP spend log items

    // apply obligation values
    const obligation = await this.calcObligation();
    await newActor.update({"system": {
      [obligation.key]: {
        value: obligation.available,
      }
    }});

    const careerItem = newActor.items.find(i => i.type === "career");
    if (careerItem) {
      for (const skillPurchase of this.data.selected.careerCareerSkillRanks) {
        const nk = new Date().getTime();
        await careerItem.update({
          "system.attributes": {
            [`attr${nk}`]: {
              modtype: "Skill Rank",
              mod: skillPurchase,
              value: 1,
            },
          }
        });
        const AE = {
          name: `attr${nk}`,
          changes: [{
            key: `system.skills.${skillPurchase}.rank`,
            mode: AE_MODES.ADD,
            value: 1,
          }],
        };
        await careerItem.createEmbeddedDocuments("ActiveEffect", [AE]);
      }
    }

    const specializationItem = newActor.items.find(i => i.type === "specialization" && i.name === this.data.selected.specialization?.name);
    if (specializationItem) {
      for (const skillPurchase of this.data.selected.specializationCareerSkillRanks) {
        const nk = new Date().getTime();
        await specializationItem.update({
          "system.attributes": {
            [`attr${nk}`]: {
              modtype: "Skill Rank",
              mod: skillPurchase,
              value: 1,
            },
          }
        });
        const AE = {
          name: `attr${nk}`,
          changes: [{
            key: `system.skills.${skillPurchase}.rank`,
            mode: AE_MODES.ADD,
            value: 1,
          }],
        };
        await specializationItem.createEmbeddedDocuments("ActiveEffect", [AE]);
      }
    }

    await xpLogEarn(newActor, totalXp, totalXp, totalXp, "Initial State");
    await xpLogSpend(newActor, "Character Creation Changes", totalXp - availableXp, availableXp, totalXp);

    newActor.sheet.render(true);
  }
}

export default class Helpers {
  static logger = {
    log: (...args) => {
      console.log(`${CONFIG.module} | `, ...args);
    },
    debug: (...args) => {
      if (game.settings.get("starwarsffg", "enableDebug")) {
        console.debug(`${CONFIG.module} | `, ...args);
      }
    },
    warn: (...args) => {
      console.warn(`${CONFIG.module} | `, ...args);
    },
    error: (...args) => {
      console.error(`${CONFIG.module} | `, ...args, new Error().stack);
    },
  };

  static async getSpecializationTalent(itemId, packName) {
    let item = game.items.get(itemId);
    if (item) {
      return item;
    } else {
      const pack = await game.packs.get(packName);
      if ( !pack.indexed ) await pack.getIndex();
      const entry = await pack.getIndex({fields: ["name", "type"]});
      if (entry) {
        const entryId = entry.filter((i) => i._id === itemId);
        return await pack.getDocument(entryId[0]._id);
      }
    }
  }

  /**
   * Uploads a file to Foundry without the UI Notification
   * @param  {string} source
   * @param  {string} path
   * @param  {blog} file
   * @param  {object} options
   */
  static async UploadFile(source, path, file, options) {
    if (typeof ForgeVTT !== "undefined" && ForgeVTT?.usingTheForge) {
      return Helpers.ForgeUploadFile("forgevtt", path, file, options);
    }

    let fd = new FormData();
    fd.set("source", source);
    fd.set("target", path);
    fd.set("upload", file);
    Object.entries(options).forEach((o) => fd.set(...o));

    const request = await fetch(foundry.applications.apps.FilePicker.implementation.uploadURL, { method: "POST", body: fd });
    if (request.status === 413) {
      return ui.notifications.error(game.i18n.localize("FILES.ErrorTooLarge"));
    }

    const response = await request.json().catch((err) => {
      return {};
    });
    if (response.error) {
      ui.notifications.error(response.error);
      return false;
    } else if (!response.path) {
      return ui.notifications.error(game.i18n.localize("FILES.ErrorSomethingWrong"));
    }
  }

  static async ForgeUploadFile(source, path, file, options) {
    const fd = new FormData();
    fd.append("file", file);
    fd.append("path", `${path}/${file.name}`);

    const response = await ForgeAPI.call("assets/upload", fd);
    if (!response || response.error) {
      ui.notifications.error(response ? response.error : "An unknown error occured accessing The Forge API");
      return false;
    } else {
      return { path: response.url };
    }
  }

  /**
   * Returns the difference between object 1 and 2
   * @param  {object} obj1
   * @param  {object} obj2
   * @returns {object}
   */
  static diff(obj1, obj2) {
    var result = {};
    for (const key in obj1) {
      if (obj2[key] != obj1[key]) result[key] = obj2[key];
      // NB: arrays are typeof "object", so the line below already recurses into
      // them; a separate `== "array"` check is dead (typeof never returns that).
      if (typeof obj2[key] == "object" && typeof obj1[key] == "object") result[key] = this.diff(obj1[key], obj2[key]);
    }
    return result;
  }

  /**
   * Returns the MIME type for a media file
   * @param  {string} header - Hex header for file.
   */
  static getMimeType(header) {
    let type = "";
    switch (header) {
      case "89504e47":
        type = "image/png";
        break;
      case "47494638":
        type = "image/gif";
        break;
      case "ffd8ffe0":
      case "ffd8ffe1":
      case "ffd8ffe2":
      case "ffd8ffe3":
      case "ffd8ffe8":
        type = "image/jpeg";
        break;
      default:
        type = "unknown"; // Or you can use the blob.type as fallback
    }

    return type;
  }
}

