/**
 * Capture a drag-and-drop event (used to capture adding crew members via a flag)
 * @param args - actor receiving the event, actor being dropped onto the recipient, ID of the actor being dropped on
 * @returns args - the input args (unmodified)
 */
export async function register_crew(...args) {
    CONFIG.logger.debug("Got possible register crew request");
    // check if this is an actor being dragged onto a vehicle
    let vehicle_actor;
    if (args[1].token) {
      // this is a token, not a real actor
      vehicle_actor = args[1].token?.actor;
      if (!vehicle_actor) {
        CONFIG.logger.debug("Not registering crew as entity is a token without a matching actor");
      }
    } else {
      vehicle_actor = args[0];
    }
    if (vehicle_actor.type !== 'vehicle' || args[2].type !== 'Actor') {
        // the target is not a vehicle or the actor being dragged onto it is a vehicle
        CONFIG.logger.debug("Not registering crew as item is not an actor or the target is not a vehicle");
        return args;
    }
    let drag_actor = null;
    if (args[2].hasOwnProperty('uuid')) {
        drag_actor = game.actors.get(args[2].uuid.split('.').pop());
    } else {
        drag_actor = game.actors.get(args[2].id);
    }
    if (drag_actor.type === 'vehicle') {
      CONFIG.logger.debug("Not registering crew as item is a vehicle");
      return args;
    }

    // prompt the user to select roles
    await selectRoles(vehicle_actor, drag_actor.id);
    return args;
}

/**
 * Remove a crew member + role pair from an actor
 * @param vehicle_actor actor object of the vehicle receiving the crew change
 * @param crew_member actor ID of the crew being changed
 * @param crew_role role of the crew to remove
 */
export function deregister_crew(vehicle_actor, crew_member, crew_role) {
    CONFIG.logger.debug("Got deregister crew request");
    const flag_data = vehicle_actor.getFlag('starwarsffg', 'crew');
    let new_flag_data = [];

    for (let i = 0; i < flag_data.length; i++) {
        if (flag_data[i].actor_id !== crew_member) {
            new_flag_data.push(flag_data[i]);
        } else if (flag_data[i].actor_id === crew_member && flag_data[i].role !== crew_role) {
            new_flag_data.push(flag_data[i]);
        } else {
            CONFIG.logger.debug("skipping removed crew - old data:", flag_data[i]);
        }
    }

    CONFIG.logger.debug("Final updated flag data: ", new_flag_data);
    if (new_flag_data.length === 0) {
      // the last crew member was removed, delete the data
      vehicle_actor.unsetFlag('starwarsffg', 'crew');
    } else {
      vehicle_actor.setFlag('starwarsffg', 'crew', new_flag_data);
    }
}

/**
 *
 * @param vehicle_actor actor object of the vehicle receiving the crew change
 * @param crew_member actor ID of the crew being changed
 * @param old_crew_role old role of the crew member
 * @param new_crew_role new role of the crew member
 */
export async function change_role(vehicle_actor, crew_member, old_crew_role, new_crew_role) {
    CONFIG.logger.debug(
      `Got role change request: vehicle ID: ${vehicle_actor} | crew ID: ${crew_member} | old role: ${old_crew_role} | new role: ${new_crew_role}`
    );
    const flag_data = vehicle_actor.getFlag('starwarsffg', 'crew');
    let new_flag_data = [];

    if (flag_data.filter(i => i.actor_id === crew_member && i.role === new_crew_role).length > 0) {
      CONFIG.logger.debug("Crew member already has same role, aborting");
      ui.notifications.warn(game.i18n.localize("SWFFG.Crew.Role.Duplicate"));
      return;
    }

    for (let i = 0; i < flag_data.length; i++) {
        if (flag_data[i].actor_id === crew_member && flag_data[i].role === old_crew_role) {
            flag_data[i].role = new_crew_role;
            new_flag_data.push(flag_data[i]);
        } else {
            new_flag_data.push(flag_data[i]);
        }
    }

    CONFIG.logger.debug("Final updated flag data: ", new_flag_data);
    // set the updated flag data
    vehicle_actor.setFlag('starwarsffg', 'crew', new_flag_data);
}

/**
 * Set the roles of a crew member on a vehicle to a new array of roles (deleting any not in the new array)
 * @param vehicle_actor - actor object of the vehicle receiving the crew change
 * @param crew_member_id - actor ID of the crew member being changed
 * @param new_crew_roles - array of new roles for the crew member
 * @returns {Promise<void>}
 */
export async function updateRoles(vehicle_actor, crew_member_id, new_crew_roles) {
  const flag_data = vehicle_actor.getFlag('starwarsffg', 'crew') || [];
  let new_flag_data = [];
  const crew_member = game.actors.get(crew_member_id);

  for (let i = 0; i < flag_data.length; i++) {
      if (flag_data[i].actor_id === crew_member_id) {
        const crewIndex = new_crew_roles.indexOf(flag_data[i].role);
        if (crewIndex >= 0) {
          new_flag_data.push(flag_data[i]);
          new_crew_roles.splice(crewIndex, 1);
        }
      } else {
          new_flag_data.push(flag_data[i]);
      }
  }

  for (const newRole of new_crew_roles) {
    new_flag_data.push({
      'actor_id': crew_member.id,
      'actor_name': crew_member.name,
      'role': newRole,
      'link':  await foundry.applications.ux.TextEditor.implementation.enrichHTML(crew_member?.link) || null,
    });
  }

  CONFIG.logger.debug("Final updated flag data: ", new_flag_data);
  // set the updated flag data
  vehicle_actor.setFlag('starwarsffg', 'crew', new_flag_data);
}

/**
 * Create a string representation of a skill check for a crew member in a particular role on a vehicle
 * @param vehicle actor object for the vehicle the crew is on
 * @param crew_id actor ID of the crew member
 * @param crew_role role of the actor (used to determine which skill to use)
 * @returns {string|boolean} a string representation of HTML for the dice in the roll
 */
export function build_crew_roll(vehicle, crew_id, crew_role) {
  // look up the sheet for passing to the roller
  const crew_member = game.actors.get(crew_id);
  const vehicle_actor = game.actors.get(vehicle);
  if (crew_member === undefined) {
    ui.notifications.warn(game.i18n.localize("SWFFG.Crew.Actor.Removed"));
    deregister_crew(vehicle_actor, crew_id, crew_role);
    return false;
  }
  const starting_pool = {'difficulty': 0};
  const registeredRoles = game.settings.get('starwarsffg', 'arrayCrewRoles');
  // don't attempt to draw a roll for the initiative role
  const initiativeRole = game.settings.get('starwarsffg', 'initiativeCrewRole');
  if (crew_role === initiativeRole.role_name) {
    return false;
  }
  // look up the defined metadata for the assigned role
  const role_info = registeredRoles.filter(i => i.role_name === crew_role);
  // validate the role still exists in our settings
  if (role_info.length === 0) {
    ui.notifications.warn(game.i18n.localize("SWFFG.Crew.Role.Removed"));
    return false;
  }
  // validate that it's a valid role
  if (role_info[0].role_skill === undefined) {
    ui.notifications.warn(game.i18n.localize("SWFFG.Crew.Role.Invalid"));
    return false;
  }
  // check if the pool uses handling
  if (role_info[0].use_handling) {
    const handling = vehicle_actor?.system?.stats?.handling?.value;
    // add modifiers from the vehicle handling
    if (handling > 0) {
      starting_pool['boost'] = handling;
    } else if (handling < 0) {
      starting_pool['setback'] = handling * -1;
    }
  }
  let pool = new DicePoolFFG(starting_pool);
  pool = get_dice_pool(crew_id, role_info[0].role_skill, pool);
  return pool.renderPreview().innerHTML;
}

/**
 * Build the dice pool for the built-in piloting check, which automatically resolves the correct piloting skill
 * @param vehicle_id - the vehicle actor object
 * @param pilot_id - the actor ID of the pilot
 * @param difficulty - the difficulty of the check (omit to default to "average")
 * @returns {Promise<Window.DicePoolFFG>}
 */
export async function buildPilotRoll(vehicle_id, pilot_id, difficulty = 2) {
  const starting_pool = {'difficulty': difficulty};
  const vehicle = game.actors.get(vehicle_id);
  const skillTheme = game.settings.get("starwarsffg", "skilltheme");

  // add modifiers from the vehicle handling
  const handling = vehicle?.system?.stats?.handling?.value;
  if (handling > 0) {
    starting_pool['boost'] = handling;
  } else if (handling < 0) {
    starting_pool['setback'] = handling * -1;
  }

  // create the dice pool
  let pool = new DicePoolFFG(starting_pool);

  // determine if the vehicle is land or space
  let skill;
  if (vehicle?.system?.spaceShip) {
    if (skillTheme === "starwars") {
      skill = "Piloting: Space";
    } else {
      skill = "Piloting";
    }
  } else {
    if (skillTheme === "starwars") {
      skill = "Piloting: Planetary";
    } else {
      skill = "Driving";
    }
  }

  // update the pool with actor information
  return get_dice_pool(pilot_id, skill, pool);
}

/**
 * Create the dice pool and dialog window for the built-in piloting check
 * @param vehicle - the vehicle actor object
 * @param pilot_id - the actor ID of the pilot
 * @returns {Promise<void>}
 */
export async function handlePilotCheck(vehicle, pilot_id) {
  const crewSheet = game.actors.get(pilot_id)?.sheet;
  const pool = await buildPilotRoll(vehicle.id, pilot_id);

  // create chat card data
  const card_data = {
    "crew": {
      "name": vehicle.name,
      "img": vehicle.img,
      "crew_card": true,
      "role": "Pilot",
    }
  };

  // determine if the vehicle is land or space
  let skill;
  if (vehicle?.system?.spaceShip) {
    skill = "Piloting: Space";
  } else {
    skill = "Piloting: Planetary";
  }

  // open the roll dialog (skill name is already localized)
  await DiceHelpers.displayRollDialog(
    crewSheet,
    pool,
    `${game.i18n.localize("SWFFG.Rolling")} ${skill}`,
    skill,
    card_data
  );
}

export async function selectRoles(vehicle, crew_member_id) {
  const crew_member = game.actors.get(crew_member_id);
  const registeredRoles = game.settings.get('starwarsffg', 'arrayCrewRoles');
  const vehicleRoles = vehicle.getFlag('starwarsffg', 'crew') || [];

  const crewMemberRoles = vehicleRoles.filter(role => role.actor_id === crew_member_id);
  const rolesInUse = crewMemberRoles.map(role => role.role);

  const content = await foundry.applications.handlebars.renderTemplate(
    "systems/starwarsffg/templates/dialogs/ffg-crew-change.html",
    {
      actor: crew_member,
      roles: registeredRoles,
      rolesInUse: rolesInUse,
    }
  );

  DialogV2.wait({
    window: { title: game.i18n.localize("SWFFG.Crew.Title") },
    content: content,
    buttons: [
      {
        action: "confirm",
        label: "Update Roles",
        default: true,
        callback: async (event, button, dialog) => {
          const select = dialog.element.querySelector('[name="select-many-things"]');
          // The template uses Foundry's <multi-select> custom element, which has
          // NO native .selectedOptions — it exposes the chosen values as an array
          // via .value. Reading .selectedOptions threw (Array.from(undefined)),
          // which aborted this callback so the dialog never closed and no crew
          // role was written. Use .value, falling back to a native multiselect.
          let newRoles = [];
          if (select) {
            if (Array.isArray(select.value)) newRoles = select.value;
            else if (select.selectedOptions) newRoles = Array.from(select.selectedOptions).map((o) => o.value);
          }
          await updateRoles(vehicle, crew_member_id, newRoles);
        },
      },
    ],
    rejectClose: false,
  });
}

import PopoutEditor from "../popout-editor.js";
import RollBuilderFFG from "../dice/roll-builder.js";
import ModifierHelpers from "../helpers/modifiers.js";
import ImportHelpers from "../importer/import-helpers.js";
import { DicePoolFFG } from "../dice-pool-ffg.js";

export default class DiceHelpers {
  static async rollSkill(obj, event, type, flavorText, sound) {
    const data = await obj.getData();
    // Resolve the skill/weapon row by climbing to the nearest [data-ability]
    // ancestor rather than counting fixed parentElement hops. The dice preview
    // wraps each die in a <span class="ffg-die-icon">, so a hard-coded hop count
    // lands one level short and skillName comes back undefined — which builds a
    // pool with 0 ability dice (no positive dice at all).
    const abilityEl = event.target?.closest?.("[data-ability]") ?? null;
    let skillName = abilityEl?.dataset?.["ability"];

    let skills;
    const theme = await game.settings.get("starwarsffg", "skilltheme");
    try {
      skills = JSON.parse(JSON.stringify(CONFIG.FFG.alternateskilllists.find((list) => list.id === theme).skills));
    } catch (err) {
      // if we run into an error use the default starwars skill set
      skills = JSON.parse(JSON.stringify(CONFIG.FFG.alternateskilllists.find((list) => list.id === "starwars").skills));
      CONFIG.logger.warn(`Unable to load skill theme ${theme}, defaulting to starwars skill theme`, err);
    }

    let skillData = skills?.[skillName];

    if (!skillData) {
      skillData = data.data[skillName];
    }

    let skill = {
      rank: 0,
      characteristic: "",
      boost: 0,
      setback: 0,
      force: 0,
      advantage: 0,
      dark: 0,
      light: 0,
      failure: 0,
      threat: 0,
      success: 0,
      triumph: 0,
      despair: 0,
      remsetback: 0,
      upgrades: 0,
      label: skillData?.label ? game.i18n.localize(skillData.label) : game.i18n.localize(skillName),
      source: {},
    };
    let characteristic = {
      value: 0,
    };

    if (data?.data?.skills?.[skillName]) {
      skill = data.data.skills[skillName];
    }
    if (data?.data?.characteristics?.[skill?.characteristic]) {
      characteristic = data.data.characteristics[skill.characteristic];
    }

    const actor = await game.actors.get(data.actor._id);

    // Determine if this roll is triggered by an item.
    let item;
    const itemEl = event.target?.closest?.(".item");
    if (itemEl) {
      const itemID = itemEl.dataset["itemId"];
      // Check if token is linked to actor; unlinked tokens carry their own items.
      const owner = obj.actor.token === null ? actor : obj.actor.token.actor;
      item = owner.items.get(itemID);
    }

    if (item && item.type === "weapon") {
      const ammoEnabled = item.getFlag("starwarsffg", "config.enableAmmo");
      if (ammoEnabled && item.system.ammo.value <= 0) {
        return ui.notifications.warn("Not enough ammo!");
      }
    }

    const itemData = item || {};
    const status = this.getWeaponStatus(itemData);
    let defenseDice = this.getDefenseDice(skill, itemData);

    // TODO: Get weapon specific modifiers from itemmodifiers and itemattachments

    let dicePool = new DicePoolFFG({
      ability: Math.max(characteristic.value, skill.rank),
      boost: skill.boost ?? 0,
      setback: (skill.setback ?? 0) + status.setback + defenseDice,
      force: skill.force ?? 0,
      advantage: skill.advantage ?? 0,
      dark: skill.dark ?? 0,
      light: skill.light ?? 0,
      failure: skill.failure ?? 0,
      threat: skill.threat ?? 0,
      success: skill.success ?? 0,
      triumph: skill.triumph ?? 0,
      despair: skill.despair ?? 0,
      upgrades: skill.upgrades ?? 0,
      remsetback: skill.remsetback ?? 0,
      difficulty: 2 + status.difficulty + (skill.difficulty ?? 0), // default average + status-effect difficulty dice
    });

    dicePool.upgrade(Math.min(characteristic.value, skill.rank) + dicePool.upgrades);
    // status-effect difficulty upgrades (mirrors skill.upgrades for ability)
    dicePool.upgradeDifficulty(skill.upgradeDifficulty ?? 0);

    if (type === "ability") {
      dicePool.upgrade();
    } else if (type === "difficulty") {
      dicePool.upgradeDifficulty();
    }

    dicePool = new DicePoolFFG(await this.getModifiers(dicePool, itemData));
    await this.displayRollDialog(data, dicePool, `${game.i18n.localize("SWFFG.Rolling")} ${game.i18n.localize(skill.label)}`, skill.label, itemData, flavorText, sound);
  }

  static getDefenseDice(skill, itemData){
    let defenseDice = 0;
    if (game.settings.get("starwarsffg", "useDefense")) {
      let isRanged = ["Ranged: Light", "Ranged: Heavy", "Gunnery"].includes(skill.value);
      let isMelee = ["Melee", "Brawl", "Lightsaber"].includes(skill.value);
      if (itemData?.type === "weapon" || itemData?.metaData?.tags?.includes("weapon")) {
        if (game.user.targets.size > 0) {
          for (const target of game.user.targets) {
            if (isRanged) {
              defenseDice = Math.max(defenseDice, target.actor.system.stats.defence.ranged);
            } else if (isMelee) {
              defenseDice = Math.max(defenseDice, target.actor.system.stats.defence.melee);
            }
          }
        }
      }
    }
    return defenseDice;
  }

  static async displayRollDialog(data, dicePool, description, skillName, item, flavorText, sound) {
    return new RollBuilderFFG(data, dicePool, description, skillName, item, flavorText, sound).render(true);
  }

  static async addSkillDicePool(data, elem, item = null) {
    const skillName = elem.dataset["ability"];
    if (data.data.skills[skillName]) {
      const skill = data.data.skills[skillName];
      const characteristic = data.data.characteristics[skill.characteristic];

      // A damaged weapon costs a setback (Minor) or a difficulty (Moderate), same
      // as rollItem. Resolved BEFORE the pool so it lands in the constructor and
      // is therefore subject to the difficulty upgrades below — the order rollItem
      // uses. Quiet: an unusable (Major) weapon must not toast on every render; it
      // yields undefined, and the preview simply omits the penalty (rollItem still
      // refuses the roll itself).
      const isWeapon = !!item && (item.type === "weapon" || item.type === "shipweapon");
      const status = (isWeapon ? this.getWeaponStatus(item, false) : null) ?? { setback: 0, difficulty: 0 };

      // Weapon damage is computed, not an active effect, so _prepareSources never
      // records it — synthesise the hint lines here or the dice appear unexplained.
      const damageSource = (key) => {
        if (!status[key]) return [];
        return [{
          modtype: key === "setback" ? "Skill Setback" : "Skill Difficulty",
          key: "damaged",
          name: item.name,
          value: String(status[key]),
          type: game.i18n.localize(CONFIG.FFG.itemstatus[item.system.status].label),
        }];
      };

      let dicePool = new DicePoolFFG({
        ability: Math.max(characteristic?.value ? characteristic.value : 0, skill?.rank ? skill.rank : 0),
        boost: skill.boost,
        setback: (skill.setback ?? 0) + status.setback,
        force: skill.force,
        advantage: skill.advantage,
        dark: skill.dark,
        light: skill.light,
        failure: skill.failure,
        threat: skill.threat,
        success: skill.success,
        triumph: skill?.triumph ? skill.triumph : 0,
        despair: skill?.despair ? skill.despair : 0,
        upgrades: skill?.upgrades ? skill.upgrades : 0,
        remsetback: skill?.remsetback ? skill.remsetback : 0,
        // Status-effect difficulty dice (system.skills.<skill>.difficulty) plus any
        // weapon-damage difficulty. NB no BASE difficulty is added here, unlike
        // rollItem's `2 + …`: the preview shows what the actor brings to the pool,
        // and the average-difficulty default belongs to the roll dialog.
        difficulty: (skill?.difficulty ?? 0) + status.difficulty,
        source: {
          skill: skill?.ranksource?.length ? skill.ranksource : [],
          boost: skill?.boostsource?.length ? skill.boostsource : [],
          remsetback: skill?.remsetbacksource?.length ? skill.remsetbacksource : [],
          setback: [...(skill?.setbacksource?.length ? skill.setbacksource : []), ...damageSource("setback")],
          difficulty: [...(skill?.difficultysource?.length ? skill.difficultysource : []), ...damageSource("difficulty")],
          upgradeDifficulty: skill?.upgradeDifficultysource?.length ? skill.upgradeDifficultysource : [],
          advantage: skill?.advantagesource?.length ? skill.advantagesource : [],
          dark: skill?.darksource?.length ? skill.darksource : [],
          light: skill?.lightsource?.length ? skill.lightsource : [],
          failure: skill?.failuresource?.length ? skill.failuresource : [],
          threat: skill?.threatsource?.length ? skill.threatsource : [],
          success: skill?.successsource?.length ? skill.successsource : [],
          triumph: skill?.triumphsource?.length ? skill.triumphsource : [],
          despair: skill?.despairsource?.length ? skill.despairsource : [],
          upgrades: skill?.upgradessource?.length ? skill.upgradessource : [],
        },
      });
      dicePool.upgrade(Math.min(characteristic.value, skill.rank) + dicePool.upgrades);
      // Status-effect difficulty upgrades — mirrors .upgrades for ability above.
      // Must pass an explicit 0: upgradeDifficulty() defaults to ONE upgrade.
      dicePool.upgradeDifficulty(skill?.upgradeDifficulty ?? 0);

      // When a weapon item is supplied, fold in its roll modifiers (weapon
      // qualities, attachments, and item modifiers) so the preview matches what
      // rollItem actually rolls, instead of showing only the bare skill pool.
      // trackSources: this is a hover-hint surface, so each contributing quality /
      // attachment also gets a tooltip line. Only this path asks for them.
      if (isWeapon) {
        dicePool = await this.getModifiers(dicePool, item, true);
      }

      const rollButton = elem.querySelector(".roll-button");
      dicePool.renderPreview(rollButton);
    }
  }

  static async rollItem(itemId, actorId, flavorText, sound) {
    const actor = game.actors.get(actorId);
    const actorSheet = await actor.sheet.getData();

    const item = actor.items.get(itemId);
    const itemData = item.system;
    await item.setFlag("starwarsffg", "uuid", item.uuid);

    const status = this.getWeaponStatus(item);

    const skill = actor.system.skills[itemData.skill.value];
    const characteristic = actor.system.characteristics[skill.characteristic];
    let defenseDice = this.getDefenseDice(skill, itemData);
    let dicePool = new DicePoolFFG({
      ability: Math.max(characteristic.value, skill.rank),
      boost: skill.boost,
      setback: (skill.setback ?? 0) + status.setback + defenseDice,
      force: skill.force,
      advantage: skill.advantage,
      dark: skill.dark,
      light: skill.light,
      failure: skill.failure,
      threat: skill.threat,
      success: skill.success,
      triumph: skill?.triumph ? skill.triumph : 0,
      despair: skill?.despair ? skill.despair : 0,
      upgrades: skill?.upgrades ? skill.upgrades : 0,
      remsetback: skill?.remsetback ? skill.remsetback : 0,
      difficulty: 2 + status.difficulty + (skill.difficulty ?? 0), // default average + status-effect difficulty dice
    });

    dicePool.upgrade(Math.min(characteristic.value, skill.rank) + dicePool.upgrades);
    dicePool.upgradeDifficulty(skill.upgradeDifficulty ?? 0);

    dicePool = new DicePoolFFG(await this.getModifiers(dicePool, item));

    this.displayRollDialog(actorSheet, dicePool, `${game.i18n.localize("SWFFG.Rolling")} ${skill.label}`, skill.label, item, flavorText, sound);
  }

  // Takes a skill object, characteristic object, difficulty number and ActorSheetFFG.getData() object and creates the appropriate roll dialog.
  static async rollSkillDirect(skill, characteristic, difficulty, sheet, flavorText, sound) {
    const dicePool = new DicePoolFFG({
      ability: Math.max(characteristic.value, skill.rank),
      boost: skill.boost,
      setback: skill.setback,
      force: skill.force,
      difficulty: difficulty + (skill.difficulty ?? 0),
      advantage: skill.advantage,
      dark: skill.dark,
      light: skill.light,
      failure: skill.failure,
      threat: skill.threat,
      success: skill.success,
      triumph: skill?.triumph ? skill.triumph : 0,
      despair: skill?.despair ? skill.despair : 0,
      remsetback: skill?.remsetback ? skill.remsetback : 0,
      upgrades: skill?.upgrades ? skill.upgrades : 0,
    });

    dicePool.upgrade(Math.min(characteristic.value, skill.rank) + dicePool.upgrades);
    dicePool.upgradeDifficulty(skill.upgradeDifficulty ?? 0);

    this.displayRollDialog(sheet, dicePool, `${game.i18n.localize("SWFFG.Rolling")} ${skill.label}`, skill.label, {}, flavorText, sound);
  }

  /**
   * Damage penalty for a wielded weapon: Minor adds a setback, Moderate adds a
   * difficulty, Major is unusable (returns undefined).
   * @param notify pass false from display-only paths (e.g. pool previews, which
   *   re-run on every render) so an unusable weapon doesn't pop a toast per render.
   */
  static getWeaponStatus(item, notify = true) {
    let setback = 0;
    let difficulty = 0;

    if ((item.type === "weapon" || item.type === "shipweapon" ) && item?.system?.status && item.system.status !== "None") {
      const status = CONFIG.FFG.itemstatus[item.system.status].attributes.find((i) => i.mod === "Setback");

      if (status.value < 99) {
        if (status.value === 1) {
          setback = status.value;
        } else {
          difficulty = 1;
        }
      } else {
        if (notify) ui.notifications.error(`${item.name} ${game.i18n.localize("SWFFG.ItemTooDamagedToUse")} (${game.i18n.localize(CONFIG.FFG.itemstatus[item.system.status].label)}).`);
        return;
      }
    }

    return { setback, difficulty };
  }

  /**
   * Fold a weapon's own mods, its attachments, and their active modifiers into a pool.
   * @param trackSources see ModifierHelpers.getDicePoolModifiers — off by default so the
   *   roll paths are unaffected; the Codex weapon-card preview opts in to explain its dice.
   */
  static async getModifiers(dicePool, item, trackSources = false) {
    if (item.type === "weapon" || item.type === "shipweapon") {
      dicePool = await ModifierHelpers.getDicePoolModifiers(dicePool, item, [], trackSources);

      if (item?.system?.itemattachment) {
        await ImportHelpers.asyncForEach(item.system.itemattachment, async (attachment) => {
          //get base mods and additional mods totals
          dicePool = await ModifierHelpers.getDicePoolModifiers(dicePool, attachment, [], trackSources);
          const activeModifiers = attachment.system.itemmodifier.filter((i) => i.system?.active);
          await ImportHelpers.asyncForEach(activeModifiers, async (modifier) => {
            dicePool = await ModifierHelpers.getDicePoolModifiers(dicePool, modifier, [], trackSources);
          });
        });
      }
      if (item?.system?.itemmodifier) {
        await ImportHelpers.asyncForEach(item.system.itemmodifier, async (modifier) => {
          dicePool = await ModifierHelpers.getDicePoolModifiers(dicePool, modifier, [], trackSources);
        });
      }
    }

    return dicePool;
  }
}

/**
 * Helper function to build a dice pool
 * @param actor_id ID of the actor making the check
 * @param skill_name name of the string of the skill
 * @param incoming_roll existing dice, e.g. difficulty dice
 * @returns {DicePoolFFG}
 */
export function get_dice_pool(actor_id, skill_name, incoming_roll) {
  const incomingPool = incoming_roll instanceof DicePoolFFG ? incoming_roll : new DicePoolFFG(incoming_roll ?? {});
  const actor = resolveDicePoolActor(actor_id, skill_name);
  const { skill } = resolveSkill(actor, skill_name);
  const characteristic = actor?.system?.characteristics?.[skill?.characteristic];

  if (!actor || !skill || !characteristic) {
    CONFIG.logger.debug(`Unable to build dice pool for actor ${actor_id} and skill ${skill_name}`);
    return incomingPool;
  }

  const characteristicValue = Number(characteristic.value) || 0;
  const skillRank = Number(skill.rank) || 0;

  const dicePool = new DicePoolFFG({
    ability: Math.max(characteristicValue, skillRank) + incomingPool.ability - (Math.min(characteristicValue, skillRank) + incomingPool.proficiency),
    proficiency: Math.min(characteristicValue, skillRank) + incomingPool.proficiency,
    boost: (skill.boost ?? 0) + incomingPool.boost,
    setback: (skill.setback ?? 0) + incomingPool.setback,
    force: (skill.force ?? 0) + incomingPool.force,
    advantage: (skill.advantage ?? 0) + incomingPool.advantage,
    dark: (skill.dark ?? 0) + incomingPool.dark,
    light: (skill.light ?? 0) + incomingPool.light,
    failure: (skill.failure ?? 0) + incomingPool.failure,
    threat: (skill.threat ?? 0) + incomingPool.threat,
    success: (skill.success ?? 0) + incomingPool.success,
    triumph: (skill.triumph ?? 0) + incomingPool.triumph,
    despair: (skill.despair ?? 0) + incomingPool.despair,
    upgrades: (skill.upgrades ?? 0) + incomingPool.upgrades,
    remsetback: (skill.remsetback ?? 0) + incomingPool.remsetback,
    difficulty: +incomingPool.difficulty + (skill.difficulty ?? 0),
    challenge: +incomingPool.challenge,
  });
  dicePool.upgradeDifficulty(skill.upgradeDifficulty ?? 0);
  return dicePool;
}

function resolveDicePoolActor(actor_id, skill_name) {
  const actors = [];
  const worldActor = game.actors.get(actor_id);

  for (const token of globalThis.canvas?.tokens?.controlled ?? []) {
    if (token?.actor?.id === actor_id) {
      actors.push(token.actor);
    }
  }

  if (worldActor) {
    actors.push(worldActor);
  }

  for (const token of worldActor?.getActiveTokens?.() ?? []) {
    if (token?.actor) {
      actors.push(token.actor);
    }
  }

  return actors.find((actor) => resolveSkill(actor, skill_name).skill) ?? actors[0] ?? null;
}

function resolveSkill(actor, skill_name) {
  const skills = actor?.system?.skills ?? {};
  const candidates = [
    skill_name,
    findSkillKeyByData(skills, skill_name),
    convert_skill_name(skill_name),
  ].filter((skillKey, index, array) => skillKey && array.indexOf(skillKey) === index);

  for (const skillKey of candidates) {
    if (skills?.[skillKey]) {
      const configuredSkill = getConfiguredSkill(skillKey) ?? {};
      return {
        key: skillKey,
        skill: {
          ...configuredSkill,
          ...skills[skillKey],
          characteristic: skills[skillKey].characteristic ?? configuredSkill.characteristic,
        },
      };
    }
  }

  const configuredSkillKey = candidates.find((skillKey) => getConfiguredSkill(skillKey));
  if (configuredSkillKey) {
    return {
      key: configuredSkillKey,
      skill: {
        rank: 0,
        ...getConfiguredSkill(configuredSkillKey),
      },
    };
  }

  return { key: null, skill: null };
}

function findSkillKeyByData(skills, skill_name) {
  if (!skill_name) {
    return null;
  }

  if (skills?.[skill_name]) {
    return skill_name;
  }

  const normalizedName = String(skill_name).toLowerCase();
  return Object.keys(skills ?? {}).find((skillKey) => {
    const skill = skills[skillKey];

    if (!skill) {
      return false;
    }

    const localizedLabel = skill.label ? game.i18n.localize(skill.label) : null;
    return [skillKey, skill.name, skill.value, skill.label, localizedLabel]
      .filter((candidate) => candidate !== undefined && candidate !== null)
      .some((candidate) => String(candidate).toLowerCase() === normalizedName);
  }) ?? null;
}

function getConfiguredSkill(skillKey) {
  if (!skillKey) {
    return null;
  }

  const theme = game.settings.get("starwarsffg", "skilltheme");
  const skillLists = CONFIG.FFG?.alternateskilllists ?? [];
  const themeSkill = skillLists.find((list) => list.id === theme)?.skills?.[skillKey];
  const starWarsSkill = skillLists.find((list) => list.id === "starwars")?.skills?.[skillKey];
  const configuredSkill = {
    ...(CONFIG.FFG?.skills?.[skillKey] ?? {}),
    ...(starWarsSkill ?? {}),
    ...(themeSkill ?? {}),
  };

  if (Object.keys(configuredSkill).length === 0) {
    return null;
  }

  return configuredSkill;
}

/**
 * Convert the skill name to how the game handles it
 * @param pool_skill_name skill name to be converted
 * @returns {null|string}
 */
function convert_skill_name(pool_skill_name) {
  if (!pool_skill_name) {
    return null;
  }

  CONFIG.logger.debug(`Converting ${pool_skill_name} to skill name`);
  const skills = CONFIG.FFG?.skills ?? {};

  if (skills?.[pool_skill_name]) {
    CONFIG.logger.debug(`Found direct mapping to ${pool_skill_name}`);
    return pool_skill_name;
  }

  for (const skill in skills) {
    if (skills[skill]["label"] && game.i18n.localize(skills[skill]["label"]) === pool_skill_name) {
      CONFIG.logger.debug(`Found mapping to ${skill}`);
      return skill;
    }
  }
  // it would appear that sometimes it's value instead of label
  for (const skill in skills) {
    if (skills[skill]["value"] === pool_skill_name) {
      CONFIG.logger.debug(`Found mapping to ${skill}`);
      return skill;
    }
  }
  CONFIG.logger.debug('WARNING: Found no mapping!');
  return null;
}

import { AE_MODES } from "../config/ffg-active-effect-modes.js";
export default class EffectHelpers {

  // Lookup mode name from int
  static MODES = Object.fromEntries(
    Object.entries(AE_MODES).map(
      ([key, value]) => [value, key])
    );

  // Map effects from EmbeddedCollection
  static transformEffects(originalEffect, _iterator, _effects) {
    // originalEffect is a live ActiveEffect Document. toObject() gives a plain,
    // mutable copy of most source fields (duration, name, ...). On V14, though,
    // the serialized copy comes back WITHOUT `changes` (structuredClone dropped
    // it the same way), so read the changes off the live effect explicitly and
    // deep-clone them so the mode/key rewrites below don't mutate the document.
    // The `?? []` keeps this from ever throwing if changes are absent.
    let effect = originalEffect.toObject();

    // Copy properties we need from the live document
    effect.id = originalEffect.id;
    effect.parentName = originalEffect.parent.name;
    effect.active = originalEffect.active;
    effect.changes = foundry.utils.deepClone(originalEffect.changes ?? []);

    // Convert duration to a display string.
    //
    // The system tracks its own dice-status lifetimes in flags, NOT in the core
    // ActiveEffect.duration: "once" = consumed on the next check, "combat" = cleared
    // when combat ends. Those statuses leave the core duration unset (permanent), so
    // show the flag lifetime first — otherwise e.g. "Advantage Next Check" reads
    // "Permanent". Read it off the live document (toObject can drop it on V14).
    const ffgDuration = originalEffect.flags?.starwarsffg?.duration ?? effect.flags?.starwarsffg?.duration;
    const d = effect.duration ?? {};
    // On V14 the legacy {seconds, rounds, turns, combat} fields survive only as
    // deprecated getters that log a compatibility warning on every READ (removed in
    // V16). Feature-detect so we never touch them on V14 — the real duration there is
    // {value, units} — while keeping the V13 fallback chain intact on older cores.
    const isV14 = game.release.generation >= 14;
    if (ffgDuration === "once") {
      effect.duration = game.i18n.localize("SWFFG.Effect.Duration.NextCheck");
    } else if (ffgDuration === "combat") {
      effect.duration = game.i18n.localize("SWFFG.Effect.Duration.CurrentCombat");
    }
    // V14 rewrote the core duration model from {seconds, rounds, turns, combat, ...}
    // to {value, units, ...}. Handle the V14 {value, units} shape first, then fall back
    // to the legacy V13 fields (guarded by !isV14 so the deprecated getters are never
    // read on V14) so timed core durations read correctly on both.
    else if (Number.isInteger(d.value) && d.units) {
      // V14: value + units (seconds/rounds/turns/minutes/hours/days/...). Use the
      // localized label for the units we ship strings for; otherwise show the raw
      // unit name so exotic units still read sensibly.
      const unitKey = { seconds: "Seconds", rounds: "Rounds", turns: "Turns" }[d.units];
      const unitLabel = unitKey ? game.i18n.localize(`SWFFG.Effect.Duration.${unitKey}`) : d.units;
      effect.duration = `${d.value} ${unitLabel}`;
    } else if (!isV14 && d.combat) {
      effect.duration = game.i18n.localize("SWFFG.Effect.Duration.CurrentCombat");
    } else if (!isV14 && d.seconds) {
      effect.duration = `${d.seconds} ${game.i18n.localize("SWFFG.Effect.Duration.Seconds")}`;
    } else if (!isV14 && d.rounds) {
      effect.duration = `${d.rounds} ${game.i18n.localize("SWFFG.Effect.Duration.Rounds")}`;
    } else if (!isV14 && d.turns) {
      effect.duration = `${d.turns} ${game.i18n.localize("SWFFG.Effect.Duration.Turns")}`;
    } else {
      effect.duration = game.i18n.localize("SWFFG.Effect.Duration.Permanent");
    }

    // Update each change from this effect
    effect.changes.forEach((change, index) => {
      // Convert mode to string
      change.mode = EffectHelpers.MODES[change.mode];

      // LStrip 'system.' for shorter keys
      if (change.key.startsWith("system.")) {
        change.key = change.key.substring(7);
      }
    });

    return effect;
  }
}

import PopoutEditor from "../popout-editor.js";
import ItemHelpers from "./item-helpers.js";

export default class EmbeddedItemHelpers {

  /**
   * Actually grabs both the real item and the flag Hierarchy
   * @param temporaryItem - the item which data will be merged into (the attachment, in our test case)
   * @returns {Promise<*>}
   */
  static async _getRealItem(temporaryItem) {
    // NOTE: If data is no-op update, there was previous logic here to not populate parents. We think that's dead, but leaving a note to be removed before commit in case that turned out to be important.
    // https://github.com/StarWarsFoundryVTT/StarWarsFFG/blob/3721dd62caeb7b18e3b9907dfb5ec0342e4dd3ac/modules/helpers/embeddeditem-helpers.js#L14-L16

    // NOTE: Previously, only add the ffgParent from flags to parents if NOT in the compendium. Don't think we want or need that anymore.
    // https://github.com/StarWarsFoundryVTT/StarWarsFFG/blob/3721dd62caeb7b18e3b9907dfb5ec0342e4dd3ac/modules/helpers/embeddeditem-helpers.js#L17-L20

    let flags = temporaryItem.flags.starwarsffg;
    let flagHierarchy = [flags];
    let uuid;
    if (flags.ffgUuid) {
        flagHierarchy = [flags];
        uuid = flags.ffgUuid;
    }
    while (flags.ffgParent) {
      if (Object.values(flags.ffgParent).length === 0) {
        // TODO: We think this code path is dead, but being paranoid for now. Should clean-up later.
        ui.notifications.warn("We think this code path is dead, let us know that it's not! (parent is empty)");
        CONFIG.logger.error("FFG parent is empty");
      }
      flags = flags.ffgParent.starwarsffg;
      if (Object.keys(flags).includes("ffgUuid")) {
        uuid = flags.ffgUuid;
      }
      flagHierarchy.unshift(flags);
    }
    CONFIG.logger.debug("After flagHierarchy population", flagHierarchy);

    if (!flags.ffgTempId && !flags.ffgUuid) {
      ui.notifications.error("Unable to find parent ffgTempId or ffgUuid, aborting action");
      throw new Error("Unable to find parent ffgTempId or ffgUuid");
    }

    // TODO: we do not currently resolve items within compendiums
    let realItem;
    if (uuid) {
      realItem = await fromUuid(uuid);
    } else {
      realItem = await game.items.get(flags.ffgTempId);
    }
    CONFIG.logger.debug("Real item", realItem);

    return {
      realItem,
      flagHierarchy,
    };
  }

  static async updateRealObject(temporaryItem, data) {
    // TODO: drop parents once the refactor is done
    const {realItem, flagHierarchy: parents} = await EmbeddedItemHelpers._getRealItem(temporaryItem);
    // this code was mostly written by Phind
    // removing a key from a dict in Foundry requires submitting it with a new key of `-=key` and a value of null
    // without explicitly replacing values, we end up duplicating entries instead of removing the one
    // so instead, we go and manually remove any mods which have been deleted

    // find any deleted attributes
    const deleted_keys = EmbeddedItemHelpers.findKeysIncludingStringRecursively(
        data,
        '-=attr',
    );
    // remove matching attributes from the existing object
    deleted_keys.forEach(function (cur_key) {
      cur_key = cur_key.substring(2);
      EmbeddedItemHelpers.removeKeyFromObject(
          temporaryItem,
          cur_key,
      );
      EmbeddedItemHelpers.removeKeyFromObject(
          realItem,
          cur_key,
      );
    });
    // this is the end of the de-duplicating -=key stuff

    if (!realItem) {
      ui.notifications.error("Could not locate the real item, aborting action");
      CONFIG.logger.error("Could not locate the real item, aborting action");
      return;
    }
    // because this could be a temporary item, item-ffg.js may not fire, we need to set the renderedDesc.
    if (temporaryItem.system.description) {
      temporaryItem.system.renderedDesc = await PopoutEditor.renderDiceImages(
          temporaryItem.system.description,
          {},
      );
    }
    // TODO: we don't check for compendiums here, either (and we may need to)
    let dataPointer = realItem;
    CONFIG.logger.debug("Starting dataPointer", dataPointer);
    let reconstruct = [];
    parents.forEach((flags) => {
      if (flags.ffgTempItemType && flags.ffgTempItemIndex !== undefined && flags.ffgTempItemIndex !== null) {
        CONFIG.logger.debug(`Traversing into ${flags.ffgTempItemType} #${flags.ffgTempItemIndex}`);
        dataPointer = dataPointer.system[flags.ffgTempItemType][flags.ffgTempItemIndex];
        reconstruct.push({type: flags.ffgTempItemType, index: flags.ffgTempItemIndex});
      }
    });
    CONFIG.logger.debug("Final dataPointer", dataPointer);
    await foundry.utils.mergeObject(
        temporaryItem,
        ItemHelpers.normalizeDataStructure(data),
        {
          recursive: true,
          insertKeys: true,
          insertValues: true,
        },
    );

    foundry.utils.mergeObject(dataPointer, {...temporaryItem, ...ItemHelpers.normalizeDataStructure(data)});
    foundry.utils.mergeObject(dataPointer.flags, temporaryItem.flags);

    let formData;
    if (reconstruct.length === 1) {
      // this fucks up on activating stuff because activate is called on the attachment but it's trying to set data on the mod, not the attachment
      formData = {
        system: {
          [temporaryItem.flags.starwarsffg.ffgTempItemType]: realItem.system[temporaryItem.flags.starwarsffg.ffgTempItemType]
        },
      };
    } else if (reconstruct.length === 2) {
      // update the attachment list with our updated dataPointer data, so we can add it to the formData
      realItem.system[reconstruct[0].type][reconstruct[0].index].system[temporaryItem.flags.starwarsffg.ffgTempItemType][temporaryItem.flags.starwarsffg.ffgTempItemIndex] = dataPointer;

      formData = {
        system: {
          [reconstruct[0].type]: realItem.system[reconstruct[0].type],
        }
      };
    } else {
      ui.notifictions.warn(`You shouldn't see this. Please notify the devs if you do - reconstruct length was ${reconstruct.length}`);
      CONFIG.logger.warn(`You shouldn't see this. Please notify the devs if you do - reconstruct length was ${reconstruct.length}`);
    }

    CONFIG.logger.debug("Final formData", formData);
    await realItem.update(formData);
  }

  /**
   * Displays Owned Item, Item Modifier as a journal entry
   *
   * @param  {string} itemId - Owned Item Id
   * @param  {string} modifierType - Item Modifier Type (itemattachment/itemmodifier)
   * @param  {string} modifierId - Item Modifier Id
   * @param  {string} actorId = Actor Id
   */
  static async displayOwnedItemItemModifiersAsJournal(itemId, modifierType, modifierId, actorId, compendium) {
    try {
      let actor;

      if (compendium) {
        actor = await compendium.get(actorId);
      } else {
        actor = await game.actors.get(actorId);
      }
      const ownedItem = await actor.items.get(itemId);

      if (!ownedItem) ui.notifications.warn(`The item had been removed or can not be found!`);

      let modifierIndex;
      let item;
      if (ownedItem?.system[modifierType]) {
        modifierIndex = ownedItem.system[modifierType].findIndex((i) => i?._id === modifierId || i?.id === modifierId);
        item = ownedItem.system[modifierType][modifierIndex];
      }

      if (!item) {
        // this is a modifier on an attachment
        ownedItem.system.itemattachment.forEach((a) => {
          modifierIndex = a.system[modifierType].findIndex((m) => m.id === modifierId);
          if (modifierIndex > -1) {
            item = a.data[modifierType][modifierIndex];
          }
        });
      }

      const readonlyItem = {
        name: item.name,
        pages: [{
          name: item.name,
          type: 'text',
          text: {
            content: item.system.description,
            format: CONST.JOURNAL_ENTRY_PAGE_FORMATS.HTML
          },
        }],
        ownership: {
          default: CONST.DOCUMENT_OWNERSHIP_LEVELS.OBSERVER,
        },
      };

      let readonlyItemJournalEntry = await new JournalEntry(readonlyItem, {
        temporary: true,
      });
      readonlyItemJournalEntry.sheet.render(true)
    } catch (err) {
      ui.notifications.warn(`The item or quality has been removed or can not be found!`);
      CONFIG.logger.warn(`Error loading Read-Only Journal Item`, err);
    }
  }

  static async loadItemModifierSheet(itemId, modifierType, modifierId, actorId) {
    let parent;
    let ownedItem;

    if (actorId) {
      parent = await game.actors.get(actorId);
      ownedItem = await parent.items.get(itemId);
    } else {
      ownedItem = await game.items.get(itemId);
    }

    let modifierIndex;
    if (!isNaN(modifierId)) {
      modifierIndex = modifierId;
    } else {
      modifierIndex = ownedItem.system[modifierType].findIndex((i) => i.id === modifierId);
    }

    let item;
    if (ownedItem?.system[modifierType]) {
      item = ownedItem.system[modifierType][modifierIndex];
    }
    let rename_item;

    if (!item) {
      // this is a modifier on an attachment
      ownedItem.system.itemattachment.forEach((a, index) => {
        if (!isNaN(modifierId)) {
          modifierIndex = modifierId;
        } else {
          modifierIndex = a.system[modifierType].findIndex((m) => m.id === parseInt(modifierId, 10));
        }
        if (modifierIndex > -1) {
          item = a.system[modifierType][modifierIndex];
          rename_item = {
            flags: {
              starwarsffg: {
                ffgTempItemType: "itemattachment",
                ffgTempItemIndex: index,
                ffgTempId: itemId,
              }
            }
          };
        }
      });
    }

    const temp = {
      ...item,
      flags: {
        starwarsffg: {
          ffgTempId: itemId,
          ffgTempItemType: modifierType,
          ffgTempItemIndex: modifierIndex,
          ffgIsTemp: true,
          ffgUuid: ownedItem.uuid,
          readonly: true,
          ffgParent: rename_item.flags,
        }
      },
    };

    delete temp._id;
    delete temp.id;
    let tempItem = await new Item.implementation(temp, { temporary: true });
    tempItem.sheet.render(true);
  }

  static async createNewEmbeddedItem(type, data, flags) {
    let temp = {
      img: "icons/svg/mystery-man.svg",
      name: "",
      type,
      flags: {
        starwarsffg: {
          ffgTempItemType: type,
          ffgTempItemIndex: -1,
          ...flags,
        }
      },
      data,
    };

    let tempItem = await new Item(temp, { temporary: true });

    tempItem.data._id = temp.id;
    if (!temp.id) {
      tempItem.data._id = foundry.utils.randomID();
    }

    return tempItem;
  }

  // Only descend into plain objects/arrays when walking for `-=attr` keys. Live
  // Documents, DataModels and EmbeddedCollections carry parent/collection back-
  // references that form cycles; on V14 for...in reaches those (the getData
  // context now holds the live item Document) and the recursion overflows the
  // stack. The keys we care about only ever live in plain data anyway.
  static _isWalkable(value) {
    if (Array.isArray(value)) return true;
    if (value === null || typeof value !== "object") return false;
    const proto = Object.getPrototypeOf(value);
    return proto === Object.prototype || proto === null;
  }

  // totally not ripped from phind telling me how to do this
  static removeKeyFromObject(obj, keyToRemove) {
    for (let key in obj) {
      if (obj.hasOwnProperty(key)) {
        if (key === keyToRemove) {
          delete obj[key];
        } else if (EmbeddedItemHelpers._isWalkable(obj[key])) {
          EmbeddedItemHelpers.removeKeyFromObject(obj[key], keyToRemove);
        }
      }
    }
  }

  // totally not ripped from phind telling me how to do this
  static findKeysIncludingStringRecursively(obj, str) {
    let keys = [];
    for (let key in obj) {
      if (obj.hasOwnProperty(key)) {
        if (key.includes(str)) {
          keys.push(key);
        }
        if (EmbeddedItemHelpers._isWalkable(obj[key])) {
          keys = keys.concat(EmbeddedItemHelpers.findKeysIncludingStringRecursively(obj[key], str));
        }
      }
    }
    return keys;
  }
}

export default class FlagMigrationHelpers {
  // Old scopes used in prior versions that need to be cleaned up
  static oldFlagScopes = [
    "ffg",
    "ffgTempId",
    "ffgUuid",
    "ffgParent",
    "ffgimportid",
    "config", // Actor sheet settings
    "importid", // Doesn't appear to be read anymore but still exists
  ];

  // Clean up flags for all document types
  static migrateFlags() {
    this.rescopeActorFlags();
    this.rescopeItemFlags();
    this.rescopePackFlags();
  }

  // Loop all items
  // and copy old flags into new scope
  static rescopeItemFlags() {
    for (let doc of game.items) {
      for (let flag in doc.system.flags) {
        this.rescopeFlag(doc, flag);
      }
    }
  }

  // Actors
  static rescopeActorFlags() {
    for (let doc of game.actors) {
      for (let flag in doc.system.flags) {
        this.rescopeFlag(doc, flag);
      }
    }
  }

  // Packs
  static rescopePackFlags() {
    for (let pack of game.packs) {
      this.handlePack(pack);
    }
  }

  /**
   * Apply migration rules to all Documents within a single Compendium pack
   * Shamelessly stolen and adapted from dnd5e
   * @param {CompendiumCollection} pack  Pack to be migrated.
   * @returns {Promise}
   *
   */
  static handlePack = async function (pack) {
    const documentName = pack.documentName;
    if (!["Actor", "Item"].includes(documentName)) return;

    // Unlock the pack for editing
    const wasLocked = pack.locked;
    await pack.configure({ locked: false });

    // Get the contents
    const documents = await pack.getDocuments();

    // Iterate over compendium entries
    for (let doc of documents) {
      try {
        switch (documentName) {
          case "Actor":
          case "Item":
            for (let flag in doc.system.flags) {
              this.rescopeFlag(doc, flag);
            }
        }

        await doc.update();
        console.debug(
          `Migrated ${documentName} document ${doc.name} in Compendium ${pack.collection}`
        );
      } catch (err) {
        // Handle migration failures
        err.message = `Failed migration for document ${doc.name} in pack ${pack.collection}: ${err.message}`;
        console.error(err);
      }
    }

    // Apply the original locked status for the pack
    await pack.configure({ locked: wasLocked });
    console.log(
      `Migrated all ${documentName} documents from Compendium ${pack.collection}`
    );
  };

  // Copy individual flag into system ('starwarsffg') scope
  static rescopeFlag(doc, flag) {
    if (this.oldFlagScopes.includes(flag)) {
      try {
        doc.setFlag("starwarsffg", flag, doc.system.flags[flag]);
        console.debug(
          `Copied flag into starwarsffg scope: ${doc.name}.system.flags.${flag}`
        );
      } catch (err) {
        console.log(`Flag migration error at document: ${doc.name}`);
        console.log(err);
      }
    }
  }
}

import { AE_MODES } from "../config/ffg-active-effect-modes.js";
import ModifierHelpers from "./modifiers.js";

export default class ItemHelpers {
  static async itemUpdate(event, formData, { render = false } = {}) {
    formData = foundry.utils.expandObject(formData);

    if (this.object.isEmbedded && this.object.actor?.compendium?.metadata) {
      return;
    }
    CONFIG.logger.debug(`Updating ${this.object.type}`);

    // Handle the free-form attributes list
    const formAttrs = foundry.utils.expandObject(formData)?.data?.attributes || {};
    const attributes = Object.values(formAttrs).reduce((obj, v) => {
      let k = v["key"].trim();
      delete v["key"];
      obj[k] = v;
      return obj;
    }, {});

    // Remove attributes which are no longer used
    if (this.object.system?.attributes) {
      for (let k of Object.keys(this.object.system.attributes)) {
        if (!attributes.hasOwnProperty(k)) attributes[`-=${k}`] = null;
      }
    }

    // apply active effects
    await ModifierHelpers.applyActiveEffectOnUpdate(this.object, formData);

    // recombine attributes to formData
    if (Object.keys(attributes).length > 0) {
      foundry.utils.setProperty(formData, `data.attributes`, attributes);
    }

    // migrate data to v10 structure
    let updated_id = formData._id;
    delete formData._id;

    foundry.utils.setProperty(formData, `flags.starwarsffg.loaded`, false);
    await this.object.update(formData, { render });
    // sync the active effect state (if applicable). needs to be after the update so we have the updated state
    await ItemHelpers.syncAEStatus(this.object, this.object.getEmbeddedCollection("ActiveEffect"));
    // Gate the explicit sheet re-render on the render flag. With the auto-
    // render hook suppressed (render: false from the change pipeline), an
    // unconditional this.render(true) here would re-introduce the mid-
    // interaction DOM swap that the render-race fix removes. Structural and
    // editor-save flows pass render: true to get the redraw they need.
    if (render) await this.render(true);

    // `render: false` on the update above suppresses every sheet render
    // triggered by Foundry's updateItem hook -- including the parent actor
    // sheet's. That's correct for THIS item's sheet (avoids mid-edit DOM
    // swaps) but the owning actor's sheet shows derived data (weapon rolls,
    // talent panels, etc.) that goes stale until the actor sheet is closed
    // and reopened. Explicitly re-render the actor sheet here when the
    // edited item is embedded; the sheet's own coalesce/race guards already
    // handle the case where the user hasn't opened it.
    if (this.object.isEmbedded && this.object.actor?.sheet?.rendered) {
      this.object.actor.sheet.render(false);
    }

    if (this.object.type === "talent") {
      if (this.object.flags?.clickfromparent?.length) {
        let listofparents = JSON.parse(JSON.stringify(this.object.flags.clickfromparent));
        while (listofparents.length > 0) {
          const parent = listofparents.shift();
          const spec = await fromUuid(parent.id);
          if (spec) {
            let updateData = {};
            foundry.utils.setProperty(updateData, `data.talents.${parent.talent}.name`, formData.name);
            foundry.utils.setProperty(updateData, `data.talents.${parent.talent}.description`, this.object.system.description);
            foundry.utils.setProperty(updateData, `data.talents.${parent.talent}.activation`, formData.data.activation.value);
            foundry.utils.setProperty(updateData, `data.talents.${parent.talent}.isRanked`, formData.data.ranks.ranked);
            foundry.utils.setProperty(updateData, `data.talents.${parent.talent}.isForceTalent`, formData.data.isForceTalent);
            foundry.utils.setProperty(updateData, `data.talents.${parent.talent}.isConflictTalent`, formData.data.isConflictTalent);

            // Remove attributes which are no longer used
            if (spec?.system?.talents?.[parent.talent]?.attributes) {
              for (let k of Object.keys(spec.system.talents[parent.talent].attributes)) {
                if (!formData.data.attributes.hasOwnProperty(k)) formData.data.attributes[`-=${k}`] = null;
              }
            }

            foundry.utils.setProperty(updateData, `data.talents.${parent.talent}.attributes`, formData.data.attributes);

            if (parent.id.includes(".OwnedItem.")) {
              const ids = parent.id.split(".OwnedItem.");
              const actor = await fromUuid(ids[0]);
              const item = await actor.items.get(ids[1]);
              foundry.utils.setProperty(updateData, `flags.starwarsffg.loaded`, false);
              await item.update(updateData);
              await item.sheet.render(true);
            } else {
              foundry.utils.setProperty(updateData, `flags.starwarsffg.loaded`, false);
              await spec.update(updateData);
              await spec.sheet.render(true);
            }
          }
        }
      }
    } else if (this.object.type === "career") {
      // apply career skills from Careers
      const existingEffects = this.object.getEmbeddedCollection("ActiveEffect");
      const itemEffect = existingEffects.find(i => i.name === `(inherent)`);
      const changes = [];
      for (let i = 0; i < 8; i++) {
        let path;
        const skill = formData.data.careerSkills[`careerSkill${i}`];
        if (skill !== "(none)") {
          path = `system.skills.${skill}.careerskill`;
        } else {
          path = "(none)";
        }
        changes.push({
          key: path,
          mode: AE_MODES.ADD,
          value: true,
        });
      }
      if (itemEffect) {
        await itemEffect.update({changes: changes});
      }
    } else if (this.object.type === "specialization") {
      // apply career skills from Careers
      const existingEffects = this.object.getEmbeddedCollection("ActiveEffect");
      const itemEffect = existingEffects.find(i => i.name === `(inherent)`);
      const changes = [];
      for (let i = 0; i < 5; i++) {
        let path;
        const skill = formData.data.careerSkills[`careerSkill${i}`];
        if (skill !== "(none)") {
          path = `system.skills.${skill}.careerskill`;
        } else {
          path = "(none)";
        }
        changes.push({
          key: path,
          mode: AE_MODES.ADD,
          value: true,
        });
      }
      if (itemEffect) {
        await itemEffect.update({changes: changes});
      }
    }
  }

  /**
   * Takes formData and move anything under .data into .system in preparation for an item.update() call
   * @param formData
   * @returns {*}
   */
  static normalizeDataStructure(formData) {
    const updatedData = foundry.utils.deepClone(formData);
    if (Object.keys(formData).includes('data')) {
      if (!Object.keys(formData).includes('system')) {
        // sometimes we get formData with a mix of data and system...
        updatedData.system = {};
      }
      updatedData.system = foundry.utils.mergeObject(
          updatedData.system,
          updatedData.data
      );
      delete updatedData.data;
    }
    // Initialize updatedData.system if the key is present with no value
    if (Object.keys(updatedData).includes('system') && typeof updatedData.system === "undefined")
      {
        updatedData.system = {};
      }
    return updatedData;
  }

  /**
   * Takes formData and converts certain fields into an array, rather than the odd name they have by default
   * For example, submitting a form with a modifier on it results in a field value of "itemmodifier[0]", rather than
   *  a field named "itemmodifier" with a single entry in an array
   * @param formData
   */
  static explodeFormData(formData) {
    // convert the formdata into a dict
    formData = foundry.utils.expandObject(formData);
    // collapse the resulting entries with an index into an array
    const relevantEntries = Object.keys(formData?.system).filter(i => i.includes("[") && i.includes("]"));
    for (const cur_entry in relevantEntries) {
      const updatedKeyName =  relevantEntries[cur_entry].replace(/\[.*\]/, "");
      if (!Object.keys(formData.system).includes(updatedKeyName)) {
        formData.system[updatedKeyName] = [];
      }
      formData.system[updatedKeyName].push(formData.system[relevantEntries[cur_entry]]);
      delete formData.system[relevantEntries[cur_entry]];
    }
    return formData;
  }

  /**
   * Determines if a given Active Effect should have a status updated or not - based on the item it's a part of
   * For example, if a piece of armor has an attachment with a modification with a mod that's not installed,
   *  that mod should not apply any effect to the actor - even if the armor is equipped / unequipped
   * Similarly, unpurchased talents on specializations should not do anything until they are purchased
   * @param item - the item the active effect is a part of
   * @param activeEffect - the specific active effect to check
   * @returns {Promise<boolean>} - bool representing if the changes should be applied or not
   *
   */
  static async shouldUpdateAEStatus(item, activeEffect) {
    CONFIG.logger.debug(`Checking if ${activeEffect.name} from ${item.name} should be applied`);
    if (["armour", "weapon", "shipweapon"].includes(item.type)) {
      for (const attachment of item.system.itemattachment) {
        for (const modification of attachment.system.itemmodifier) {
          try {
            const foundMod = modification.system.attributes[activeEffect.name];
            CONFIG.logger.debug(`Located mod ${activeEffect.name}, checking if it's active or not`);
            if (foundMod && !modification.system.active) {
              CONFIG.logger.debug(`Mod ${activeEffect.name} is not active, not syncing AE status`);
              return false;
            } else {
              CONFIG.logger.debug(`Mod ${activeEffect.name} is active, syncing AE status`);
              return true;
            }
          } catch {
            CONFIG.logger.debug(`No mod located, continuing search...`);
          }
        }
      }
    }
    CONFIG.logger.debug(`No reason to avoid updating status found, syncing AE status`);
    return true;
  }

  /**
   * Sync the status of an active effect to the parent object when an item is updated
   * For example, enable an active effect on a talent as a part of a specialization when that talent is purchased
   * @param item
   * @param activeEffects
   * @returns {Promise<void>}
   */
  static async syncAEStatus(item, activeEffects) {
    CONFIG.logger.debug(`Syncing ${activeEffects.length} Active Effects status...`);
    if (["specialization"].includes(item.type)) {
      CONFIG.logger.debug("specialization, looking through AEs to sync");
      await ItemHelpers.syncTreeActiveEffects(item, item.system.talents, "talent");
    } else if (["forcepower", "signatureability"].includes(item.type)) {
      CONFIG.logger.debug("force power or signature ability, looking through AEs to sync");
      await ItemHelpers.syncTreeActiveEffects(item, item.system.upgrades, "upgrade");
    } else if (["armour", "weapon", "shipweapon"].includes(item.type)) {
      CONFIG.logger.debug("armor and weapon, checking modifiers to sync value to rank");
      // sync AEs to the rank value - that is, if we have a mod which adds 1 to max wounds with 4 ranks, the AE should have a value of 4, not 1
      const existingEffects = item.getEmbeddedCollection("ActiveEffect");
      for (const modifier of item.system.itemmodifier) {
        for (const attr of Object.keys(modifier.system.attributes)) {
          const matchingEffect = existingEffects.find(effect => effect.name === attr);
          if (matchingEffect) {
            // the mod should be applied once per rank
            const newValue = modifier.system.rank_current * modifier.system.attributes[attr].value;
            CONFIG.logger.debug(`Located ${attr}, updating with new value of ${newValue}`);
            await matchingEffect.update({
              "changes": [{
                key: matchingEffect.changes[0].key,
                mode: matchingEffect.changes[0].mode,
                value: newValue,
              }],
            });
          }
        }
      }
    } else {
      CONFIG.logger.debug(`'other' item type ${item.type}, no need to sync AE status'`);
    }
  }

  /**
   * Rebuild Active Effects for learned tree nodes from their current modifier data.
   * Some imported or migrated tree-node effects can have stale change payloads; updating
   * disabled alone does not reliably make Foundry re-apply those item effects.
   *
   * @param item
   * @param tree
   * @param nodeLabel
   * @returns {Promise<void>}
   */
  static async syncTreeActiveEffects(item, tree, nodeLabel) {
    const existingEffects = Array.from(item.getEmbeddedCollection("ActiveEffect"));
    const desiredEffects = [];
    const toCreate = [];
    const claimedEffects = new Set();

    for (const nodeKey of Object.keys(tree || {})) {
      const node = tree[nodeKey];
      for (const attrName of Object.keys(node.attributes || {})) {
        if (attrName.startsWith("-=")) {
          continue;
        }

        const changes = ItemHelpers.buildActiveEffectChanges(node.attributes[attrName], attrName);
        if (!changes.length) {
          continue;
        }

        desiredEffects.push({
          name: attrName,
          img: node.img || item.img,
          changes,
          disabled: !node.islearned,
          flags: {
            starwarsffg: {
              treeActiveEffect: true,
              treeAttribute: attrName,
              treeNode: nodeKey,
              treeNodeType: nodeLabel,
            },
          },
          nodeName: node.name,
        });
      }
    }

    for (const effectData of desiredEffects) {
      const flaggedEffect = existingEffects.find(effect =>
        !claimedEffects.has(effect.id) &&
        effect.getFlag("starwarsffg", "treeActiveEffect") &&
        effect.getFlag("starwarsffg", "treeAttribute") === effectData.flags.starwarsffg.treeAttribute &&
        effect.getFlag("starwarsffg", "treeNode") === effectData.flags.starwarsffg.treeNode &&
        effect.getFlag("starwarsffg", "treeNodeType") === effectData.flags.starwarsffg.treeNodeType
      );
      const unclaimedEffect = flaggedEffect || existingEffects.find(effect => !claimedEffects.has(effect.id) && effect.name === effectData.name);

      CONFIG.logger.debug(`located attribute granting AE (${effectData.name}) from ${nodeLabel} (${effectData.nodeName}), syncing changes and disabled=${effectData.disabled}`);
      if (unclaimedEffect) {
        claimedEffects.add(unclaimedEffect.id);
        await unclaimedEffect.update({
          changes: effectData.changes,
          disabled: effectData.disabled,
          flags: effectData.flags,
        });
      } else {
        toCreate.push({
          name: effectData.name,
          img: effectData.img,
          changes: effectData.changes,
          disabled: effectData.disabled,
          flags: effectData.flags,
        });
      }
    }

    if (toCreate.length) {
      await item.createEmbeddedDocuments("ActiveEffect", toCreate);
    }
  }

  /**
   * Convert a modifier attribute into Active Effect changes.
   *
   * @param attribute
   * @param attrName
   * @returns {Array}
   */
  static buildActiveEffectChanges(attribute, attrName) {
    const changes = [];
    let modtype = attribute?.modtype;
    let mod = attribute?.mod;
    let value = attribute?.value;

    if ((!modtype || !mod) && attrName?.includes(".")) {
      const parts = attrName.split(".");
      if (parts.length >= 3) {
        modtype = modtype || parts[0];
        mod = mod || parts.slice(1, -1).join(".");
        value = value ?? parts[parts.length - 1];
      }
    }

    if (!modtype || !mod) {
      return changes;
    }

    const explodedMods = ModifierHelpers.explodeMod(modtype, mod);
    for (const curMod of explodedMods) {
      const key = ModifierHelpers.getModKeyPath(curMod.modType, curMod.mod);
      if (key) {
        changes.push({
          key,
          mode: AE_MODES.ADD,
          value,
        });
      }
    }

    return changes;
  }

  /**
   * Update the inherent Encumbrance Active Effect when armor is equipped/unequipped
   * (because the encumbrance is reduced by 3 when worn)
   * @param item - item being equipped
   * @param activeEffect - inherent AE for that item
   * @param equipped - if the item is now equipped or not
   * @returns {Promise<void>} - N/A, updates the change on the AE
   */
  static async updateEncumbranceOnEquip(item, activeEffect, equipped) {
    CONFIG.logger.debug("Updating encumbrance Active Effect on equip state change");
    const realEncumbrance = item?.system?.encumbrance?.value;
    if (item.type === "armour" && realEncumbrance) {
      const encumbranceModPath = ModifierHelpers.getModKeyPath("Stat", "Encumbrance");
      let updatedEncumbrance;
      if (equipped) {
        updatedEncumbrance = Math.max(realEncumbrance - 3, 0);
      } else {
        updatedEncumbrance = realEncumbrance;
      }
      CONFIG.logger.debug(`Original encumbrance: ${realEncumbrance}, new encumbrance: ${updatedEncumbrance}`);
      for (const change of activeEffect.changes) {
        if (change.key === encumbranceModPath) {
          change.value = updatedEncumbrance;
          break;
        }
      }
      await activeEffect.update({changes: activeEffect.changes});
    }
  }

  /**
   * Ensures unique attribute keys for a dropped item by checking and modifying its attributes, modifiers, and attachments
   * to avoid key collisions within the parent item. Also updates any matching active effects to align with the new attribute keys.
   *
   * @param {Object} droppedItem - The item being added or moved, whose attributes need to be checked and adjusted if necessary
   * @param {Object} parentItem - The target item that will contain the dropped item, used to determine existing keys for comparison
   * @return {Object} - Returns the modified dropped item with updated attribute keys and effects
   */
  static async uniqueAttrs(droppedItem, parentItem) {
    CONFIG.logger.debug(`Unique-ing attributes for dropped item ${droppedItem.name} on parent item ${parentItem.name}`);
    // collect the existing attrs so we can determine if there's a collision
    let existingAttrs = Object.keys(parentItem.system.attributes) || [];
    if (Object.keys(parentItem.system).includes("itemmodifier")) {
      for (const modifier of parentItem.system.itemmodifier) {
        existingAttrs = [...existingAttrs, ...Object.keys(modifier.system.attributes || {})];
      }
    }
    if (Object.keys(parentItem.system).includes("itemattachment")) {
      for (const attachment of parentItem.system.itemattachment) {
        existingAttrs = [...existingAttrs, ...Object.keys(attachment.system.attributes || {})];
        for (const modification of attachment.system.itemmodifier) {
          existingAttrs = [...existingAttrs, ...Object.keys(modification.system.attributes || {})];
        }
      }
    }
    if (Object.keys(parentItem.system).includes("talents")) {
      for (const talent of Object.keys(parentItem.system.talents)) {
        if (!Object.keys(parentItem.system.talents[talent]).includes("attributes")) {
          // some talent slots do not have the "attributes" key, so we can skip them
          continue;
        }
        existingAttrs = [...existingAttrs, ...Object.keys(parentItem.system.talents[talent].attributes)];
      }
    }
    CONFIG.logger.debug(`Existing attributes: ${JSON.stringify(existingAttrs)}`);

    // now that we know the existing attrs, start looking for ones in the dropped item
    if (Object.keys(droppedItem.system).includes("attributes")) {
      for (const attr of Object.keys(droppedItem.system.attributes)) {
        const matchingEffect = droppedItem.effects.find(effect => effect.name === attr);
        const newKey = `attr${new Date().getTime()}`;
        // copy the data to the new field
        droppedItem.system.attributes[newKey] = droppedItem.system.attributes[attr];
        // delete the old field
        delete droppedItem.system.attributes[attr];
        // update the active effect
        if (matchingEffect) {
          CONFIG.logger.debug(`located matching effect from attributes ${matchingEffect.name}, updating to ${newKey}`);
          matchingEffect.name = newKey;
        }
        // ensure further keys have a new entry
          await new Promise(r => setTimeout(r, 1));
      }
    }

    if (Object.keys(droppedItem.system).includes("itemmodifier")) {
      for (const droppedModifier of droppedItem.system.itemmodifier) {
        if (droppedModifier.system.attributes) {
          for (const attr of Object.keys(droppedModifier.system.attributes)) {
            CONFIG.logger.debug(`checking ${attr}`);
            const matchingEffect = droppedItem.effects.find(effect => effect.name === attr);
            const newKey = `attr${new Date().getTime()}`;
            CONFIG.logger.debug(`located matching effect from itemmodifier ${droppedModifier.name} for ${attr}, updating to ${newKey}`);
            // copy the data to the new field
            droppedModifier.system.attributes[newKey] = droppedModifier.system.attributes[attr];
            // delete the old field
            delete droppedModifier.system.attributes[attr];
            // update the active effect
            if (matchingEffect) {
              matchingEffect.name = newKey;
            }
            // ensure further keys have a new entry
            await new Promise(r => setTimeout(r, 1));
          }
        }
      }
    }

    CONFIG.logger.debug(`Done Unique-ing attributes!`);
    return droppedItem;
  }
}

/**
 * Registers enrichers for the Journal pages - automatically runs the regex and replaces it with the return value of the function
 */
export function register_dice_enricher() {
  const dicetheme = game.settings.get("starwarsffg", "dicetheme");
  // ability die
  CONFIG.TextEditor.enrichers.push({
    pattern: /:(ability):|\[(AB)(ILITY)?\]/gim,
    enricher: async (match, options) => {
        let element = document.createElement("span");
        element.classList.add("dietype");
        element.classList.add("starwars");
        element.classList.add("ability");
        element.append("d");
        return element;
      }
  });
    // advantage die
  CONFIG.TextEditor.enrichers.push({
    pattern: /:(advantage):|\[(AD)(VANTAGE)?\]/gim,
    enricher: async (match, options) => {
        let element = document.createElement("span");
        element.classList.add("dietype");
        element.classList.add(dicetheme);
        element.classList.add("advantage");
        element.append("a");
        return element;
      }
  });
  // difficulty die
  CONFIG.TextEditor.enrichers.push({
    pattern: /:(average):/gim,
    enricher: async (match, options) => {
        let element = document.createElement("span");
        element.classList.add("dietype");
        element.classList.add(dicetheme);
        element.classList.add("difficulty");
        element.append("di");
        return element;
      }
  });
  // boost die
  CONFIG.TextEditor.enrichers.push({
    pattern: /:(boost):|\[(BO)(OST)?\]/gim,
    enricher: async (match, options) => {
        let element = document.createElement("span");
        element.classList.add("dietype");
        element.classList.add("starwars");
        element.classList.add("boost");
        element.append("b");
        return element;
      }
  });
  // challenge die
  CONFIG.TextEditor.enrichers.push({
    pattern: /:(challenge):|\[(CH)(ALLENGE)?\]/gim,
    enricher: async (match, options) => {
        let element = document.createElement("span");
        element.classList.add("dietype");
        element.classList.add("starwars");
        element.classList.add("challenge");
        element.append("c");
        return element;
      }
  });
  // dark die
  CONFIG.TextEditor.enrichers.push({
    pattern: /:(darkside):|\[(DA)(RK)?\]/gim,
    enricher: async (match, options) => {
        let element = document.createElement("span");
        element.classList.add("dietype");
