  });
  game.settings.register("starwarsffg", "enableAdversaryCalc", {
    name: game.i18n.localize("SWFFG.Settings.enableAdversaryCalc.Name"),
    hint: game.i18n.localize("SWFFG.Settings.enableAdversaryCalc.Hint"),
    scope: "world",
    config: false,
    default: true,
    type: Boolean,
    onChange: (rule) => window.location.reload()
  });
}

export function drawMinionCount(token) {
  if (!game.settings.get("starwarsffg", "showMinionCount")) {
    return;
  }
  const borderWidth = 0.35;
  const friendlyColor = "0x00A2E84D";
  const enemyColor = "0x8800154D";
  const overflowColor = "0xDAA520";
  // calculate total and alive numbers of minions
  const curCount = Math.max(token.actor.system.quantity.value, 0);
  const maxCount = token.actor.system.quantity.max;
  const maxRender = 6;

  // attempt to draw it on the token directly
  // check for existing copies of the container
  if (!token.children.find(i => i.name === "minionCount")) {
    const countContainer = new PIXI.Container();
    countContainer.name = "minionCount";
    token.minionCount = token.addChild(countContainer);
  } else {
    token.minionCount.removeChildren().forEach(i => i.destroy());
  }

  const tokenWidth = token.w;
  const markerWidth = 7;
  const markerHeight = 15;
  const insideGap = 5;
  const availableSpace = tokenWidth - ((markerWidth * maxCount) + (insideGap * (maxCount - 1)));
  const outsideGap = availableSpace / 2;

  if (maxCount > maxRender) {
    const text = new PIXI.Text(
      "∞",
      {
        fontFamily: "Arial",
        fontSize: 48,
        fill: overflowColor,
        align: "center",
        stroke: "0x000000",
        strokeThickness: 1,
        fontWeight: "bold" ,
      }
    );
    text.anchor.set(0.5);
    text.x = tokenWidth / 2;
    text.y = token.h - 12;
    token.minionCount.addChild(text);
  } else {
    for (let i = 0; i < curCount; i++) {
      const element = new PIXI.Graphics();
      // add the border
      element.lineStyle(borderWidth, "0x000000", 1);
      // draw the rectangle
      element.beginFill(friendlyColor);
      element.drawRoundedRect(0, 0, markerWidth, markerHeight, 2);
      element.endFill();
      element.endFill();
      // position it
      element.x = (i * (markerWidth + insideGap)) + outsideGap;
      element.y = token.h - markerHeight - 2;
      // add it to the container
      token.minionCount.addChild(element);
    }

    for (let i = 0; i < maxCount - curCount; i++) {
      const element = new PIXI.Graphics();
      // add the border
      element.lineStyle(borderWidth, "0x000000", 1);
      // draw the rectangle
      element.beginFill(enemyColor);
      element.drawRoundedRect(0, 0, markerWidth, markerHeight, 2);
      element.endFill();
      // position it
      element.x = ((i + curCount) * (markerWidth + insideGap)) + outsideGap;
      element.y = token.h - markerHeight - 2;
      // add it to the container
      token.minionCount.addChild(element);
    }
  }
}

export function drawAdversaryCount(token) {
  if (!game.settings.get("starwarsffg", "showAdversaryCount")) {
    return;
  }
  const overflowColor = "0xDAA520";
  const itemName = game.settings.get("starwarsffg", "adversaryItemName");
  const adversaryItems = token?.actor?.items?.filter(i => i.name === itemName) || [];
  let adversaryLevel = 0;
  adversaryItems.forEach(function (item) {
    adversaryLevel += item?.system?.ranks?.current || 0;
  });
  if (adversaryLevel > 0) {
    // attempt to draw it on the token directly
    // check for existing copies of the container
    if (!token.children.find(i => i.name === "adversaryLevel")) {
      const countContainer = new PIXI.Container();
      countContainer.name = "adversaryLevel";
      token.adversaryLevel = token.addChild(countContainer);
    } else {
      token.adversaryLevel.removeChildren().forEach(i => i.destroy());
    }
    const sprite = PIXI.Sprite.from(`systems/starwarsffg/images/adversary/adversary-${adversaryLevel}.png`);
    sprite.scale.set(0.15, 0.15);
    sprite.x = (token.w / 2) - 20;
    sprite.y = token.h / 2 + 15;
    if (adversaryLevel > 5) {
      sprite.tint = overflowColor;
      adversaryLevel = 6;
    }
    token.adversaryLevel.addChild(sprite);
  }
}

import { AE_MODES } from "../config/ffg-active-effect-modes.js";
class CharacterTour extends foundry.nue.Tour {
  #originalDeactivate = null;

  async start() {
    await this.createActor();
    // fix for tooltips sometimes dismissing the tour
    // Store the original deactivate method and replace it with one that respects tour state
    this.#originalDeactivate = game.tooltip.deactivate.bind(game.tooltip);
    game.tooltip.deactivate = () => {
      // Don't deactivate tooltips during the tour
      if (foundry.nue.Tour.tourInProgress) return;
      this.#originalDeactivate();
    };
    await super.start();
  }

  /** override */
  async _preStep() {

    const currentStep = this.currentStep;

    if (currentStep.id === "roll-dice") {
      await this.giveActorStats();
    } else if (currentStep.id === "dice-pool") {
      // render the dice roller for info about it
      $("[data-ability=\"Athletics\"] .pure-u-6-24 .dice-pool").trigger("click");
      await delay(100);
    } else if (currentStep.id === "spending-xp-1") {
      // close the dice roller
      $("#roll-builder .control.close").trigger("click");
      await delay(100);
    }

    await super._preStep();
  }

  /** override */
  async _postStep() {
    await super._postStep();
    if (this.currentStep?.id === "spending-xp-3") {
      await this.deleteActor();
    }
  }

  /** override */
  async exit() {
    // Restore original tooltip deactivate method
    if (this.#originalDeactivate) {
      game.tooltip.deactivate = this.#originalDeactivate;
      this.#originalDeactivate = null;
    }
    await this.deleteActor();
    await super.exit();
  }

  async createActor() {
    this.tempActor = await createActor();
    this.tempActor.sheet.bringToTop();
    await delay(100);
  }

  async deleteActor() {
    await this.tempActor.delete()
  }

  async giveActorStats() {
    await this.tempActor.update({"system.characteristics.Brawn.value": 3});
    await delay(100);
  }
}

class EditModeTour extends foundry.nue.Tour {
  #originalDeactivate = null;

  async start() {
    await this.createActor();
    await this.giveActorAE();
    // fix for tooltips sometimes dismissing the tour
    // Store the original deactivate method and replace it with one that respects tour state
    this.#originalDeactivate = game.tooltip.deactivate.bind(game.tooltip);
    game.tooltip.deactivate = () => {
      // Don't deactivate tooltips during the tour
      if (foundry.nue.Tour.tourInProgress) return;
      this.#originalDeactivate();
    };
    await super.start();
  }

  /** override */
  async _preStep() {
    const currentStep = this.currentStep;

    if (currentStep.id === "enable-edit-mode") {
      $(".ffg-sheet-options").trigger("click");
      await delay(100);
    } else if (currentStep.id === "stat-changes") {
      await this.enableEditMode();
    }

    await super._preStep();
  }

  /** override */
  async _postStep() {
    await super._postStep();
    if (this.currentStep?.id === "disable-edit-mode") {
      await this.deleteActor();
    }
  }

  /** override */
  async exit() {
    // Restore original tooltip deactivate method
    if (this.#originalDeactivate) {
      game.tooltip.deactivate = this.#originalDeactivate;
      this.#originalDeactivate = null;
    }
    await this.deleteActor();
    await super.exit();
  }

  async createActor() {
    this.tempActor = await createActor();
    this.tempActor.sheet.bringToTop();
    await delay(100);
  }

  async deleteActor() {
    await this.tempActor.delete()
  }

  /**
   * Give the actor an AE so it can be suspended when we enable Edit Mode
   * @returns {Promise<void>}
   */
  async giveActorAE() {
    const AEData = {
      changes: [{
        key: "system.characteristics.Brawn.value",
        mode: AE_MODES.ADD,
        value: 3,
      }],
      name: "example",
      disabled: false,
    };
    await this.tempActor.createEmbeddedDocuments("ActiveEffect", [AEData]);
    await delay(100);
  }

  /**
   * Trigger Edit Mode on the actor so we can show changes with it on
   * @returns {Promise<void>}
   */
  async enableEditMode() {
    $("[name=\"config.enableEditMode\"]").trigger("click");
    $("[data-button=\"one\"]").trigger("click");
    await delay(300);
  }
}

/**
 * Register our tours for Foundry to see
 * @returns {Promise<void>}
 */
export async function register_system_tours() {
  try {
    game.tours.register("starwarsffg", 'character', await CharacterTour.fromJSON('/systems/starwarsffg/modules/tours/character.json'));
    game.tours.register("starwarsffg", 'edit-mode', await EditModeTour.fromJSON('/systems/starwarsffg/modules/tours/edit-mode.json'));
