const delay = (delayInMs) => {
  return new Promise(resolve => setTimeout(resolve, delayInMs));
};

/**
 * Create an actor for showing the tour within
 * @returns {Promise<Document|Document[]|undefined>}
 */
async function createActor() {
  const tempActorData = {
    name: "Tutorial Character",
    type: "character",
  };
  const tempActor = await Actor.create(tempActorData);

  await tempActor.sheet.render(true);
  // wait for the rendering to actually finish
  await new Promise(async resolve => {
    while (!tempActor.sheet.rendered) {
      await delay(5);
    }
    resolve();
  });
  return tempActor;
}

import ImportHelpers from "./import-helpers.js";
import OggDude from "./oggdude/oggdude.js";

const { ApplicationV2, HandlebarsApplicationMixin } = foundry.applications.api

export default class DataImporter extends HandlebarsApplicationMixin(ApplicationV2) {
  static DEFAULT_OPTIONS = {
    id: "data-importer",
    tag: "form",
    form: {
      handler: DataImporter._startImport,
      submitOnChange: false,
      closeOnSubmit: false
    },
    window: {
      title: "Data Importer",
      contentClasses: ["standard-form"]
    },
    actions: {
      loadFile: DataImporter._loadFile,
      selectAll: DataImporter._enableImportAll,
    },
  }

  static PARTS = {
    importer: {
      template: "systems/starwarsffg/templates/importer/data-importer.html",
      classes: ["starwarsffg", "data-import"],
    },
    footer: {
      template: "templates/generic/form-footer.hbs",
    }
  }

  /** @override */
  constructor(options) {
    super(options);
    this.oggdude = OggDude;
    this.importers = this.oggdude.Meta;
    this.canImport = {};
    this.shouldImport = {};
  }

  /** @override */
  async close(options = {}) {
    const closeOptions = this.minimized && options.animate !== false ? { ...options, animate: false } : options;
    return super.close(closeOptions);
  }

  /**
   * Return a reference to the target attribute
   * @type {String}
   */
  get attribute() {
    return this.options.name;
  }

  /** @override */
  async _prepareContext() {
    let data = await foundry.applications.apps.FilePicker.implementation.browse("data", "", { bucket: null, extensions: [".zip", ".ZIP"], wildcard: false });
    const files = data.files.map((file) => decodeURIComponent(file));

    document.querySelectorAll('.import-progress').forEach(el => el.classList.add('import-hidden'));

    if (!CONFIG?.temporary) {
      CONFIG.temporary = {};
    }

    return {
      importers: this.importers,
      data,
      files,
      cssClass: "data-importer-window",
      buttons: [
        { type: "submit", icon: "fas fa-file-import", label: "SWFFG.ImportFile", disabled: true }
      ]
    };
  }

  /** @override */
  _onRender(context, options) {
    // Add debug log option to window header
    const debugSpan = document.createElement("span");
    debugSpan.className = "debug";
    debugSpan.innerHTML = `<label><input type="checkbox" /> Generate Log</label>`;
    const headerCloseButton = this.element?.querySelector("#data-importer header button[data-action=close]");
    if (headerCloseButton && headerCloseButton.parentNode) {
      headerCloseButton.parentNode.insertBefore(debugSpan, headerCloseButton);
    }

    // Use a short timeout to ensure all async DOM updates are complete before positioning
    setTimeout(this.setPosition.bind(this), 50);
  }

  _importLog = [];
  _importLogger(message) {
    let checked = false;
    checked = Array.from(document.querySelectorAll('.debug input')).some(el => el.checked);
    if (checked) {
      this._importLog.push(`[${new Date().getTime()}] ${message}`);
    }
    CONFIG.logger.debug(message)
  }

  /**
   * Enable all checkboxes for import rather than forcing the user to click them all one at a time
   * @private
   */
  static _enableImportAll(event, target) {
    document.querySelectorAll("input[type='checkbox'][name='imports']").forEach(el => el.checked = true);
  }

  static async _readFile() {
    let selectedFile, form, file, zip;

    const input = document.querySelector("#import-file");
    selectedFile = input ? input.value : "";

    if (selectedFile) {
      // Read file on server from selector
      zip = await fetch(`/${selectedFile}`)
        .then(function (response) {
          if (response.status === 200 || response.status === 0) {
            return Promise.resolve(response.blob());
          } else {
            return Promise.reject(new Error(response.statusText));
          }
        })
        .then(JSZip.loadAsync);
    } else {
      // Read local file from picker
      form = document.querySelector("form.data-importer-window");
      file = form?.data?.files[0];

      if (typeof file !== "undefined") {
        zip = await ImportHelpers.readBlobFromFile(file).then(JSZip.loadAsync);
      } else {
        ui.notifications.warn(game.i18n.localize("SWFFG.Notifications.Import.NoFileWarning"));
        return undefined;
      }
    }
    return zip;
  }

  static async _loadFile(event, target) {
    // Reset defaults
    const form = target.closest("form");
    if (form) {
      form.querySelectorAll("input[type='checkbox'][name='imports']").forEach(el => el.disabled = true);
    }

    try {
      let zip = await DataImporter._readFile();
      if (typeof zip === "undefined") return;

      const selectAll = document.querySelector("[data-action='selectAll']");
      if (importAll !== null) selectAll.disabled = false;

      for (const importer of Object.values(this.importers)) {
        this.canImport[importer.itemName] = this._enableImportSelection(importer.displayName, importer.className, zip.files);
      }

      const startImport = document.querySelector("button[type='submit']")
      if (startImport !== null) startImport.disabled = false;

    } catch (err) {
      ui.notifications.error(game.i18n.localize("SWFFG.Notifications.Import.FileLoadError"));
      console.error(err);
    }
  }

  static async _startImport(event, form, formData) {
    CONFIG.logger.debug("Importing Data Files");
    this._importLogger(`Starting import`);

    let zip = await DataImporter._readFile();
    if (typeof zip === "undefined") {
      this._importLogger("zip file not found, exiting!");
      return;
    }

    // Disable submit button to prevent double clicking
    const startImport = document.querySelector("button[type='submit']")
    if (startImport !== null) startImport.disabled = true;

    let importFiles = Array.from(document.querySelectorAll("input[type='checkbox'][name='imports']:checked")).map(el => (
      el.dataset.itemtype
    ));

    for (const importer of document.querySelectorAll("input[type='checkbox'][name='imports']")) {
      const itemName = $(importer).data("itemtype");
      this.shouldImport[itemName] = importer.checked;
    }

    if (document.querySelector("#deleteExisting").checked) {
      for (const itemType of importFiles) {
        await this._deleteCompendium(itemType);
      }
    }

    // If skills are not selected for import, pre-populate the skills cache so other importers
    // (weapons, species, careers, etc.) can still resolve skill keys without errors.
    if (!this.shouldImport["skills"]) {
      CONFIG.temporary["skills"] = {};
      const skillsPack = game.packs.get("world.oggdudeskilldescriptions");
      if (skillsPack) {
        this._importLogger("Skills not selected for import - loading skills from world compendium");
        const skillDocs = await skillsPack.getDocuments();
        for (const doc of skillDocs) {
          const importId = doc.flags?.starwarsffg?.ffgimportid;
          if (importId) {
            CONFIG.temporary.skills[importId] = doc.name;
          }
        }
        this._importLogger(`Loaded ${Object.keys(CONFIG.temporary.skills).length} skills from world compendium`);
      }
    }

    for (let cur_phase = 1; cur_phase < 9; cur_phase++) {
      this._importLogger(`Beginning import phase ${cur_phase}`);
      const cur_phase_promises = [];
      const cur_phase_imports = Object.values(this.importers).filter(i => i.phase === cur_phase);
      await this.asyncForEach(cur_phase_imports, async (curImport) => {
        if (!this.shouldImport[curImport.itemName]) {
          this._importLogger(`Skipping unselected import of ${curImport.displayName}`);
        } else {
          if (curImport.filesAreDir && !["background"].includes(curImport.itemName) ) {
            cur_phase_promises.push(
              OggDude.Import[curImport.className](zip)
            );
          } else {
            for (const curFilename of curImport.fileNames) {
              this._importLogger(`Importing from ${curFilename}`);
              const selectedFile = Object.values(zip.files).find(f => f.name.includes(curFilename));
              const data = await zip.file(selectedFile.name).async("text");
              const xmlDoc = ImportHelpers.stringToXml(data);

              cur_phase_promises.push(
                OggDude.Import[curImport.className](xmlDoc, zip)
              );
            }
          }
        }
      });
      await Promise.all(cur_phase_promises);
      this._importLogger(`Done importing phase ${cur_phase}!`);
    }
    this._importLogger("Done with import!");

    let checked = false;
    checked = Array.from(document.querySelectorAll('.debug input')).some(el => el.checked);
    if (checked) {
      foundry.utils.saveDataToFile(this._importLog.join("\n"), "text/plain", "import-log.txt");
    }

    CONFIG.temporary = {};
    this.close();
  }

  /**
   * Called when Load File is clicked - enables checkboxes for item types which are in the selected ZIP
   * @param displayName - the display name of the item type we're checking for (used for logging)
   * @param className - the class name of the item type we're checking for (used to find the input)
   * @param files - files object for the uploaded ZIP
   * @private
   */
  _enableImportSelection(displayName, className, files) {
    const element = $(this.element).find(`#import${className}`);
    const canEnable = this.canEnable(displayName, element, files);
    if (canEnable) {
      element.removeAttr("disabled");
    }
    return canEnable;
  }

  /**
   * Checks if a given input should be enabled based on the presence of pre-defined files in the selected ZIP
   * @param displayName - the display name of the input we're checking for (used for logging)
   * @param element - input element which contains additional metadata
   * @param zipFiles - files object for the uploaded ZIP
   * @returns {boolean} - should this be enabled or not?
   * @private
   */
  canEnable(displayName, element, zipFiles) {
    this._importLogger(`Determining if we should enable import for ${displayName}`);
    const fileNames = element.data("filenames").split(",");
    const filesAreDir = element.data("filesaredir");
    let shouldEnable = true;

    for (const file of fileNames) {
      const foundFile = Object.values(zipFiles).filter(i => i.name.includes(file) && i.dir === filesAreDir).length > 0;
      if (!foundFile) {
        shouldEnable = false;
        break;
      }
    }

    this._importLogger(`Should include outcome for ${displayName}: ${shouldEnable}`);
    return shouldEnable;
  }

  asyncForEach = async (array, callback) => {
    for (let index = 0; index < array.length; index += 1) {
      await callback(array[index], index, array);
    }
  };

  async _deleteCompendium(itemType) {
    const typeToCompendium = {
      armor: ["world.oggdudearmor"],
      background: ["world.oggdudebackgrounds"],
      career: ["world.oggdudecareers"],
      forcepower: ["world.oggdudeforcepowers"],
      gear: ["world.oggdudegear"],
      itemmodifier: ["world.oggdudearmormods", "world.oggdudeweaponmods", "world.oggdudegenericmods", "world.oggdudevehiclemods"],
      itemattachment: ["world.oggdudearmorattachments", "world.oggdudeweaponattachments", "world.oggdudegenericattachments", "world.oggdudevehicleattachments"],
      motivation: ["world.oggdudemotivations"],
      obligation: ["world.oggdudeobligation"],
      signatureability: ["world.oggdudesignatureabilities"],
      skills: ["world.oggdudeskilldescriptions"],
      specialization: ["world.oggdudespecializations"],
      species: ["world.oggdudespecies"],
      talent: ["world.oggdudetalents"],
      vehicle: ["world.oggdudevehiclesplanetary", "world.oggdudevehiclesspace"],
      weapon: ["world.oggdudeweapons", "world.oggdudevehicleweapons"],
    };

    for (const curType of typeToCompendium[itemType]) {
      const pack = game.packs.get(curType);
      if (pack) {
        this._importLogger(`Deleting compendium: ${pack.metadata.name}`);
        await pack.deleteCompendium();
      }
    }
  }
}

import { AE_MODES } from "../config/ffg-active-effect-modes.js";
import Helpers from "../helpers/common.js";
import {migrateDataToSystem} from "../helpers/migration.js";
import {ItemFFG} from "../items/item-ffg.js";
import ModifierHelpers from "../helpers/modifiers.js";

export default class ImportHelpers {
  /**
   * Verifies server path exists, and if it doesn't creates it.
   *
   * @param  {string} startingSource - Source
   * @param  {string} path - Server path to verify
   * @returns {boolean} - true if verfied, false if unable to create/verify
   */
  static async verifyPath(startingSource, path) {
    try {
      const paths = path.split("/");
      let currentSource = paths[0];

      for (let i = 0; i < paths.length; i += 1) {
        try {
          if (currentSource !== paths[i]) {
            currentSource = `${currentSource}/${paths[i]}`;
          }
          await foundry.applications.apps.FilePicker.implementation.createDirectory(startingSource, `${currentSource}`, { bucket: null });
        } catch (err) {
          CONFIG.logger.debug(`Error verifying path ${startingSource}, ${path}`, err);
        }
      }
    } catch (err) {
      return false;
    }

    return true;
  }

  /**
   * Imports binary file, by extracting from zip file and uploading to path.
   *
   * @param  {string} path - Path to image within zip file
   * @param  {object} zip - Zip file
   * @param  {object} pack - Compendium Pack
   * @returns {string} - Path to file within VTT
   */
  static async importImage(path, zip, pack) {
    if (path) {
      const serverPath = `worlds/${game.world.id}/images/packs/${pack.metadata.name}`;
      const filename = path.replace(/^.*[\\\/]/, "");
      if (!CONFIG.temporary.images) {
        CONFIG.temporary.images = [];
      }
      try {
        if (!CONFIG.temporary.images.includes(`${serverPath}/${filename}`)) {
          CONFIG.temporary.images.push(`${serverPath}/${filename}`);
          await ImportHelpers.verifyPath("data", serverPath);
          const img = await zip.file(path).async("uint8array");
          var arr = img.subarray(0, 4);
          var header = "";
          for (var a = 0; a < arr.length; a++) {
            header += arr[a].toString(16);
          }
          const type = Helpers.getMimeType(header);

          const i = new File([img], filename, { type });
          await Helpers.UploadFile("data", `${serverPath}`, i, { bucket: null });
        }

        return `${serverPath}/${filename}`;
      } catch (err) {
        CONFIG.logger.error(`Error Uploading File: ${path} to ${serverPath}`);
      }
    }
  }

  /**
   * Imports binary file, by extracting from zip file and uploading to path.
   * Uploads to a different directory than the standard importer
   *
   * @param  {string} path - Path to image within zip file
   * @param  {object} zip - Zip file
   * @param  {object} pack - Compendium Pack
   * @returns {string} - Path to file within VTT
   */
  static async importSilhouetteImage(path, zip, pack) {
    if (path) {
      const serverPath = `worlds/${game.world.id}/images/packs/${pack.metadata.name}Silhouettes`;
      const filename = path.replace(/^.*[\\\/]/, "");
      if (!CONFIG.temporary.images) {
        CONFIG.temporary.images = [];
      }
      try {
        if (!CONFIG.temporary.images.includes(`${serverPath}/${filename}`)) {
          CONFIG.temporary.images.push(`${serverPath}/${filename}`);
          await ImportHelpers.verifyPath("data", serverPath);
          const img = await zip.file(path).async("uint8array");
          var arr = img.subarray(0, 4);
          var header = "";
          for (var a = 0; a < arr.length; a++) {
            header += arr[a].toString(16);
          }
          const type = Helpers.getMimeType(header);

          const i = new File([img], filename, { type });
          await Helpers.UploadFile("data", `${serverPath}`, i, { bucket: null });
        }

        return `${serverPath}/${filename}`;
      } catch (err) {
        CONFIG.logger.error(`Error Uploading File: ${path} to ${serverPath}`);
      }
    }
  }

  /**
   * Returns the name of a file within the zip file based on a built string.
   *
   * @param  {object} zip - Zip file
   * @param  {string} type - Object Type
   * @param  {string} itemtype - Item Type
   * @param  {string} key - Item Key
   * @param {string} secondStageFilename - optional string to append to the object type; defaults to 'Images'
   * @returns {string} - Path to file within Zip File
   */
  static async getImageFilename(zip, type, itemtype, key, secondStageFilename='Images') {
    const imgFileName = `${type}${secondStageFilename}/${itemtype}${key}`;

    return Object.values(zip.files).find((file) => {
      if (file.name.includes(imgFileName)) {
        return file.name;
      }
      return undefined;
    });
  }

  /**
   * Converts and object into an update object for entity update function
   * @param  {object} newItem - Object data
   * @returns {object} - Entity Update Object
   */
  static buildUpdateData = (newItem) => {
    CONFIG.logger.debug(`Starting BuildUpdateData for item - ${newItem.name}`);
    let updateData = {};
    if (newItem.img) {
      updateData.img = newItem.img;
    }

    for (let key in newItem.data) {
      const recursiveObject = (itemkey, obj) => {
        for (let objkey in obj) {
          if (typeof obj[objkey] === "object") {
            recursiveObject(`${itemkey}.${objkey}`, obj[objkey]);
          } else {
            if (typeof obj[objkey] !== undefined) {
              const datakey = `data.${itemkey}.${objkey}`;
              updateData[datakey] = obj[objkey];
            }
          }
        }
      };

      if (typeof newItem.data[key] === "object") {
        recursiveObject(key, newItem.data[key]);
      } else {
        const datakey = `data.${key}`;
        updateData[datakey] = newItem.data[key];
      }
    }
    CONFIG.logger.debug(`Completed BuildUpdateData for item - ${newItem.name}`);
    return updateData;
  };

  /**
   * Find an entity by the import key.
   * @param  {string} type - Entity type to search for
   * @param  {string} id - Entity Id
   * @returns {object} - Entity Object Data
   */
  static findEntityByImportId(type, id) {
    return game.data[type].find((item) => {
      return item.flags.starwarsffg.ffgimportid === id;
    });
  }

  /**
   * Find a compendium entity by type an id
   * @param  {string} type - Entity type to search for
   * @param  {string} id - Entity Id
   * @returns {object} - Entity Object Data
   */
  static async findCompendiumEntityById(type, id) {
    let packs = Array.from(await game.packs.keys());
    for (let i = 0; i < packs.length; i += 1) {
      let packId = packs[i];
      const pack = await game.packs.get(packId);
      if (pack.documentName === type) {
        const entity = await pack.getDocument(id);
        if (entity) {
          return entity;
        }
      }
    }
  }

  /**
   * Find a compendium entity by type and name
   * we can encounter the ID changing seemingly during Foundry version transitions, even within minor version changes
   * @param  {string} type - Entity type to search for
   * @param {string} name - Name of the item (optional)
   * @returns {object} - Entity Object Data
   */
  static async findCompendiumEntityByName(type, name) {
    let packs = Array.from(await game.packs.keys());
    for (let i = 0; i < packs.length; i += 1) {
      let packId = packs[i];
      const pack = await game.packs.get(packId);
      if (pack.documentName === type) {
        const entity = pack.index.find(t => t.name === name);
        if (entity) {
          return await pack.getDocument(entity._id);
        }
      }
    }
  }

  static clearCache() {
    CONFIG.temporary = {};
  }

  /**
   * Find an entity by the import key.
   * @param  {string} type - Entity type to search for
   * @param  {string} id - Entity Id
   * @returns {object} - Entity Object Data
   */
  static async findCompendiumEntityByImportId(type, id, packId, itemType, skipCache) {
    if (skipCache) {
      const pack = game.packs.get(packId);
      const contents = await pack.getDocuments();
      return contents.find((item) => {
        return item.flags.starwarsffg.ffgimportid === id;
      });
    }
    const cachePack = async (packid) => {
      if (!CONFIG.temporary[packid]) {
        const pack = await game.packs.get(packid);
        if (pack.documentName === type && !pack.locked) {
          CONFIG.logger.debug(`Caching pack content ${packid}`);
          CONFIG.temporary[packid] = {};

          const content = await pack.getDocuments();
          for (var i = 0; i < content.length; i++) {
            CONFIG.temporary[packid][content[i].flags?.starwarsffg?.ffgimportid] = foundry.utils.deepClone(content[i]);
          }
        }
      }

      if (CONFIG.temporary?.[packid]?.[id]) {
        if (!itemType || CONFIG.temporary?.[packid]?.[id]?.type === itemType) {
          return packid;
        }
      }
      return undefined;
    };

    let packname;
    if (!packId) {
      let packs = Array.from(await game.packs.keys());

      await this.asyncForEach(packs, async (packid) => {
        const temppackname = await cachePack(packid);
        if (temppackname) {
          packname = temppackname;
        }
      });
    } else {
      packname = await cachePack(packId);
    }

    if (packname) {
      return CONFIG.temporary[packname][id];
    }

    return undefined;
  }

  static getAttributeObject(attributes) {
    const attrs = JXON.xmlToJs(attributes);

    let itemAttributes = {};
    if (attrs.SoakValue) {
      itemAttributes.Soak = { mod: "Soak", modtype: "Stat", value: attrs.SoakValue };
    }
    if (attrs.ForceRating) {
      itemAttributes.ForcePool = { mod: "ForcePool", modtype: "Stat", value: attrs.ForceRating };
    }
    if (attrs.StrainThreshold) {
      itemAttributes.Strain = { mod: "Strain", modtype: "Stat", value: attrs.StrainThreshold };
    }
    if (attrs.DefenseRanged) {
      itemAttributes["Defence-Ranged"] = { mod: "Defence-Ranged", modtype: "Stat", value: attrs.DefenseRanged };
    }
    if (attrs.DefenseMelee) {
      itemAttributes["Defence-Melee"] = { mod: "Defence-Melee", modtype: "Stat", value: attrs.DefenseMelee };
    }
    if (attrs.WoundThreshold) {
      itemAttributes.Wounds = { mod: "Wounds", modtype: "Stat", value: attrs.WoundThreshold };
    }

    return itemAttributes;
  }

  static getBaseModAttributeObject(mod) {
    let type;
    let modtype;
    let value = mod?.Count ? parseInt(mod.Count, 10) : 0;

    if (["BR", "AG", "INT", "CUN", "WIL", "PR"].includes(mod.Key)) {
      modtype = "Characteristic";
      type = ImportHelpers.convertOGCharacteristic(mod.Key);
    }

    if (Object.keys(CONFIG.temporary.skills).includes(mod.Key)) {
      if (mod.SkillIsCareer) {
        modtype = "Career Skill";
      } else if (mod.BoostCount || mod.SetbackCount || mod.AddSetbackCount || mod.ForceCount || mod.AdvantageCount || mod.ThreatCount || mod.SuccessCount || mod.FailureCount) {
        modtype = "Skill Boost";

        if (mod.AddSetbackCount) {
          modtype = "Skill Setback";
          value = parseInt(mod.AddSetbackCount, 10);
        }
        if (mod.SetbackCount) {
          modtype = "Skill Remove Setback";
          value = parseInt(mod.SetbackCount, 10);
        }
        if (mod.ForceCount) {
          modtype = "Force Boost"
          value = true;
        }
        if (mod.BoostCount) {
          value = parseInt(mod.BoostCount, 10);
        }
        if (mod.AdvantageCount) {
          modtype = "Skill Add Advantage";
          value = parseInt(mod.AdvantageCount, 10);
        }
        if (mod.ThreatCount) {
          modtype = "Skill Add Threat";
          value = parseInt(mod.ThreatCount, 10);
        }
        if (mod.SuccessCount) {
          modtype = "Skill Add Success";
          value = parseInt(mod.SuccessCount, 10);
        }
        if (mod.FailureCount) {
          modtype = "Skill Add Failure";
          value = parseInt(mod.FailureCount, 10);
        }
        if (mod.TriumphCount) {
          modtype = "Skill Add Triumph";
          value = parseInt(mod.TriumphCount, 10);
        }
        if (mod.DespairCount) {
          modtype = "Skill Add Despair";
          value = parseInt(mod.DespairCount, 10);
        }
      } else {
        modtype = "Skill Rank";
      }

      let skill = CONFIG.temporary.skills[mod.Key];

      if (skill.includes(":") && !skill.includes(": ")) {
        skill = skill.replace(":", ": ");
      }

      if (Object.keys(CONFIG.FFG.skills).includes(skill)) {
        type = skill;
      }
    }

    if (mod.Key === "ENCTADD") {
      modtype = "Stat";
      type = "Encumbrance";
      value = value;
    }

    if (type) {
      return { type, value: { mod: type, modtype, value } };
    }
  }

  /**
   * @param  {object} basemods
   */
  static getBaseModObject(basemods) {
    const attrs = JXON.xmlToJs(basemods);
    let itemAttributes = {};

    if (Array.isArray(attrs.Mod)) {
      attrs.Mod.forEach((mod) => {
        if (mod.Key) {
          const attr = this.getBaseModAttributeObject(mod);
          if (attr) {
            itemAttributes[attr.type] = attr.value;
          }
        } else if (mod.DieModifiers?.DieModifier) {
          if (Array.isArray(mod.DieModifiers.DieModifier)) {
            mod.DieModifiers.DieModifier.forEach((diemod) => {
              const attr = this.getBaseModAttributeObject({
                Key: diemod.SkillKey,
                ...diemod,
              });
              if (attr) {
                itemAttributes[attr.type] = attr.value;
              }
            });
          } else {
            const attr = this.getBaseModAttributeObject({
              Key: mod.DieModifiers.DieModifier.SkillKey,
              ...mod.DieModifiers.DieModifier,
            });
            if (attr) {
              itemAttributes[attr.type] = attr.value;
            }
          }
        }
      });
    }

    if (attrs?.Mod?.Key) {
      const attr = this.getBaseModAttributeObject(attrs.Mod);
      if (attr) {
        itemAttributes[attr.type] = attr.value;
      }
    } else if (attrs?.Mod?.DieModifiers?.DieModifier) {
      if (!Array.isArray(attrs.Mod.DieModifiers.DieModifier)) {
        attrs.Mod.DieModifiers.DieModifier = [attrs.Mod.DieModifiers.DieModifier];
      }
      attrs.Mod.DieModifiers.DieModifier.forEach((mod) => {
        const attr = this.getBaseModAttributeObject({
          Key: mod.SkillKey,
          ...mod,
        });
        if (attr) {
          itemAttributes[attr.type] = attr.value;
        }
      });
    }

    return itemAttributes;
  }

  static async getQualities(qualityList) {
    let qualities = [];
    let attributes = {};

    if (qualityList && !Array.isArray(qualityList)) {
      qualityList = [qualityList];
    }

    if (qualityList && qualityList.length > 0) {
      await this.asyncForEach(qualityList, async (quality) => {
        let descriptor = await ImportHelpers.findCompendiumEntityByImportId("JournalEntry", quality.Key);

        if (descriptor?.compendium?.metadata) {
          qualities.push(`<a class="entity-link" draggable="true" data-pack="${descriptor.compendium.metadata.package}.${descriptor.compendium.metadata.name}" data-id="${descriptor.id}"> ${quality.Key}  ${quality.Count ? quality.Count : ""}</a>`);
        } else {
          qualities.push(`${quality.Key} ${quality.Count ? quality.Count : ""}`);
        }

        if (quality.Key === "DEFENSIVE") {
          const nk = foundry.utils.randomID();
          const count = quality.Count ? parseInt(quality.Count) : 0;

          attributes[`attr${nk}`] = {
            isCheckbox: false,
            mod: "Defence-Melee",
            modtype: "Stat",
            value: count,
          };
        }
      });

      return { qualities, attributes };
    }
  }

  static asyncForEach = async (array, callback) => {
    for (let index = 0; index < array.length; index += 1) {
      await callback(array[index], index, array);
    }
  };

