  static b64toBlob = (b64Data, contentType, sliceSize) => {
    contentType = contentType || "";
    sliceSize = sliceSize || 512;

    var byteCharacters = atob(b64Data);
    var byteArrays = [];

    for (var offset = 0; offset < byteCharacters.length; offset += sliceSize) {
      var slice = byteCharacters.slice(offset, offset + sliceSize);

      var byteNumbers = new Array(slice.length);
      for (var i = 0; i < slice.length; i++) {
        byteNumbers[i] = slice.charCodeAt(i);
      }

      var byteArray = new Uint8Array(byteNumbers);

      byteArrays.push(byteArray);
    }

    var blob = new Blob(byteArrays, { type: contentType });
    return blob;
  };

  static stringToXml = (s) => {
    let data = s.replace(/^\uFEFF/, "");
    const parser = new DOMParser();
    const xmlDoc = parser.parseFromString(data, "text/xml");

    return xmlDoc;
  };

  /**
   * Read data from a user provided File object
   * @param {File} file           A File object
   * @return {Promise.<String>}   A Promise which resolves to the loaded text data
   */
  static readBlobFromFile(file) {
    const reader = new FileReader();
    return new Promise((resolve, reject) => {
      reader.onload = (ev) => {
        resolve(reader.result);
      };
      reader.onerror = (ev) => {
        reader.abort();
        reject();
      };
      reader.readAsBinaryString(file);
    });
  }

  static convertOGCharacteristic(value) {
    let type;

    switch (value) {
      case "BR":
        type = "Brawn";
        break;
      case "AG":
        type = "Agility";
        break;
      case "INT":
        type = "Intellect";
        break;
      case "CUN":
        type = "Cunning";
        break;
      case "WIL":
        type = "Willpower";
        break;
      case "PR":
        type = "Presence";
        break;
    }

    return type;
  }

  /**
   * Converts sources to an array (instead of HTML) for rendering in a dedicated location
   * @param sources
   * @returns {*[]}
   */
  static getSourcesAsArray(sources) {
    let parsedSources = [];

    // if there are no sources, don't bother trying to parse
    if (!sources) {
      return parsedSources;
    }

    // sometimes there's a single source not inside a `source` block
    if (sources?._) {
      sources.Source = [sources];
    }

    try {
      // convert the sources to an array if they aren't already one (silly XML)
      if (!Array.isArray(sources.Source)) {
        sources.Source = [sources.Source];
      }

      for (const source of sources.Source) {
        if (source?.$Page) {
          parsedSources.push(`${source._} pg.${source.$Page}`);
        } else {
          parsedSources.push(source._);
        }
      }
    } catch {
      // in all the cases I looked at, this is due to bad data. just return what we've got so far
      return parsedSources;
    }
    return parsedSources;
  }

  /**
   * Converts sources to text
   * @param  {} sources
   */
  static getSources(sources) {
    if (!sources) return "";

    let sourceArray = [];

    if (!sources?.Source) {
      sourceArray = [sources];
    } else {
      if (!Array.isArray(sources.Source)) {
        sourceArray = [sources.Source];
      } else {
        sourceArray = sources.Source;
      }
    }

    const text = sourceArray.map((s) => {
      if (s?.$Page) {
        return `Page ${s.$Page} - ${s._}<br>`;
      } else {
        return `${s}<br>`;
      }
    });

    const sourceText = `<p><h3>Sources:</h3>${text.join("")}</p>`;

    return sourceText;
  }

  static prepareBaseObject(obj, type) {
    return {
      name: obj.Name,
      type,
      flags: {
        starwarsffg: {
          ffgimportid: obj.Key
        }
      },
      data: {},
    };
  }

  static async addImportItemToCompendium(type, data, pack, removeFirst) {
    let entry = await ImportHelpers.findCompendiumEntityByImportId(type, data.flags.starwarsffg.ffgimportid, pack.collection);
    let objClass;
    let dataType;
    switch (type) {
      case "Item": {
        objClass = Item;
        dataType = data.type;
        break;
      }
      case "JournalEntry": {
        objClass = JournalEntry;
        if (!data.img) {
          data.img = `icons/sundries/scrolls/scroll-rolled-white.webp`;
        }
        dataType = type;
        break;
      }
      case "Actor": {
        objClass = Actor;
        dataType = data.type;
        break;
      }
    }

    if (!entry) {
      let compendiumItem;
      CONFIG.logger.debug(`Importing ${type} ${dataType} ${data.name}`);
      data._id = foundry.utils.randomID();
      data.id = foundry.utils.randomID();
      data = migrateDataToSystem(data);
      switch (type) {
        case "Item":
          compendiumItem = await new CONFIG.Item.documentClass(data, { temporary: true });
          break;
        case "Actor":
          compendiumItem = await new CONFIG.Actor.documentClass(data, { temporary: true });
          break;
        case "JournalEntry":
          compendiumItem = await new CONFIG.JournalEntry.documentClass(data, { temporary: true });
          break;
        default:
          CONFIG.logger.error(`Unable to import item type ${type}, unhandled type.`);
      }
      CONFIG.logger.debug(`New ${type} ${dataType} ${data.name} : ${JSON.stringify(compendiumItem)}`);
      const crt = await pack.importDocument(compendiumItem);
      if (type === "Item") {
        // make sure Active Effects get created
        await new Promise(r => setTimeout(r, 50));
        await ImportHelpers.applyActiveEffectOnUpdate(crt, data);
        await ImportHelpers.applyTalentActiveEffects(crt);
      }
      CONFIG.temporary[pack.collection][data.flags.starwarsffg.ffgimportid] = foundry.utils.deepClone(crt);
      return crt;
    } else {
      CONFIG.logger.debug(`Found existing ${type} ${dataType} ${data.name}`);
      let upd;
      if (removeFirst) {
        await pack.delete(entry._id);
        let compendiumItem;
        CONFIG.logger.debug(`Importing ${type} ${dataType} ${data.name}`);
        switch (type) {
          case "Item":
            compendiumItem = await new CONFIG.Item.documentClass(data, { temporary: true });
            break;
          case "Actor":
            compendiumItem = await new CONFIG.Actor.documentClass(data, { temporary: true });
            break;
          case "JournalEntry":
            compendiumItem = await new CONFIG.JournalEntry.documentClass(data, { temporary: true });
            break;
          default:
            CONFIG.logger.error(`Unable to import item type ${type}, unhandled type.`);
        }

        compendiumItem = migrateDataToSystem(compendiumItem);
        CONFIG.logger.debug(`New ${type} ${dataType} ${data.name} : ${JSON.stringify(compendiumItem)}`);
        upd = await pack.importDocument(compendiumItem);
      } else {
        CONFIG.logger.debug(`Updating ${type} ${dataType} ${data.name}`);

        let updateData = data;
        updateData["_id"] = entry._id;

        if (updateData?.data?.attributes) {
          // Remove and repopulate all modifiers
          if (entry.system?.attributes) {
            for (let k of Object.keys(entry.system.attributes)) {
              if (!updateData.data.attributes.hasOwnProperty(k)) updateData.data.attributes[`-=${k}`] = null;
            }
          }
        }
        if (updateData?.data?.specializations) {
          // Remove and repopulate all specializations
          if (entry.system?.specializations) {
            for (let k of Object.keys(entry.system.specializations)) {
              if (!updateData.data.specializations.hasOwnProperty(k)) updateData.data.specializations[`-=${k}`] = null;
            }
          }
        }
        if (updateData?.data?.talents) {
          // Remove and repopulate all talents
          if (entry.system?.talents) {
            for (let k of Object.keys(entry.system.talents)) {
              if (!updateData.data.talents.hasOwnProperty(k)) updateData.data.talents[`-=${k}`] = null;
            }
          }
        }
        if (updateData?.data?.abilities) {
          // Remove and repopulate all abilities
          if (entry.system?.abilities) {
            for (let k of Object.keys(entry.system.abilities)) {
              if (!updateData.data.abilities.hasOwnProperty(k)) updateData.data.abilities[`-=${k}`] = null;
            }
          }
        }

        upd = foundry.utils.duplicate(entry);
        updateData = migrateDataToSystem(updateData);
        CONFIG.logger.debug(`Updating ${type} ${dataType} ${data.name} : ${JSON.stringify(updateData)}`);
        try {
          if (dataType === "vehicle") {
            // don't re-import items for existing vehicles, in order to avoid duplicating them
            updateData.items = [];
          }
          await pack.get(updateData._id).update(updateData);
          // update here does not return the UUID, so retrieve the item from the pack to get it
          const updatedItem = await pack.get(updateData._id);
          upd.uuid = updatedItem.uuid;
        } catch (e) {
          CONFIG.logger.error(`Failed to update ${type} ${dataType} ${data.name} : ${e.toString()}`);
        }
        if (upd.data) {
          upd.data = foundry.utils.mergeObject(upd.data, data.data);
        }
      }
      upd = migrateDataToSystem(upd);
      CONFIG.temporary[pack.collection][data.flags.starwarsffg.ffgimportid] = upd;
      return upd;
    }
  }

  static async getCompendiumPack(type, name) {
    CONFIG.logger.debug(`Checking for existing compendium pack ${name}`);
    const searchName = "world." + name.toString().replaceAll(".", "").toLowerCase();
    const pack = game.packs.get(searchName);
    if (!pack) {
      const compendiumLabel = name.split(".")[name.split(".").length - 1];
      const createdCompendium = await foundry.documents.collections.CompendiumCollection.createCompendium({
        label: compendiumLabel,
        name: name.replaceAll(".", "").toLowerCase(),
        type: type,
      });
      // get the folder for the compendium, creating it if needed
      const compendiumFolder = await this.lookupOrCreateFolder(compendiumLabel);
      // move the compendium into the proper folder
      await createdCompendium.configure({
        folder: compendiumFolder.id,
      });
      return game.packs.get(searchName);
    } else {
      await pack.configure({locked: false});
    }

    return pack;
  }

  /**
   * Creates the folder structure for an oggdude import (based on what's being imported).
   * Yes, it's ugly. It can probably be refactored to be more simple. But it works, and I want to get the other
   * changes out.
   * @param packName
   * @returns {Promise<*>}
   */
  static async lookupOrCreateFolder(packName) {
    const parentFolderName = "OggDude Import";
    let parentFolder = game.folders.find((f) => f.name === parentFolderName);
    if (!parentFolder) {
      await Folder.create({
        name: parentFolderName,
        type: "Compendium",
      });
      parentFolder = game.folders.find((f) => f.name === parentFolderName);
    }

    const actorItemFolder = "Actor Items";
    const equipmentItemFolder = "Equipment";
    const vehicleItemFolder = "Vehicles";
    const characterCreatorFolderName = "Character Creator";

    if (["Careers", "ForcePowers", "SignatureAbilities", "Specializations", "Species", "Talents"].includes(packName)) {
      // create the actor item folder
      let actorFolder = game.folders.find((f) => f.name === actorItemFolder);
      if (!actorFolder) {
        await Folder.create({
          name: actorItemFolder,
          type: "Compendium",
        });
        actorFolder = game.folders.find((f) => f.name === actorItemFolder);
        await actorFolder.update({
          folder: parentFolder.id,
        });
      }
      return actorFolder;
    } else if (["ArmorAttachments", "GenericAttachments", "WeaponAttachments", "ArmorMods", "GenericMods", "WeaponMods", "Armor", "Gear", "Weapons"].includes(packName)) {
      // create or locate the top-level equipment folder
      let equipmentFolder = game.folders.find((f) => f.name === equipmentItemFolder);
      if (!equipmentFolder) {
        await Folder.create({
          name: equipmentItemFolder,
          type: "Compendium",
        });
        equipmentFolder = game.folders.find((f) => f.name === equipmentItemFolder);
        await equipmentFolder.update({
          folder: parentFolder.id,
        });
      }
      if (["ArmorAttachments", "GenericAttachments", "WeaponAttachments"].includes(packName)) {
        // create and move sub-folder
        let attachmentFolder = game.folders.find((f) => f.name === "Attachments");
        if (!attachmentFolder) {
          await Folder.create({
            name: "Attachments",
            type: "Compendium",
          });
          attachmentFolder = game.folders.find((f) => f.name === "Attachments");
          await attachmentFolder.update({
            folder: equipmentFolder.id,
          });
        }
        // we want to return the attachment folder
        equipmentFolder = attachmentFolder;
      } else if (["ArmorMods", "GenericMods", "WeaponMods"].includes(packName)) {
        // create and move sub-folder
        // create and move sub-folder
        let modFolder = game.folders.find((f) => f.name === "Mods");
        if (!modFolder) {
          await Folder.create({
            name: "Mods",
            type: "Compendium",
          });
          modFolder = game.folders.find((f) => f.name === "Mods");
          await modFolder.update({
            folder: equipmentFolder.id,
          });
        }
        // we want to return the mod folder
        equipmentFolder = modFolder;
      }
      return equipmentFolder;
    } else if (["Backgrounds", "Obligations", "Motivations"].includes(packName)) {
      // create or locate the top-level equipment folder
      let characterCreatorFolder = game.folders.find((f) => f.name === characterCreatorFolderName);
      if (!characterCreatorFolder) {
        await Folder.create({
          name: characterCreatorFolderName,
          type: "Compendium",
        });
        characterCreatorFolder = game.folders.find((f) => f.name === characterCreatorFolderName);
        await characterCreatorFolder.update({
          folder: parentFolder.id,
        });
      }
      return characterCreatorFolder;
    } else if (["VehicleWeapons", "VehicleAttachments", "VehicleMods", "Planetary", "Space"].includes(packName)) {
        // create the actor item folder
        let actorFolder = game.folders.find((f) => f.name === vehicleItemFolder);
        if (!actorFolder) {
          await Folder.create({
            name: vehicleItemFolder,
            type: "Compendium",
          });
          actorFolder = game.folders.find((f) => f.name === vehicleItemFolder);
          await actorFolder.update({
            folder: parentFolder.id,
          });
        }
        return actorFolder;
      }
    return parentFolder;
  }

  static processCharacteristicMod(mod) {
    const nk = new Date().getTime();
    const modtype = "Characteristic";
    const type = ImportHelpers.convertOGCharacteristic(mod.Key);

    return {
      type: `attr${nk}`,
      value: {
        mod: type,
        modtype,
        value: mod?.Count ? parseInt(mod.Count, 10) : 0,
      },
    };
  }

  static processSkillMod(mod, isDescriptor) {
    let type;
    let modtype;
    let value = mod?.Count ? parseInt(mod.Count, 10) : 0;

    if (isDescriptor) {
      // handle description modifiers ** Experimental **
      Object.keys(mod).forEach((m) => {
        value = parseInt(mod[m], 10);
        switch (m) {
          case "BoostCount": {
            modtype = "Roll Modifiers";
            type = "Add Boost";
          }
        }
      });
    } else {
      if (mod.SkillIsCareer) {
        modtype = "Career Skill";
      } else if (mod.BoostCount || mod.SetbackCount || mod.AddSetbackCount || mod.ForceCount || mod.AdvantageCount || mod.ThreatCount || mod.SuccessCount || mod.FailureCount) {
        modtype = "Skill Boost";

        if (mod.AddSetbackCount) {
          modtype = "Skill Setback";
          value = parseInt(mod.AddSetbackCount, 10);
        }
        if (mod.SetbackCount) {
          modtype = "Skill Remove Setback";
          value = parseInt(mod.SetbackCount, 10);
        }
        if (mod.ForceCount) {
          modtype = "Force Boost"
          value = true;
        }
        if (mod.BoostCount) {
          value = parseInt(mod.BoostCount, 10);
        }
        if (mod.AdvantageCount) {
          modtype = "Skill Add Advantage";
          value = parseInt(mod.AdvantageCount, 10);
        }
        if (mod.ThreatCount) {
          modtype = "Skill Add Threat";
          value = parseInt(mod.ThreatCount, 10);
        }
        if (mod.SuccessCount) {
          modtype = "Skill Add Success";
          value = parseInt(mod.SuccessCount, 10);
        }
        if (mod.FailureCount) {
          modtype = "Skill Add Failure";
          value = parseInt(mod.FailureCount, 10);
        }
      } else {
        modtype = "Skill Rank";
      }
      if (mod.Key) {
        let skill = CONFIG.temporary.skills[mod.Key];

        if (skill.includes(":") && !skill.includes(": ")) {
          skill = skill.replace(":", ": ");
        }

        if (Object.keys(CONFIG.FFG.skills).includes(skill)) {
          type = CONFIG.temporary.skills[mod.Key];
        }
      } else if (mod?.Skill) {
        type = mod.Skill;
      }
    }
    if (type) {
      return { type, value: { mod: type, modtype, value } };
    }
  }

  static async processDieMod(mod) {
    if (!Array.isArray(mod.DieModifier)) {
      mod.DieModifier = [mod.DieModifier];
    }

    let output = {
      attributes: {},
    };

    await ImportHelpers.asyncForEach(mod.DieModifier, async (dieMod) => {
      const key = `attr${new Date().getTime()}`;
      // ensure further keys have a new entry
      await new Promise(r => setTimeout(r, 1));
      if (!dieMod) {
        return;
      } else if (dieMod.SkillKey) {
        // this is a skill modifier
        const skillModifier = ImportHelpers.processSkillMod({ Key: dieMod.SkillKey, ...dieMod });
        output.attributes[key] = skillModifier.value;
      } else if (dieMod.SkillChar) {
        // this is a skill modifier based on characteristic (ex all Brawn skills);
        const skillTheme = await game.settings.get("starwarsffg", "skilltheme");
        const allSkillsLists = await game.settings.get("starwarsffg", "arraySkillList");
        const skills = allSkillsLists.find((i) => i.id === skillTheme).skills;
        const characteristicSkills = Object.keys(skills).filter((s) => skills[s].characteristic === ImportHelpers.convertOGCharacteristic(dieMod.SkillChar));

        characteristicSkills.forEach((cs) => {
          const skillModifier = ImportHelpers.processSkillMod({ Skill: cs, ...dieMod });

          if (output.attributes[key]) {
            output.attributes[key].value += skillModifier.value.value;
          } else {
            output.attributes[key] = skillModifier.value;
          }
        });
      } else if (dieMod.SkillType) {
        const skillTheme = await game.settings.get("starwarsffg", "skilltheme");
        const allSkillsLists = await game.settings.get("starwarsffg", "arraySkillList");
        const skills = allSkillsLists.find((i) => i.id === skillTheme).skills;
        const characteristicSkills = Object.keys(skills).filter((s) => skills[s].type.toLowerCase() === dieMod.SkillType.toLowerCase());

        characteristicSkills.forEach((cs) => {
          const skillModifier = ImportHelpers.processSkillMod({ Skill: cs, ...dieMod });

          if (output.attributes[key]) {
            output.attributes[key].value += skillModifier.value.value;
          } else {
            output.attributes[key] = skillModifier.value;
          }
        });
      } else {
        const skillModifier = ImportHelpers.processSkillMod({ Key: dieMod.SkillKey, ...dieMod }, true);
        output.attributes[key] = skillModifier.value;
      }
    });

    return output;
  }

  static async processModsData(modifiersData) {
    let output = {
      attributes: {},
      description: "",
      itemattachment: [],
      itemmodifier: [],
    };

    if (modifiersData?.Mod || modifiersData?.Quality) {
      let mods;
      if (modifiersData?.Mod) {
        if (!Array.isArray(modifiersData.Mod)) {
          mods = [modifiersData.Mod];
        } else {
          mods = modifiersData.Mod;
        }
      } else {
        if (!Array.isArray(modifiersData.Quality)) {
          mods = [modifiersData.Quality];
        } else {
          mods = modifiersData.Quality;
        }
      }
      let unique_mods = 0;
      await this.asyncForEach(mods, async (modifier) => {
        if (modifier.Key) {
          // this is a characteristic or stat or skill or quality modifier.
          if (["BR", "AG", "INT", "CUN", "WIL", "PR"].includes(modifier.Key)) {
            // this is a characteristic modifier
            const attribute = ImportHelpers.processCharacteristicMod(modifier);

            output.attributes[attribute.type] = attribute.value;
          } else {
            const compendiumEntry = await ImportHelpers.findCompendiumEntityByImportId("Item", modifier.Key);
            if (compendiumEntry) {
              if (compendiumEntry?.type === "itemmodifier") {
                const descriptor = foundry.utils.duplicate(compendiumEntry);
                descriptor.id = foundry.utils.randomID();
                descriptor.system.rank = modifier?.Count ? parseInt(modifier.Count, 10) : 1;
                output.itemmodifier.push(descriptor);
                let rank = "";
                if (descriptor.system.rank > 1) {
                  rank = `${game.i18n.localize("SWFFG.Count")} ${descriptor.system.rank}`;
                }
                output.description += `<div>${descriptor.name} - ${descriptor.system.description} ${rank}</div>`;
              }
            } else if (Object.keys(CONFIG.temporary.skills).includes(modifier.Key)) {
              // this is a skill upgrade
              const skillModifier = ImportHelpers.processSkillMod(modifier);
              if (skillModifier) {
                output.attributes[skillModifier.type] = skillModifier.value;
              }
            } else {
              CONFIG.logger.warn(`${modifier.Key} not found`);
            }
          }
        } else if (modifier.DieModifiers) {
          // this is a die modifier
          const dieModifiers = await ImportHelpers.processDieMod(modifier.DieModifiers);
          output.attributes = foundry.utils.mergeObject(output.attributes, dieModifiers.attributes);
        } else {
          unique_mods++;
          // this is just a text modifier
          const unique = {
            name: `Unique Mod ${unique_mods}`,
            type: "itemmodifier",
            system: {
              description: modifier.MiscDesc,
              attributes: {},
              type: "all",
              rank: modifier?.Count ? parseInt(modifier.Count, 10) : null,
            },
          };
          const descriptor = await new Item(unique, { temporary: true });
          let rank = "";
          if (unique.system.rank > 1) {
            rank = `${game.i18n.localize("SWFFG.Count")} ${unique.system.rank}`;
          }

          output.description += `<div>${unique.system.description} ${rank}</div>`;
          output.itemmodifier.push(descriptor);
        }
      });
    }
    return output;
  }

  static async processMods(obj) {
    let output = {};

    if (obj?.BaseMods?.Mod) {
      output.baseMods = await ImportHelpers.processModsData(obj.BaseMods);
    }

    if (obj?.AddedMods?.Mod) {
      output.addedMods = await ImportHelpers.processModsData(obj.AddedMods);
    }

    if (obj?.Qualities?.Quality) {
      output.qualities = await ImportHelpers.processModsData(obj.Qualities);
    }

    return output;
  }

  static async processDiceMods(obj) {
    const nk = new Date().getTime();
    if (obj.Key === "BOOSTADD" || obj.Key === "ACCURATE") {
      return {
        [`attr${nk}`]: {
          modtype: "Roll Modifiers",
          mod: "Add Boost",
          value: '1',
        }
      };
    } else if (obj.Key === "INACCURATE" || obj.Key === "SETBACKADD") {
      return {
        [`attr${nk}`]: {
          modtype: "Roll Modifiers",
          mod: "Add Setback",
          value: '1',
        }
      };
    } else if (obj.Key === "SUCCADD") {
      return {
        [`attr${nk}`]: {
          modtype: "Result Modifiers",
          mod: "Add Success",
          value: '1',
        }
      };
    } else if (obj.Key === "THRADD") {
      return {
        [`attr${nk}`]: {
          modtype: "Result Modifiers",
          mod: "Add Threat",
          value: '1',
        }
      };
    } else if (obj.Key === "UPGRADEDIFF") {
      return {
        [`attr${nk}`]: {
          modtype: "Dice Modifiers",
          mod: "Upgrade Difficulty",
          value: '1',
        }
      };
    }
    return false;
  }

  static async processStatMod(mod) {
    let attributes = {};
    if (mod) {
      for (const m of Object.keys(mod)) {
        const value = parseInt(mod[m], 10);
        const modtype = "Stat";
        let type;
        switch (m) {
          case "SoakValue": {
            type = "Soak";
            break;
          }
          case "ForceRating": {
            type = "ForcePool";
            break;
          }
          case "StrainThreshold": {
            type = "Strain";
            break;
          }
          case "DefenseRanged": {
            type = "Defence-Ranged";
            break;
          }
          case "DefenseMelee": {
            type = "Defence-Melee";
            break;
          }
          case "WoundThreshold": {
            type = "Wounds";
            break;
          }
        }

        const key = `attr${new Date().getTime()}`;
        if (type) {
          attributes[key] = { mod: type, modtype, value };
        }
        // ensure further keys have a new entry
        await new Promise(r => setTimeout(r, 1));
      }
    }

    return attributes;
  }

  static async processCareerSkills(skills, includeRank) {
    let attributes = {};
    if (skills?.Key) {
      if (!Array.isArray(skills.Key)) {
        skills.Key = [skills.Key];
      }

      for (const skill of skills.Key) {
        let mod = CONFIG.temporary.skills[skill];
        if (mod) {
          if (mod.includes(":") && !mod.includes(": ")) {
            mod = mod.replace(":", ": ");
          }

          if (Object.keys(CONFIG.FFG.skills).includes(mod)) {
            const key = `attr${new Date().getTime()}`;
            // ensure further keys have a new entry
            await new Promise(r => setTimeout(r, 1));
            if (mod) {
              const modtype = "Career Skill";
              attributes[key] = { mod, modtype, value: true };

              if (includeRank) {
                attributes[key] = { mod, modtype: "Skill Rank", value: 0 };
              }
            } else {
              CONFIG.logger.warn(`Skill ${skill} was not found in the current skills list.`);
            }
          }
        } else {
          CONFIG.logger.warn(`Skill ${skill} was not found in the current skills list.`);
        }
      }
    }

    return attributes;
  }

  static async getTemplate(type) {
    const response = await fetch("systems/starwarsffg/template.json");
    const template = await response.json();

    const obj = Object.values(template).find((i) => i.types.includes(type));

    let item = obj[type];

    if (item.templates) {
      item.templates.forEach((i) => {
        item = foundry.utils.mergeObject(item, obj.templates[i]);
      });
      delete item.templates;
    }

    return item;
  }

  static async createActiveEffects(item) {
    if (["species", "gear", "weapon", "armour", "shipattachment"].includes(item.type)) {
      const existingEffects = item.getEmbeddedCollection("ActiveEffect");
      // items are "created" when they are pulled from Compendiums, so don't duplicate Active Effects
      const inherentEffect = existingEffects.find(i => i.name === `(inherent)`);
      if (!inherentEffect) {
        CONFIG.logger.debug(`Creating inherent Active Effect for item ${item.name}`);
        const effects = {
          name: `(inherent)`,
          img: item.img,
          changes: [],
        };
        if (item.type === "species") {
          for (const attribute of Object.keys(item.system.attributes)) {
            const explodedMods = ModifierHelpers.explodeMod(
              item.system.attributes[attribute].modtype,
              attribute
            );
            for (const cur_mod of explodedMods) {
              const path = ModifierHelpers.getModKeyPath(
                cur_mod['modType'],
                cur_mod['mod']
              );
              effects.changes.push({
                key: path,
                mode: AE_MODES.ADD,
                value: item.system.attributes[attribute].value,
              });
            }
          }
        } else if (["gear", "weapon"].includes(item.type)) {
          const explodedMods = ModifierHelpers.explodeMod(
            "Stat",
            "Encumbrance"
          );
          for (const cur_mod of explodedMods) {
            const path = ModifierHelpers.getModKeyPath(
              cur_mod['modType'],
              cur_mod['mod']
            );
            effects.changes.push({
              key: path,
              mode: AE_MODES.ADD,
              value: 0,
            });
          }
        } else if (item.type === "armour") {
          for (const key of ["Encumbrance", "Defence", "Soak"]) {
            const explodedMods = ModifierHelpers.explodeMod(
              "Stat",
              key
            );
            for (const cur_mod of explodedMods) {
              const path = ModifierHelpers.getModKeyPath(
                cur_mod['modType'],
                cur_mod['mod']
              );
              effects.changes.push({
                key: path,
                mode: AE_MODES.ADD,
                value: 0,
              });
            }
          }
        } else if (item.type === "shipattachment") {
          const explodedMods = ModifierHelpers.explodeMod(
            "Vehicle Stat",
            "Vehicle.Hardpoints"
          );
          for (const cur_mod of explodedMods) {
            const path = ModifierHelpers.getModKeyPath(
              cur_mod['modType'],
              cur_mod['mod']
            );
            effects.changes.push({
              key: path,
              mode: AE_MODES.ADD,
              value: 0,
            });
          }
        }

        CONFIG.logger.debug(`Creating Active Effect for ${item.name}/${item.type} on item creation`);
        CONFIG.logger.debug(effects);
        await item.createEmbeddedDocuments("ActiveEffect", [effects]);
      }
    }
  }

  /**
   * Given an updateObject event, update active effects on the item being updated
   * This is an importer helper so that it can operate on .system (used during import) instead of .data (used in forms)
   * @type {*|{}}
  */
  static async applyActiveEffectOnUpdate(item, formData) {
    CONFIG.logger.debug("Updating active effects on item import");
    const existing = item.getEmbeddedCollection("ActiveEffect");
    const toDelete = [];
    const toUpdate = [];
    const toCreate = [];

    // first update anything inherent to the item type (such as "brawn" on "species")
    const inherentEffectName = "(inherent)";
    const inherentEffect = existing.find(e => e.name === inherentEffectName);
    if (inherentEffect && Object.keys(formData.system).includes("attributes")) {
      for (let k of Object.keys(formData.system.attributes)) {
        if (k.startsWith("attr")) {
          // inherent effects like "brawn" on "species" only - skip user-created active effects only
          continue;
        }

        const explodedMods = ModifierHelpers.explodeMod(
          formData.system.attributes[k].modtype,
          formData.system.attributes[k].mod
        );

        for (const curMod of explodedMods) {
          let modPath = ModifierHelpers.getModKeyPath(curMod['modType'], curMod['mod']);
          const inherentEffectChangeIndex = inherentEffect.changes.findIndex(c => c.key === modPath);
          if (inherentEffectChangeIndex >= 0) {
            if (modPath === "system.stats.wounds.max" && item.type === "species") {
              inherentEffect.changes[inherentEffectChangeIndex].value = parseInt(inherentEffect.changes[inherentEffectChangeIndex].value) + parseInt(item.system.attributes.Brawn.value);
            } else if (modPath === "system.stats.strain.max" && item.type === "species") {
              inherentEffect.changes[inherentEffectChangeIndex].value = parseInt(inherentEffect.changes[inherentEffectChangeIndex].value) + parseInt(item.system.attributes.Willpower.value);
            } else if (modPath === "system.stats.encumbrance.max" && item.type === "species") {
              inherentEffect.changes[inherentEffectChangeIndex].value = parseInt(inherentEffect.changes[inherentEffectChangeIndex].value) + 5;
            } else {
              inherentEffect.changes[inherentEffectChangeIndex].value = formData.system.attributes[k].value;
            }
          }
        }
      }
      await inherentEffect.update({changes: inherentEffect.changes});
    }
    // some inherent effects are not in the `attribute` keyspace; make sure to get them as well
    if (inherentEffect && ["gear", "weapon", "armour"].includes(item.type)) {
      const explodedMods = ModifierHelpers.explodeMod(
        "Stat",
        "Encumbrance",
      );

      for (const curMod of explodedMods) {
        let modPath = ModifierHelpers.getModKeyPath(
          curMod['modType'],
          curMod['mod'],
        );
        const inherentEffectChangeIndex = inherentEffect.changes.findIndex(c => c.key === modPath);
        if (inherentEffectChangeIndex >= 0) {
          inherentEffect.changes[inherentEffectChangeIndex].value = formData.system.encumbrance.value;
        }
      }

      if (item.type === "armour") {
        // armor has additional stats
        let explodedMods = ModifierHelpers.explodeMod(
          "Stat",
          "Defence",
        );
        for (const curMod of explodedMods) {
          let modPath = ModifierHelpers.getModKeyPath(
            curMod['modType'],
            curMod['mod'],
          );
          const inherentEffectChangeIndex = inherentEffect.changes.findIndex(c => c.key === modPath);
          if (inherentEffectChangeIndex >= 0) {
            inherentEffect.changes[inherentEffectChangeIndex].value = formData.system.defence.value;
          }
        }

        explodedMods = ModifierHelpers.explodeMod(
          "Stat",
          "Soak",
        );
        for (const curMod of explodedMods) {
          let modPath = ModifierHelpers.getModKeyPath(
            curMod['modType'],
            curMod['mod'],
          );
          const inherentEffectChangeIndex = inherentEffect.changes.findIndex(c => c.key === modPath);
          if (inherentEffectChangeIndex >= 0) {
            inherentEffect.changes[inherentEffectChangeIndex].value = formData.system.soak.value;
          }
        }
      }
      await inherentEffect.update({changes: inherentEffect.changes});
    }

    // iterate over formdata attributes to add/update them if they were added
    if (formData.system?.attributes) {
      for (let k of Object.keys(formData.system.attributes)) {
        const match = existing.find(i => i.name === k);
        const explodedMods = ModifierHelpers.explodeMod(
          formData.system.attributes[k].modtype,
          formData.system.attributes[k].mod
        );

        const changes = [];
        for (const curMod of explodedMods) {
          changes.push({
            key: ModifierHelpers.getModKeyPath(curMod['modType'], curMod['mod']),
            mode: AE_MODES.ADD,
            value: formData.system.attributes[k].value,
          });
        }

        if (match) {
          // existing entry
          CONFIG.logger.debug(`>>>> Staged AE changes for update: ${JSON.stringify(changes)}`);
          await match.update({
            changes: changes,
          });
        } else if (k.startsWith("attr")) {
          // new entry
          const effect = {
            name: k,
            icon: item.img,
            changes: changes,
          };
          CONFIG.logger.debug(`>>>> Staged AE for creation: ${JSON.stringify(effect)}`);
          toCreate.push(effect);
        }
      }
    }

    // careers and specializations are created with the template, then populated with the data passed in
    // check for careerSkills being set and update them
    if (item.type === "career" && inherentEffect) {
      const changes = [];
      for (let i = 0; i < 8; i++) {
        let path;
        const skill = item.system.careerSkills[`careerSkill${i}`];
        if (skill !== "(none)") {
          path = `system.skills.${skill}.careerskill`;
        } else {
          path = "(none)";
        }
        changes.push({
          key: path,
          mode: AE_MODES.ADD,
          value: true,
        });
      }
      await inherentEffect.update({changes: changes});
    } else if (item.type === "specialization" && inherentEffect) {
      const changes = [];
      for (let i = 0; i < 5; i++) {
        let path;
        const skill = item.system.careerSkills[`careerSkill${i}`];
        if (skill !== "(none)") {
          path = `system.skills.${skill}.careerskill`;
        } else {
          path = "(none)";
        }
        changes.push({
          key: path,
          mode: AE_MODES.ADD,
          value: true,
        });
      }
      await inherentEffect.update({changes: changes});
    }

    if (toCreate.length) {
      await item.createEmbeddedDocuments("ActiveEffect", toCreate);
    }

    if (toDelete.length) {
      await item.deleteEmbeddedDocuments("ActiveEffect", toDelete);
    }

    CONFIG.logger.debug("applyActiveEffectOnUpdate", toCreate, toUpdate, toDelete);
  }

  /**
   * Create active effects on specializations during import
   * This is required because embedded items like talents normally get their AEs created from the embedded item editor,
   * which is not in use during import.
   * @param specialization - specialization with talents on it to create AEs for
   * @returns {Promise<void>}
   */
  static async applyTalentActiveEffects(specialization) {
    if (specialization.type !== "specialization") {
      return;
    }
    CONFIG.logger.debug(`Transferring Active Effects from talents for specialization ${specialization.name}`);
    const toCreate = [];
    // iterate over talents, find attributes on them, and create active effects
    for (const talentId of Object.keys(specialization.system.talents)) {
      const talent = specialization.system.talents[talentId];
      if (Object.keys(talent).includes("attributes")) {
        for (const attributeName of Object.keys(talent.attributes)) {
          const attribute = talent.attributes[attributeName];
          const explodedMods = ModifierHelpers.explodeMod(
            attribute.modtype,
            attribute.mod
          );

          const changes = [];
          for (const curMod of explodedMods) {
            const changeKey = ModifierHelpers.getModKeyPath(curMod['modType'], curMod['mod']);
            // only create an active effect if the mod is a type requiring one (e.g., weapon stats don't)
            if (changeKey) {
              changes.push({
                key: changeKey,
                mode: AE_MODES.ADD,
                value: attribute.value,
              });
            }
          }

          if (changes.length) {
            toCreate.push({
              name: attributeName,
              img: talent.img,
              changes: changes,
              disabled: true,
            });
          }
        }
      }
    }
    CONFIG.logger.debug(toCreate);
    if (toCreate.length) {
      await specialization.createEmbeddedDocuments("ActiveEffect", toCreate);
    }
  }
}

/*
  Rather than update the functions to reflect v10, simply modify the resulting data structure to reflect the expected
    format
 */
function prep_for_v10(actor) {
  actor.system = actor.data;
  // iterate over items so we can iterate over their modifiers
  actor.items.forEach(function (item) {
    if (item.system.hasOwnProperty('itemmodifier')) {
      item.system?.itemmodifier.forEach(function (modifier) {
        if (modifier) { // handle null modifiers (often from bad input)
          modifier.system = modifier.data;
        }
      });
    }
  });
  return actor;
}

