            if (item?.DieModifiers) {
              const dieModifiers = await ImportHelpers.processDieMod(item.DieModifiers);
              data.data.attributes = foundry.utils.mergeObject(data.data.attributes, dieModifiers.attributes);
            }

            // populate tags
