                }

                if (item.skills) {
                  let isMinion = Array.isArray(item.skills);
                  let adversarySkills = isMinion ? item.skills : Object.keys(item.skills);
                  adversarySkills.forEach((skillRaw) => {
                    let skill = skillRaw.match(/^[^\(]*/)[0];
                    skill = $.trim(skill);
                    let alternateCharacteristic = skillRaw.match(/(?<=\()(.*?)(?=\))/)?.length ? skillRaw.match(/(?<=\()(.*?)(?=\))/)[0] : undefined;

                    const ffgSkill = Object.keys(skills).find((s) => skill.toLowerCase() === s.toLowerCase());

                    if (ffgSkill) {
                      adversary.system.skills[ffgSkill].groupskill = isMinion ? true : false;
                      if (!isMinion) {
                        adversary.system.attributes[skill] = {
                          key: skill,
                          mod: skill,
                          modType: 'Skill Rank',
                          value: item.skills[skill],
                        };
                        adversary.system.skills[ffgSkill].rank = item.skills[skill];
                      }
                      if (CONFIG.temporary.swa.skills?.[skill]?.characteristic) {
                        if (alternateCharacteristic) {
                          adversary.system.skills[ffgSkill].characteristic = alternateCharacteristic;
                        } else {
                          adversary.system.skills[ffgSkill].characteristic = CONFIG.temporary.swa.skills[skill].characteristic;
                        }
                      }

                      if ((!adversary.system.skills[ffgSkill]?.type && skilltheme !== "starwars") || (skilltheme === "starwars" && !CONFIG.FFG.skills[ffgSkill])) {
                        adversary.system.skills[ffgSkill].Key = ffgSkill.toUpperCase();
                        adversary.system.skills[ffgSkill].custom = true;
                        adversary.system.skills[ffgSkill].type = "General";
                        adversary.system.skills[ffgSkill].label = ffgSkill;
                      }
                    }
                  });
                }

                if (item.talents) {
                  item.talents.forEach((talent) => {
                    if (typeof talent === "object") {
                      let adversaryTalent = {
                        name: talent.name,
                        type: "talent",
                        flags: {},
                        system: {
                          attributes: {},
                          description: talent.description,
                          activation: {
                            value: "Passive",
                          },
                          ranks: {
                            ranked: false,
                          },
                        },
                      };

                      adversary.items.push(adversaryTalent);
                    } else {
                      const swaTalentKey = Object.keys(CONFIG.temporary.swa.talents).find((t) => talent.substr(0, talent.lastIndexOf(' ')) === t);

                      if (swaTalentKey) {
                        const swaTalent = CONFIG.temporary.swa.talents[swaTalentKey];
                        let rank = 0;
                        if (swaTalent.ranked) {
                          if (talent.replace(swaTalentKey, "").length > 0) {
                            rank = parseInt(talent.replace(swaTalentKey, ""), 10);
                          }
                        }

                        let adversaryTalent = {
                          name: swaTalent.name,
                          type: "talent",
                          flags: {},
                          system: {
                            attributes: {},
                            description: swaTalent.description,
                            ranks: {
                              current: rank,
                              ranked: swaTalent.ranked,
                            },
                            activation: {
                              value: "Passive",
                            },
                            isForceTalent: false,
                          },
                        };

                        adversary.items.push(adversaryTalent);
                      }
                    }
                  });
                }

                if (item.weapons) {
                  const template = await ImportHelpers.getTemplate("weapon");
                  item.weapons.forEach((weapon) => {
                    let data = JSON.parse(JSON.stringify(template));
                    let weaponData;

                    if (typeof weapon === "object") {
                      weaponData = {
                        name: weapon.name,
                        type: "weapon",
                        flags: {},
                        system: {
                          attributes: {},
                          description: "No description provided",
                          damage: {
                            value: parseInt(!weapon?.damage ? weapon["plus-damage"] : weapon.damage, 10),
                          },
                          crit: {
                            value: parseInt(weapon.critical, 10),
                          },
                          special: {
                            value: weapon?.qualities?.length ? weapon.qualities.join(",") : "",
                          },
                          skill: {
                            value: weapon.skill,
                          },
                          range: {
                            value: weapon.range,
                          },
                        },
                      };
                      weaponData.system.skill.useBrawn = ["Melee", "Brawl", "Lightsaber"].some((element) => weaponData.system.skill.value.includes(element)) && (!weapon.damage || weapon.damage === "0");
                      if (weapon?.["plus-damage"] && parseInt(weapon["plus-damage"], 10) > 0) {
                        weaponData.system.attributes[foundry.utils.randomID()] = {
                          isCheckbox: false,
                          mod: "damage",
                          modtype: "Weapon Stat",
                          value: parseInt(weapon["plus-damage"], 10),
                        };
                      }
                    } else {
                      const swaWeaponKey = Object.keys(CONFIG.temporary.swa.weapons).find((t) => weapon.includes(t));

                      if (swaWeaponKey) {
                        const swaWeapon = CONFIG.temporary.swa.weapons[swaWeaponKey];
                        weaponData = {
                          name: swaWeapon.name,
                          type: "weapon",
                          flags: {},
                          system: {
                            attributes: {},
                            description: "No description provided",
                            damage: {
                              value: parseInt(!swaWeapon?.damage ? swaWeapon["plus-damage"] : swaWeapon.damage, 10),
                            },
                            crit: {
                              value: parseInt(swaWeapon.critical, 10),
                            },
                            special: {
                              value: swaWeapon?.qualities?.length ? swaWeapon.qualities.join(",") : "",
                            },
                            skill: {
                              value: swaWeapon.skill,
                            },
                            range: {
                              value: swaWeapon.range,
                            },
                          },
                        };

                        weaponData.system.skill.useBrawn = ["Melee", "Brawl", "Lightsaber"].some((element) => weaponData.system.skill.value.includes(element)) && (!swaWeapon.damage || swaWeapon.damage === "0");

                        if (swaWeapon?.["plus-damage"] && parseInt(swaWeapon["plus-damage"], 10) > 0) {
                          weaponData.system.attributes[foundry.utils.randomID()] = {
                            isCheckbox: false,
                            mod: "damage",
                            modtype: "Weapon Stat",
                            value: parseInt(swaWeapon["plus-damage"], 10),
                          };
                        }
                      }
                    }

                    if (weaponData) {
                      const templatedData = weaponData;
                      templatedData.system = foundry.utils.mergeObject(data, weaponData.system);

                      if (templatedData.system.special?.value?.length > 0) {
                        templatedData.system.special.value.split(",").forEach((w) => {
                          const wName = w.match(/^.*([^0-9\s]+)/gim);
                          const wRank = w.match(/[^\w][0-9]/gim);

                          const id = foundry.utils.randomID();
                          const unique = {
                            name: wName[0],
                            id: id,
                            _id: id,
                            type: "itemmodifier",
                            flags: {},
                            system: {
                              description: CONFIG.temporary.swa?.qualities?.[wName]?.description ? CONFIG.temporary.swa.qualities[wName].description : "No description provided",
                              attributes: {},
                              type: "all",
                              rank: wRank ? parseInt(wRank[0].replace(" ", ""), 10) : 1,
                            },
                          };
                          const descriptor = new CONFIG.Item.documentClass(unique, { temporary: true });
                          templatedData.system.itemmodifier.push(descriptor);
                        });
                      }

                      let w = new CONFIG.Item.documentClass(templatedData, { temporary: true });
                      adversary.items.push(foundry.utils.duplicate(w));
                    }
                  });
                }

                if (item.gear) {
                  if (Array.isArray(item.gear)) {
                    item.gear.forEach((gear) => {
                      if (gear.includes("Soak") && gear.includes("Defence")) {
                        let Armordata = {
                          name: gear.slice(0, gear.indexOf("(") - 1).trim(),
                          type: "armour",
                          flags: {},
                          system: {
                            description: "No description provided",
                            defence: {
                              value: gear.charAt(gear.indexOf("Defence") - 2),
                            },
                            soak: {
                              value: gear.charAt(gear.indexOf("Soak") - 2),
                            },
                          },
                        };
                        adversary.items.push(Armordata);
                      } else if (gear.includes("Soak")) {
                        let Armordata = {
                          name: gear.slice(0, gear.indexOf("(") - 1).trim(),
                          type: "armour",
                          flags: {},
                          system: {
                            description: "No description provided",

                            soak: {
                              value: gear.charAt(gear.indexOf("Soak") - 2),
                            },
                          },
                        };
                        adversary.items.push(Armordata);
                      } else if (gear.includes("Defence")) {
                        let Armordata = {
                          name: gear.slice(0, gear.indexOf("(") - 1).trim(),
                          type: "armour",
                          flags: {},
                          system: {
                            description: "No description provided",
                            defence: {
                              value: gear.charAt(gear.indexOf("Defence") - 2),
                            },
                          },
                        };
                        adversary.items.push(Armordata);
                      } else {
                        let gearData = {
                          name: gear,
                          type: "gear",
                          flags: {},
                          system: {
                            description: "No description provided",
                          },
                        };
                        adversary.items.push(gearData);
                      }
                    });
                  } else if (item.gear.includes("Soak") && item.gear.includes("Defence")) {
                    let Armordata = {
                      name: item.gear.slice(0, item.gear.indexOf("(") - 1).trim(),
                      type: "armour",
                      flags: {},
                      system: {
                        description: "No description provided",
                        defence: {
                          value: item.gear.charAt(item.gear.indexOf("Defence") - 2),
                        },
                        soak: {
                          value: item.gear.charAt(item.gear.indexOf("Soak") - 2),
                        },
                      },
                    };
                    adversary.items.push(Armordata);
                  } else if (item.gear.includes("Soak")) {
                    let Armordata = {
                      name: item.gear.slice(0, item.gear.indexOf("(") - 1).trim(),
                      type: "armour",
                      flags: {},
                      system: {
                        description: "No description provided",

                        soak: {
                          value: item.gear.charAt(item.gear.indexOf("Soak") - 2),
                        },
                      },
                    };
                    adversary.items.push(Armordata);
                  } else if (item.gear.includes("Defence")) {
                    let Armordata = {
                      name: item.gear.slice(0, item.gear.indexOf("(") - 1).trim(),
                      type: "armour",
                      flags: {},
                      system: {
                        description: "No description provided",
                        defence: {
                          value: item.gear.charAt(item.gear.indexOf("Defence") - 2),
                        },
                      },
                    };
                    adversary.items.push(Armordata);
                  } else {
                    let gearData = {
                      name: item.gear,
                      type: "gear",
                      flags: {},
                      system: {
                        description: "No description provided",
                      },
                    };
                    adversary.items.push(gearData);
                  }
                }

                let biography = "";

                if (item.description) {
                  biography += `<p>${item.description}</p>`;
                }

                if (item.abilities) {
                  for (const ability of item.abilities) {
                    if (typeof ability === "object") {
                      adversary.items.push({
                        name: ability.name,
                        type: "ability",
                        system: {
                          description: ability.description,
                        },
                      });
                    } else {
                      const swaAbilityKey = Object.keys(CONFIG.temporary.swa.abilities).find((t) => ability.includes(t));
                      if (swaAbilityKey) {
                        const swaAbility = CONFIG.temporary.swa.abilities[swaAbilityKey];
                        adversary.items.push({
                          name: swaAbility.name,
                          type: "ability",
                          system: {
                            description: swaAbility.description,
                          },
                        });
                      }
                    }
                  }
                }

                adversary.system.biography = biography;

                let compendiumItem;
                await pack.getIndex();
                let entry = pack.index.find((e) => e.name === item.name);

                if (!entry) {
                  CONFIG.logger.debug(`Importing Adversary - Actor`);
                  compendiumItem = new CONFIG.Actor.documentClass(adversary, { temporary: true });
                  this._importLogger(`New Adversary ${name} : ${JSON.stringify(compendiumItem)}`);
                  const created = await pack.importDocument(compendiumItem);
                  // trigger active effect creation
                  for (const item of created.items) {
                    await ImportHelpers.createActiveEffects(item);
                    // this line can be uncommented to cause the active effects to have the correct values.
                    // on the other hand, this will mess up stats for the actors
                    // (whose values have it taken into account already)
                    // and those values can be updated by modifying the data at all. so, I think leave it off for now
                    //await ImportHelpers.applyActiveEffectOnUpdate(item, item.toJSON());
                  }
                } else {
                  CONFIG.logger.debug(`Update Adversary - Actor`);
                  //let updateData = ImportHelpers.buildUpdateData(item);
                  let updateData = adversary;
                  updateData["_id"] = entry._id;
                  this._importLogger(`Updating talent ${name} : ${JSON.stringify(updateData)}`);
                  let to_update = await pack.getDocument(updateData._id)
                  await to_update.update(updateData);
                  for (const item of to_update.items) {
                    await ImportHelpers.createActiveEffects(item);
                    // see above
                    //await ImportHelpers.applyActiveEffectOnUpdate(item, item.toJSON());
                  }
                }
              } catch (err) {
                CONFIG.logger.error(`Error importing ${item.name} from ${f.name}`, err);
              }

              currentCurrentTotal += 1;
              $(".current .import-progress-bar")
                .width(`${Math.trunc((currentCurrentTotal / currentTotalCount) * 100)}%`)
                .html(`<span>${Math.trunc((currentCurrentTotal / currentTotalCount) * 100)}%</span>`);
            });
          }
        } catch (err) {
          CONFIG.logger.error(`Unable to import ${f.name}`, err);
        }

        overallCurrentCount += 1;
        $(".overall .import-progress-bar")
          .width(`${Math.trunc((overallCurrentCount / overallTotalCount) * 100)}%`)
          .html(`<span>${Math.trunc((overallCurrentCount / overallTotalCount) * 100)}%</span>`);
      });
    }
    this._importLogger(`Completed Adversary Import`);
  }

  _importLog = [];
  _importLogger(message) {
    if ($(".debug input:checked").length > 0) {
      this._importLog.push(`[${new Date().getTime()}] ${message}`);
    }
  }

  _getFilePath(files, name, isDirectory) {
    try {
      this._importLogger(`Checking zip file for ${name}`);
      const filteredFiles = Object.values(files).filter(f => f.name.endsWith(`/${name}.json`) || (isDirectory && f.name.endsWith(`/${name}/`)))
      let file;
      if (filteredFiles.length === 1) {
        file = filteredFiles[0]
      }
      else if (filteredFiles.length > 1) {
        const srcFiles = filteredFiles.filter(f => f.name.includes('/src/'))
        if (srcFiles.length === 1)
          file = srcFiles[0]
        else
          throw new Error(`Found multiple files named ${name}.json with /src/ in the path.`)
      }
      else
        throw new Error(`Found no file named ${name}.json`)

      return file.name;
    }
    catch (e) {
      ui.notifications.error(`Failed to process data file ${name}.json! Import failed.`);
      console.error(e);
    }
  }

  async _getCompendiumPack(type, name) {
    this._importLogger(`Checking for existing compendium pack ${name}`);
    let pack = game.packs.find((p) => {
      return p.metadata.label === name;
    });
    if (!pack) {
      this._importLogger(`Compendium pack ${name} not found, creating new`);
      pack = await foundry.documents.collections.CompendiumCollection.createCompendium({ type: type, label: name });
    } else {
      this._importLogger(`Existing compendium pack ${name} found`);
    }

    return pack;
  }
}

/**
 * Codex II item sheets — an opt-in "Codex II Item Sheet" registered alongside
 * the stock item sheet. Reuses the `.cdx` CSS scope and the six scheme palettes
 * from the actor work; the scheme is a per-ITEM flag, falling back to the owning
 * actor's scheme, then republic.
 *
 * Scope: bespoke templates for weapon/armour/gear/talent, the three talent-tree
 * types (force power / specialization / signature ability — bespoke .cdx-ft-*
 * tree), plus ship weapon / item attachment / ship attachment; a generic Codex
 * frame (codex-item.html) covers the remaining simple types (ability, crit
 * injury/damage, obligation, motivation, background, homestead upgrade). The
 * remaining config types (career, species, item modifier) keep the stock sheet
 * and are NOT registered for this sheet.
 *
 * Tabs: the simple/detailed item templates keep native `.sheet-tabs` / `.sheet-body`
 * (restyled). The tree templates use a bespoke `.cdx-tabstrip` switched in JS
 * (see activateListeners), the same as the codex actor sheets.
 */
import { ItemSheetFFG } from "./item-sheet-ffg.js";
import { cdxDefaultScheme, cdxBuildNotchOutlines, cdxNormalizeScheme, cdxSchemeClasses, CDX_SCHEME_STRIP, cdxPickScheme } from "../actors/codex-sheets.js";

/** Types with a bespoke codex template; everything else uses codex-item.html.
 *  Only list a type once its `codex-<type>.html` actually exists — a missing
 *  file throws ENOENT when the sheet renders. (talent still pending.) */
const CODEX_DETAILED = new Set(["gear", "weapon", "armour", "talent", "forcepower", "specialization", "signatureability"]);

/** data.status values ↔ condition-track labels (None = Undamaged). */
const CODEX_STATUS = ["None", "Minor", "Moderate", "Major"];
const CODEX_STATUS_LABELS = ["Undamaged", "Minor", "Moderate", "Major"];

export class CodexItemSheet extends ItemSheetFFG {
  // Concatenated onto the base classes → the OUTER window <div> ends up
  // `…item v2 cdx`. `cdx` is our CSS scope.
  static DEFAULT_OPTIONS = {
    classes: ["cdx"],
  };

  /** Per-item palette: item flag → owning actor's flag → republic. */
  _cdxScheme() {
    const s = this.item?.getFlag?.("starwarsffg", "scheme")
      ?? this.item?.actor?.getFlag?.("starwarsffg", "scheme");
    return cdxNormalizeScheme(s) ?? cdxDefaultScheme();
  }

  /** Replace the legacy root classes with the palette class(es) (mirrors the
   *  actor mixin; Eldritch variants also carry the base `scheme-eldritch`) so
   *  mandar's structural item-form rules don't match us. The editable/locked
   *  classes are still applied by the base. @override */
  _getLegacyRootClasses(_context = {}) {
    return cdxSchemeClasses(this._cdxScheme());
  }

  /** Strip stale `scheme-*` before super re-adds the current one(s). @override */
  _applyLegacyRootClasses(form, context = {}) {
    for (const c of CDX_SCHEME_STRIP) form.classList.remove(c);
    super._applyLegacyRootClasses(form, context);
  }

  /** Bespoke template for the four detailed types; generic frame otherwise. @override */
  get template() {
    const base = "systems/starwarsffg/templates/items/codex";
    const type = this.item?.type;
    // Critical injury + critical damage share one template (same data model).
    if (type === "criticalinjury" || type === "criticaldamage") return `${base}/codex-crit.html`;
    if (type === "shipweapon") return `${base}/codex-shipweapon.html`;
    if (type === "itemattachment") return `${base}/codex-itemattachment.html`;
    if (type === "shipattachment") return `${base}/codex-shipattachment.html`;
    return CODEX_DETAILED.has(type) ? `${base}/codex-${type}.html` : `${base}/codex-item.html`;
  }

  /** @override — add the condition/status track model (weapon/armour). */
  async getData(options) {
    const ctx = await super.getData(options);
    // Localized item-type name for the header type pill (shared by every codex
    // item template via the general .cdx-ihead header).
    try { ctx.cdxTypeLabel = game.i18n.localize(`TYPES.Item.${this.item?.type}`); } catch (e) { ctx.cdxTypeLabel = ""; }
    // Tree types (force power / signature / specialization): edit is a TRANSIENT
    // per-session toggle (this._cdxEdit, default off), so the tree always opens
    // read-only regardless of any persisted system.isEditing. The bespoke edit
    // pencil flips _cdxEdit and re-renders (see activateListeners).
    if (["forcepower", "signatureability", "specialization"].includes(this.item?.type) && ctx.data) {
      ctx.data.isEditing = !!this._cdxEdit;
    }
    try {
      const cur = Math.max(0, CODEX_STATUS.indexOf(ctx?.data?.status ?? "None"));
      ctx.cdxConditions = CODEX_STATUS.map((value, i) => ({
        value,
        label: CODEX_STATUS_LABELS[i],
        current: i === cur,
        filled: i >= 1 && i <= cur, // Minor..current shade in as a progress track
      }));
    } catch (e) { ctx.cdxConditions = []; }
    return ctx;
  }

  /** Add a scheme picker to the window header controls. @override */
  _getHeaderControls() {
    const controls = super._getHeaderControls();
    controls.push({ action: "cdxScheme", icon: "fa-solid fa-palette", label: "Scheme", onClick: () => this._cdxPickScheme() });
    return controls;
  }

  /** Categorised DialogV2 palette picker; writes the item flag. */
  async _cdxPickScheme() {
    const choice = await cdxPickScheme(this._cdxScheme(), this.item?.name ?? "item");
    if (choice) await this.item.setFlag("starwarsffg", "scheme", choice);
  }

  /** @override — keep every stock listener; make the form the scroll container
   *  (mandar forces overflow:visible !important on it) and wire the inline rarity
   *  "(R)" Restricted toggle. */
  activateListeners(html) {
    super.activateListeners(html);
    const form = this.form;
    if (form) {
      form.style.setProperty("overflow-y", "auto", "important");
      form.style.setProperty("overflow-x", "hidden", "important");
    }
    const root = html?.[0] ?? form;

    // Tree edit pencil: flip the transient edit flag and re-render (read-only <->
    // edit). NOT the persisted stock data.isEditing path.
    root?.querySelector?.(".cdx-ft-edit-toggle")?.addEventListener("click", (ev) => {
      ev.preventDefault();
      this._cdxEdit = !this._cdxEdit;
      this.render({ force: true });
    });

    // Bespoke tab switching — same as the codex actor sheets (.cdx-tab buttons /
    // .cdx-pane sections, toggled in JS). The stock native Tabs controller keyed
    // off .sheet-tabs doesn't apply here: we use .cdx-tabstrip so the item tabs
    // match the character sheet. Remember the active tab across re-renders (e.g.
    // a scheme change re-renders the whole sheet).
    if (root) {
      root.querySelectorAll(".cdx-tab").forEach((btn) => {
        btn.addEventListener("click", (ev) => {
          ev.preventDefault();
          const tab = ev.currentTarget.dataset.tab;
          if (!tab) return;
          root.querySelectorAll(".cdx-tab").forEach((t) => t.classList.toggle("active", t.dataset.tab === tab));
          root.querySelectorAll(".cdx-pane").forEach((p) => p.classList.toggle("active", p.dataset.tab === tab));
          this._cdxTab = tab;
        });
      });
      if (this._cdxTab && root.querySelector(`.cdx-tab[data-tab="${this._cdxTab}"]`)) {
        root.querySelectorAll(".cdx-tab").forEach((t) => t.classList.toggle("active", t.dataset.tab === this._cdxTab));
        root.querySelectorAll(".cdx-pane").forEach((p) => p.classList.toggle("active", p.dataset.tab === this._cdxTab));
      }
    }

    // Live header subtitle "{skill} - {characteristic}" (weapon Special tab). The
    // selects submit render:false, so reflect the choice into the header without
    // waiting for a re-render.
    const sub = root?.querySelector?.(".cdx-isub");
    if (sub) {
      const skillSel = root.querySelector('select[name="data.skill.value"]');
      const charSel = root.querySelector('select[name="data.characteristic.value"]');
      const none = game.i18n?.localize?.("SWFFG.None");
      const optText = (sel) => (sel && sel.selectedIndex >= 0 ? (sel.options[sel.selectedIndex]?.text ?? "") : "").trim();
      const sync = () => {
        const parts = [optText(skillSel), optText(charSel)].filter((p) => p && p !== none);
        sub.textContent = parts.join(" - ");
        sub.style.display = parts.length ? "" : "none";
      };
      skillSel?.addEventListener("change", sync);
      charSel?.addEventListener("change", sync);
      // An owned weapon folds the wielder's characteristic into damage.adjusted
      // (Brawn-based weapons), and the skill gates whether that applies. The
      // generic change pipeline submits render:false, so a characteristic/skill
      // change wouldn't refresh the adjusted badges — request an explicit
      // re-render (coalesces with the pipeline's own submit), mirroring the
      // base sheet's cross-field reactivity for "ranked"/"islearned".
      const reRender = async (ev) => { await this._onSubmit(ev, { render: true }); };
      skillSel?.addEventListener("change", reRender);
      charSel?.addEventListener("change", reRender);
    }

    root?.querySelectorAll?.(".cdx-restrict-btn").forEach((btn) => {
      btn.addEventListener("click", async (ev) => {
        ev.preventDefault();
        if (!this.isEditable) return;
        await this.item.update({ "system.rarity.isrestricted": !this.item.system?.rarity?.isrestricted });
      });
    });
    // Price — same comma rules as actor credits. The field is NOT Foundry-bound
    // (no name=), so the comma'd display string can never round-trip into the
    // stored Number when a neighbouring field triggers a submit. Show commas at
    // rest, raw digits while editing, reformat + persist the integer on commit.
    const fmt = (v) => (parseInt(String(v).replace(/[^\d]/g, ""), 10) || 0).toLocaleString("en-US");
    const curPrice = () => parseInt(String(this.item?.system?.price?.value ?? "0").replace(/[^\d]/g, ""), 10) || 0;
    root?.querySelectorAll?.("input.cdx-price").forEach((field) => {
      field.value = fmt(curPrice());
      field.addEventListener("focus", () => { field.value = String(curPrice()); setTimeout(() => field.select(), 0); });
      field.addEventListener("input", () => {
        const caret = field.selectionStart;
        const stripped = field.value.replace(/[^\d]/g, "");
        if (stripped !== field.value) { field.value = stripped; try { field.setSelectionRange(caret - 1, caret - 1); } catch (e) {} }
      });
      field.addEventListener("keydown", (ev) => {
        if (ev.key === "Enter") { ev.preventDefault(); field.blur(); }
        else if (ev.key === "Escape") { ev.preventDefault(); field.value = String(curPrice()); field.blur(); }
      });
      field.addEventListener("blur", async () => {
        const n = parseInt(field.value.replace(/[^\d]/g, ""), 10) || 0;
        field.value = fmt(n);
        if (this.isEditable && n !== curPrice()) { try { await this.item.update({ "system.price.value": n }); } catch (e) {} }
      });
    });
    // Digits-only fields (Damage/Crit/Encum/HP/Rarity/Qty/Soak/Defence):
    // strip any non-digit on input so the field can only ever hold an integer.
    root?.querySelectorAll?.("input.cdx-num").forEach((inp) => {
      inp.setAttribute("inputmode", "numeric");
      inp.addEventListener("input", () => {
        const cleaned = inp.value.replace(/[^0-9]/g, "");
        if (cleaned !== inp.value) {
          const pos = inp.selectionStart;
          inp.value = cleaned;
          try { inp.setSelectionRange(pos - 1, pos - 1); } catch (e) {}
        }
      });
      inp.addEventListener("keypress", (ev) => {
        if (ev.key.length === 1 && !/[0-9]/.test(ev.key)) ev.preventDefault();
      });
    });

    // Notched-block outlines — same SVG overlay the actor sheets use, covering
    // the item-sheet diamond blocks (item header, pills, stat boxes, checks,
    // force-power rows, vehicle rarity). See cdxBuildNotchOutlines.
    if (root) cdxBuildNotchOutlines(this, root);
  }

  /** @override — drop the notch-outline ResizeObserver when the sheet closes. */
  async close(options = {}) {
    this._cdxNotchRO?.disconnect();
    this._cdxNotchRO = null;
    return super.close(options);
  }
}

import { AE_MODES } from "../config/ffg-active-effect-modes.js";
import ItemHelpers from "../helpers/item-helpers.js";
import ModifierHelpers from "../helpers/modifiers.js";
import { FFGFormApplication } from "../apps/ffg-form-application.js";
import { cdxNormalizeScheme, cdxSchemeClasses } from "../actors/codex-sheets.js";

export class itemEditor extends FFGFormApplication {
  /*
  Known issues:
    - The title of the editor doesn't get updated when you update the name
    - Modification descriptions are rendered in an input field, not a rich text editor. I can't figure out how to get them to work in RTEs
    - Qualities added from an attachment do not get totaled if they are also already present on the weapon (e.g. a weapon with Pierce 2 and an attachment which adds Pierce 1)
  */
  constructor(data) {
    super();
    this.data = data;
    // Inline {{editor}} state, keyed by field name. FormDataExtended reads live
    // ProseMirror content from these on submit (see _getSubmitData).
    this.editors = {};
    // appId mirrors the V1 field some handlers still reference.
    this.appId = this.id;
    // The header title is dynamic (current + parent item). Set it up front so
    // it is available before the frame header renders; _prepareContext refreshes
    // it on re-render.
    this._title = game.i18n.format("SWFFG.Items.Popout.Title", {
      currentItem: data.clickedObject.name,
      parentItem: data.sourceObject.name,
    });
    // Codex skin — applied ONLY when the host item's resolved sheet is the Codex
    // item sheet (so a stock-sheet weapon keeps the stock embedded editor). The
    // Codex class is read from CONFIG.FFG.codexSheets (set at registration) to
    // avoid importing the sheet module here. Scheme follows the host item/actor.
    try {
      const codexCls = CONFIG.FFG?.codexSheets?.item?.cls;
      this._cdx = !!(codexCls && data.sourceObject?._getSheetClass?.() === codexCls);
      if (this._cdx) {
        const s = data.sourceObject?.getFlag?.("starwarsffg", "scheme") ?? data.sourceObject?.actor?.getFlag?.("starwarsffg", "scheme");
        this._cdxScheme = cdxNormalizeScheme(s) ?? "republic";
      }
    } catch (e) { this._cdx = false; }
  }

  static DEFAULT_OPTIONS = {
    classes: ["starwarsffg", "flat_editor"],
    tag: "div",
    window: {
      title: "Embedded Item Editor",
      contentTag: "form",
      resizable: true,
    },
    position: {
      width: 520,
      height: 600,
    },
    form: {
      submitOnChange: true,
      closeOnSubmit: false,
    },
    submitOnClose: true,
  };

  static PARTS = {
    content: { root: true, template: "" },
  };

  /**
   * Render the type-specific template (ffg-embedded-<type>.html) as the root
   * part, preserving the modifier list's scroll position across re-renders.
   * @override
   */
  _configureRenderParts(_options) {
    return {
      content: {
        root: true,
        template: this.template,
        scrollable: [".modification_container"],
      },
    };
  }

  /** @override */
  get title() {
    return this._title ?? game.i18n.localize(this.options.window.title);
  }

  /** @override */
  get template() {
    const path = "systems/starwarsffg/templates/items/dialogs";
    return `${path}/ffg-embedded-${this.data.clickedObject.type}.html`;
  }

  /** @override */
  async _prepareContext(_options) {
    // refresh the dynamic title on (re-)render
    this._title = game.i18n.format("SWFFG.Items.Popout.Title", {currentItem: this.data.clickedObject.name, parentItem: this.data.sourceObject.name});
    const data = await this._enrichData();
    let modifierChoices = CONFIG.FFG.allowableModifierChoices;

    // add in custom skills from the actor, if present
    if (this.data.sourceObject?.actor?.system?.skills) {
      const updatedChoices = foundry.utils.deepClone(modifierChoices);
      for (const modifierChoice of Object.keys(modifierChoices).filter(i => i.indexOf("Skill") >= 0)) {
        updatedChoices[modifierChoice] = this.data.sourceObject?.actor?.system?.skills;
      }
      modifierChoices = updatedChoices;
    }

    return {
      modifierTypes: CONFIG.FFG.allowableModifierTypes,
      modifierChoices: modifierChoices,
      data: data,
    };
  }

  /**
   * retrieves data and converts rich text editor fields into the enriched version. this results in things like dice displaying
   * @returns {Promise<*>}
   * @private
   */
  async _enrichData() {
    let enriched = this.data;
    const co = enriched.clickedObject;
    if (co?.system?.description !== undefined) {
      co.system.enrichedDescription = await foundry.applications.ux.TextEditor.implementation.enrichHTML(co.system.description);
      for (let modification of co.system.itemmodifier ?? []) {
        modification.system.enrichedDescription = await foundry.applications.ux.TextEditor.implementation.enrichHTML(modification.system.description);
      }
    } else if (co?.description !== undefined) {
      // Force-power / signature upgrades (and specialization talents) carry the
      // description directly on the object, not under .system.
      co.enrichedDescription = await foundry.applications.ux.TextEditor.implementation.enrichHTML(co.description);
    }
    return enriched;
  }

  /** @override */
  async _onRender(context, options) {
    await super._onRender(context, options);
    // Apply the Codex scope when the host uses a Codex sheet: `cdx` (+ `cdx-embed`)
    // on the window so the palette vars resolve and the editor is skinned, and
    // the scheme class on the content form.
    if (this._cdx && this.element) {
      this.element.classList.add("cdx", "cdx-embed");
      this.form?.classList?.add(...cdxSchemeClasses(this._cdxScheme));
    }
    this._setupTabs();
    this._activateListeners($(this.form));
    this._activateEditors();
  }

  /* ---- Inline {{editor}} (ProseMirror) support ----
     FFGFormApplication half-wired this (it has the `.editor.prosemirror` change
     guard) but never activated the editors or fed them to FormDataExtended.
     Mirrors FFGDocumentSheet, but the field source is the embedded clickedObject
     and the save flows through the form (_onSubmit -> _updateObject -> write-back)
     rather than a document update. */

  /** @override — feed live editor content into the submitted form data. */
  _getSubmitData(updateData = {}) {
    if (!this.form) throw new Error("The form application has no registered form element.");
    const fd = new foundry.applications.ux.FormDataExtended(this.form, { editors: this.editors });
    let data = fd.object;
    if (updateData) data = foundry.utils.mergeObject(data, updateData, { inplace: false });
    return foundry.utils.flattenObject(data);
  }

  /** Bind each {{editor}} Edit button to mount a ProseMirror editor inline. */
  _activateEditors() {
    const root = this.element;
    if (!root) return;
    for (const content of root.querySelectorAll(".editor-content[data-edit]")) {
      const name = content.dataset.edit;
      if (!name) continue;
      const containerEl = content.closest(".editor");
      const button = containerEl?.querySelector(".editor-edit");
      if (!button || button.dataset.editorBound) continue;
      button.dataset.editorBound = "1";
      button.addEventListener("click", (event) => {
        event.preventDefault();
        this._activateEditor(name, content, containerEl, button);
      });
    }
  }

  async _activateEditor(name, contentEl, containerEl, buttonEl) {
    if (this.editors[name]?.instance?.view) return;
    if (this.editors[name]) this._destroyEditor(name);
    const initial = foundry.utils.getProperty(this.data.clickedObject, name) ?? "";
    const { ProseMirrorEditor } = foundry.applications.ux;
    // Register the FormDataExtended-compatible entry BEFORE create() resolves so
    // a submit-on-change mid-mount still serializes this editor.
    this.editors[name] = {
      instance: null,
      options: { engine: "prosemirror", target: name, button: true, owner: this.isEditable },
      active: true,
      button: buttonEl,
      container: containerEl,
    };
    const editor = await ProseMirrorEditor.create(contentEl, initial, {
      // sourceObject (the host item) is a real Document — used for relative link
      // resolution only; the actual save goes through the form, not this doc.
      document: this.data.sourceObject,
      fieldName: name,
      relativeLinks: true,
      plugins: {
        menu: ProseMirror.ProseMirrorMenu.build(ProseMirror.defaultSchema, {
          destroyOnSave: false,
          onSave: () => this._saveEditor(name, { remove: true }),
        }),
        keyMaps: ProseMirror.ProseMirrorKeyMaps.build(ProseMirror.defaultSchema, {
          onSave: () => this._saveEditor(name, { remove: true }),
        }),
      },
    });
    this.editors[name].instance = editor;
    // `prosemirror` on the container is what FFGFormApplication's _onChangeForm
    // guard looks for to avoid submitting on every keystroke.
    containerEl.classList.add("editor-active", "prosemirror");
    if (buttonEl) buttonEl.style.display = "none";
  }

  async _saveEditor(name, { remove = true } = {}) {
    const state = this.editors[name];
    if (!state?.instance?.view || state._saving) return;
    state._saving = true;
    try {
      // _onSubmit reads the form via our _getSubmitData (which serializes the
      // live editor) and routes through _updateObject -> embedded write-back.
      await this._onSubmit(new Event("submit", { cancelable: true }));
    } finally {
      if (remove) this._destroyEditor(name);
      this.render(true);
    }
  }

  _destroyEditor(name) {
    const state = this.editors[name];
    if (!state) return;
    try { state.instance?.destroy(); } catch (_e) { /* already torn down */ }
    state.container?.classList.remove("editor-active", "prosemirror");
    if (state.button) state.button.style.display = "";
    delete this.editors[name];
  }

  /** Bind the BASICS / BASE MODS tab navigation, remembering the active tab. */
  _setupTabs() {
    if (!this.element) return;
    new foundry.applications.ux.Tabs({
      navSelector: ".tabs",
      contentSelector: ".content",
      initial: this._activeTab ?? "tab1",
      callback: (_event, _tabs, active) => { this._activeTab = active; },
    }).bind(this.element);
  }

  _activateListeners(html) {
    html.find('[name="system.type"]').on("change", this._updateType.bind(this));
    html.find(".flat_editor.dropdown").on("change", this._updateDropdown.bind(this));
    html.find(".flat_editor.add-mod").on("click", this._modControl.bind(this));
    html.find(".flat_editor.add-modification").on("click", this._modificationControl.bind(this));

    // allow drag-and-dropping mods if this is an attachment
    if (this.data.clickedObject.type === "itemattachment") {
      const dragDrop = new foundry.applications.ux.DragDrop({
        dragSelector: ".item",
        dropSelector: ".starwarsffg.flat_editor",
        permissions: { dragstart: this._canDragStart.bind(this), drop: this._canDragDrop.bind(this) },
        callbacks: { drop: this.onDropMod.bind(this) },
      });
      dragDrop.bind(this.element);
    }
  }

  /** DragDrop permission hooks. itemEditor extends FFGFormApplication (not the
   *  sheet classes that define these), so without them `this._canDragStart.bind`
   *  on the attachment DragDrop above throws a TypeError — which aborted
   *  _onRender and left the attachment editor window un-draggable (qualities,
   *  which skip the DragDrop, were unaffected). */
  _canDragStart(_selector) { return true; }
  _canDragDrop(_selector) { return true; }

  async onDropMod(event) {
    CONFIG.logger.debug("caught mod drag-and-drop");
    if (this.data.clickedObject.type !== "itemattachment") {
      ui.notifications.info("You can only drag-and-drop mods onto attachments.");
      return;
    }

    let data;
    const specialization = this.object;
    const li = event.currentTarget;
    const talentId = $(li).attr("id");

    try {
      data = JSON.parse(event.dataTransfer.getData("text/plain"));
      if (data.type !== "Item") return;
    } catch (err) {
      return false;
    }

    const droppedObject = await fromUuid(data.uuid);

    // if it's an attachment, locate the attachment to update
    let updateData;
    if (this.data.clickedObject.type === "itemattachment") {
      updateData = this.data.sourceObject.system.itemattachment;
      for (let attachment of updateData) {
        if (attachment._id === this.data.clickedObject._id) {
          // update the local object so we can see the update in the editor
          this.data.clickedObject.system.itemmodifier.push(droppedObject.toObject());
        }
      }
      await this.data.sourceObject.update({system: {itemattachment: updateData}});
      this.render(true);
    }
  }

  /**
   * Controls creating, deleting, or modifying mods (which contain modifiers)
   * @param event
   */
  async _modControl(event) {
    // The control is an <a data-action="create|delete">; stop the click here so
    // it doesn't bubble to ApplicationV2's [data-action] dispatcher / the form,
    // which (on delete) was closing the editor window.
    event.preventDefault();
    event.stopPropagation();
    let action = event.currentTarget.getAttribute('data-action');
    if (action === 'create') {
      const nk = new Date().getTime();
      const modifierTypes = CONFIG.FFG.allowableModifierTypes;
      const modifierChoices = CONFIG.FFG.allowableModifierChoices;
      const modificationId = $(event.currentTarget).data("modification-id");
      let direct = this.data.clickedObject.type !== "itemattachment";
      if (modificationId === undefined) {
        // we aren't adding it to a modification, so this is true
        direct = true;
      }

      CONFIG.logger.debug(`caught creating a new mod on an attachment. data: ${modificationId}, ${direct}`);
      CONFIG.logger.debug(modifierTypes);
      CONFIG.logger.debug(modifierChoices);
      CONFIG.logger.debug(`expected new modtype is ${Object.keys(modifierTypes)[0]}`);
      CONFIG.logger.debug(`expected new mod mod is ${modifierChoices[Object.keys(modifierTypes)[0]]}`);

      let rendered = await foundry.applications.handlebars.renderTemplate(
        'systems/starwarsffg/templates/items/dialogs/ffg-mod.html',
        {
          modifierTypes: modifierTypes,
          modifierChoices: modifierChoices,
          direct: direct,
          number: modificationId,
          attachmentType: this.data.clickedObject.system.type,
          id: `attr${nk}`,
          attr: {
            modtype: Object.keys(CONFIG.FFG.allowableModifierTypes)[0],
            mod: Object.keys(CONFIG.FFG.allowableModifierChoices[Object.keys(CONFIG.FFG.allowableModifierTypes)[0]])[0],
            value: 1,
          },
        }
      );

      $(event.currentTarget).parent().parent().children(".attributes-list").append(rendered);
      // update the listeners, so we catch events on these new entries
      this._activateListeners($(event.currentTarget).parent().parent().children(".attributes-list"));
      // submit the changes so it gets saved even if the user reloads without closing the editor
      await this._updateObject(undefined, this._getSubmitData());
    } else if (action === 'delete') {
      const modContainer = $(event.currentTarget).parents(".modification_title").find(".attributes-list");
      for (const mod of modContainer.children()) {
        const modId = $(mod).data("attribute");
        const match = this.data.sourceObject.effects.find(i => i.name === modId);
        if (match) {
          CONFIG.logger.debug(`Detected mod present on removed modification, deleting active effect added by ${modId}`);
          await this.data.sourceObject.deleteEmbeddedDocuments("ActiveEffect", [match.id]);
        }
      }
      $(event.currentTarget).parent().remove();
      // submit the changes so it gets saved even if the user reloads without closing the editor
      await this._updateObject(undefined, this._getSubmitData());
    }
  }

  /**
   * Controls creating, deleting, or modifying modifications (which go on attachments)
   * @param event
   */
  async _modificationControl(event) {
    // Stop the <a data-action="delete"> click from bubbling to ApplicationV2's
    // [data-action] dispatcher / the form, which was closing the editor window.
    event.preventDefault();
    event.stopPropagation();
    if(this.actor && !this.data.sourceObject.parent?.verifyEditModeIsNotEnabled()) return;

    let action = event.currentTarget.getAttribute('data-action');
    if (action === 'create') {
      const modTypeChoices = CONFIG.FFG.allowableModifierTypes;
      const modChoices = CONFIG.FFG.allowableModifierChoices;
      let rendered = await foundry.applications.handlebars.renderTemplate(
        'systems/starwarsffg/templates/items/dialogs/ffg-modification.html',
        {
          modTypeChoices: modTypeChoices,
          modChoices: modChoices,
          direct: true,
          mod: {
            name: "New Modification",
            system: {
              description: "Placeholder description",
              active: false,
              rank: 0,
              attribute: {},
            },
          },
        }
      );
      $(event.currentTarget).parent().children('.modification_container').append(rendered);
      // update the listeners, so we catch events on these new entries
      this._activateListeners($(event.currentTarget).parent().children('.modification_container'));
      // submit the changes so it gets saved even if the user reloads without closing the editor
      await this._updateObject(undefined, this._getSubmitData());
    } else if (action === 'delete') {
      const modContainer = $(event.currentTarget).parents(".modification_title").find(".attributes-list");
      for (const mod of modContainer.children()) {
        const modId = $(mod).data("attribute");
        const match = this.data.sourceObject.effects.find(i => i.name === modId);
        if (match) {
          CONFIG.logger.debug(`Detected mod present on removed modification, deleting active effect added by ${modId}`);
          await this.data.sourceObject.deleteEmbeddedDocuments("ActiveEffect", [match.id]);
        }
      }
      $(event.currentTarget).parent().parent().remove();
      // submit the changes so it gets saved even if the user reloads without closing the editor
      await this._updateObject(undefined, this._getSubmitData());
    }
  }

  /**
   * When an attachment or mod type is changed, update the dropdown choices
   * @param event
   * @returns {Promise<void>}
   */
  async _updateType(event) {
    // update our local record of which "attachmentType" we're on so dropdowns render correctly
    this.data.clickedObject.system.type = event.currentTarget.value;
    // iterate over mods and update the modifier to be the first choice of the first modifierType
    // this is done because the selected modifier type changes when the "attachmentType" is changed
    for (let mod of Object.keys(this.data.clickedObject.system.attributes)) {
      this.data.clickedObject.system.attributes[mod].modtype = Object.values(CONFIG.FFG.allowableModifierTypes[event.currentTarget.value])[0].value;
      this.data.clickedObject.system.attributes[mod].mod = Object.values(CONFIG.FFG.allowableModifierTypes[Object.values(CONFIG.FFG.allowableModifierTypes[event.currentTarget.value])[0].value])[0].value;
    }

    // if the item is an attachment, we also need to update mods on modifications
    if (this.data.clickedObject.type === "itemattachment") {
      for (let modifier of Object.keys(this.data.clickedObject.system.itemmodifier)) {
        // modifiers sometimes don't have the attributes in them...
        if (Object.keys(this.data.clickedObject.system.itemmodifier[modifier].system).includes("attributes")) {
          for (let mod of Object.keys(this.data.clickedObject.system.itemmodifier[modifier].system.attributes)) {
            this.data.clickedObject.system.itemmodifier[modifier].system.attributes[mod].modtype = Object.values(CONFIG.FFG.allowableModifierTypes[event.currentTarget.value])[0].value;
            this.data.clickedObject.system.itemmodifier[modifier].system.attributes[mod].mod = Object.values(CONFIG.FFG.allowableModifierTypes[Object.values(CONFIG.FFG.allowableModifierTypes[event.currentTarget.value])[0].value])[0].value;
          }
        }
      }
    }

    // re-render the form so we see the updated dropdown selections/options
    this.render(true);
  }

  /**
   * Updates the modifier 2nd level selector when the 1st level is updated
   * @param event "change" event
   */
  async _updateDropdown(event) {
    // TODO: I think the handlebars select helper can be used here, basically to remove most of this function
    let new_value = event.currentTarget.value;
    let dropdown = event.currentTarget.getAttribute('data-type');

    if (dropdown === 'modtype') {
      let new_html = '';
      let chosen_config = CONFIG.FFG.allowableModifierChoices[new_value];
      Object.keys(chosen_config).forEach(function (choice) {
        new_html += `<option value="${chosen_config[choice]['value']}">${game.i18n.localize(chosen_config[choice]['label'])}</option>`
      });
      $(event.currentTarget).parent().find(".flat_editor.dropdown.mod").html(new_html);

      // swap the value input between checkbox and number based on modtype
      const valueName = event.currentTarget.name.replace(/\.modtype$/, '.value');
      const $valueInput = $(event.currentTarget).parent().find(".modvalue");
      if (new_value === "Career Skill") {
        $valueInput.replaceWith(`<input name="${valueName}" type="checkbox" class="modvalue" data-attr-id="${$valueInput.data('attr-id')}">`);
      } else if ($valueInput.attr('type') === 'checkbox') {
        $valueInput.replaceWith(`<input name="${valueName}" type="number" class="modvalue" value="0" data-attr-id="${$valueInput.data('attr-id')}">`);
      }
    }
  }

  /** @override */
  async _updateObject(event, formData) {
    formData = ItemHelpers.explodeFormData(formData);
    const equipped = this.data.sourceObject.system?.equippable?.equipped;

    // removing all itemmodifiers removes them from the form entirely; add them back in as an empty array
    if (!Object.keys(formData.system).includes("itemmodifier")) {
      formData.system.itemmodifier = [];
    }

    // removing all base mods removes them from the form entirely; add back an empty dic (for our deletion keys)
    if (!Object.keys(formData.system).includes("attributes")) {
      formData.system.attributes = {};
    }

    const existingActiveEffects = this.data.sourceObject.getEmbeddedCollection("ActiveEffect");

    // if it's an attachment, locate the attachment to update
    let updateData;
    if (this.data.clickedObject.type === "itemattachment") {
      CONFIG.logger.debug("> Detected item type of itemattachment");
      updateData = this.data.sourceObject.system.itemattachment;
      for (let attachment of updateData) {
        if (attachment._id === this.data.clickedObject._id) {
          CONFIG.logger.debug(`>> Found relevant attachment: ${attachment.name} / ${attachment.id}, looking for removed keys`);
          // iterate over the mods on the existing attachment and remove them if they are not present in the new data
          for (let modKey of Object.keys(attachment.system.attributes)) {
            if (!Object.keys(formData.system.attributes).includes(modKey)) {
              CONFIG.logger.debug(`>> Detected key ${modKey} was removed, attempting to locate matching active effect`);
              formData.system.attributes[`-=${modKey}`] = null;
              delete attachment.system.attributes[modKey];
              // delete the active effect
              const match = existingActiveEffects.find(i => i.name === modKey);
              if (match) {
               CONFIG.logger.debug(`>>> Active effect located (${match.id}), deleting`);
                await this.data.sourceObject.deleteEmbeddedDocuments("ActiveEffect", [match.id]);
              }
            }
          }
          CONFIG.logger.debug(">> Looking for new or updated ");
          if (Object.keys(formData.system).includes("attributes")) {
            for (const modKey of Object.keys(formData.system.attributes)) {
              CONFIG.logger.debug(">>> Checking modKey", modKey);
              if (modKey.startsWith("-=")) {
                CONFIG.logger.debug(`>>>> Skipping mod ${modKey} which will be deleted`);
                // skip anything queued for deletion
                continue;
              }
              const match = existingActiveEffects.find(i => i.name === modKey);
              const explodedMods = ModifierHelpers.explodeMod(
                formData.system.attributes[modKey].modtype,
                formData.system.attributes[modKey].mod
              );

              const changes = [];
              for (const curMod of explodedMods) {
                changes.push({
                  key: ModifierHelpers.getModKeyPath(curMod['modType'], curMod['mod']),
                  mode: AE_MODES.ADD,
                  value: formData.system.attributes[modKey].value,
                });
              }

              if (match) {
                // existing entry
                CONFIG.logger.debug(`>>>> Staged AE changes for update: ${JSON.stringify(changes)}`);
                await match.update({
                  changes: changes,
                  disabled: !equipped,
                });
              } else {
                // new entry
                const effect = {
                  name: modKey,
                  changes: changes,
                  disabled: !equipped,
                };
                CONFIG.logger.debug(`>>>> Staged AE for creation: ${JSON.stringify(effect)}`);
                await this.data.sourceObject.createEmbeddedDocuments("ActiveEffect", [effect]);
              }
            }
          }

          // repeat the process, but this time for mods on modifications on the attachment
          CONFIG.logger.debug(">> checking modifications...");
          if (Object.keys(formData.system).includes("itemmodifier")) {
            for (const modifier of Object.values(formData.system.itemmodifier)) {
              if (!Object.keys(modifier.system).includes("attributes")) {
                // skip anything that doesn't have attributes
                CONFIG.logger.debug(`>>> modification ${modifier.name} has no mods, skipping further processing`);
                continue;
              }

              for (const modKey of Object.keys(modifier.system.attributes)) {
                CONFIG.logger.debug(">>> Checking modKey", modKey);
                if (modKey.startsWith("-=")) {
                  CONFIG.logger.debug(`>>>> Skipping mod ${modKey} which will be deleted`);
                  // skip anything queued for deletion
                  continue;
                }


                const match = existingActiveEffects.find(i => i.name === modKey);
                const explodedMods = ModifierHelpers.explodeMod(
                  modifier.system.attributes[modKey].modtype,
                  modifier.system.attributes[modKey].mod
                );

                const changes = [];
                for (const curMod of explodedMods) {
                  changes.push({
                    key: ModifierHelpers.getModKeyPath(curMod['modType'], curMod['mod']),
                    mode: AE_MODES.ADD,
                    value: modifier.system.attributes[modKey].value,
                  });
                }

                let disabled;
                if (modifier.system.active === equipped) {
                  // if they're both enabled or disabled, use the opposite value
                  disabled = !modifier.system.active;
                } else {
                  // if either is not enabled, disable the active effect
                  disabled = true;
                }

                if (match) {
                  // existing entry
                  CONFIG.logger.debug(`>>>> Staged AE changes for update: ${JSON.stringify(changes)}`);
                  await match.update({
                    changes: changes,
                    disabled: disabled,
                  });
                } else {
                  // new entry
                  const effect = {
                    name: modKey,
                    disabled: disabled,
                    changes: changes,
                  };
                  CONFIG.logger.debug(`>>>> Staged AE for creation: ${JSON.stringify(effect)}`);
                  await this.data.sourceObject.createEmbeddedDocuments("ActiveEffect", [effect]);
                }
              }
            }
          }

          // merge the existing data in so we end up with all fields present.
          // performDeletions:true APPLIES the `-=key` deletion markers (v12+
          // defaults this to false) — otherwise they linger in the merged
          // attributes as `{"-=attr...": null}`, and the next render iterates
          // that null entry into ffg-mod.html, throwing "Cannot convert
          // undefined or null to object" and closing the editor window.
          attachment = foundry.utils.mergeObject(
            attachment,
            formData,
            { performDeletions: true },
          );
          // pull the updated data back into our local record of what it should look like
          this.data.clickedObject = attachment;
        }
      }
      await this.data.sourceObject.update({system: {itemattachment: updateData}});
    }

    // if it's a mod, locate the mod to update
    if (this.data.clickedObject.type === "itemmodifier") {
      updateData = this.data.sourceObject.system.itemmodifier;
      for (let modifier of updateData) {
        // select based on names instead of IDs, as IDs are not present here
        if (modifier.name === this.data.clickedObject.name) {
          // iterate over the mods on the existing item and remove them if they are not present in the new data
          for (let modKey of Object.keys(modifier.system.attributes)) {
            if (!Object.keys(formData.system.attributes).includes(modKey)) {
              formData.system.attributes[`-=${modKey}`] = null;
              delete modifier.system.attributes[modKey];
              // delete the active effect
              const match = existingActiveEffects.find(i => i.name === modKey);
              if (match) {
                CONFIG.logger.debug(`>>> Active effect located (${match.id}), deleting`);
                await this.data.sourceObject.deleteEmbeddedDocuments("ActiveEffect", [match.id]);
              }
            }
          }
          // merge the existing data in so we end up with all fields present
          // (performDeletions:true applies `-=key` markers — see the attachment
          // branch above; otherwise the lingering null entry crashes re-render).
          modifier = foundry.utils.mergeObject(
            modifier,
            formData,
            { performDeletions: true },
          );
          // pull the updated data back into our local record of what it should look like
          this.data.clickedObject = modifier;
        }
      }

      // iterate over the submitted data to find new/updated entries
      for (const modKey of Object.keys(formData.system.attributes)) {
        if (modKey.startsWith("-=")) {
          continue;
        }

        const match = existingActiveEffects.find(i => i.name === modKey);
        const explodedMods = ModifierHelpers.explodeMod(
          formData.system.attributes[modKey].modtype,
          formData.system.attributes[modKey].mod
        );

        const changes = [];
        for (const curMod of explodedMods) {
          changes.push({
            key: ModifierHelpers.getModKeyPath(curMod['modType'], curMod['mod']),
            mode: AE_MODES.ADD,
            value: formData.system.attributes[modKey].value,
          });
        }

        if (match) {
          // existing entry
          CONFIG.logger.debug(`>>>> Staged AE changes for update: ${JSON.stringify(changes)}`);
          await match.update({
            changes: changes,
            disabled: !equipped,
          });
        } else {
          // new entry
          const effect = {
            name: modKey,
            changes: changes,
            disabled: !equipped,
          };
          CONFIG.logger.debug(`>>>> Staged AE for creation: ${JSON.stringify(effect)}`);
          await this.data.sourceObject.createEmbeddedDocuments("ActiveEffect", [effect]);
        }
      }
      await this.data.sourceObject.update({system: {itemmodifier: updateData}});
    }
    // needed to re-render the mod form (as the input can change types based on the selected modType)
    this.render(true)
  }
}

export class talentEditor extends itemEditor {
  /*
    Known issues:
    - The description rich text editor doesn't appear to work
  */
  static DEFAULT_OPTIONS = {
    window: {
      title: "Embedded Talent Editor",
    },
  };

  /** @override */
  get template() {
    const path = "systems/starwarsffg/templates/items/dialogs";
    return `${path}/ffg-embedded-talent.html`;
  }

    /** @override */
  async _prepareContext(_options) {
    // refresh the dynamic title on (re-)render
    this._title = game.i18n.format("SWFFG.Items.Popout.Title", {currentItem: this.data.clickedObject.name, parentItem: this.data.sourceObject.name});

    let activations = CONFIG.FFG.activations;
    let data = await this._enrichData();

    // add in custom skills from the actor, if present
    if (this.data.sourceObject?.actor?.system?.skills) {
      const updatedChoices = foundry.utils.deepClone(data.modifierChoices);
      for (const modifierChoice of Object.keys(CONFIG.FFG.allowableModifierChoices).filter(i => i.indexOf("Skill") >= 0)) {
        updatedChoices[modifierChoice] = this.data.sourceObject?.actor?.system?.skills;
      }
      data.modifierChoices = updatedChoices;
    }

    return {
      activations: activations,
      data: data,
    };
  }

  /**
   * Controls creating, deleting, or modifying mods (which contain modifiers)
   * @param event
   */
  async _modControl(event) {
    if(this.actor && !this.data.sourceObject.parent?.verifyEditModeIsNotEnabled()) return;

    let action = event.currentTarget.getAttribute('data-action');
    if (action === 'create') {
      const nk = new Date().getTime();
      const modifierTypes = CONFIG.FFG.allowableModifierTypes;
      const modifierChoices = CONFIG.FFG.allowableModifierChoices;
      const modificationId = $(event.currentTarget).data("modification-id");
      const direct = this.data.clickedObject.type !== "itemattachment";

      CONFIG.logger.debug(`caught creating a new mod on a talent. data: ${modificationId}, ${direct}`);
      CONFIG.logger.debug(modifierTypes);
      CONFIG.logger.debug(modifierChoices);
      CONFIG.logger.debug(`expected new modtype is ${Object.keys(modifierTypes)[0]}`);
      CONFIG.logger.debug(`expected new mod mod is ${modifierChoices[Object.keys(modifierTypes)[0]]}`);

      let rendered = await foundry.applications.handlebars.renderTemplate(
        'systems/starwarsffg/templates/items/dialogs/ffg-mod.html',
        { // TODO: this should probably be a new item of the correct type so it assumes any changes to the data model automatically
          modifierTypes: modifierTypes,
          modifierChoices: modifierChoices,
          direct: direct,
          number: modificationId,
          attachmentType: 'all',
          id: `attr${nk}`,
          attr: {
            modtype: Object.keys(CONFIG.FFG.allowableModifierTypes)[0],
            mod: Object.keys(CONFIG.FFG.allowableModifierChoices[Object.keys(CONFIG.FFG.allowableModifierTypes)[0]])[0],
            value: 1,
          },
        }
      );

      $(event.currentTarget).parent().parent().children(".attributes-list").append(rendered);
      // update the listeners, so we catch events on these new entries
      this._activateListeners($(event.currentTarget).parent().parent().children(".attributes-list"));
      // submit the changes so it gets saved even if the user reloads without closing the editor
      await this._updateObject(undefined, this._getSubmitData());
    } else if (action === 'delete') {
      $(event.currentTarget).parent().remove();
      // submit the changes so it gets saved even if the user reloads without closing the editor
      await this._updateObject(undefined, this._getSubmitData());
    }
  }

  /**
   * retrieves data and converts rich text editor fields into the enriched version. this results in things like dice displaying
   * @returns {Promise<*>}
   * @private
   */
  async _enrichData() {
    let enriched = this.data;
    enriched.clickedObject.enrichedDescription = await foundry.applications.ux.TextEditor.implementation.enrichHTML(this.data.clickedObject.description);
    return enriched;
  }

  /** @override */
  async _updateObject(event, formData) {
    if(this.actor && !this.data.sourceObject.parent?.verifyEditModeIsNotEnabled()) return;

    CONFIG.logger.debug("Updating talent");
    formData = foundry.utils.expandObject(formData);

    // update the activation label to match the activation
    formData.activationLabel = CONFIG.FFG.activations[formData.activation].label;

    // move attributes out of "system" since they aren't here for talents
    formData.attributes = formData.system?.attributes;
    delete formData.system?.attributes;
    // make sure attributes is a dictionary instead of whatever they end up being
    if (!Object.keys(formData).includes("attributes") || formData.attributes === undefined) {
      formData.attributes = {};
    }

    const existingActiveEffects = this.data.sourceObject.getEmbeddedCollection("ActiveEffect");

    // iterate over attributes on the specialization and remove any that aren't present in the form
    if (Object.keys(this.data.sourceObject.system.talents[this.data.talentId]).includes("attributes") && this.data.sourceObject.system.talents[this.data.talentId].attributes !== undefined) {
      for (const attrKey of Object.keys(this.data.sourceObject.system.talents[this.data.talentId].attributes)) {
        if (!Object.keys(formData.attributes).includes(attrKey)) {
          formData.attributes[`-=${attrKey}`] = null;
          delete this.data.sourceObject.system.attributes[attrKey];
          // delete the active effect
          const match = existingActiveEffects.find(i => i.name === attrKey);
          if (match) {
            CONFIG.logger.debug(`>>> Active effect located (${match.id}), deleting`);
            await this.data.sourceObject.deleteEmbeddedDocuments("ActiveEffect", [match.id]);
          }
        }
      }
    }

    CONFIG.logger.debug(">> Looking for new or updated ");
    // iterate over newly added or updated attributes and create the active effects
    if (Object.keys(formData).includes("attributes")) {
      for (const modKey of Object.keys(formData.attributes)) {
        CONFIG.logger.debug(">>> Checking modKey", modKey);
        if (modKey.startsWith("-=")) {
          CONFIG.logger.debug(`>>>> Skipping mod ${modKey} which will be deleted`);
          // skip anything queued for deletion
          continue;
        }

        const match = existingActiveEffects.find(i => i.name === modKey);
        const explodedMods = ModifierHelpers.explodeMod(
          formData.attributes[modKey].modtype,
          formData.attributes[modKey].mod
        );

        const changes = [];
        for (const curMod of explodedMods) {
          changes.push({
            key: ModifierHelpers.getModKeyPath(curMod['modType'], curMod['mod']),
            mode: AE_MODES.ADD,
            value: formData.attributes[modKey].value,
          });
        }

        if (match) {
          // existing entry
          CONFIG.logger.debug(`>>>> Staged AE changes for update: ${JSON.stringify(changes)}`);
          await match.update({
            changes: changes,
            disabled: !this.data.clickedObject.islearned,
          });
        } else {
          // new entry
          const effect = {
            name: modKey,
            changes: changes,
            disabled: !this.data.clickedObject.islearned,
          };
          CONFIG.logger.debug(`>>>> Staged AE for creation: ${JSON.stringify(effect)}`);
          await this.data.sourceObject.createEmbeddedDocuments("ActiveEffect", [effect]);
        }
      }
    }

    // merge it into the existing talent data
    formData = foundry.utils.mergeObject(
      this.data.sourceObject.system.talents[this.data.talentId],
      formData,
    );

    CONFIG.logger.debug(formData);

    await this.data.sourceObject.update({
      system: {
        talents: {
          [this.data.talentId]: formData,
        },
      },
    });
  }
}

