import PopoutEditor from "../popout-editor.js";
import { FFGDocumentSheet } from "../apps/ffg-document-sheet.js";
import Helpers from "../helpers/common.js";
import ModifierHelpers from "../helpers/modifiers.js";
import ItemHelpers from "../helpers/item-helpers.js";
import ImportHelpers from "../importer/import-helpers.js";
import DiceHelpers from "../helpers/dice-helpers.js";
import item from "../helpers/embeddeditem-helpers.js";
import EmbeddedItemHelpers from "../helpers/embeddeditem-helpers.js";
import ActorHelpers, {xpLogSpend} from "../helpers/actor-helpers.js";
import ItemOptions from "./item-ffg-options.js";
import {forcePowerEditor, itemEditor, talentEditor} from "./item-editor.js";
import { canPurchaseNode } from "../helpers/talent-tree.js";

const { DialogV2 } = foundry.applications.api;

/**
 * The system's Item sheet — native ApplicationV2 DocumentSheetV2 (via the
 * shared FFGDocumentSheet base). Handles every FFG item type.
 * @extends {FFGDocumentSheet}
 */

export class ItemSheetFFG extends FFGDocumentSheet {
  static DEFAULT_OPTIONS = {
    // `v2` is REQUIRED, not cosmetic: the served stylesheets key item-sheet
    // layout off `.starwarsffg.sheet.item.v2` (weapon/armor/gear/talent/vehicle
    // bodies, the tab strip, etc.). It was the makeDefault sheet pre-migration,
    // so the collapsed sheet keeps the class to preserve appearance (Stage 3.7).
    classes: ["starwarsffg", "sheet", "item", "v2"],
    position: { width: 500 },
    window: { resizable: true },
    // V1-parity submit flags read by the manual submit pipeline in the base.
    submitOnChange: true,
    submitOnClose: true,
    closeOnSubmit: false,
    scrollY: [".sheet-body", ".tab"],
    tabs: [{ navSelector: ".sheet-tabs", contentSelector: ".sheet-body", initial: "attributes" }],
    secrets: [{ parentSelector: ".editor" }],
    baseApplication: "ItemSheet",
    action: null,
    data: null,
  };

  /**
   * Per-item-type template. The root render part picks this up via the base's
   * `_configureRenderParts` (which reads `this.template`).
   * @override
   */
  get template() {
    const path = "systems/starwarsffg/templates/items";
    return `${path}/ffg-${this.item.type}-sheet.html`;
  }

  /** Window title is just the item name (folded from ItemSheetV2Compat). @override */
  get title() {
    return this.item.name;
  }

  /** Alias for the underlying document (folded from ItemSheetV2Compat). */
  get item() {
    return this.object;
  }

  /** The owning actor, if this item is embedded (folded from ItemSheetV2Compat). */
  get actor() {
    return this.item.actor;
  }

  /** @override */
  get isEditable() {
    return super.isEditable && !this.item.flags?.readonly;
  }

  /**
   * Per-type CSS hook applied to the inner form (e.g. `item-sheet-weapon`).
   * Folded from the former ItemSheetV2Compat. A handful of types map to a
   * shared/legacy class name rather than the default `item-sheet-<type>`.
   * @override
   */
  _getLegacyRootClasses(context = {}) {
    const classes = super._getLegacyRootClasses(context);
    const sheetClass = {
      armour: "item-sheet-armor",
      shipweapon: "item-sheet-vehicle-weapon",
      shipattachment: "item-sheet-vehicle-attachment",
      itemmodifier: "item-sheet-modifiers",
      ability: "item-sheet-talent",
      criticaldamage: "item-sheet-criticalinjury",
    }[this.item.type] ?? `item-sheet-${this.item.type}`;

    classes.push(sheetClass);
    return classes;
  }

  /* -------------------------------------------- */

  static SIZE_TO_INT = {
    "single": 1,
    "double": 2,
    "triple": 3,
    "full": 4
  }

  /**
   * Tree-grid item types (specialization / force power / signature ability)
   * need a larger floor than the generic sheet minimum to keep the grid
   * usable. Everything else inherits the base 300x200.
   * @override
   */
  _minDimensions() {
    switch (this.object?.type) {
      case "specialization":
      case "forcepower":
      case "signatureability":
        return { width: 700, height: 600 };
      case "itemmodifier":
        // The modifier sheet's header/type/rank/description panel breaks when
        // dragged smaller than this -- the title overlaps the icon and the
        // fields clip -- so give it a higher (taller) resize floor.
        return { width: 300, height: 400 };
      case "weapon":
      case "armour":
      case "gear":
        // Vertical floor x3.5 (200 -> 700); width keeps the base 300 floor.
        return { width: 300, height: 700 };
      case "ability":
        // Vertical floor x1.5 (200 -> 300); width keeps the base 300 floor.
        return { width: 300, height: 300 };
      case "talent":
        // The talent header is tall: 124px image + name + activation + the
        // three-across ranked/force/conflict block row + tab strip (plus any
        // third-party header injection such as the enhancements module's
        // "Associated Skills" block). The body flexes and scrolls below it, but
        // the header still needs ~350-400px to render without being squished,
        // so floor the window around that plus a usable body. The width floor
        // (above the base 300) keeps the ranked/force/conflict block row
        // readable.
        return { width: 385, height: 500 };
      case "itemattachment":
        // Vertical floor x2 (200 -> 400); width keeps the base 300 floor.
        return { width: 300, height: 400 };
      default:
        return super._minDimensions();
    }
  }

  /** @override */
  async getData(options) {
    let data = super.getData(options);
    // FFGDocumentSheet.getData returns { document, data, ... }; the item-sheet
    // body below and the templates read `data.item` (folded from the former
    // ItemSheetV2Compat.getData).
    data.item = data.document;
    // this code was mostly written by Phind
    // removing a key from a dict in Foundry requires submitting it with a new key of `-=key` and a value of null
    // without explicitly replacing values, we end up duplicating entries instead of removing the one
    // so instead, we go and manually remove any mods which have been deleted

    // find any deleted attributes
    const deleted_keys = EmbeddedItemHelpers.findKeysIncludingStringRecursively(
        data,
        '-=attr',
    );
    // remove matching attributes from the existing object
    deleted_keys.forEach(function (cur_key) {
      EmbeddedItemHelpers.removeKeyFromObject(
        data,
        cur_key,
      );
      EmbeddedItemHelpers.removeKeyFromObject(
        data,
        cur_key,
      );
    });
    // this is the end of the de-duplicating -=key stuff

    data.data = data.item.system;


    if (options?.action === "update" && this.object.compendium) {
      delete options.data._id;
      data.item = foundry.utils.mergeObject(data.item, options.data);
    } else if (options?.action === "ffgUpdate") {
      delete options?.data?.system?.description;
      if (options?.data?.data) {
        data.data = foundry.utils.mergeObject(data.data, options.data.data);
        // we are going to merge options.data into data.item and can't set data.item.data this way
        delete options.data.data;
      } else {
        data.data = foundry.utils.mergeObject(data.data, options.data);
      }
      data.item = foundry.utils.mergeObject(data.item, options.data); // some fields are read out of item, some are read out of data
    }

    // Annotate each modifier row with whether its backing Active Effect is enabled. A bulk
    // suspend (e.g. Sheet Options edit mode, or GM XP granting) disables every effect on every
    // item so derived stats can be hand-edited without a feedback loop, then is supposed to
    // restore each one's original state. If that restore is ever interrupted, an item's effect
    // is left disabled in the database with nothing in the sheet to show or fix it (gear items
    // in particular have no equip toggle to force a resync). This exposes a direct checkbox.
    if (data.data?.attributes) {
      const existingEffects = this.object.effects;
      for (const key of Object.keys(data.data.attributes)) {
        const attr = data.data.attributes[key];
        if (!attr || key.startsWith("-=")) continue;
        const matchingEffect = existingEffects.find((e) => e.name === key);
        attr.hasEffect = !!matchingEffect;
        attr.effectEnabled = matchingEffect ? !matchingEffect.disabled : true;
      }
    }

    // The sheet templates branch on `contains classType "V2"` to render the V2
    // layout (icon tab strip, refined panels, shown-by-default tabs). After the
    // Stage 3 collapse the real class is `ItemSheetFFG` (no "V2" suffix), so
    // carry the V2 marker explicitly — this IS the V2 sheet. Without it the
    // templates fall back to the retired V1 layout (text tabs, etc.).
    data.classType = this.constructor.name.includes("V2") ? this.constructor.name : `${this.constructor.name}V2`;
    CONFIG.logger.debug(`Getting Item Data ${this.object.name}`);

    data.dtypes = ["String", "Number", "Boolean"];
    if (data?.data?.attributes) {
      for (let attr of Object.values(data.data.attributes)) {
        if (attr?.dtype) {
          attr.isCheckbox = attr.dtype === "Boolean";
        }
      }
    }

    if (data?.data?.description) {
      data.data.enrichedDescription = await foundry.applications.ux.TextEditor.implementation.enrichHTML(data.data.description);
    }

    if (data?.data?.longDesc !== undefined) {
      data.data.enrichedLongDesc = await foundry.applications.ux.TextEditor.implementation.enrichHTML(data.data.longDesc);
      data.data.hasLongDesc = true;
    } else {
      data.data.hasLongDesc = false;
    }

    data.isTemp = false;
    if (this.object.flags?.starwarsffg?.ffgIsOwned || this.object.flags?.starwarsffg?.ffgIsTemp) {
      data.isTemp = true;
    }
    data.isOwned = this.object.flags?.starwarsffg?.ffgIsOwned;
    data.isGM = game.user.isGM;
    data.modTypeSelected = "all";

    const setInitialSize = !this._sizeInitialized;
    this._sizeInitialized = true;

    switch (this.object.type) {
      case "weapon":
        if (setInitialSize) {
          this.position.width = 550;
          this.position.height = 750;
        }
        data.data.enrichedSpecial = await PopoutEditor.renderDiceImages(data?.data?.special?.value, this.actor ? this.actor : {});
        data.modTypeSelected = "weapon";
        break;
      case "shipweapon":
        if (setInitialSize) {
          this.position.width = 550;
          this.position.height = 750;
        }
        data.data.enrichedSpecial = await PopoutEditor.renderDiceImages(data?.data?.special?.value, this.actor ? this.actor : {});
        data.modTypeSelected = "vehicle";
        break;
      case "itemattachment":
        if (setInitialSize) {
          this.position.width = 500;
          this.position.height = 550;
        }
        data.modTypeSelected = this.object.system.type;
        // enrich modification descriptions for display
        if (data.data.itemmodifier) {
          for (let modification of data.data.itemmodifier) {
            modification.system.enrichedDescription = await foundry.applications.ux.TextEditor.implementation.enrichHTML(modification.system.description);
          }
        }
        break;
      case "itemmodifier":
        if (setInitialSize) {
          // Height opens at the 400 floor (see _minDimensions); the prior 350
          // was below the new minimum and would just be clamped up on open.
          this.position.width = 450;
          this.position.height = 400;
        }
        data.modTypeSelected = this.object.system.type;
        break;
      case "armour":
        if (setInitialSize) {
          this.position.width = 385;
          this.position.height = 750;
        }
        data.modTypeSelected = "armor";
        break;
      case "gear":
        if (setInitialSize) {
          this.position.width = 385;
          this.position.height = 750;
        }
        break;
      case "shipattachment":
        if (setInitialSize) {
          this.position.width = 385;
          this.position.height = 615;
        }
        data.modTypeSelected = "vehicle";
        break;
      case "ability":
      case "homesteadupgrade":
        if (setInitialSize) {
          this.position.width = 385;
          this.position.height = 615;
        }
        break;
      case "talent":
        if (setInitialSize) {
          this.position.width = 405;
          this.position.height = 535;
        }
        break;
      case "criticalinjury":
      case "criticaldamage":
        if (setInitialSize) {
          this.position.width = 320;
          this.position.height = 500;
        }
        break;
      case "forcepower":
        if (setInitialSize) {
          this.position.width = 720;
          this.position.height = 840;
        }
        data.isReadOnly = false;
        if (!this.isEditable) {
          data.isEditing = false;
          data.isReadOnly = true;
        }
        // Pre-populate sizeInt and canPurchase BEFORE the await-heavy loop
        // so they remain set even if enrichHTML throws mid-loop (e.g. for a
        // non-GM viewer hitting a permission-restricted embedded reference).
        for (let x = 0; x < 16; x++) {
          if (!data.data.upgrades[`upgrade${x}`]) continue;
          data.data.upgrades[`upgrade${x}`].sizeInt = ItemSheetFFG.SIZE_TO_INT[data.data.upgrades[`upgrade${x}`].size];
        }
        for (let x = 0; x < 16; x++) {
          if (!data.data.upgrades[`upgrade${x}`]) continue;
          data.data.upgrades[`upgrade${x}`].canPurchase = canPurchaseNode(
            data.data.upgrades,
            `upgrade${x}`,
            { prefix: "upgrade", width: 4, total: 16, sizeAware: true, rootHasImplicitParent: true }
          );
        }
        for (let x = 0; x < 16; x++) {
          data.data.upgrades[`upgrade${x}`].enrichedDescription = await foundry.applications.ux.TextEditor.implementation.enrichHTML(data.data.upgrades[`upgrade${x}`].description);
          let upgradeSize = ItemSheetFFG.SIZE_TO_INT[data.data.upgrades[`upgrade${x}`].size];
          data.data.upgrades[`upgrade${x}`].sizeInt = upgradeSize;

          // Check if top connections are learned
          if (x - 4 < 0) {
            // Top row, all true because basic power is always learned
            for (let y = 1; y < upgradeSize + 1; y++) {
              data.data.upgrades[`upgrade${x}`][`isTop${y}Learned`] = true;
            }
          } else {
            // Other rows
            for (let y = 1; y < upgradeSize + 1; y++) {
              for (let z = 0; z < x % 4 + y; z++) {
                if (data.data.upgrades[`upgrade${x-5+y-z}`].sizeInt >= z + 1) {
                  data.data.upgrades[`upgrade${x}`][`isTop${y}Learned`] = data.data.upgrades[`upgrade${x-5+y-z}`]?.islearned ?? false;
                }
              }
            }
          }

          // Check if right connection is learned
          if ((x + upgradeSize) % 4 == 0) {
            data.data.upgrades[`upgrade${x}`].isRightLearned = false;
          } else {
            data.data.upgrades[`upgrade${x}`].isRightLearned = data.data.upgrades[`upgrade${x+upgradeSize}`]?.islearned ?? false;
          }
        }
        break;
      case "specialization":
        if (setInitialSize) {
          this.position.width = 850;
          this.position.height = 1005;
        }
        data.isReadOnly = false;
        if (!this.isEditable) {
          data.isEditing = false;
          data.isReadOnly = true;
        }

        if (!this.item.flags?.starwarsffg?.loaded) {
          CONFIG.logger.debug(`Running Item initial load`);
          if (!Object.keys(this.item.flags).includes('starwarsffg')) {
              // the object is not properly set up yet; bail to let it finish
              return;
          }
          this.item.flags.starwarsffg.loaded = true;
        }
        // Compute canPurchase first so it's always populated even if a later
        // `await` (e.g. enrichHTML on a restricted embedded reference) throws
        // mid-loop for non-GM viewers.
        for (let x = 0; x < 20; x++) {
          if (!data.data.talents[`talent${x}`]) continue;
          data.data.talents[`talent${x}`].canPurchase = canPurchaseNode(
            data.data.talents,
            `talent${x}`,
            { prefix: "talent", width: 4, total: 20, sizeAware: false }
          );
        }
        for (let x = 0; x < 20; x++) {
          data.data.talents[`talent${x}`].enrichedDescription = await foundry.applications.ux.TextEditor.implementation.enrichHTML(data.data.talents[`talent${x}`].description);

          if (x - 4 < 0) {
            data.data.talents[`talent${x}`].isTopLearned = false;
          } else {
            data.data.talents[`talent${x}`].isTopLearned = data.data.talents[`talent${x-4}`]?.islearned ?? false;
          }

          if ((x + 1) % 4 == 0) {
            data.data.talents[`talent${x}`].isRightLearned = false;
          } else {
            data.data.talents[`talent${x}`].isRightLearned = data.data.talents[`talent${x+1}`]?.islearned ?? false;
          }
        }
        break;
      case "species":
        if (setInitialSize) {
          this.position.width = 550;
          this.position.height = 650;
        }

        const attributesForCharacteristics = Object.keys(data.data.attributes).filter((key) => {
          return Object.keys(CONFIG.FFG.characteristics).includes(key);
        });

        const speciesCharacteristics = attributesForCharacteristics.map((key) => Object.assign(data.data.attributes[key], { key }));
        data.characteristics = Object.keys(CONFIG.FFG.characteristics).map((key) => {
          let attr = speciesCharacteristics.find((item) => item.mod === key);

          if (!attr) {
            data.data.attributes[`${key}`] = {
              modtype: "Characteristic",
              mod: key,
              value: 0,
              exclude: true,
            };
            attr = {
              key: `${key}`,
              value: 0,
            };
          } else {
            data.data.attributes[`${key}`].exclude = true;
          }

          return {
            id: attr.key,
            key,
            value: attr?.value ? parseInt(attr.value, 10) : 0,
            modtype: "Characteristic",
            mod: key,
            label: game.i18n.localize(CONFIG.FFG.characteristics[key].label),
          };
        });

        if (!data.data.attributes?.Wounds) {
          data.data.attributes.Wounds = {
            modtype: "Stat",
            mod: "Wounds",
            value: 0,
            exclude: true,
          };
        } else {
          data.data.attributes.Wounds.exclude = true;
        }
        if (!data.data.attributes?.Strain) {
          data.data.attributes.Strain = {
            modtype: "Stat",
            mod: "Strain",
            value: 0,
            exclude: true,
          };
        } else {
          data.data.attributes.Strain.exclude = true;
        }

        break;
      case "career":
        if (setInitialSize) {
          this.position.width = 500;
          this.position.height = 600;
        }
        if (Object.keys(this.object.system.specializations).length === 0) {
          // handlebars sucks
          data.data.specializations = false;
        } else {
          for (const specializationId of Object.keys(data.data.specializations)) {
            if (!fromUuidSync(data.data.specializations[specializationId].source)) {
              // this item no longer exists, tag it as broken
              data.data.specializations[specializationId].broken = true;
            }
          }
        }
        if (Object.keys(this.object.system.signatureabilities).length === 0) {
          // handlebars sucks
          data.data.signatureabilities = false;
        } else {
          for (const signatureAbilityId of Object.keys(data.data.signatureabilities)) {
            if (!fromUuidSync(data.data.signatureabilities[signatureAbilityId].source)) {
              // this item no longer exists, tag it as broken
              data.data.signatureabilities[signatureAbilityId].broken = true;
            }
          }
        }
        break;
      case "signatureability": {
        if (setInitialSize) {
          // Codex tree (full-width banner + uplink bar + 2-row size-aware grid)
          // needs more height than the stock compact sheet's 545.
          this.position.width = 720;
          this.position.height = 720;
        }
        data.data.isReadOnly = false;
        if (!this.isEditable) {
          data.data.isEditing = false;
          data.data.isReadOnly = true;
        }
        // Pre-populate sizeInt and canPurchase BEFORE the await-heavy loop
        // (see force-power case for rationale — non-GM viewers can hit a
        // restricted reference inside enrichHTML and abort the loop).
        for (let x = 0; x < 8; x++) {
          if (!data.data.upgrades[`upgrade${x}`]) continue;
          data.data.upgrades[`upgrade${x}`].sizeInt = ItemSheetFFG.SIZE_TO_INT[data.data.upgrades[`upgrade${x}`].size];
        }
        for (let x = 0; x < 8; x++) {
          if (!data.data.upgrades[`upgrade${x}`]) continue;
          data.data.upgrades[`upgrade${x}`].canPurchase = canPurchaseNode(
            data.data.upgrades,
            `upgrade${x}`,
            { prefix: "upgrade", width: 4, total: 8, sizeAware: true, rootHasImplicitParent: true }
          );
        }
        for (let x = 0; x < 8; x++) {
          data.data.upgrades[`upgrade${x}`].enrichedDescription = await foundry.applications.ux.TextEditor.implementation.enrichHTML(data.data.upgrades[`upgrade${x}`].description);
          let upgradeSize = ItemSheetFFG.SIZE_TO_INT[data.data.upgrades[`upgrade${x}`].size];
          data.data.upgrades[`upgrade${x}`].sizeInt = upgradeSize;

          // Check if top connections are learned
          if (x - 4 < 0) {
            // Top row, all true because basic power is always learned
            for (let y = 1; y < upgradeSize + 1; y++) {
              data.data.upgrades[`upgrade${x}`][`isTop${y}Learned`] = true;
            }
          } else {
            // Other rows
            for (let y = 1; y < upgradeSize + 1; y++) {
              for (let z = 0; z < x % 4 + y; z++) {
                if (data.data.upgrades[`upgrade${x-5+y-z}`].sizeInt >= z + 1) {
                  data.data.upgrades[`upgrade${x}`][`isTop${y}Learned`] = data.data.upgrades[`upgrade${x-5+y-z}`]?.islearned ?? false;
                }
              }
            }
          }

          // Check if right connection is learned
          if ((x + upgradeSize) % 4 == 0) {
            data.data.upgrades[`upgrade${x}`].isRightLearned = false;
          } else {
            data.data.upgrades[`upgrade${x}`].isRightLearned = data.data.upgrades[`upgrade${x+upgradeSize}`]?.islearned ?? false;
          }
        }
        break;
      }
      case "background": {
        if (setInitialSize) this.position.height = 545;
        data.data.backgroundTypes = CONFIG.FFG.characterCreator.backgroundTypes;
        break;
      }
      case "obligation": {
        if (setInitialSize) this.position.height = 545;
        data.data.obligationTypes = CONFIG.FFG.characterCreator.obligationTypes;
        data.data.subtypes = CONFIG.FFG.characterCreator.obligationSubTypes;
        break;
      }
      case "motivation": {
        if (setInitialSize) this.position.height = 545;
        data.data.motivationTypes = CONFIG.FFG.characterCreator.motivationTypes;
        break;
      }
      break;
      default:
    }

    data.FFG = CONFIG.FFG;

    // prepare skills for career skill usage
    if (this?.actor?.system?.skills) {
      data.careerSkills = foundry.utils.mergeObject(
        {
          "(none)": {
            value: "(none)",
            label: "SWFFG.CareerSkills.None",
          }
        },
        foundry.utils.deepClone(this.actor.system.skills)
      );
    } else {
      data.careerSkills = foundry.utils.mergeObject(
        {
          "(none)": {
            value: "(none)",
            label: "SWFFG.CareerSkills.None",
          }
        },
        foundry.utils.deepClone(CONFIG.FFG.skills)
      );
    }

    data.renderedDesc = PopoutEditor.renderDiceImages(data.description, this.actor ? this.actor : {});
    if (!data.renderedDesc) {
      data.data.renderedDesc = PopoutEditor.renderDiceImages(data?.item?.system?.description, this.actor ? this.actor : {});
    }

    // get summarized data for qualities (e.g. weapons)
    data = this._getSummarizedQualities(data);

    data.modifierTypes = CONFIG.FFG.allowableModifierTypes;
    data.modifierChoices = CONFIG.FFG.allowableModifierChoices;
    // allow modifiers to impact actor-specific custom skills, if present

    if (this?.actor?.system?.skills) {
      const updatedChoices = foundry.utils.deepClone(data.modifierChoices);
      for (const modifierChoice of Object.keys(CONFIG.FFG.allowableModifierChoices).filter(i => i.indexOf("Skill") >= 0)) {
        updatedChoices[modifierChoice] = this?.actor?.system?.skills;
      }
      data.modifierChoices = updatedChoices;
    }

    return data;
  }

  /**
   * Summarizes the qualities of an item (drawing from both the direct qualities and those added by attachments)
   * The goal is to provide a unified view (e.g. "Accurate 3" instead of "Accurate 1" and "Accurate 2 - from attachment")
   * This data is intended for user viewing only; it should not be submitted back or otherwise used to update anything
   * @param data (from getData)
   * @returns {*}
   * @private
   */
  _getSummarizedQualities(data) {
    CONFIG.logger.debug("Summarizing qualities");
    // enrich attachment data
    data.data.doNotSubmit = {
      qualities: [],
    };

    if (Object.keys(data.data).includes("itemmodifier")) {
      for (const mod of data.data.itemmodifier) {
        const modName = mod.name;
        const rank = mod.system.rank;
        const description = mod.system.description;
        const modId = mod._id;
        let modIndex = data.data.doNotSubmit.qualities.findIndex(i => i.name === modName);
        if (modIndex < 0) {
          modIndex = data.data.doNotSubmit.qualities.length;
          data.data.doNotSubmit.qualities.push({
            name: modName,
            img: mod.img,
            description: description,
            itemIndex: modIndex,
            totalRanks: 0,
            modId: modId,
            includeControls: true,
            summarizedRanks: {
              mods: 0,
            }
          });
        }
        data.data.doNotSubmit.qualities[modIndex].totalRanks += rank;
        data.data.doNotSubmit.qualities[modIndex].summarizedRanks.mods += rank;
      }
    }
    CONFIG.logger.debug(data.data.doNotSubmit.qualities);

    CONFIG.logger.debug("Pulling qualities from attachments");
    if (Object.keys(data.data).includes("itemattachment")) {
      for (const attachment of data.data.itemattachment) {
        const source = attachment.name;
        if (Object.keys(attachment.system).includes("itemmodifier")) {
          for (const mod of attachment.system.itemmodifier) {
            if (!mod.system.active) {
              // this modifier isn't active, skip processing
              continue;
            }
            const modName = mod.name;
            const rank = mod.system.rank;
            const description = mod.system.description;
            let modIndex = data.data.doNotSubmit.qualities.findIndex(i => i.name === modName);
            if (modIndex < 0) {
              modIndex = data.data.doNotSubmit.qualities.length;
              data.data.doNotSubmit.qualities.push({
                name: modName,
                description: description,
                itemIndex: modIndex,
                totalRanks: 0,
                includeControls: false,
                summarizedRanks: {
                  [source]: 0,
                }
              });
            }
            // validate this source is present in the data
            if (!Object.keys(data.data.doNotSubmit.qualities[modIndex].summarizedRanks).includes(source)) {
              data.data.doNotSubmit.qualities[modIndex].summarizedRanks[source] = 0;
            }
            // update the ranks
            data.data.doNotSubmit.qualities[modIndex].totalRanks += rank;
            data.data.doNotSubmit.qualities[modIndex].summarizedRanks[source] += rank;
          }
        }
      }
    }
    CONFIG.logger.debug(data.data.doNotSubmit.qualities);
    return data;
  }

  /* -------------------------------------------- */

  /**
   * Handle adding/deleting modifications on a standalone itemattachment sheet
   */
  async _onStandaloneModificationControl(event) {
    event.preventDefault();
    const action = event.currentTarget.getAttribute('data-action');
    if (action === 'create') {
      const itemmodifier = foundry.utils.deepClone(this.object.system.itemmodifier || []);
      itemmodifier.push({
        name: "New Modification",
        type: "itemmodifier",
        img: "icons/svg/item-bag.svg",
        system: {
          description: "Placeholder description",
          active: false,
          rank: 0,
          attributes: {},
        },
      });
      await this.object.update({ "system.itemmodifier": itemmodifier });
    } else if (action === 'delete') {
      const modIndex = $(event.currentTarget).closest(".modification_title").index();
      const itemmodifier = foundry.utils.deepClone(this.object.system.itemmodifier || []);
      itemmodifier.splice(modIndex, 1);
      await this.object.update({ "system.itemmodifier": itemmodifier });
    }
  }

  /**
   * Handle adding/deleting mods (modifiers) within modifications on a standalone itemattachment sheet
   */
  async _onStandaloneModControl(event) {
    event.preventDefault();
    const action = event.currentTarget.getAttribute('data-action');
    const modificationId = $(event.currentTarget).data("modification-id");

    if (action === 'create') {
      const isDirectBaseMod = modificationId === undefined;

      if (isDirectBaseMod) {
        // This is for base mods, not modifications - let the existing handler deal with it
        return;
      }

      const nk = new Date().getTime();
      const modifierTypes = CONFIG.FFG.allowableModifierTypes;
      const modifierChoices = CONFIG.FFG.allowableModifierChoices;

      let rendered = await foundry.applications.handlebars.renderTemplate(
        'systems/starwarsffg/templates/items/dialogs/ffg-mod.html',
        {
          modifierTypes: modifierTypes,
          modifierChoices: modifierChoices,
          direct: false,
          number: modificationId,
          attachmentType: this.object.system.type,
          id: `attr${nk}`,
          attr: {
            modtype: Object.keys(CONFIG.FFG.allowableModifierTypes)[0],
            mod: Object.keys(CONFIG.FFG.allowableModifierChoices[Object.keys(CONFIG.FFG.allowableModifierTypes)[0]])[0],
            value: 1,
          },
        }
      );

      $(event.currentTarget).parent().parent().children(".attributes-list").append(rendered);
      // re-bind listeners on the new elements
      this.activateListeners($(event.currentTarget).parent().parent().children(".attributes-list"));
      // submit the form to persist the change. submit() throws in this compat
      // layer (form handler is nulled), so use the manual pipeline; render to
      // rebuild the attribute list from persisted data.
      this._onSubmit(new Event("submit", { cancelable: true }), { render: true });
    } else if (action === 'delete') {
      // check if this is a mod within a modification (has a parent .modification_title)
      const inModification = $(event.currentTarget).closest(".modification_title").length > 0;
      if (inModification) {
        $(event.currentTarget).parent().remove();
        this._onSubmit(new Event("submit", { cancelable: true }), { render: true });
      }
    }
  }

  /**
   * Handle dropdown changes for modifier type selectors on standalone itemattachment modifications
   */
  async _onStandaloneDropdownChange(event) {
    const newValue = event.currentTarget.value;
    const dropdown = event.currentTarget.getAttribute('data-type');

    if (dropdown === 'modtype') {
      let newHtml = '';
      const chosenConfig = CONFIG.FFG.allowableModifierChoices[newValue];
      Object.keys(chosenConfig).forEach(function (choice) {
        newHtml += `<option value="${chosenConfig[choice]['value']}">${game.i18n.localize(chosenConfig[choice]['label'])}</option>`;
      });
      $(event.currentTarget).parent().find(".flat_editor.dropdown.mod").html(newHtml);
    }
  }

  /** @override */
  activateListeners(html) {
    super.activateListeners(html);
    html.find(".ffg-purchase").click(async (ev) => {
      if(this.actor && !this.actor?.verifyEditModeIsNotEnabled()) return;
      await this._handleItemBuy(ev)
    });

    // Cross-field reactivity: toggling "Ranked" shows/hides the rank-count
    // field via {{#if data.ranks.ranked}}. The generic change pipeline now
    // submits with render:false (render-race fix), so request an explicit
    // re-render for this one field. Coalesces with the pipeline's own submit.
    html.find('[name="data.ranks.ranked"]').on("change", async (ev) => {
      await this._onSubmit(ev, { render: true });
    });

    // Cross-field reactivity: toggling a talent/upgrade "islearned" checkbox
    // changes which nodes are purchasable (the .ffg-purchase buy buttons) for
    // this node AND its tree neighbours, via the canPurchase pass in getData.
    // Under render:false the buy button would not reappear after un-learning a
    // node, so re-render on change to recompute canPurchase across the tree.
    html.find('input[name$=".islearned"]').on("change", async (ev) => {
      await this._onSubmit(ev, { render: true });
    });

    html.find(".source-control").click(async (ev) => {
      await this._handleSourceControl(ev);
    });

    html.find(".tag-control").click(async (ev) => {
      await this._handleTagControl(ev);
    });

    // register sheet options
    if (["gear", "weapon", "armour"].includes(this.object.type)) {
      this.sheetoptions = new ItemOptions(this, html);
      this.sheetoptions.register("enablePrice", {
        name: game.i18n.localize("SWFFG.SheetOptions2.EnablePrice.Name"),
        hint: game.i18n.localize("SWFFG.SheetOptions2.EnablePrice.Hint"),
        type: "Boolean",
        default: true,
      });
      this.sheetoptions.register("enableRarity", {
        name: game.i18n.localize("SWFFG.SheetOptions2.enableRarity.Name"),
        hint: game.i18n.localize("SWFFG.SheetOptions2.enableRarity.Hint"),
        type: "Boolean",
        default: true,
      });

      if (this.object.type === "gear") {
        this.sheetoptions.register("medicalType", {
          name: game.i18n.localize("SWFFG.SheetOptions2.isMedical.Name"),
          hint: game.i18n.localize("SWFFG.SheetOptions2.isMedical.Hint"),
          type: "Array",
          default: 0,
          options: {
            0: game.i18n.localize("SWFFG.MedicalItemType.No"),
            1: game.i18n.localize("SWFFG.MedicalItemType.Stimpack"),
            2: game.i18n.localize("SWFFG.MedicalItemType.EmergencyRepairPatch"),
          },
        });
      }
      if (this.object.type === "weapon") {
        this.sheetoptions.register("enableAmmo", {
          name: game.i18n.localize("SWFFG.SheetOptions2.enableAmmo.Name"),
          hint: game.i18n.localize("SWFFG.SheetOptions2.enableAmmo.Hint"),
          type: "Boolean",
          default: false,
        });
      }
    }

    // Tabs are bound by FFGDocumentSheet._activateCoreListeners using the
    // DEFAULT_OPTIONS.tabs config and the per-document _activeTabCache. Do not
    // re-bind here; a second Tabs controller on the same nav races and snaps
    // back to the default tab on the next render.

    html.find(".items .item, .header-description-block .item, .injuries .item").click(async (ev) => {
      const li = $(ev.currentTarget);
      let itemId = li.data("itemId");
      const itemType = li.data("itemType");
      let item;
      let itemDetails;
      if (itemType === "ability") {
        item = this.item.system.abilities[itemId];
        itemDetails = {
          name: item.name,
          description: item.system.description,
        };
      } else if (itemType === "talent") {
        item = await fromUuid(this.item.system.talents[itemId].source);
        if (item) {
          itemDetails = {
            name: item.name,
            description: item.system.description,
          };
        }
      }
      if (item) {
        await this._itemDisplayDetails(item, ev, itemDetails);
      }
    });

    // Toggle attachment and mod details (not actually force powers, but we are reusing it!)
      html.find(".expand-desc").click(async (ev) => {
        ev.stopPropagation();
        if (!$(ev.target).hasClass("fa-trash") && !$(ev.target).hasClass("fas") && !$(ev.target).hasClass("rollable") && !$(ev.target).closest(".item-control").length) {
          CONFIG.logger.debug("Caught attachment or mod description click");
          // expand or shrink the description
          const li = $(ev.currentTarget);
          let desc = li.data("desc");
          const rarity = li.data("rarity");
          const price = li.data("price");
          if (price) {
            desc = `<span class="statt" title="Price"><i class="fa-solid fa-dollar-sign"></i>${price}</span>${desc}`
          }
          if (rarity) {
            desc = `<span class="stat stat-right" title="Rarity"><i class="fa-solid fa-magnifying-glass"></i>${rarity}</span>${desc}`
          }

          // if the item has embedded mods, pull the data and add it to the description
          let modNames = li.data("mod-names");
          let modDescs = li.data("mod-descs");
          let modActives = li.data("mod-actives");
          if (modNames) {
            modNames = modNames.split("~");
            modDescs = modDescs.split("~");
            modActives = modActives.split("~");
            CONFIG.logger.debug(modNames);
            CONFIG.logger.debug(modDescs);
            CONFIG.logger.debug(modActives);
            let newDesc = `<hr><b>Mods</b>:<br>`;
            for (let i = 0; i < modNames.length - 1; i++) {
              if (modActives[i] === "true") {
                modNames[i] = `<i class="fa-solid fa-user-check" title="Installed"></i>&nbsp;${modNames[i]}`;
              } else {
                modNames[i] = `<i class="fa-duotone fa-solid fa-user-xmark" title="Not Installed"></i>&nbsp;${modNames[i]}`;
              }
              newDesc += `<u>${modNames[i]}</u>:&nbsp;${modDescs[i]}<br>`;
            }
            desc+= newDesc;
          }

          await this._itemDisplayDesc(desc, ev);
        } else {
          // Edit only when the click is within the edit control (icon OR its
          // <a> wrapper) — clicking the anchor padding used to fall through to
          // the expand branch (nothing happened), and delete clicks must not
          // open the editor.
          if ($(ev.target).closest(".item-edit").length) {
            // edit the item
            CONFIG.logger.debug("Caught mod or attachment edit request");
            // pull the item which the edit is on
            const li = $(ev.currentTarget);
            const clickedId = li.data('item-id');
            const clickedType = li.data('item-type');
            const parentObject = await fromUuid(this.object.uuid);
            // locate the clicked object on the parent
            let clickedObject = parentObject.system[clickedType].find(i => i._id === clickedId);
            if (!clickedObject) {
              // this is most likely a unique mod - we have to look it up by name :|
              clickedObject = parentObject.system[clickedType].find(i => i.name === li.data('upgrade-name'));
            }
            CONFIG.logger.debug(clickedObject);
            const typeChoices = {};
            for (const key of Object.keys(CONFIG.FFG.itemmodifier_types)) {
              const entry = CONFIG.FFG.itemmodifier_types[key];
              typeChoices[entry.value] = game.i18n.localize(entry.label);
            }
            const data = {
              sourceObject: this.object,
              clickedObject: clickedObject,
              typeChoices: typeChoices,
            }
            new itemEditor(data).render(true);
          }
        }
      });

    html.find(".item-delete").click(async (ev) => {
      const li = $(ev.currentTarget);
      let itemId = li.data("itemId");
      const itemType = li.data("itemType");
      if (itemType === "ability") {
        const item = this.item.system.abilities[itemId];
        await this._deleteAbility(item, event);
      } else if (itemType === "talent") {
        const item = this.item.system.talents[itemId];
        await this._deleteTalent(item, event);
      }
    });

    if (this.object.type === "talent") {
      if (!Hooks?.events[`closeAssociatedTalent_${this.object._id}`]?.length) {
        Hooks.once(`closeAssociatedTalent_${this.object._id}`, (item) => {
          item.object.flags.clickfromparent = [];
          Hooks.off(`closeAssociatedTalent_${item.object._id}`);
        });
      }
    }

    // Everything below here is only needed if the sheet is editable
    if (!this.isEditable) return;

    // Standalone itemattachment modification controls
    if (this.object.type === "itemattachment") {
      html.find(".flat_editor.add-modification").on("click", this._onStandaloneModificationControl.bind(this));
      html.find(".flat_editor.add-mod").on("click", this._onStandaloneModControl.bind(this));
      html.find(".flat_editor.dropdown").on("change", this._onStandaloneDropdownChange.bind(this));
    }

    // Add or Remove Attribute
    html.find(".attributes").on("click", ".attribute-control", ModifierHelpers.onClickAttributeControl.bind(this));

    // Enable/disable the Active Effect backing a modifier row
    html.find(".attributes").on("change", ".attribute-effect-toggle", ModifierHelpers.onToggleAttributeEffect.bind(this));

    // When the modifier TYPE changes, (a) swap the value input between
    // checkbox/number and (b) repopulate the sibling "Modifier" dropdown to the
    // new type's option set. (b) used to happen implicitly: the change pipeline
    // re-rendered the sheet, rebuilding the <select> from modifierChoices server-
    // side. The render-race fix switched that pipeline to render:false, so the
    // dropdown now goes stale until the sheet is reopened. Rebuild it in-place.
    //
    // This delegated handler is bound on `.attributes` (a descendant of the
    // form), so it runs during bubbling BEFORE the form's own change listener
    // fires _onSubmit -> the repopulated select's new value is already in the DOM
    // when _getSubmitData reads it, and the corrected `.mod` is persisted in the
    // same submit. No manual submit needed here.
    html.find(".attributes").on("change", ".flat_editor.dropdown.modtype", (event) => {
      const new_value = event.currentTarget.value;
      const valueName = event.currentTarget.name.replace(/\.modtype$/, '.value');
      const $valueInput = $(event.currentTarget).parent().find(".modvalue");
      if (new_value === "Career Skill") {
        $valueInput.replaceWith(`<input name="${valueName}" type="checkbox" class="modvalue" data-attr-key="${$valueInput.data('attr-key')}">`);
      } else if ($valueInput.attr('type') === 'checkbox') {
        $valueInput.replaceWith(`<input name="${valueName}" type="number" class="modvalue" value="0" data-attr-key="${$valueInput.data('attr-key')}">`);
      }
      const chosenConfig = CONFIG.FFG.allowableModifierChoices[new_value];
      if (chosenConfig) {
        let modHtml = '';
        Object.keys(chosenConfig).forEach((choice) => {
          modHtml += `<option value="${chosenConfig[choice]['value']}">${game.i18n.localize(chosenConfig[choice]['label'])}</option>`;
        });
        $(event.currentTarget).parent().find(".flat_editor.dropdown.mod").html(modHtml);
      }
    });

    if (["signatureability"].includes(this.object.type)) {
      html.find(".talent-action").on("click", this._onClickTalentControl.bind(this));
      html.find(".talent-actions .fa-cog").on("click", ModifierHelpers.popoutModiferWindow.bind(this));
      html.find(".talent-modifiers .fa-cog").on("click", this._onClickUpgradeEdit.bind(this));
      // Codex bespoke tree (.cdx-ft-*) renames the stock cog containers (same as
      // the force-power/spec trees), so bind the codex base/upgrade modifier cogs.
      html.find(".cdx-ft-power-actions .fa-cog").on("click", ModifierHelpers.popoutModiferWindow.bind(this));
      html.find(".cdx-ft-edit-actions .fa-cog").on("click", this._onClickUpgradeEdit.bind(this));
    }

    if (["forcepower"].includes(this.object.type)) {
      html.find(".talent-action").on("click", this._onClickTalentControl.bind(this));
      html.find(".talent-actions .fa-cog").on("click", ModifierHelpers.popoutModiferWindow.bind(this));
      html.find(".talent-modifiers .fa-cog").on("click", this._onClickUpgradeEdit.bind(this));
      // Codex bespoke tree (.cdx-ft-*) renames the stock cog containers, so bind
      // the codex power/upgrade modifier cogs explicitly.
      html.find(".cdx-ft-power-actions .fa-cog").on("click", ModifierHelpers.popoutModiferWindow.bind(this));
      html.find(".cdx-ft-edit-actions .fa-cog").on("click", this._onClickUpgradeEdit.bind(this));
    }

    if (this.object.type === "specialization") {
      html.find(".talent-action").on("click", this._onClickTalentControl.bind(this));
      html.find(".talent-actions .fa-cog").on("click", ModifierHelpers.popoutModiferWindow.bind(this));
      html.find(".talent-modifiers .fa-cog").on("click", this._onClickUpgradeEdit.bind(this));
      // Codex bespoke tree (.cdx-ft-*) renames the stock cog containers (same as
      // the force-power tree above), so bind the codex spec/talent modifier cogs.
      html.find(".cdx-ft-power-actions .fa-cog").on("click", ModifierHelpers.popoutModiferWindow.bind(this));
      html.find(".cdx-ft-edit-actions .fa-cog").on("click", this._onClickUpgradeEdit.bind(this));
      try {
        const dragDrop = new foundry.applications.ux.DragDrop({
          dragSelector: ".item",
          dropSelector: ".specialization-talent",
          permissions: { dragstart: this._canDragStart.bind(this), drop: this._canDragDrop.bind(this) },
          callbacks: { drop: this._onDropTalentToSpecialization.bind(this) },
        });

        dragDrop.bind($(`form.editable.item-sheet-${this.object.type}`)[0]);
      } catch (err) {
        CONFIG.logger.debug(err);
      }
    } else if (this.object.type === "career") {
      try {
        const dragDrop = new foundry.applications.ux.DragDrop({
          dragSelector: ".item",
          dropSelector: ".tab.career",
          permissions: { dragstart: this._canDragStart.bind(this), drop: this._canDragDrop.bind(this) },
          callbacks: { drop: this._onDragItemCareer.bind(this) },
        });

        dragDrop.bind($(`form.editable.item-sheet-${this.object.type}`)[0]);
      } catch (err) {
        CONFIG.logger.debug(err);
      }
      // handle click events for specialization and signature ability on careers
      html.find(".item-delete").on("click", async (event) => {
        event.stopPropagation();
        const itemId = $(event.target).data("specialization-id");
        const itemType = $(event.target).data("item-type");
        if (itemType === "specialization") {
          const updateData = this.object.system.specializations;
          delete updateData[itemId];
          updateData[`-=${itemId}`] = null;
          this.object.update({system: {specializations: updateData}})
        } else if (itemType === "signatureability") {
          const updateData = this.object.system.signatureabilities;
          delete updateData[itemId];
          updateData[`-=${itemId}`] = null;
          this.object.update({system: {signatureabilities: updateData}})
        }
      });
      // handle click events for specialization and signature ability on careers
      html.find(".item-pill2").on("click", async (event) => {
        event.stopPropagation();
        const itemId = $(event.target).data("specialization-id");
        const itemType = $(event.target).data("item-type");
        let item = game.items.get(itemId);
        if (!item) {
          // it was removed or came from a compendium, try that instead
          if (itemType === "specialization") {
            item = await fromUuid(this.object.system.specializations[itemId].source);
          } else if (itemType === "signatureability") {
            item = await fromUuid(this.object.system.signatureabilities[itemId].source);
          }
        }
        new Item.implementation(item).sheet.render(true);
      });
    } else if (this.object.type === "species") {
      try {
        const dragDrop = new foundry.applications.ux.DragDrop({
          dragSelector: ".item",
          dropSelector: ".tab.talents",
          permissions: { dragstart: this._canDragStart.bind(this), drop: this._canDragDrop.bind(this) },
          callbacks: { drop: this.onDropItemToSpecies.bind(this) },
        });

        dragDrop.bind($(`form.editable.item-sheet-${this.object.type}`)[0]);

        // handle click events for talents on species
        html.find(".item-delete").on("click", async (event) => {
          event.stopPropagation();
          const itemId = $(event.target).data("talent-id");
          const itemType = $(event.target).data("item-type");
          if (itemType === "talent") {
            const updateData = this.object.system.talents;
            delete updateData[itemId];
            updateData[`-=${itemId}`] = null;
            await this.object.update({system: {talents: updateData}})
          }
        });
         // handle click events for specialization and signature ability on careers
        html.find(".item-pill2").on("click", async (event) => {
          event.stopPropagation();
          const itemId = $(event.target).data("talent-id");
          const itemType = $(event.target).data("item-type");
          let item = await fromUuid(this.object.system.talents[itemId].source);
          new Item.implementation(item).sheet.render(true);
        });
      } catch (err) {
        CONFIG.logger.debug(err);
      }
    }

    // hidden here instead of css to prevent non-editable display of edit button
    html.find(".popout-editor").on("mouseover", (event) => {
      $(event.currentTarget).find(".popout-editor-button").show();
    });
    html.find(".popout-editor").on("mouseout", (event) => {
      $(event.currentTarget).find(".popout-editor-button").hide();
    });
    html.find(".popout-editor .popout-editor-button").on("click", this._onPopoutEditor.bind(this));

    // Roll from [ROLL][/ROLL] tag.
    html.find(".rollSkillDirect").on("click", async (event) => {
      event.preventDefault();
      event.stopPropagation();

      let data = event.currentTarget.dataset;
      if (data) {
        let sheet = this.actor.data;
        let skill = sheet.data.skills[data["skill"]];
        let characteristic = sheet.data.characteristics[skill.characteristic];
        let difficulty = data["difficulty"];
        await DiceHelpers.rollSkillDirect(skill, characteristic, difficulty, sheet);
      }
    });

    if (["weapon", "armour", "itemattachment", "shipweapon"].includes(this.object.type)) {
      const itemToItemAssociation = new foundry.applications.ux.DragDrop({
        dragSelector: ".item",
        dropSelector: null,
        permissions: { dragstart: true, drop: true },
        callbacks: { drop: this._onDropItem.bind(this) },
      });
