  importItemFromCollection(collection, entryId) {
    const pack = game.packs.get(collection);
    if (pack.documentName !== "Item") return;
    return pack.getDocument(entryId).then((ent) => {
      CONFIG.logger.debug(`Importing Item ${ent.name} from ${collection}`);
      return ent;
    });
  }

  async _onDropTalentToSpecialization(event) {
    let data;
    const specialization = this.object;
    const li = event.currentTarget;
    const talentId = $(li).attr("id");

    try {
      data = JSON.parse(event.dataTransfer.getData("text/plain"));
      if (data.type !== "Item") return;
    } catch (err) {
      return false;
    }
    // as of v10, "id" is not passed in - instead, "uuid" is. Let's use the Foundry API to get the item Document from the uuid.
    let itemObject = await fromUuid(data.uuid);

    if (!itemObject) return;

    if (itemObject.type === "talent") {
      itemObject = await ItemHelpers.uniqueAttrs(itemObject, specialization);
      // we need to remove if this is the last instance of the talent in the specialization
      const previousItemId = $(li).find(`input[name='data.talents.${talentId}.itemId']`).val();
      const isPreviousItemFromPack = $(li).find(`input[name='data.talents.${talentId}.pack']`).val() === "" ? false : true;
      if (!isPreviousItemFromPack) {
        CONFIG.logger.debug("Non-compendium pack talent update");

        const talentList = [];
        for (let talent in specialization.system.talents) {
          if (talent.itemId === itemObject.id) {
            talentList.push(talent);
          }
        }

        // check if this is the last talent of the specializtion
        if (talentList.length === 1) {
          let tree = itemObject.system.trees;

          const index = tree.findIndex((tal) => {
            return tal === specialization.id;
          });

          // remove the specialization reference from the talent
          tree.splice(index, 1);

          let formData;
          foundry.utils.setProperty(formData, `data.trees`, tree);
          itemObject.update(formData);

          //itemObject.update({ [`data.trees`]: tree });
        }
      }

      $(li).find(`input[name='data.talents.${talentId}.name']`).val(itemObject.name);
      $(li).find(`input[name='data.talents.${talentId}.activation']`).val(itemObject.system.activation.value);
      $(li).find(`input[name='data.talents.${talentId}.activationLabel']`).val(itemObject.system.activation.label);
      $(li).find(`input[name='data.talents.${talentId}.isRanked']`).val(itemObject.system.ranked);
      $(li).find(`input[name='data.talents.${talentId}.isForceTalent']`).val(itemObject.system.isForceTalent);
      $(li).find(`input[name='data.talents.${talentId}.isConflictTalent']`).val(itemObject.system.isConflictTalent);
      $(li).find(`input[name='data.talents.${talentId}.itemId']`).val(itemObject.id);
      $(li).find(`input[name='data.talents.${talentId}.pack']`).val(itemObject.pack);

      const fields = $(li).find(`input[name='data.talents.${talentId}.name']`).parent();
      Object.keys(itemObject.system.attributes).forEach((attr) => {
        const a = itemObject.system.attributes[attr];
        $(fields).append(`<input class="talent-hidden" type="text" name="data.talents.${talentId}.attributes.${attr}.key" value="${attr}" />`);
        $(fields).append(`<input class="talent-hidden" type="text" name="data.talents.${talentId}.attributes.${attr}.value" value="${a.value}" />`);
        $(fields).append(`<input class="talent-hidden" type="text" name="data.talents.${talentId}.attributes.${attr}.modtype" value="${a.modtype}" />`);
        $(fields).append(`<input class="talent-hidden" type="text" name="data.talents.${talentId}.attributes.${attr}.mod" value="${a.mod}" />`);
      });

      // check to see if the talent already has a reference to the specialization
      if (!itemObject.system.trees.includes(specialization.id)) {
        // the talent doesn't already have the reference, add it
        let tree = itemObject.system.trees;
        tree.push(specialization.id);

        if (!data.pack) {
          let formData = {};
          foundry.utils.setProperty(formData, `data.trees`, tree);
          //itemObject.update(formData);
          //itemObject.update({ [`data.trees`]: tree });
        }
      }

      const updateData = {
        system: {
          talents: {
            [talentId]: {
              // these are cloned to avoid local-only clobbers to the dropped object
              description: foundry.utils.deepClone(itemObject.system.description),
              attributes: foundry.utils.deepClone(itemObject.system.attributes),
              isRanked: itemObject.system.ranks.ranked,
              isForceTalent: itemObject.system.isForceTalent,
              isConflictTalent: itemObject.system.isConflictTalent,
            },
          },
        },
      };

      // build a list of existing active effects and attributes so we can delete them
      const existingAttrs = specialization.system.talents[talentId].attributes || {};
      const existingEffects = specialization.getEmbeddedCollection("ActiveEffect");
      const toDelete = [];
      for (const attr of Object.keys(existingAttrs)) {
        updateData.system.talents[talentId].attributes[`-=${attr}`] = null;
        const matchingEffect = existingEffects.find(ae => ae.name === attr);
        if (matchingEffect) {
          toDelete.push(matchingEffect.id);
        }
      }

      await this._onSubmit(event);
      await specialization.update(updateData);
      // actually delete any already-existing AEs on the same talent slot
      await specialization.deleteEmbeddedDocuments("ActiveEffect", toDelete);

      await this._transferActiveEffects(itemObject);

      this.render(true);
    }
  }

  _updateSpecializationTalentReference(specializationTalentItem, talentItem) {
    CONFIG.logger.debug(`Updating Specializations Talent during sheet render`);
    specializationTalentItem.name = talentItem.name;
    specializationTalentItem.description = talentItem.system.description;
    specializationTalentItem.activation = talentItem.system.activation.value;
    specializationTalentItem.activationLabel = talentItem.system.activation.label;
    specializationTalentItem.isRanked = talentItem.system.ranks.ranked;
    specializationTalentItem.isForceTalent = talentItem.system.isForceTalent;
    specializationTalentItem.isConflictTalent = talentItem.system.isConflictTalent;
    specializationTalentItem.attributes = talentItem.system.attributes;
  }

  async _onDropItem(event) {
    let data;
    const obj = this.object;
    const li = event.currentTarget;

    try {
      data = JSON.parse(event.dataTransfer.getData("text/plain"));
      if (data.type !== "Item") return;
    } catch (err) {
      return false;
    }

    // as of v10, "id" is not passed in - instead, "uuid" is. Let's use the Foundry API to get the item Document from the uuid.
    let itemObject = foundry.utils.duplicate(await fromUuid(data.uuid));

    if (!itemObject) return;

    itemObject.id = foundry.utils.randomID(); // why do we do this?!

    // for a rank-only update, we simply update the rank of an existing attr, not transfer AEs
    let rankOnlyUpdate = false;

    if ((itemObject.type === "itemattachment" || itemObject.type === "itemmodifier") && ((obj.type === "shipweapon" && itemObject.system.type === "weapon") || obj.type === itemObject.system.type || itemObject.system.type === "all" || obj.type === "itemattachment")) {
      let items = obj?.system[itemObject.type];
      if (!items) {
        items = [];
      }

      const foundItem = items.find((i) => {
        return i?.name === itemObject.name || (i?.flags?.starwarsffg?.ffgimportid?.length ? i?.flags.starwarsffg.ffgimportid === itemObject.flags.starwarsffg.ffgimportid : false);
      });

      switch (itemObject.type) {
        case "itemmodifier": {
          if (parseInt(itemObject.system.rank, 10) === 0) {
            itemObject.system.rank = 1;
          }

          if (foundItem && this.object.type !== "itemattachment") {
            rankOnlyUpdate = true;
            foundItem.system.rank = (parseInt(foundItem.system.rank) + parseInt(itemObject.system.rank)).toString();
          } else {
            items.push(itemObject);
          }
          break;
        }
        case "itemattachment": {
          if (this.object.system.hardpoints.adjusted - itemObject.system.hardpoints.value >= 0) {
            itemObject = await ItemHelpers.uniqueAttrs(itemObject, this.object);
            items.push(itemObject);
          } else {
            ui.notifications.warn(`Item does not have enough available hardpoints (${this.object.system.hardpoints.adjusted} left)`);
          }
          break;
        }
        default: {
          return;
        }
      }

      let formData = {};
      foundry.utils.setProperty(formData, `data.${itemObject.type}`, items);

      await obj.update(formData);
      // TODO: this happens even if there isn't enough HP (meaning the item gets rejected)
      if (rankOnlyUpdate) {
        await ItemHelpers.syncAEStatus(this.object, this.object.effects);
      } else {
        await this._transferActiveEffects(itemObject);
      }
    }
  }

  /**
   * Transfer active effects from one item to another when they are dragged-and-dropped
   * For example, putting a quality onto a weapon should transfer the AEs to the weapon
   * @param droppedItem - the fromUuid item dropped onto this object
   * @returns {Promise<void>}
   * @private
   */
  async _transferActiveEffects(droppedItem) {
    const droppedType = droppedItem.type;
    const myType = this.object.type;
    const toCreate = [];

    // note that abilities currently don't have a UI to add activeeffects, but we'll try to transfer them anyway
    if (
      (droppedType === "itemattachment" && ["armour", "weapon", "shipweapon"].includes(myType)) ||
      (droppedType === "itemmodifier" && ["armour", "weapon", "shipweapon", "itemattachment"].includes(myType)) ||
      (droppedType === "ability" && myType === "species") || (droppedType === "talent" && myType === "species") ||
      (droppedType === "talent" && myType === "specialization")
    ) {
      CONFIG.logger.debug(`Processing transferring AEs for drag-and-drop of ${droppedType} -> ${myType}`);
      for (const activeEffect of droppedItem.effects) {
        // it appears that Foundry will use the source data over anything else if it's present, so update the source
        //  data to match our updated information (if it exists)
        try {
          activeEffect._source.name = activeEffect.name;
        } catch {
          CONFIG.logger.debug("No source data found for AE (this is sometimes expected)");
        }
        toCreate.push(activeEffect);
      }
      CONFIG.logger.debug(toCreate);
      const createdEffects = await this.object.createEmbeddedDocuments("ActiveEffect", toCreate);
      await ItemHelpers.syncAEStatus(this.object, createdEffects);
    } else {
      CONFIG.logger.debug(`Rejected transferring AEs for drag-and-drop of ${droppedType} -> ${myType}`);
    }
  }

  /**
   * Handles dragging specializations and signature abilities to the career sheet.
   * This is used for purchasing (in order to determine which specializations are career specializations)
   * @param event
   * @returns {Promise<boolean>}
   * @private
   */
  async _onDragItemCareer(event) {
    let data;

    try {
      data = JSON.parse(event.dataTransfer.getData("text/plain"));
      if (data.type !== "Item") return;
    } catch (err) {
      return false;
    }

    // as of v10, "id" is not passed in - instead, "uuid" is. Let's use the Foundry API to get the item Document from the uuid.
    const itemObject = await fromUuid(data.uuid);

    if (!itemObject) return;

    if (itemObject.type === "specialization") {
      await this.object.update({system: {specializations: {[itemObject.id]: {name: itemObject.name, source: itemObject.uuid, id: itemObject.id}}}});
    } else if (itemObject.type === "signatureability") {
      await this.object.update({system: {signatureabilities: {[itemObject.id]: {name: itemObject.name, source: itemObject.uuid, id: itemObject.id}}}});
    }
  }

  /**
   * Handles dragging talents to the species sheet.
   * @param event
   * @returns {Promise<boolean>}
   */
  async onDropItemToSpecies(event) {
    let data;

    try {
      data = JSON.parse(event.dataTransfer.getData("text/plain"));
      if (data.type !== "Item") return;
    } catch (err) {
      return false;
    }

    // as of v10, "id" is not passed in - instead, "uuid" is. Let's use the Foundry API to get the item Document from the uuid.
    const itemObject = await fromUuid(data.uuid);

    if (!itemObject) return;

    if (itemObject.type === "talent") {
      await this.object.update({system: {talents: {[itemObject.id]: {name: itemObject.name, source: itemObject.uuid, id: itemObject.id}}}});
    } else if (itemObject.type === "ability") {
      await this.object.update({system: {abilities: {[itemObject.id]: {name: itemObject.name, system: {description: itemObject.system.description}}}}});
    }
    await this._transferActiveEffects(itemObject);
  }

  async _onDragItemStart(event) {}

  /**
   * Remove an talent from a species item
   * @param item - the item data for the talent to be removed
   * @param event - the event data from the onclick event
   * @returns {Promise<void>}
   * @private
   */
  async _deleteTalent(item, event) {
    event.preventDefault();
    event.stopPropagation();
    const li = $(event.currentTarget);
    const deleteId = li.data("item-id");
    delete this.item.system.talents[deleteId];
    await this.item.update({
      system: {
        talents: {
          [`-=${deleteId}`]: null
        },
      },
    });
    await this.render();
  }

  /**
   * Remove an ability from a species item
   * @param item - the item data for the ability to be removed
   * @param event - the event data from the onclick event
   * @returns {Promise<void>}
   * @private
   */
  async _deleteAbility(item, event) {
    event.preventDefault();
    event.stopPropagation();
    const li = $(event.currentTarget);
    const deleteId = li.data("item-id");
    delete this.item.system.abilities[deleteId];
    await this.item.update({
      system: {
        abilities: {
          [`-=${deleteId}`]: null
        },
      },
    });
    await this.render();
  }

   /**
   * Display details of an ability embedded in a species.
   * @private
   */
  async _itemDisplayDetails(item, event, itemDetails) {
    event.preventDefault();
    let li = $(event.currentTarget);

    // Toggle summary
    if (li.hasClass("expanded")) {
      let details = li.children(".item-details");
      details.slideUp(200, () => details.remove());
    } else {
      let div = $(`<div class="item-details">${await PopoutEditor.renderDiceImages(itemDetails.description, this.item)}</div>`);
      li.append(div.hide());
      $(div)
        .find(".rollSkillDirect")
        .on("click", async (event) => {
          event.preventDefault();
          event.stopPropagation();

          let data = event.currentTarget.dataset;
          if (data) {
            let sheet = await this.getData();
            let skill = sheet.data.skills[data["skill"]];
            let characteristic = sheet.data.characteristics[skill.characteristic];
            let difficulty = data["difficulty"];
            await DiceHelpers.rollSkillDirect(skill, characteristic, difficulty, sheet);
          }
        });

      div.slideDown(200);
    }
    li.toggleClass("expanded");
  }

  /**
   * Currently copy-pasted from _forcePowerDisplayDetails; used to render an inline description of a clicked item
   * @param desc
   * @param event
   * @returns {Promise<void>}
   * @private
   */
  async _itemDisplayDesc(desc, event) {
    event.preventDefault();
    let li = $(event.currentTarget);

    // Toggle summary
    if (li.hasClass("expanded")) {
      let details = li.children(".item-details");
      details.slideUp(200, () => details.remove());
    } else {
      let div = $(`<div class="item-details">${await foundry.applications.ux.TextEditor.implementation.enrichHTML(desc)}</div>`);
      li.append(div.hide());
      div.slideDown(200);
    }
    li.toggleClass("expanded");
  }
}

import {migrateDataToSystem} from "./helpers/migration.js";

const { ApplicationV2, HandlebarsApplicationMixin } = foundry.applications.api;

/**
 * A specialized window used to pop out a ProseMirror editor for a document
 * field. Saving is driven by the native <prose-mirror> `save` event; the
 * caller positions/sizes the window via the legacy (object, options) call.
 * @extends {ApplicationV2}
 */
export default class PopoutEditor extends HandlebarsApplicationMixin(ApplicationV2) {
  static DEFAULT_OPTIONS = {
    id: "popout-editor",
    classes: ["starwarsffg", "sheet"],
    tag: "div",
    window: {
      title: "Pop-out Editor",
      resizable: true,
    },
    position: {
      width: 320,
      height: 320,
    },
  };

  static PARTS = {
    content: {
      root: true,
      template: "systems/starwarsffg/templates/popout-editor.html",
    },
  };

  /**
   * @param {foundry.abstract.Document} object  The document whose field is edited.
   * @param {object} [options]                  Legacy options: `name` (the field
   *   path), `title`, and `width`/`height`/`left`/`top` position hints.
   */
  constructor(object = {}, options = {}) {
    const { name, title, width, height, left, top, ...rest } = options;
    super({
      ...rest,
      window: { ...(rest.window ?? {}), ...(title ? { title } : {}) },
      position: {
        ...(rest.position ?? {}),
        ...(Number.isFinite(width) ? { width } : {}),
        ...(Number.isFinite(height) ? { height } : {}),
        ...(Number.isFinite(left) ? { left } : {}),
        ...(Number.isFinite(top) ? { top } : {}),
      },
    });
    this.object = object;
    this._name = name;
  }

  /**
   * Minimum window size. The editor toolbar (~440px of buttons) wraps to
   * multiple rows in a narrow window and the editing area is unusably small;
   * clamp to a size that keeps the toolbar on one row with a comfortable
   * editing area. Enforced by setPosition below.
   */
  _minDimensions() {
    return { width: 720, height: 520 };
  }

  /** Track the minimize animation so setPosition doesn't fight the collapse. */
  async minimize(...args) {
    this._minimizing = true;
    try {
      return await super.minimize(...args);
    } finally {
      this._minimizing = false;
    }
  }

  /** Clamp interactive resize to the editor's usable minimum. */
  setPosition(position = {}) {
    if (!this.element?.parentElement) return position;
    if (this._minimizing || this.minimized) return super.setPosition(position);
    const min = this._minDimensions();
    const clamped = { ...position };
    if (typeof clamped.width === "number" && clamped.width < min.width) clamped.width = min.width;
    if (typeof clamped.height === "number" && clamped.height < min.height) clamped.height = min.height;
    return super.setPosition(clamped);
  }

  async close(options = {}) {
    const closeOptions = this.minimized && options.animate !== false ? { ...options, animate: false } : options;
    return super.close(closeOptions);
  }

  /**
   * Return a reference to the target attribute
   * @type {String}
   */
  get attribute() {
    return this._name;
  }

  /** @override */
  async _prepareContext(_options) {
    // Get current value
    let attr = foundry.utils.getProperty(this.object.system, this.attribute.replace('data.', ''));

    // Return data
    return {
      value: attr,
      cssClass: "editable popout-editor-window",
    };
  }

  /* -------------------------------------------- */

  /** @override */
  async _onRender(context, options) {
    await super._onRender(context, options);
    const el = this.element;
    // The `root` PARTS entry strips the template's wrapping <form>, injecting
    // the sheet-body straight into .window-content -- so the flex container we
    // own (and must keep filled) is the window-content itself.
    const content = el?.querySelector(".window-content");
    const sheetBody = el?.querySelector("section.sheet-body");
    const pm = el?.querySelector("prose-mirror");

    // Make the editor fill the window instead of leaving a gap below it.
    // sheet-body / prose-mirror otherwise take only their content height; the
    // mandar theme sets flex with !important and beats plain inline styles, so
    // set the column container and our fill rules with "important" too.
    if (content) {
      content.style.setProperty("display", "flex", "important");
      content.style.setProperty("flex-direction", "column", "important");
    }
    if (sheetBody) {
      sheetBody.style.setProperty("flex", "1 1 auto", "important");
      sheetBody.style.setProperty("min-height", "0", "important");
    }
    if (pm) {
      pm.style.setProperty("flex", "1 1 auto", "important");
      pm.style.setProperty("min-height", "0", "important");
      pm.style.setProperty("height", "auto", "important");
    }

    // The native <prose-mirror> element's save button dispatches a `save`
    // event -- the editor's only save path. Persist the value and close on
    // save. The element fires `save` twice (menu button + keymap);
    // _saveAndClose guards re-entry. Bind once per element.
    if (pm && !pm.dataset.ffgSaveBound) {
      pm.dataset.ffgSaveBound = "1";
      pm.addEventListener("save", () => this._saveAndClose(pm.value));
    }
  }

  async _saveAndClose(value) {
    if (this._saving) return;
    this._saving = true;
    const updateData = {};
    updateData[`${this.attribute}`] = value;
    await this.object.update(migrateDataToSystem(updateData));
    await this.close();
  }

  /**
   * Renders the dice symbols based on strings
   * @param  {String} string
   */
  static async renderDiceImages(str, actorData) {
    let html = str || "";

    html = this.replaceRollTags(html, actorData);
    try {
      html = await foundry.applications.ux.TextEditor.implementation.enrichHTML(html, { secrets: true, documents: true, async: false });
    } catch (err) {
      // ignore the message below, it means that we already created an entity link (this could be part of an editor text)
      if (err.message !== "An Entity subclass must configure the EntityCollection it belongs to.") {
        CONFIG.logger.error(err);
      }
    }

    const dicetheme = game.settings.get("starwarsffg", "dicetheme");

    const replaceValues = [
      {
        type: "ability",
        character: "d",
        class: "starwars",
        pattern: /:(ability):|\[(AB)(ILITY)?\]/gim,
      },
      {
        type: "advantage",
        character: "a",
        class: dicetheme,
        pattern: /:(advantage):|\[(AD)(VANTAGE)?\]/gim,
      },
      {
        type: "difficulty",
        character: "di",
        class: "starwars",
        pattern: /:(average):/gim,
      },
      {
        type: "boost",
        character: "b",
        class: "starwars",
        pattern: /:(boost):|\[(BO)(OST)?\]/gim,
      },
      {
        type: "challenge",
        character: "c",
        class: "starwars",
        pattern: /:(challenge):|\[(CH)(ALLENGE)?\]/gim,
      },
      {
        type: "dark",
        character: "z",
        class: "starwars",
        pattern: /:(darkside):|\[(DA)(RK)?\]/gim,
      },
      {
        type: "difficulty",
        character: "dddd",
        class: "starwars",
        pattern: /:(daunting):/gim,
      },
      {
        type: "despair",
        character: dicetheme === "starwars" ? "y" : "d",
        class: dicetheme,
        pattern: /:(despair):|\[(DE)(SPAIR)?\]/gim,
      },
      {
        type: "difficulty",
        character: "d",
        class: "starwars",
        pattern: /:(difficulty):|\[(DI)(FFICULTY)?\]/gim,
      },
      {
        type: "difficulty",
        character: "d",
        class: "starwars",
        pattern: /:(easy):/gim,
      },
      {
        type: "challenge",
        character: "c",
        class: "starwars",
        pattern: /:(easy-1):/gim,
      },
      {
        type: "forcepoint",
        character: "Y",
        class: "starwars",
        pattern: /:(forcepip):|\[(FP|FORCEPOINT)\]/gim,
      },
      {
        type: "difficulty",
        character: "ddddd",
        class: "starwars",
        pattern: /:(formidable):/gim,
      },
      {
        type: "failure",
        character: "f",
        class: dicetheme,
        pattern: /:(failure):|\[(FA)(ILURE)?\]/gim,
      },
      {
        type: "force",
        character: "C",
        class: "starwars",
        pattern: /:(force):|\[(FO)(RCE)?\]/gim,
      },
      {
        type: "difficulty",
        character: "ddd",
        class: "starwars",
        pattern: /:(hard):/gim,
      },
      {
        type: "light",
        character: "Z",
        class: "starwars",
        pattern: /:(lightside):|\[(LI)(GHT)?\]/gim,
      },
      {
        type: "proficiency",
        character: "c",
        class: "starwars",
        pattern: /:(proficiency):|\[(PR)(OFICIENCY)?\]/gim,
      },
      {
        type: "remsetback",
        character: "b",
        class: "starwars",
        pattern: /\[(RS*|REMSETBACK)\]/gim,
      },
      {
        type: "restricted",
        character: "z",
        class: "starwars",
        pattern: /\[(RE)(STRICTED)?\]/gim,
      },
      {
        type: "setback",
        character: "b",
        class: "starwars",
        pattern: /:(setback):|\[(SE)(TBACK)?\]/gim,
      },
      {
        type: "success",
        character: "s",
        class: dicetheme,
        pattern: /:(success):|\[(SU)(CCESS)?\]/gim,
      },
      {
        type: "threat",
        character: dicetheme === "starwars" ? "t" : "h",
        class: dicetheme,
        pattern: /:(threat):|\[(TH)(REAT)?\]/gim,
      },
      {
        type: "triumph",
        character: dicetheme === "starwars" ? "x" : "t",
        class: dicetheme,
        pattern: /:(triumph):|\[(TR)(IUMPH)?\]/gim,
      },
      {
        type: "adddifficulty",
        character: "d",
        class: "starwars",
        pattern: /\[(DD|ADDDIFFICULTY)\]/gim,
      },
      {
        type: "updifficulty",
        character: "d",
        class: "starwars",
        pattern: /\[(UD|UPDIFFICULTY)\]/gim,
      },
      {
        type: "cancelthreat",
        character: "t",
        class: dicetheme,
        pattern: /\[(CT|CANCELTHREAT)\]/gim,
      },
    ];

    replaceValues.forEach((item) => {
      html = html.toString().replace(item.pattern, `<span class='dietype ${item.class} ${item.type}'>${item.character}</span>`);
    });

    const regex = /:([\w]*)-(\d):/gim;
    let m;
    while ((m = regex.exec(html)) !== null) {
      // This is necessary to avoid infinite loops with zero-width matches
      if (m.index === regex.lastIndex) {
        regex.lastIndex++;
      }

      let symbolCount = 0;
      let replaceString = "";

      switch (m[1]) {
        case "average": {
          symbolCount = 2;
          break;
        }
        case "hard": {
          symbolCount = 3;
          break;
        }
        case "daunting": {
          symbolCount = 4;
          break;
        }
        case "formidable": {
          symbolCount = 5;
          break;
        }
      }

      for (let i = 0; i < symbolCount; i += 1) {
        if (i + 1 <= parseInt(m[2], 10)) {
          replaceString += `<span class='dietype starwars challenge'>c</span>`;
        } else {
          replaceString += `<span class='dietype starwars difficulty'>d</span>`;
        }
      }

      html = html.toString().replace(m[0], replaceString);
    }

    const oggdudeTags = [
      {
        startTag: "<span class='bold'>",
        endTag: "</span>",
        pattern: /(\[B\])(.[^\[]*)\[b\]/gm,
      },
      {
        startTag: "<p>",
        endTag: "</p>",
        pattern: /(\[P\])(.[^\[]*)/gm,
      },
      {
        startTag: "<br />",
        endTag: "",
        pattern: /(\[BR\])(.[^\[]*)/gm,
      },
      {
        startTag: "<span class='italic'>",
        endTag: "</span>",
        pattern: /(\[I\])(.[^\[]*)\[i\]/gm,
      },
      {
        startTag: "<h1>",
        endTag: "</h1>",
        pattern: /(\[H1\])(.[^\[]*)\[h1\]/gm,
      },
      {
        startTag: "<h2>",
        endTag: "</h2>",
        pattern: /(\[H2\])(.[^\[]*)\[h2\]/gm,
      },
      {
        startTag: "<h3>",
        endTag: "</h3>",
        pattern: /(\[H3\])(.[^\[]*)\[h3\]/gm,
      },
      {
        startTag: "<h4>",
        endTag: "</h4>",
        pattern: /(\[H4\])(.[^\[]*)\[h4\]/gm,
      },
    ];

    oggdudeTags.forEach((item) => {
      html = html.toString().replace(item.pattern, `${item.startTag}$2${item.endTag}`);
    });

    return html;
  }

  static replaceRollTags(html, actorData) {
    const rollTag = /(\[ROLL\])(.[^\[]*)\[\/ROLL\]/gm;
    const formula = html.toString().replace(rollTag, function (content) {
      content = content.replace(rollTag, `$2`);
      const args = content.split(",").map(function (arg) {
        return arg.trim();
      });
      const di = "[DI]";
      let difficulty = "";
      switch (args[1]) {
        case "0":
          difficulty = "Simple";
          break;
        case "1":
          difficulty = "Easy";
          break;
        case "2":
          difficulty = "Average";
          break;
        case "3":
          difficulty = "Hard";
          break;
        case "4":
          difficulty = "Daunting";
          break;
        case "5":
          difficulty = "Formidable";
          break;
      }
      const id = actorData?._id ? actorData._id : "";

      let formula = `<span class="rollable rollSkillDirect" data-skill="${args[0]}" data-difficulty="${args[1]}" data-actor-id="${id}"><strong>${difficulty} (${di.repeat(args[1])}) ${args[0]}</strong></span>`;
      return formula;
    });

    return formula;
  }
}

import ModifierHelpers from "./helpers/modifiers.js";
import { FFGFormApplication } from "./apps/ffg-form-application.js";

/**
 * Pop-out window for editing an item / upgrade / talent's modifier (attribute)
 * list. Live-edits: each change submits and re-renders, and closing flushes a
 * final submit (submitOnClose).
 * @extends {FFGFormApplication}
 */
export default class PopoutModifiers extends FFGFormApplication {
  static DEFAULT_OPTIONS = {
    id: "popout-modifiers",
    classes: ["starwarsffg", "sheet"],
    window: {
      title: "Pop-out Modifiers",
      resizable: true,
    },
    position: {
      width: 320,
      height: 320,
    },
    form: {
      submitOnChange: true,
      closeOnSubmit: false,
    },
    submitOnClose: true,
  };

  static PARTS = {
    content: {
      root: true,
      template: "systems/starwarsffg/templates/items/dialogs/ffg-popout-modifiers.html",
    },
  };

  /** @override */
  async _prepareContext(_options) {
    const data = {
      data: this.object.system,
      modTypeSelected: "all",
      modifierTypes: CONFIG.FFG.allowableModifierTypes,
      modifierChoices: CONFIG.FFG.allowableModifierChoices,
    };

    if (this.object.isUpgrade) {
      data.data = this.object.parent.system.upgrades[this.object.keyname];
    } else if (this.object.isTalent) {
      data.data = this.object.parent.system.talents[this.object.keyname];
    }

    data.FFG = CONFIG.FFG;
    data.cssClass = "editable popout-modifiers-window attributes";

    // Return data
    return data;
  }

  /* -------------------------------------------- */

  /** @override */
  async _onRender(context, options) {
    await super._onRender(context, options);
    // window-content is the <form> (contentTag); the `root` PARTS entry strips
    // the template's own <form>, so `.attributes` is a direct child of
    // window-content. Constrain the (potentially long) modifier list to scroll
    // within the window instead of overflowing the frame -- a flex column so
    // the list takes the remaining height. Inline + !important so the mandar
    // theme can't win the cascade and reintroduce overflow.
    const content = this.element?.querySelector(".window-content");
    const attributes = content?.querySelector(":scope > .attributes");
    if (content && attributes) {
      content.style.setProperty("display", "flex", "important");
      content.style.setProperty("flex-direction", "column", "important");
      attributes.style.setProperty("flex", "1 1 auto", "important");
      attributes.style.setProperty("min-height", "0", "important");
      attributes.style.setProperty("overflow-y", "auto", "important");
    }

    if (this.isEditable && content) {
      // Delegated add/remove modifier-row controls. `.attributes` is re-created
      // on every render, so (re)bind here. onClickAttributeControl reads
      // `this.form` and calls `this._onSubmit` -- both provided by the base.
      $(content).find(".attributes").on("click", ".attribute-control", ModifierHelpers.onClickAttributeControl.bind(this));
    }
  }

  /* -------------------------------------------- */

  /** @override */
  async _updateObject(event, formData) {
    formData = foundry.utils.expandObject(formData);

    // Handle the free-form attributes list
    const formAttrs = foundry.utils.expandObject(formData)?.data?.attributes || {};
    const attributes = Object.values(formAttrs).reduce((obj, v) => {
      let k = v["key"].trim();
      if (/[\s\.]/.test(k)) return ui.notifications.error("Attribute keys may not contain spaces or periods");
      delete v["key"];
      obj[k] = v;
      return obj;
    }, {});

    // Remove attributes which are no longer used
    if (this.object.system?.attributes) {
      for (let k of Object.keys(this.object.system.attributes)) {
        if (!attributes.hasOwnProperty(k)) attributes[`-=${k}`] = null;
      }
    }

    // recombine attributes to formData
    if (Object.keys(attributes).length > 0) {
      foundry.utils.setProperty(formData, `data.attributes`, attributes);
    }

    if (this.object.isUpgrade) {
      // redo the earlier code but with the proper attribute path
      // Remove attributes which are no longer used
      if (this.object.parent.system.upgrades[this.object.keyname].attributes) {
        for (let k of Object.keys(this.object.parent.system.upgrades[this.object.keyname].attributes)) {
          if (!attributes.hasOwnProperty(k)) attributes[`-=${k}`] = null;
        }
      }

      // recombine attributes to formData
      if (Object.keys(attributes).length > 0) {
        foundry.utils.setProperty(formData, `data.attributes`, attributes);
      }

      let data = attributes;

      let upgradeFormData = {};
      foundry.utils.setProperty(upgradeFormData, `data.upgrades.${this.object.keyname}.attributes`, data);

      upgradeFormData.system = upgradeFormData.data;
      delete upgradeFormData.data;
      delete upgradeFormData._id;

      await this.object.parent.update(upgradeFormData);
    } else if (this.object.isTalent) {
      // redo the earlier code but with the proper attribute path
      // Remove attributes which are no longer used
      if (this.object.parent.system.talents[this.object.keyname].attributes) {
        for (let k of Object.keys(this.object.parent.system.talents[this.object.keyname].attributes)) {
          if (!attributes.hasOwnProperty(k)) {
            attributes[`-=${k}`] = null;
          }
        }
      }
      let test_item = await game.items.get(this.object.parent.system.talents[this.object.keyname]?.itemId);
      if (this.object.parent.system.talents[this.object.keyname].pack || test_item) {
        ui.notifications.error(game.i18n.localize("SWFFG.Notifications.TalentEditGlobally"));
        return;
      }

      // recombine attributes to formData
      if (Object.keys(attributes).length > 0) {
        foundry.utils.setProperty(formData, `data.attributes`, attributes);
      }

      let data = attributes;

      let upgradeFormData = {};
      foundry.utils.setProperty(upgradeFormData, `data.talents.${this.object.keyname}.attributes`, data);

      upgradeFormData.system = upgradeFormData.data;
      delete upgradeFormData.data;
      delete upgradeFormData._id;
      await this.object.parent.update(upgradeFormData);
    } else {
      // Update the Item
      const syncFormData = foundry.utils.deepClone(formData);
      if (syncFormData?.data?.attributes) {
        for (const attr of Object.keys(syncFormData.data.attributes)) {
          if (attr.startsWith("-=")) {
            delete syncFormData.data.attributes[attr];
          }
        }
      }
      await ModifierHelpers.applyActiveEffectOnUpdate(this.object, syncFormData);
      // sets _id, which is not settable
      formData.system = formData.data;
      delete formData.data;
      delete formData._id;
      await this.object.update(formData);
    }
    this.render();
  }
}

import { FFGFormApplication } from "../apps/ffg-form-application.js";

export default class CrewSettings extends FFGFormApplication {
  static DEFAULT_OPTIONS = {
    id: "data-importer",
    classes: ["starwarsffg", "data-import"],
    window: {
      title: "SWFFG.UISettingsLabel",
      resizable: true,
    },
    position: {
      height: 265,
    },
    form: {
      closeOnSubmit: true,
    },
  };

  static PARTS = {
    content: {
      root: true,
      template: "systems/starwarsffg/templates/dialogs/crew-settings.html",
    },
  };

  async _prepareContext(_options) {
    const gs = game.settings;
    const canConfigure = game.user.can("SETTINGS_MODIFY");

    const data = {
      system: { title: game.system.title, menus: [], settings: [] },
    };

    // Classify all settings
    for (let setting of gs.settings.values()) {
      // Exclude settings the user cannot change
      if (!setting.key.includes("arrayCrewRoles") || (!canConfigure && setting.scope !== "client")) continue;

      // Update setting data
      const s = foundry.utils.duplicate(setting);
      s.name = game.i18n.localize(s.name);
      s.hint = game.i18n.localize(s.hint);
      s.value = game.settings.get(s.namespace, s.key);
      s.type = setting.type instanceof Function ? setting.type.name : "String";
      s.isCheckbox = setting.type === Boolean;
      s.isSelect = s.choices !== undefined;
      s.isRange = setting.type === Number && s.range;
      s.isFilePicker = setting.valueType === "FilePicker";

      // Classify setting
      if (s.namespace === game.system.id && s.key.includes("arrayCrewRoles")) data.system.settings.push(s);
    }

    data.skills = CONFIG.FFG.skills;
    data.initiativeRole = game.settings.get('starwarsffg', 'initiativeCrewRole');

    // Return data
    return {
      user: game.user,
      canConfigure: canConfigure,
      systemTitle: game.system.title,
      data: data,
    };
  }

  async _onRender(context, options) {
    await super._onRender(context, options);
    const html = $(this.element);
    html.find('button[name="reset"]').click(this._onResetDefaults.bind(this));
  }

  /* -------------------------------------------- */

  /**
   * Handle button click to reset default settings
   * @param event {Event}   The initial button click event
   * @private
   */
  _onResetDefaults(event) {
    event.preventDefault();
    const defaults = game.settings.settings.get("starwarsffg.arrayCrewRoles").default;
    game.settings.set("starwarsffg", "arrayCrewRoles", defaults);
    this.close();
  }


  /* -------------------------------------------- */

  /** @override */
  async _updateObject(event, formData) {
    const existing_settings = game.settings.get("starwarsffg", "arrayCrewRoles");
    let new_settings = [];
    // convert the arrays into the format expected
    for (let i = 0; i < formData['role_name'].length; i++) {
      new_settings.push({
        'role_name': formData['role_name'][i],
        'role_skill': formData['role_skill'][i],
        'use_handling': formData['use_handling'][i],
        'use_weapons': formData['use_weapons'][i],
      })
    }
    // update the settings if they don't match the old ones
    if (existing_settings !== new_settings) {
      await game.settings.set("starwarsffg", "arrayCrewRoles", new_settings);
    }
    const updateData = {
      "role_name":  formData['initiativeCrewRole'],
      "role_skill": undefined,
      "use_weapons": false,
      "use_handling": false
    };
    await game.settings.set("starwarsffg", "initiativeCrewRole", updateData);
  }
}

